        void shutdown() noexcept
        {
            RollbackReplaySelectionAvailabilityHook::instance().deactivate();
            restore_background_idle_override();
            LuxBattleLauncherStartHook::instance()
                .set_rounds_to_win_override(0);
            LuxBattleLauncherStartHook::instance()
                .clear_replay_seed_override();
            if (m_replay_injection_armed)
            {
                RollbackStockTransportObserveHook::instance()
                    .end_replay_input_script();
                RollbackLiveBoundaryHook::instance()
                    .end_replay_input_script();
            }
            m_replay_injection_armed = false;
            m_cfg.enabled = false;
            m_service_game_thread_in_progress = false;
            m_process_event_followup_in_progress = false;
            m_process_event_followup_pending = false;
            reset_online_navigator_caches();
            m_title_scene_stability.reset();
            s_luxor_network_check_compat_enabled.store(
                false, std::memory_order_release);
            s_peer_route_tag_fix_enabled.store(
                false, std::memory_order_release);
            reset_join_callback_state();
            if (m_native_lifecycle_trace_owned)
            {
                NativeReplayTraceHook::instance()
                    .release_replay_lifecycle_trace(
                        m_native_lifecycle_trace_owner);
            }
            m_native_lifecycle_trace_owned = false;
            m_native_lifecycle_trace_ready = false;
            s_steam_p2p_connect_fail_current_lifecycle_serial.store(
                0, std::memory_order_release);
            auto* expected = this;
            (void)s_active_instance.compare_exchange_strong(
                expected, nullptr, std::memory_order_acq_rel);
        }

        void service_connection_terminal_events_game_thread(
            uint64_t tick) noexcept
        {
            if (!m_cfg.enabled) return;
            consume_steam_p2p_connect_fail_observations(tick);
        }

        void service_game_thread(uint64_t tick) noexcept
        {
            if (!m_cfg.enabled) return;
            if (m_service_game_thread_in_progress) return;
            m_service_game_thread_in_progress = true;
            m_last_service_tick = tick;
            service_connection_terminal_events_game_thread(tick);
            RollbackReplaySelectionAvailabilityHook::instance()
                .update_peer_contract(
                    production_steam_session_contract_ready(),
                    m_stock_native_battle_tick_seen
                        || m_cfg.online_stage_cleanup_only);
            const bool dispatch_callback_followup =
                m_process_event_followup_pending &&
                tick >= m_process_event_followup_last_tick;
            if (dispatch_callback_followup)
            {
                m_process_event_followup_pending = false;
                m_process_event_followup_in_progress = true;
                ReplayTraceFields f;
                f.string("request_id", m_cfg.request_id)
                 .string("client_role", m_cfg.client_role)
                 .string("function", m_process_event_followup_last_kind)
                 .uinteger("followup_count",
                           m_process_event_followup_count)
                 .uinteger("tick", tick)
                 .uinteger("followup_tick",
                           m_process_event_followup_last_tick)
                 .uinteger("last_attempt_tick",
                           m_online_stage_last_attempt_tick);
                ReplayDebugTrace::instance().event(
                    "rollback_online_stage_callback_followup_dispatch", f);
            }
            if (m_cfg.online_stage_requested
                && !m_cfg.stock_session_observe_only
                && RollbackStockJoinRouteUsesAuthenticatedOffer(
                    m_cfg.stock_join_route))
            {
                (void)ensure_create_player_session_observe_hook();
            }
            const bool stock_menu_rate_completed_now =
                m_stock_menu_rate_first_tick != 0
                && !m_stock_menu_rate_complete
                && update_stock_menu_rate_sample(tick);
            const bool stock_menu_rate_sampling =
                m_stock_menu_rate_first_tick != 0
                && !m_stock_menu_rate_complete;
            const bool stock_battle_observer_idle =
                m_cfg.stock_join_route ==
                    RollbackStockJoinRoute::InjectedStockInvite &&
                m_stock_process_event_capture_complete.load(
                    std::memory_order_acquire) &&
                (tick % RollbackOnlineStageTraceCadence::kStockBattleTicks) != 0;
            const bool stock_setup_observer_idle =
                m_cfg.stock_join_route ==
                    RollbackStockJoinRoute::InjectedStockInvite &&
                !m_stock_process_event_capture_complete.load(
                    std::memory_order_acquire) &&
                !dispatch_callback_followup &&
                !stock_menu_rate_completed_now &&
                (stock_menu_rate_sampling ||
                 (tick % RollbackOnlineStageTraceCadence::kStockSetupTicks) != 0);
            service_stock_battle_asset_scheduled_release(tick);
            if ((m_cfg.online_stage_requested
                    || m_cfg.stock_session_observe_only) &&
                !stock_battle_observer_idle &&
                !stock_setup_observer_idle)
                service_online_stage(tick);
            if (m_cfg.stock_join_route ==
                    RollbackStockJoinRoute::InjectedStockInvite &&
                m_stock_process_event_capture_complete.load(
                    std::memory_order_acquire) &&
                !stock_battle_observer_idle)
            {
                (void)bind_production_presentation_actors_if_ready();
            }
            if (m_cfg.observe_gameflow_requested)
                service_gameflow_observe(tick);
            if (dispatch_callback_followup)
                m_process_event_followup_in_progress = false;
            m_service_game_thread_in_progress = false;
        }

