        RollbackSteamSessionIdentity
        stock_steam_session_identity() const noexcept
        {
            RollbackSteamSessionIdentity identity {};
            identity.lobby_id = m_native_named_session_lobby_id;
            identity.owner_steam_id =
                m_native_named_session_lobby_owner_id;
            identity.local_steam_id = m_steam_local_id;
            identity.remote_steam_id = m_stock_remote_steam_id;
            identity.selection_hash = m_cfg.stock_session_observe_only
                ? stock_observed_selection_hash()
                : RollbackStockOnlineLabDriver::selection_hash(
                    m_stock_driver.selection());
            identity.lifecycle_serial =
                m_native_connection_lifecycle_serial;
            identity.named_session = m_native_named_session_ptr;
            identity.session_info = m_native_named_session_info;
            identity.connect_manager = m_luxor_connect_manager;
            identity.active_connect = m_luxor_active_connect_object;
            identity.active_transport = m_luxor_active_transport;
            identity.session_connection =
                m_luxor_session_connection_object;
            identity.active_connect_state = m_luxor_active_connect_state;
            identity.active_connect_sub_state =
                m_luxor_active_connect_sub_state;
            identity.named_session_valid =
                RollbackOnlineNamedSessionReusable(
                    current_named_session_evidence());
            identity.transport_connected =
                RollbackStockOnlineLabDriver::steam_connection_complete(
                    m_cfg.client_role == "host",
                    m_luxor_active_connect_state,
                    m_luxor_session_connection_object,
                    m_session_member_join_seen);
            identity.terminal_evidence =
                m_native_connection_terminal_evidence;
            identity.native_terminal = identity.terminal_evidence
                != RollbackSteamNativeTerminalEvidence::None;
            return identity;
        }

        void update_native_connection_lifecycle_serial(
            bool manager_fields_observed) noexcept
        {
            if (!manager_fields_observed) return;
            const bool core_present = m_native_named_session_ptr != 0
                && m_native_named_session_info != 0
                && m_luxor_connect_manager != 0
                && m_luxor_active_connect_object != 0
                && m_luxor_active_transport != 0;
            if (!core_present)
            {
                if (m_native_connection_lifecycle_serial != 0
                    && m_luxor_active_connect_object == 0)
                {
                    m_native_connection_epoch_absent = true;
                }
                return;
            }

            const auto conflicts = [](uintptr_t accepted,
                                      uintptr_t observed) noexcept {
                return accepted != 0 && observed != 0
                    && accepted != observed;
            };
            const bool core_changed =
                conflicts(m_native_connection_epoch_named_session,
                    m_native_named_session_ptr)
                || conflicts(m_native_connection_epoch_session_info,
                    m_native_named_session_info)
                || conflicts(m_native_connection_epoch_connect_manager,
                    m_luxor_connect_manager)
                || conflicts(m_native_connection_epoch_active_connect,
                    m_luxor_active_connect_object)
                || conflicts(m_native_connection_epoch_active_transport,
                    m_luxor_active_transport)
                || conflicts(m_native_connection_epoch_session_connection,
                    m_luxor_session_connection_object);
            const bool terminal_tuple =
                m_luxor_active_connect_state == 5
                && m_luxor_active_connect_sub_state == 9;
            const bool join_failure_edge = m_join_scene_terminal_failure
                && !m_native_connection_last_join_scene_terminal_failure;
            const bool active_attempt = m_luxor_active_connect_state != 0
                && m_luxor_active_connect_state != 0xffu
                && !terminal_tuple;
            const bool new_attempt =
                m_native_connection_lifecycle_serial == 0
                || core_changed
                || (m_native_connection_epoch_absent && active_attempt)
                || (m_native_connection_epoch_terminal && active_attempt);
            if (new_attempt)
            {
                ++m_native_connection_serial_counter;
                if (m_native_connection_serial_counter == 0)
                    ++m_native_connection_serial_counter;
                m_native_connection_lifecycle_serial =
                    m_native_connection_serial_counter;
                m_native_connection_epoch_named_session =
                    m_native_named_session_ptr;
                m_native_connection_epoch_session_info =
                    m_native_named_session_info;
                m_native_connection_epoch_connect_manager =
                    m_luxor_connect_manager;
                m_native_connection_epoch_active_connect =
                    m_luxor_active_connect_object;
                m_native_connection_epoch_active_transport =
                    m_luxor_active_transport;
                m_native_connection_epoch_session_connection =
                    m_luxor_session_connection_object;
                m_native_connection_epoch_absent = false;
                m_native_connection_epoch_terminal = false;
                m_native_connection_terminal_evidence =
                    RollbackSteamNativeTerminalEvidence::None;
            }
            else if (m_native_connection_epoch_session_connection == 0
                && m_luxor_session_connection_object != 0)
            {
                // The connection object is created after the active-connect
                // attempt begins. Latch it into the same serial once.
                m_native_connection_epoch_session_connection =
                    m_luxor_session_connection_object;
            }
            if (join_failure_edge)
            {
                m_native_connection_epoch_terminal = true;
                m_native_connection_terminal_evidence =
                    RollbackSteamNativeTerminalEvidence::JoinSceneFailure;
            }
            if (terminal_tuple)
            {
                // Both native retry tasks write the tuple together on final
                // exhaustion. Substate 9 alone is also written by nonterminal
                // opcode/watch failure paths and is not sufficient evidence.
                m_native_connection_epoch_terminal = true;
                m_native_connection_terminal_evidence =
                    RollbackSteamNativeTerminalEvidence
                        ::LuxorRetryExhausted;
            }
            m_native_connection_last_join_scene_terminal_failure =
                m_join_scene_terminal_failure;
            s_steam_p2p_connect_fail_current_lifecycle_serial.store(
                m_native_connection_lifecycle_serial,
                std::memory_order_release);
        }

        void latch_steam_p2p_connect_fail_terminal(
            const RollbackSteamP2PConnectFailObservation& observation,
            uint64_t tick,
            RollbackSteamP2PConnectFailDisposition disposition) noexcept
        {
            m_native_connection_epoch_terminal = true;
            m_native_connection_terminal_evidence =
                RollbackSteamNativeTerminalEvidence
                    ::P2PSessionConnectFail;
            ++m_steam_p2p_connect_fail_matches;
            m_steam_p2p_connect_fail_last_remote_steam_id =
                observation.remote_steam_id;
            m_steam_p2p_connect_fail_last_lifecycle_serial =
                observation.lifecycle_serial;
            m_steam_p2p_connect_fail_last_error = observation.error;

            ReplayTraceFields f;
            add_session_trace_identity(f);
            f.uinteger("tick", tick)
             .uinteger("event_sequence", observation.sequence)
             .uinteger("lifecycle_serial", observation.lifecycle_serial)
             .hex("remote_steam_id", observation.remote_steam_id)
             .uinteger("error", observation.error)
             .boolean("stream_overflow",
                      disposition ==
                          RollbackSteamP2PConnectFailDisposition
                              ::TerminalStreamOverflow);
            ReplayDebugTrace::instance().event(
                "rollback_steam_p2p_connect_fail_terminal", f);
        }

        void consume_steam_p2p_connect_fail_observations(
            uint64_t tick) noexcept
        {
            const uint64_t published =
                s_steam_p2p_connect_fail_published_sequence.load(
                    std::memory_order_acquire);
            if (published <=
                m_steam_p2p_connect_fail_last_consumed_sequence)
                return;

            uint64_t first =
                m_steam_p2p_connect_fail_last_consumed_sequence + 1;
            bool stream_overflow = false;
            if (published - first >= kSteamP2PConnectFailEventCapacity)
            {
                stream_overflow = true;
                first = published - kSteamP2PConnectFailEventCapacity + 1;
                ++m_steam_p2p_connect_fail_stream_overflows;
            }

            for (uint64_t sequence = first; sequence <= published;
                 ++sequence)
            {
                const auto& slot = s_steam_p2p_connect_fail_events[
                    sequence & (kSteamP2PConnectFailEventCapacity - 1)];
                if (slot.sequence.load(std::memory_order_acquire) !=
                    sequence)
                {
                    stream_overflow = true;
                    ++m_steam_p2p_connect_fail_stream_overflows;
                    continue;
                }

                RollbackSteamP2PConnectFailObservation observation {};
                observation.sequence = sequence;
                observation.lifecycle_serial =
                    slot.lifecycle_serial.load(std::memory_order_relaxed);
                observation.remote_steam_id =
                    slot.remote_steam_id.load(std::memory_order_relaxed);
                observation.error = static_cast<uint8_t>(
                    slot.error.load(std::memory_order_relaxed));
                observation.stream_overflow = false;
                ++m_steam_p2p_connect_fail_observations;

                const auto disposition =
                    ClassifyRollbackSteamP2PConnectFailObservation(
                        observation,
                        m_native_connection_lifecycle_serial,
                        m_stock_remote_steam_id);
                if (disposition ==
                    RollbackSteamP2PConnectFailDisposition::Terminal)
                {
                    latch_steam_p2p_connect_fail_terminal(
                        observation, tick, disposition);
                }
                else if (disposition ==
                    RollbackSteamP2PConnectFailDisposition
                        ::StaleLifecycle)
                {
                    ++m_steam_p2p_connect_fail_stale_lifecycle;
                }
                else if (disposition ==
                    RollbackSteamP2PConnectFailDisposition::OtherRemote)
                {
                    ++m_steam_p2p_connect_fail_other_remote;
                }
            }

            m_steam_p2p_connect_fail_last_consumed_sequence = published;
            if (stream_overflow
                && m_native_connection_lifecycle_serial != 0
                && m_stock_remote_steam_id != 0)
            {
                RollbackSteamP2PConnectFailObservation observation {};
                observation.sequence = published;
                observation.lifecycle_serial =
                    m_native_connection_lifecycle_serial;
                observation.remote_steam_id = m_stock_remote_steam_id;
                observation.error = 0xff;
                observation.stream_overflow = true;
                latch_steam_p2p_connect_fail_terminal(
                    observation, tick,
                    RollbackSteamP2PConnectFailDisposition
                        ::TerminalStreamOverflow);
            }
        }

        uint64_t stock_observed_selection_hash() const noexcept
        {
            const bool synchronized_pair =
                !m_stock_synced_chara_left.empty()
                && !m_stock_synced_chara_right.empty();
            const bool sent_pair = !m_stock_send_active_code.empty()
                && !m_stock_send_passive_code.empty();
            if ((!synchronized_pair && !sent_pair)
                || !m_stock_native_stage_identity_cached)
            {
                return 0;
            }
            const std::string& left_character = synchronized_pair
                ? m_stock_synced_chara_left : m_stock_send_active_code;
            const std::string& right_character = synchronized_pair
                ? m_stock_synced_chara_right : m_stock_send_passive_code;
            try
            {
                auto observed = RollbackStockOnlineLabDriver::desired(
                    RollbackStockOnlineLabDriver::kDefaultLeftCharacter,
                    RollbackStockOnlineLabDriver::kDefaultRightCharacter,
                    static_cast<int32_t>(
                        m_stock_native_stage_identity & 0xFFFFu),
                        m_cfg.launch_rounds_to_win_override);
                observed.left_character = left_character;
                observed.right_character = right_character;
                return RollbackStockOnlineLabDriver::selection_hash(observed);
            }
            catch (...)
            {
                return 0;
            }
        }

        void emit_stock_observed_selection_if_ready() noexcept
        {
            const bool synchronized_pair =
                !m_stock_synced_chara_left.empty()
                && !m_stock_synced_chara_right.empty();
            const bool sent_pair = !m_stock_send_active_code.empty()
                && !m_stock_send_passive_code.empty();
            if (m_cfg.stock_session_observe_only)
            {
                if (!synchronized_pair && !sent_pair) return;
            }
            else if (!synchronized_pair
                || !m_stock_selection_bilateral_ok
                || !stock_battle_construction_ready())
            {
                return;
            }
            if (!m_stock_native_stage_identity_cached
                && (synchronized_pair || sent_pair))
            {
                uint32_t native_stage_identity = 0;
                if (CaptureRollbackNativeStageIdentity(
                        native_stage_identity, false, true))
                {
                    m_stock_native_stage_identity_cached = true;
                    m_stock_native_stage_identity = native_stage_identity;
                }
            }
            const uint64_t selection_hash =
                stock_observed_selection_hash();
            if (!selection_hash || m_stock_observed_selection_emitted)
                return;
            const std::string& left_character = synchronized_pair
                ? m_stock_synced_chara_left : m_stock_send_active_code;
            const std::string& right_character = synchronized_pair
                ? m_stock_synced_chara_right : m_stock_send_passive_code;
            ReplayTraceFields fields;
            fields.string("request_id", m_cfg.request_id)
                .string("client_role", m_cfg.client_role)
                .string("left_character", left_character)
                .string("right_character", right_character)
                .hex("native_stage_identity",
                    m_stock_native_stage_identity)
                .hex("selection_hash", selection_hash);
            ReplayDebugTrace::instance().event(
                "rollback_stock_observed_selection", fields);
            m_stock_observed_selection_emitted = true;
        }

        uint8_t stock_cleanup_out_of_battle_observations() const noexcept
        {
            return m_stock_driver.cleanup_out_of_battle_observations();
        }

        bool stock_cleanup_exit_dispatched() const noexcept
        {
            return m_cleanup_battle_exit_requested;
        }

        bool stock_cleanup_exit_succeeded() const noexcept
        {
            return m_cleanup_battle_exit_request_ok;
        }

        bool stock_native_battle_ready_for_ownership(
            bool immediate_replay_ownership = false) const noexcept
        {
            return RollbackStockOnlineLabDriver::ownership_ready(
                m_stock_native_battle_tick_seen,
                m_stock_battle_rate_gate.complete,
                m_stock_battle_rate_gate.ok,
                immediate_replay_ownership
                    || m_cfg.live_replay_input_requested);
        }

        RollbackStockLobbyOffer stock_local_offer(
            uint64_t generation,
            uint64_t build_id,
            uint64_t schema_id) noexcept
        {
            RollbackStockLobbyOffer offer {};
            const bool injected_route =
                RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route);
            const bool host_creation_proven = injected_route
                ? (m_host_room_create_decide_ok
                   && s_create_player_session_observe_calls.load(
                        std::memory_order_acquire) == 1
                   && s_create_player_session_private_overrides.load(
                        std::memory_order_acquire) == 0
                   && s_create_player_session_last_incoming_public_flag.load(
                        std::memory_order_acquire) == 0
                   && s_create_player_session_last_public_flag.load(
                        std::memory_order_acquire) == 0
                   && s_create_player_session_name_is_player_match.load(
                        std::memory_order_acquire))
                : (m_host_room_create_private_room_enabled
                   && m_host_room_create_private_room_down_count == 9
                   && m_host_room_create_private_room_right_count == 1
                   && m_host_room_create_private_room_up_count == 9
                   && m_host_room_create_decide_ok);
            // A host cannot have a peer connection before it advertises the
            // private room to that peer. For the stock invite route, native
            // session creation plus the authoritative InRoom FSM is the
            // readiness proof; requiring SessionConnectComplete here creates
            // a circular wait and that Blueprint callback may bypass the
            // ProcessEvent observer anyway.
            const bool host_connection_ready = injected_route
                ? m_player_match_in_room_ok
                : (m_luxor_active_connect_state == 3 &&
                   m_luxor_session_connection_object != 0 &&
                   m_luxor_active_transport != 0 &&
                   m_luxor_active_transport_status_code == 1);
            const bool host_transport_ready =
                m_cfg.client_role == "host"
                && m_steam_private_lobby_ok
                && host_creation_proven
                && m_native_named_session_lobby_id != 0
                && m_steam_private_lobby_id ==
                    m_native_named_session_lobby_id
                && host_connection_ready
                && m_player_match_in_room_ok
                && m_steam_local_id != 0
                && m_native_named_session_lobby_owner_id ==
                    m_steam_local_id;
            if (!host_transport_ready)
            {
                m_stock_host_transport_stable_first_tick = 0;
                return offer;
            }

            offer.lobby_id = m_native_named_session_lobby_id;
            offer.host_steam_id = m_steam_local_id;
            offer.invitee_steam_id = m_stock_remote_steam_id;
            offer.owner_steam_id = m_native_named_session_lobby_owner_id;
            offer.request_generation = generation;
            offer.build_id = build_id;
            offer.schema_id = schema_id;
            return offer;
        }

