        static std::wstring widen_utf8(const std::string& in)
        {
            if (in.empty()) return {};
            const int need = MultiByteToWideChar(
                CP_UTF8, 0, in.c_str(), -1, nullptr, 0);
            if (need <= 1) return {};
            std::wstring out(static_cast<size_t>(need - 1), L'\0');
            MultiByteToWideChar(CP_UTF8, 0, in.c_str(), -1,
                                out.data(), need);
            return out;
        }

        static bool host_room_ready_marker_char_safe(char ch) noexcept
        {
            return (ch >= 'a' && ch <= 'z') ||
                   (ch >= 'A' && ch <= 'Z') ||
                   (ch >= '0' && ch <= '9') ||
                   ch == '_' || ch == '-' || ch == '.';
        }

        static std::string sanitized_host_room_ready_marker_name(
            const std::string& requested,
            const std::string& request_id)
        {
            std::string source = requested.empty()
                ? ("rollback_host_room_ready_" +
                   (request_id.empty() ? std::string("default")
                                       : request_id) +
                   ".ready")
                : requested;
            std::string out;
            out.reserve(source.size());
            for (char ch : source)
            {
                out.push_back(
                    host_room_ready_marker_char_safe(ch) ? ch : '_');
            }
            if (out.empty())
                out = "rollback_host_room_ready_default.ready";
            return out;
        }

        std::string host_room_ready_marker_name() const
        {
            return sanitized_host_room_ready_marker_name(
                m_cfg.host_room_ready_marker, m_cfg.request_id);
        }

        std::wstring host_room_ready_marker_path_wide(
            std::string* out_utf8 = nullptr) const
        {
            std::string root =
                ReplayDebugTrace::instance().current_mod_root_utf8();
            if (root.empty())
            {
                if (out_utf8) out_utf8->clear();
                return {};
            }
            const char tail = root.back();
            if (tail != '\\' && tail != '/')
                root.push_back('\\');
            root += "Saved\\";
            root += host_room_ready_marker_name();
            if (out_utf8) *out_utf8 = root;
            return widen_utf8(root);
        }

        bool stock_menu_pair_rate_released() noexcept
        {
            if (!m_cfg.online_stage_wait_host_room_ready_marker)
                return true;
            std::string path_utf8;
            std::wstring path =
                host_room_ready_marker_path_wide(&path_utf8);
            if (path.empty()) return false;
            path += L".menu-rate";
            const DWORD attrs = GetFileAttributesW(path.c_str());
            m_stock_menu_pair_rate_released =
                attrs != INVALID_FILE_ATTRIBUTES
                && (attrs & FILE_ATTRIBUTE_DIRECTORY) == 0;
            return m_stock_menu_pair_rate_released;
        }

        bool role_room_ready_marker_released(
            uint64_t tick) noexcept
        {
            if (!m_cfg.online_stage_wait_host_room_ready_marker ||
                (m_cfg.client_role != "host" &&
                 m_cfg.client_role != "sandbox"))
            {
                return true;
            }

            // This is a per-root barrier.  The runner releases the sandbox
            // copy after the host advertises the room, then releases the host
            // copy after the sandbox proves native connect state 3 in the
            // same two-member lobby. Waiting for PlayerMatchInRoomState here
            // is circular: stock Ready is what completes that transition.

            m_host_room_ready_marker_wait_requested = true;
            if (m_host_room_ready_marker_first_wait_tick == 0)
                m_host_room_ready_marker_first_wait_tick = tick;

            std::string path_utf8;
            const std::wstring path =
                host_room_ready_marker_path_wide(&path_utf8);
            m_host_room_ready_marker_path = path_utf8;
            if (path.empty())
            {
                m_host_room_ready_marker_failure =
                    "host-room-ready-marker-path-unavailable";
                return false;
            }

            const DWORD attrs = GetFileAttributesW(path.c_str());
            if (attrs == INVALID_FILE_ATTRIBUTES ||
                (attrs & FILE_ATTRIBUTE_DIRECTORY) != 0)
            {
                m_host_room_ready_marker_failure =
                    "host-room-ready-marker-missing";
                return false;
            }

            m_host_room_ready_marker_observed = true;
            if (m_host_room_ready_marker_observed_tick == 0)
                m_host_room_ready_marker_observed_tick = tick;
            m_host_room_ready_marker_failure = "ok";
            return true;
        }

