        bool stock_battle_marker_released(const wchar_t* suffix) noexcept
        {
            if (!m_cfg.online_stage_wait_host_room_ready_marker)
                return true;
            std::wstring path = host_room_ready_marker_path_wide();
            if (path.empty()) return false;
            path += suffix;
            const DWORD attrs = GetFileAttributesW(path.c_str());
            if (attrs == INVALID_FILE_ATTRIBUTES ||
                (attrs & FILE_ATTRIBUTE_DIRECTORY) != 0)
            {
                return false;
            }

            HANDLE file = CreateFileW(path.c_str(), GENERIC_READ,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
            if (file == INVALID_HANDLE_VALUE) return false;
            char buffer[64] {};
            DWORD read = 0;
            const BOOL read_ok = ReadFile(
                file, buffer, sizeof(buffer) - 1, &read, nullptr);
            CloseHandle(file);
            if (!read_ok) return false;

            char* end = nullptr;
            const uint64_t target_qpc = std::strtoull(buffer, &end, 10);
            if (end == buffer || target_qpc == 0) return true;
            LARGE_INTEGER now {};
            return QueryPerformanceCounter(&now) != 0 &&
                   static_cast<uint64_t>(now.QuadPart) >= target_qpc;
        }

        void service_stock_battle_asset_scheduled_release(
            uint64_t tick) noexcept
        {
            if (!m_stock_battle_asset_release_polling_enabled
                || m_stock_battle_asset_release.release_applied()
                || m_stock_battle_asset_release.marker_invalid()
                || m_stock_native_battle_tick_seen
                || m_cfg.online_stage_cleanup_only
                || m_cfg.stock_join_route !=
                    RollbackStockJoinRoute::InjectedStockInvite
                || m_stock_battle_asset_release.request_generation() == 0
                || m_stock_battle_asset_release.request_generation() !=
                    m_cfg.stock_request_generation)
            {
                return;
            }

            if (!m_stock_battle_asset_release.target_latched())
            {
                if (m_stock_battle_asset_release_marker_path.empty()) return;
                HANDLE file = CreateFileW(
                    m_stock_battle_asset_release_marker_path.c_str(),
                    GENERIC_READ,
                    FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                    nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
                if (file == INVALID_HANDLE_VALUE) return;

                LARGE_INTEGER size {};
                char buffer[64] {};
                DWORD read = 0;
                const bool read_ok = GetFileSizeEx(file, &size) != 0
                    && size.QuadPart > 0
                    && size.QuadPart < static_cast<LONGLONG>(sizeof(buffer))
                    && ReadFile(file, buffer,
                        static_cast<DWORD>(size.QuadPart), &read, nullptr) != 0
                    && read == static_cast<DWORD>(size.QuadPart);
                CloseHandle(file);
                if (!read_ok)
                {
                    m_stock_battle_asset_release.reject_marker();
                    return;
                }
                if (!m_stock_battle_asset_release.latch_target(
                        std::string_view(buffer, read)))
                {
                    return;
                }
                const uint64_t target =
                    m_stock_battle_asset_release.target_qpc();
                NativeReplayTraceHook::instance()
                    .set_stock_battle_asset_release_schedule(
                        m_stock_battle_asset_release.request_generation(),
                        target);

                ReplayTraceFields latched;
                latched.string("request_id", m_cfg.request_id)
                    .string("client_role", m_cfg.client_role)
                    .uinteger("tick", tick)
                    .uinteger("request_generation",
                        m_stock_battle_asset_release.request_generation())
                    .uinteger("target_qpc", target);
                ReplayDebugTrace::instance().event(
                    "rollback_stock_battle_asset_release_target_latched",
                    latched);
            }

            LARGE_INTEGER now {};
            if (QueryPerformanceCounter(&now) == 0) return;
            const uint64_t now_qpc = static_cast<uint64_t>(now.QuadPart);
            const RollbackScheduledReleaseObservation native_release =
                NativeReplayTraceHook::instance()
                    .stock_battle_asset_release_observation();
            if (native_release.actual_qpc != 0
                && native_release.released
                && native_release.generation ==
                    m_stock_battle_asset_release.request_generation()
                && native_release.target_qpc ==
                    m_stock_battle_asset_release.target_qpc())
            {
                record_stock_battle_asset_scheduled_release(
                    tick, native_release.actual_qpc);
                return;
            }
            if (!m_stock_battle_asset_release.release_due(
                    m_cfg.stock_request_generation,
                    m_stock_native_battle_tick_seen,
                    now_qpc))
            {
                return;
            }
            if (!NativeReplayTraceHook::instance()
                    .release_stock_battle_asset_barrier_if_ready(
                        m_cfg.stock_request_generation,
                        m_stock_battle_asset_release.request_generation(),
                        m_stock_battle_asset_release.target_latched(),
                        m_stock_battle_asset_release.target_qpc(),
                        m_stock_battle_asset_release.release_applied(),
                        m_stock_native_battle_tick_seen,
                        now_qpc))
            {
                return;
            }

            record_stock_battle_asset_scheduled_release(tick, now_qpc);
        }

        void record_stock_battle_asset_scheduled_release(
            uint64_t tick, uint64_t actual_qpc) noexcept
        {
            if (m_stock_battle_asset_release.release_applied()) return;
            m_stock_battle_asset_release.mark_released(actual_qpc);
            ReplayTraceFields released;
            released.string("request_id", m_cfg.request_id)
                .string("client_role", m_cfg.client_role)
                .uinteger("tick", tick)
                .uinteger("request_generation",
                    m_stock_battle_asset_release.request_generation())
                .uinteger("target_qpc",
                    m_stock_battle_asset_release.target_qpc())
                .uinteger("actual_qpc", actual_qpc)
                .uinteger("lateness_qpc",
                    actual_qpc - m_stock_battle_asset_release.target_qpc());
            ReplayDebugTrace::instance().event(
                "rollback_stock_battle_asset_fast_release", released);
        }

