        static bool ensure_process_event_hook() noexcept
        {
            if (s_process_event_hook_installed.load(std::memory_order_acquire))
                return true;
            bool expected = false;
            if (!s_process_event_hook_attempted.compare_exchange_strong(
                    expected, true, std::memory_order_acq_rel))
            {
                return s_process_event_hook_installed.load(
                    std::memory_order_acquire);
            }

            try
            {
                RC::Unreal::Hook::FCallbackOptions post_options {};
                post_options.bReadonly = true;
                post_options.OwnerModName = STR("HorseMod");
                post_options.HookName = STR("RollbackStockSessionObserve");
                const uint64_t post_id =
                    RC::Unreal::Hook::RegisterProcessEventPostCallback(
                    [](RC::Unreal::Hook::TCallbackIterationData<void>&,
                       RC::Unreal::UObject* context,
                       RC::Unreal::UFunction* function,
                       void* params) {
                        handle_process_event_post(context, function, params);
                    }, post_options);
                if (!post_id)
                {
                    return false;
                }
                s_process_event_post_id.store(post_id, std::memory_order_release);
                s_process_event_hook_installed.store(
                    true, std::memory_order_release);
                RC::Output::send<RC::LogLevel::Default>(STR(
                    "[RollbackP2P] ProcessEvent hooks registered\n"));
                return true;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] ProcessEvent hook registration threw: {}\n"),
                    RC::to_generic_string(e.what()));
            }
            catch (...)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] ProcessEvent hook registration threw\n"));
            }
            return false;
        }

        static bool ensure_stock_character_send_hook() noexcept
        {
            if (s_stock_chara_ubergraph_function)
                return true;

            RC::Unreal::UnrealScriptFunctionCallable empty =
                [](RC::Unreal::UnrealScriptFunctionCallableContext&,
                   void*) {};
            if (!s_stock_chara_ubergraph_function)
            {
                auto* klass = RC::Unreal::UObjectGlobals::StaticFindObject<
                    RC::Unreal::UClass*>(
                        nullptr, nullptr,
                        STR("/Game/UI/GameFlow/GameScenes/BattleSetup/State/"
                            "Online/PlayerMatchCharaSelectExecState."
                            "PlayerMatchCharaSelectExecState_C"));
                if (!klass) return false;
                const RC::StringType path = klass->GetPathName() +
                    STR(":ExecuteUbergraph_PlayerMatchCharaSelectExecState");
                auto* found = RC::Unreal::UObjectGlobals::StaticFindObject<
                    RC::Unreal::UFunction*>(nullptr, nullptr, path);
                if (!found) return false;
                RC::Unreal::UnrealScriptFunctionCallable pre =
                [](RC::Unreal::UnrealScriptFunctionCallableContext& ctx,
                   void*) {
                    handle_stock_character_send_pre(ctx);
                };
                try
                {
                    s_stock_chara_ubergraph_hook_ids =
                        RC::Unreal::UObjectGlobals::RegisterHook(
                            found, pre, empty, nullptr);
                }
                catch (...)
                {
                    s_stock_chara_ubergraph_hook_ids = {0, 0};
                    return false;
                }
                s_stock_chara_ubergraph_function = found;
            }
            return true;
        }

