        static void clear_find_result_snapshot() noexcept
        {
            std::lock_guard<std::mutex> lock(s_find_result_snapshot_mutex);
            s_find_result_snapshot.clear();
            s_find_result_snapshot_count = 0;
            s_find_result_snapshot_element_size = 0;
        }

        static bool capture_find_result_snapshot(
            const void* data_ptr,
            int32_t count,
            int32_t element_size) noexcept
        {
            if (!data_ptr || count <= 0 || count > 64 ||
                element_size <= 0 || element_size > 512)
            {
                clear_find_result_snapshot();
                return false;
            }
            const size_t total =
                static_cast<size_t>(count) *
                static_cast<size_t>(element_size);
            if (total == 0 || total > 32768)
            {
                clear_find_result_snapshot();
                return false;
            }
            std::vector<uint8_t> bytes(total, 0);
            if (!SafeReadBytes(data_ptr, bytes.data(), total))
            {
                clear_find_result_snapshot();
                return false;
            }
            {
                std::lock_guard<std::mutex> lock(
                    s_find_result_snapshot_mutex);
                s_find_result_snapshot = std::move(bytes);
                s_find_result_snapshot_count = count;
                s_find_result_snapshot_element_size = element_size;
            }
            return true;
        }

        static RC::Unreal::UObject*
        reflected_object_property_from_valid_owner(
            RC::Unreal::UObject* owner,
            const wchar_t* name) noexcept
        {
            // The caller already validated owner in this service pass. Avoid
            // another O(GUObjectArray) UObject::IsReal scan while still
            // validating the reflected child before it is used.
            if (!owner || !name) return nullptr;
            try
            {
                RC::Unreal::FProperty* prop =
                    owner->GetPropertyByNameInChain(name);
                if (!prop || prop->GetSize() < static_cast<int32_t>(
                        sizeof(void*)))
                {
                    return nullptr;
                }
                void* slot = prop->ContainerPtrToValuePtr<void>(owner);
                void* raw = nullptr;
                if (!slot || !SafeReadPtr(slot, &raw) || !raw)
                    return nullptr;
                auto* object = reinterpret_cast<RC::Unreal::UObject*>(raw);
                return safe_is_real(object) ? object : nullptr;
            }
            catch (...)
            {
                return nullptr;
            }
        }

        static RC::Unreal::FProperty* reflected_query_output(
            RC::Unreal::UFunction* function,
            const wchar_t* named_output) noexcept
        {
            if (!function) return nullptr;
            RC::Unreal::FProperty* output =
                reflected_param(function, named_output);
            if (output) return output;
            try
            {
                return function->GetReturnProperty();
            }
            catch (...)
            {
                return nullptr;
            }
        }

        static RC::Unreal::UFunction* safe_get_function_by_name_in_chain(
            RC::Unreal::UObject* source,
            const wchar_t* function_name) noexcept
        {
            if (!source || !function_name) return nullptr;
            __try
            {
                return source->GetFunctionByNameInChain(function_name);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return nullptr;
            }
        }

        static bool call_main_menu_text_query_from_valid_source(
            RC::Unreal::UObject* source,
            const wchar_t* function_name,
            const wchar_t* output_name,
            std::string& out,
            std::string& failure) noexcept
        {
            out.clear();
            if (!source || !function_name || !output_name)
            {
                failure = "text-query-source-unavailable";
                return false;
            }
            try
            {
                RC::Unreal::UFunction* function =
                    safe_get_function_by_name_in_chain(
                        source, function_name);
                if (!function)
                {
                    failure = "text-query-function-unavailable";
                    return false;
                }
                const int32_t params_size = function->GetPropertiesSize();
                if (params_size <= 0 || params_size > 256)
                {
                    failure = "text-query-param-size-invalid";
                    return false;
                }
                RC::Unreal::FProperty* output = reflected_query_output(
                    function, output_name);
                auto* string_output = RC::Unreal::CastField<
                    RC::Unreal::FStrProperty>(output);
                auto* name_output = RC::Unreal::CastField<
                    RC::Unreal::FNameProperty>(output);
                if (!output || (!string_output && !name_output))
                {
                    failure = "text-query-output-type-unsupported";
                    return false;
                }

                std::vector<uint8_t> params(
                    static_cast<size_t>(params_size), 0);
                bool initialized = false;
                try
                {
                    output->InitializeValue_InContainer(params.data());
                    initialized = true;
                    if (!safe_process_event(
                            source, function, params.data()))
                    {
                        failure = "text-query-process-event-failed";
                    }
                    else if (string_output)
                    {
                        auto* value = string_output->ContainerPtrToValuePtr<
                            RC::Unreal::FString>(params.data());
                        if (value)
                        {
                            out = fstring_to_utf8(*value);
                            failure = "ok";
                        }
                        else
                        {
                            failure = "text-query-output-unavailable";
                        }
                    }
                    else
                    {
                        auto* value = name_output->ContainerPtrToValuePtr<
                            RC::Unreal::FName>(params.data());
                        if (value)
                        {
                            out = narrow_rc_string(value->ToString());
                            failure = "ok";
                        }
                        else
                        {
                            failure = "name-query-output-unavailable";
                        }
                    }
                }
                catch (...)
                {
                    failure = "text-query-exception";
                }
                if (initialized)
                {
                    try
                    {
                        output->DestroyValue_InContainer(params.data());
                    }
                    catch (...)
                    {
                    }
                }
                return failure == "ok";
            }
            catch (...)
            {
                failure = "text-query-reflection-exception";
                return false;
            }
        }

        static bool call_main_menu_int_query_from_valid_source(
            RC::Unreal::UObject* source,
            const wchar_t* function_name,
            const wchar_t* output_name,
            int32_t& out,
            std::string& failure) noexcept
        {
            out = -1;
            if (!source || !function_name || !output_name)
            {
                failure = "int-query-source-unavailable";
                return false;
            }
            try
            {
                RC::Unreal::UFunction* function =
                    safe_get_function_by_name_in_chain(
                        source, function_name);
                if (!function)
                {
                    failure = "int-query-function-unavailable";
                    return false;
                }
                const int32_t params_size = function->GetPropertiesSize();
                if (params_size <= 0 || params_size > 256)
                {
                    failure = "int-query-param-size-invalid";
                    return false;
                }
                RC::Unreal::FProperty* output = reflected_query_output(
                    function, output_name);
                auto* numeric_output = RC::Unreal::CastField<
                    RC::Unreal::FNumericProperty>(output);
                if (!output || !numeric_output || !numeric_output->IsInteger())
                {
                    failure = "int-query-output-type-unsupported";
                    return false;
                }
                std::vector<uint8_t> params(
                    static_cast<size_t>(params_size), 0);
                if (!safe_process_event(source, function, params.data()))
                {
                    failure = "int-query-process-event-failed";
                    return false;
                }
                void* value = numeric_output->ContainerPtrToValuePtr<void>(
                    params.data());
                if (!value)
                {
                    failure = "int-query-output-unavailable";
                    return false;
                }
                const int64_t signed_value =
                    numeric_output->GetSignedIntPropertyValue(value);
                if (signed_value < INT32_MIN || signed_value > INT32_MAX)
                {
                    failure = "int-query-output-out-of-range";
                    return false;
                }
                out = static_cast<int32_t>(signed_value);
                failure = "ok";
                return true;
            }
            catch (...)
            {
                failure = "int-query-reflection-exception";
                return false;
            }
        }

        static bool safe_set_reflected_integer(
            RC::Unreal::FNumericProperty* property,
            void* container,
            int32_t value) noexcept
        {
            if (!property || !container) return false;
            __try
            {
                if (!property->IsInteger()) return false;
                void* slot = property->ContainerPtrToValuePtr<void>(
                    container);
                if (!slot) return false;
                property->SetIntPropertyValue(
                    slot, static_cast<int64_t>(value));
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static RC::Unreal::UObject* safe_get_reflected_object(
            RC::Unreal::FObjectPropertyBase* property,
            void* container) noexcept
        {
            if (!property || !container) return nullptr;
            __try
            {
                void* slot = property->ContainerPtrToValuePtr<void>(
                    container);
                return slot ? property->GetObjectPropertyValue(slot)
                            : nullptr;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return nullptr;
            }
        }

        static bool safe_set_reflected_object(
            RC::Unreal::FObjectPropertyBase* property,
            void* container,
            RC::Unreal::UObject* value) noexcept
        {
            if (!property || !container || !value) return false;
            __try
            {
                void* slot = property->ContainerPtrToValuePtr<void>(
                    container);
                if (!slot) return false;
                property->SetObjectPropertyValue(slot, value);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool reflected_parameter_is_input(
            RC::Unreal::FProperty* property) noexcept
        {
            if (!property) return false;
            try
            {
                return property->HasAnyPropertyFlags(RC::Unreal::CPF_Parm) &&
                       !property->HasAnyPropertyFlags(
                           RC::Unreal::CPF_OutParm |
                           RC::Unreal::CPF_ReturnParm);
            }
            catch (...)
            {
                return false;
            }
        }

        static bool reflected_parameter_is_output(
            RC::Unreal::FProperty* property) noexcept
        {
            if (!property) return false;
            try
            {
                return property->HasAnyPropertyFlags(RC::Unreal::CPF_Parm) &&
                       property->HasAnyPropertyFlags(
                           RC::Unreal::CPF_OutParm |
                           RC::Unreal::CPF_ReturnParm);
            }
            catch (...)
            {
                return false;
            }
        }

        static RC::Unreal::FObjectPropertyBase*
        cast_reflected_object_property(
            RC::Unreal::FProperty* property) noexcept
        {
            if (!property) return nullptr;
            // UE4SS's field type checker does not classify this SC6 build's
            // concrete ObjectProperty as the abstract FObjectPropertyBase
            // in every reflection path. Prefer the concrete class proved by
            // the live signature, then retain the base fallback for other
            // supported object-property variants.
            if (auto* object = RC::Unreal::CastField<
                    RC::Unreal::FObjectProperty>(property))
            {
                return object;
            }
            return RC::Unreal::CastField<
                RC::Unreal::FObjectPropertyBase>(property);
        }

        static std::string describe_reflected_function_parameters(
            RC::Unreal::UFunction* function) noexcept
        {
            if (!function) return "<function-unavailable>";
            std::string out;
            try
            {
                for (RC::Unreal::FProperty* property :
                     RC::Unreal::TFieldRange<RC::Unreal::FProperty>(
                         function,
                         RC::Unreal::EFieldIterationFlags::
                             IncludeDeprecated))
                {
                    if (!property || !property->HasAnyPropertyFlags(
                            RC::Unreal::CPF_Parm))
                    {
                        continue;
                    }
                    if (!out.empty()) out += ";";
                    const std::string name = narrow_rc_string(
                        property->GetName());
                    const std::string type = narrow_rc_string(
                        property->GetClass().GetName());
                    const uint64_t flags = static_cast<uint64_t>(
                        property->GetPropertyFlags());
                    char metadata[128] {};
                    std::snprintf(
                        metadata,
                        sizeof(metadata),
                        "%s:%s:size=%d:flags=0x%llX:%s",
                        name.empty() ? "<unnamed>" : name.c_str(),
                        type.empty() ? "<unknown>" : type.c_str(),
                        property->GetSize(),
                        static_cast<unsigned long long>(flags),
                        property->HasAnyPropertyFlags(
                            RC::Unreal::CPF_ReturnParm)
                            ? "return"
                            : property->HasAnyPropertyFlags(
                                  RC::Unreal::CPF_OutParm)
                                ? "out"
                                : "in");
                    out += metadata;
                    if (out.size() > 1800)
                    {
                        out.resize(1800);
                        out += "...";
                        break;
                    }
                }
            }
            catch (...)
            {
                if (!out.empty()) out += ";";
                out += "<reflection-exception>";
            }
            return out.empty() ? "<no-CPF_Parm-properties>" : out;
        }

        static RC::Unreal::FNumericProperty*
        resolve_reflected_integer_input(
            RC::Unreal::UFunction* function,
            const wchar_t* const* preferred_names,
            size_t preferred_name_count,
            bool require_unique,
            std::string& selected_name,
            std::string& failure) noexcept
        {
            selected_name.clear();
            failure.clear();
            if (!function)
            {
                failure = "function unavailable";
                return nullptr;
            }
            RC::Unreal::FNumericProperty* unique = nullptr;
            size_t count = 0;
            try
            {
                for (RC::Unreal::FProperty* property :
                     RC::Unreal::TFieldRange<RC::Unreal::FProperty>(
                         function,
                         RC::Unreal::EFieldIterationFlags::
                             IncludeDeprecated))
                {
                    if (!reflected_parameter_is_input(property)) continue;
                    auto* numeric = RC::Unreal::CastField<
                        RC::Unreal::FNumericProperty>(property);
                    if (!numeric || !numeric->IsInteger()) continue;
                    ++count;
                    unique = numeric;
                }
                for (size_t i = 0; i < preferred_name_count; ++i)
                {
                    RC::Unreal::FProperty* raw = reflected_param(
                        function, preferred_names[i]);
                    auto* named = RC::Unreal::CastField<
                        RC::Unreal::FNumericProperty>(raw);
                    if (!named || !named->IsInteger() ||
                        !reflected_parameter_is_input(raw))
                    {
                        continue;
                    }
                    if (require_unique && count != 1)
                    {
                        failure = "named integer input exists but total "
                                  "integer input count is " +
                                  std::to_string(count);
                        return nullptr;
                    }
                    selected_name = narrow_rc_string(raw->GetName());
                    return named;
                }
                if (count == 1 && unique)
                {
                    selected_name = narrow_rc_string(unique->GetName());
                    return unique;
                }
                failure = count == 0
                    ? "no integer input CPF_Parm"
                    : "ambiguous integer input CPF_Parm count=" +
                        std::to_string(count);
            }
            catch (...)
            {
                failure = "integer input reflection exception";
            }
            return nullptr;
        }

        static RC::Unreal::FObjectPropertyBase*
        resolve_reflected_object_parameter(
            RC::Unreal::UFunction* function,
            const wchar_t* const* preferred_names,
            size_t preferred_name_count,
            bool want_output,
            bool require_unique,
            std::string& selected_name,
            std::string& failure) noexcept
        {
            selected_name.clear();
            failure.clear();
            if (!function)
            {
                failure = "function unavailable";
                return nullptr;
            }
            RC::Unreal::FObjectPropertyBase* unique = nullptr;
            size_t count = 0;
            try
            {
                for (RC::Unreal::FProperty* property :
                     RC::Unreal::TFieldRange<RC::Unreal::FProperty>(
                         function,
                         RC::Unreal::EFieldIterationFlags::
                             IncludeDeprecated))
                {
                    const bool direction_ok = want_output
                        ? reflected_parameter_is_output(property)
                        : reflected_parameter_is_input(property);
                    if (!direction_ok) continue;
                    auto* object =
                        cast_reflected_object_property(property);
                    if (!object) continue;
                    ++count;
                    unique = object;
                }
                for (size_t i = 0; i < preferred_name_count; ++i)
                {
                    RC::Unreal::FProperty* raw = reflected_param(
                        function, preferred_names[i]);
                    const bool direction_ok = want_output
                        ? reflected_parameter_is_output(raw)
                        : reflected_parameter_is_input(raw);
                    auto* named = cast_reflected_object_property(raw);
                    if (!named || !direction_ok) continue;
                    if (require_unique && count != 1)
                    {
                        failure = "named object parameter exists but total "
                                  "matching-direction object count is " +
                                  std::to_string(count);
                        return nullptr;
                    }
                    selected_name = narrow_rc_string(raw->GetName());
                    return named;
                }
                if (count == 1 && unique)
                {
                    selected_name = narrow_rc_string(unique->GetName());
                    return unique;
                }
                failure = count == 0
                    ? std::string("no object ") +
                        (want_output ? "output" : "input") + " CPF_Parm"
                    : std::string("ambiguous object ") +
                        (want_output ? "output" : "input") +
                        " CPF_Parm count=" + std::to_string(count);
            }
            catch (...)
            {
                failure = "object parameter reflection exception";
            }
            return nullptr;
        }

        static bool reflected_function_params_size(
            RC::Unreal::UFunction* function,
            const char* function_name,
            int32_t& out_size,
            std::string& reason) noexcept
        {
            out_size = 0;
            if (!function)
            {
                reason = std::string(function_name ? function_name
                                                   : "function") +
                         " unavailable";
                return false;
            }
            try
            {
                out_size = function->GetPropertiesSize();
            }
            catch (...)
            {
                reason = std::string(function_name ? function_name
                                                   : "function") +
                         " parameter reflection failed";
                return false;
            }
            if (out_size <= 0 || out_size > 512)
            {
                reason = std::string(function_name ? function_name
                                                   : "function") +
                         " parameter size invalid: " +
                         std::to_string(out_size);
                return false;
            }
            return true;
        }

        static bool call_main_menu_list_get_item(
            RC::Unreal::UObject* list_impl,
            int32_t index,
            RC::Unreal::UObject*& out_item,
            std::string& reason) noexcept
        {
            out_item = nullptr;
            reason.clear();
            RC::Unreal::UFunction* function =
                safe_get_function_by_name_in_chain(list_impl, L"GetItem");
            int32_t params_size = 0;
            if (!reflected_function_params_size(
                    function, "BP_MainMenuListImpl.GetItem",
                    params_size, reason))
            {
                return false;
            }
            static constexpr const wchar_t* kIndexNames[] = {
                L"InIndex", L"Index", L"SelectedIndex", L"InFocusIndex"};
            static constexpr const wchar_t* kItemOutputNames[] = {
                L"Item", L"MainMenuListItem", L"ReturnValue",
                L"GetItem", L"FocusItem", L"AsMain Menu List Item"};
            std::string index_name;
            std::string index_failure;
            auto* index_property = resolve_reflected_integer_input(
                function,
                kIndexNames,
                std::size(kIndexNames),
                false,
                index_name,
                index_failure);
            std::string item_name;
            std::string item_failure;
            auto* item_property = resolve_reflected_object_parameter(
                function,
                kItemOutputNames,
                std::size(kItemOutputNames),
                true,
                false,
                item_name,
                item_failure);
            if (!index_property || !item_property)
            {
                reason = "GetItem signature unsupported: index={" +
                         index_failure + "}; item={" + item_failure +
                         "}; params={" +
                         describe_reflected_function_parameters(function) +
                         "}";
                return false;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(params_size), 0);
            if (!safe_set_reflected_integer(
                    index_property, params.data(), index))
            {
                reason = "GetItem failed to write integer input " +
                         index_name;
                return false;
            }
            if (!safe_process_event(list_impl, function, params.data()))
            {
                reason = "BP_MainMenuListImpl.GetItem ProcessEvent failed";
                return false;
            }
            out_item = safe_get_reflected_object(
                item_property, params.data());
            if (!out_item)
            {
                reason = "GetItem returned null for " + index_name + "=" +
                         std::to_string(index) + " via " + item_name +
                         "; params={" +
                         describe_reflected_function_parameters(function) +
                         "}";
                return false;
            }
            reason = "called GetItem(" + index_name + "=" +
                     std::to_string(index) + ") output=" + item_name;
            return true;
        }

        static bool call_main_menu_list_get_index_from_menu_id(
            RC::Unreal::UObject* list_impl,
            const wchar_t* menu_id,
            int32_t& out_index,
            std::string& reason) noexcept
        {
            out_index = -1;
            reason.clear();
            if (!list_impl || !menu_id || !*menu_id)
            {
                reason = "GetIndexFromMenuID source/menu id unavailable";
                return false;
            }
            RC::Unreal::UFunction* function =
                safe_get_function_by_name_in_chain(
                    list_impl, L"GetIndexFromMenuID");
            int32_t params_size = 0;
            if (!reflected_function_params_size(
                    function, "BP_MainMenuListImpl.GetIndexFromMenuID",
                    params_size, reason))
            {
                return false;
            }

            RC::Unreal::FStrProperty* menu_id_property = nullptr;
            static constexpr const wchar_t* kMenuIdNames[] = {
                L"InMenuID", L"MenuID", L"MenuId"};
            for (const wchar_t* candidate_name : kMenuIdNames)
            {
                try
                {
                    auto* raw = function->FindProperty(
                        RC::Unreal::FName(
                            candidate_name, RC::Unreal::FNAME_Find));
                    menu_id_property = RC::Unreal::CastField<
                        RC::Unreal::FStrProperty>(raw);
                    if (menu_id_property) break;
                }
                catch (...)
                {
                    menu_id_property = nullptr;
                }
            }
            RC::Unreal::FIntProperty* index_property = nullptr;
            static constexpr const wchar_t* kIndexNames[] = {
                L"Index", L"OutIndex", L"ReturnValue"};
            for (const wchar_t* candidate_name : kIndexNames)
            {
                try
                {
                    auto* raw = function->FindProperty(
                        RC::Unreal::FName(
                            candidate_name, RC::Unreal::FNAME_Find));
                    index_property = RC::Unreal::CastField<
                        RC::Unreal::FIntProperty>(raw);
                    if (index_property) break;
                }
                catch (...)
                {
                    index_property = nullptr;
                }
            }
            if (!menu_id_property || !index_property)
            {
                reason = "GetIndexFromMenuID signature unsupported; params={" +
                         describe_reflected_function_parameters(function) +
                         "}";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(params_size), 0);
            bool menu_id_initialized = false;
            try
            {
                menu_id_property->InitializeValue_InContainer(params.data());
                menu_id_initialized = true;
                menu_id_property->SetPropertyValueInContainer(
                    params.data(), RC::Unreal::FString(menu_id));
                if (!safe_process_event(list_impl, function, params.data()))
                {
                    reason = "BP_MainMenuListImpl.GetIndexFromMenuID "
                             "ProcessEvent failed";
                }
                else
                {
                    auto* value = index_property->ContainerPtrToValuePtr<
                        int32_t>(params.data());
                    if (value) out_index = *value;
                    reason = out_index >= 0
                        ? "resolved menu id to index " +
                              std::to_string(out_index)
                        : "GetIndexFromMenuID returned a negative index";
                }
            }
            catch (...)
            {
                reason = "BP_MainMenuListImpl.GetIndexFromMenuID threw";
                out_index = -1;
            }
            if (menu_id_initialized)
                menu_id_property->DestroyValue_InContainer(params.data());
            return out_index >= 0;
        }

        static bool call_main_menu_list_focus_item_object(
            RC::Unreal::UObject* list_impl,
            RC::Unreal::UObject* item,
            std::string& reason) noexcept
        {
            reason.clear();
            RC::Unreal::UFunction* function =
                safe_get_function_by_name_in_chain(list_impl, L"FocusItem");
            int32_t params_size = 0;
            if (!reflected_function_params_size(
                    function, "BP_MainMenuListImpl.FocusItem",
                    params_size, reason))
            {
                return false;
            }
            static constexpr const wchar_t* kItemInputNames[] = {
                L"MainMenuListItem", L"Item", L"FocusItem", L"InItem"};
            std::string item_name;
            std::string item_failure;
            auto* item_property = resolve_reflected_object_parameter(
                function,
                kItemInputNames,
                std::size(kItemInputNames),
                false,
                true,
                item_name,
                item_failure);
            if (!item_property)
            {
                reason = "FocusItem unique object input unavailable: " +
                         item_failure + "; params={" +
                         describe_reflected_function_parameters(function) +
                         "}";
                return false;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(params_size), 0);
            if (!safe_set_reflected_object(
                    item_property, params.data(), item))
            {
                reason = "FocusItem failed to write object input " +
                         item_name;
                return false;
            }
            if (!safe_process_event(list_impl, function, params.data()))
            {
                reason = "BP_MainMenuListImpl.FocusItem(object) "
                         "ProcessEvent failed";
                return false;
            }
            reason = "called FocusItem(" + item_name + "=<GetItem item>)";
            return true;
        }

        static bool call_main_menu_list_focus_item_integer(
            RC::Unreal::UObject* list_impl,
            int32_t index,
            bool require_item_output,
            RC::Unreal::UObject*& out_item,
            std::string& reason) noexcept
        {
            out_item = nullptr;
            reason.clear();
            RC::Unreal::UFunction* function =
                safe_get_function_by_name_in_chain(list_impl, L"FocusItem");
            int32_t params_size = 0;
            if (!reflected_function_params_size(
                    function, "BP_MainMenuListImpl.FocusItem",
                    params_size, reason))
            {
                return false;
            }
            static constexpr const wchar_t* kIndexNames[] = {
                L"InIndex", L"Index", L"SelectedIndex", L"InFocusIndex"};
            static constexpr const wchar_t* kItemOutputNames[] = {
                L"FocusItem", L"Item", L"MainMenuListItem", L"ReturnValue"};
            std::string index_name;
            std::string index_failure;
            auto* index_property = resolve_reflected_integer_input(
                function,
                kIndexNames,
                std::size(kIndexNames),
                false,
                index_name,
                index_failure);
            std::string item_name;
            std::string item_failure;
            auto* item_property = resolve_reflected_object_parameter(
                function,
                kItemOutputNames,
                std::size(kItemOutputNames),
                true,
                false,
                item_name,
                item_failure);
            RC::Unreal::FBoolProperty* initialize_property = nullptr;
            const wchar_t* initialize_name = nullptr;
            static constexpr const wchar_t* kInitializeNames[] = {
                L"Initialize", L"bInitialize"};
            for (const wchar_t* candidate_name : kInitializeNames)
            {
                try
                {
                    auto* raw = function->FindProperty(
                        RC::Unreal::FName(
                            candidate_name, RC::Unreal::FNAME_Find));
                    initialize_property = RC::Unreal::CastField<
                        RC::Unreal::FBoolProperty>(raw);
                    if (initialize_property)
                    {
                        initialize_name = candidate_name;
                        break;
                    }
                }
                catch (...)
                {
                    initialize_property = nullptr;
                }
            }
            if (!index_property || !initialize_property ||
                (require_item_output && !item_property))
            {
                reason = "FocusItem integer signature unsupported: index={" +
                         index_failure + "}; item={" + item_failure +
                         "}; initialize={" +
                         (initialize_property
                              ? std::string("ok")
                              : std::string("missing Initialize bool")) +
                         "}; params={" +
                         describe_reflected_function_parameters(function) +
                         "}";
                return false;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(params_size), 0);
            if (!safe_set_reflected_integer(
                    index_property, params.data(), index))
            {
                reason = "FocusItem failed to write integer input " +
                         index_name;
                return false;
            }
            initialize_property->SetPropertyValueInContainer(
                params.data(), true);
            if (!safe_process_event(list_impl, function, params.data()))
            {
                reason = "BP_MainMenuListImpl.FocusItem(integer) "
                         "ProcessEvent failed";
                return false;
            }
            if (item_property)
                out_item = safe_get_reflected_object(
                    item_property, params.data());
            if (require_item_output && !out_item)
            {
                reason = "FocusItem integer call returned no item via " +
                         item_name;
                return false;
            }
            reason = "called FocusItem(" + index_name + "=" +
                     std::to_string(index) + ", " +
                     (initialize_name == kInitializeNames[0]
                          ? std::string("Initialize")
                          : std::string("bInitialize")) +
                     "=true)";
            if (item_property) reason += " output=" + item_name;
            return true;
        }

        static bool call_main_menu_list_select_index(
            RC::Unreal::UObject* list_impl,
            int32_t index,
            std::string& reason) noexcept
        {
            reason.clear();
            RC::Unreal::UFunction* function =
                safe_get_function_by_name_in_chain(
                    list_impl, L"SelectIndex");
            int32_t params_size = 0;
            if (!reflected_function_params_size(
                    function, "BP_MainMenuListImpl.SelectIndex",
                    params_size, reason))
            {
                return false;
            }
            static constexpr const wchar_t* kIndexNames[] = {
                L"InIndex", L"Index", L"SelectedIndex", L"InFocusIndex"};
            std::string index_name;
            std::string index_failure;
            auto* index_property = resolve_reflected_integer_input(
                function,
                kIndexNames,
                std::size(kIndexNames),
                true,
                index_name,
                index_failure);
            if (!index_property)
            {
                reason = "SelectIndex requires exactly one integer input: " +
                         index_failure + "; params={" +
                         describe_reflected_function_parameters(function) +
                         "}";
                return false;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(params_size), 0);
            if (!safe_set_reflected_integer(
                    index_property, params.data(), index))
            {
                reason = "SelectIndex failed to write integer input " +
                         index_name;
                return false;
            }
            if (!safe_process_event(list_impl, function, params.data()))
            {
                reason = "BP_MainMenuListImpl.SelectIndex ProcessEvent failed";
                return false;
            }
            reason = "called SelectIndex(" + index_name + "=" +
                     std::to_string(index) + ")";
            return true;
        }

        static bool call_main_menu_list_focus_item(
            RC::Unreal::UObject* list_impl,
            int32_t index,
            RC::Unreal::UObject*& out_item,
            std::string& reason) noexcept
        {
            out_item = nullptr;
            reason.clear();
            if (!list_impl)
            {
                reason = "FocusItem source unavailable";
                return false;
            }
            if (index < 0)
            {
                reason = "FocusItem index is negative";
                return false;
            }

            std::string get_item_reason;
            RC::Unreal::UObject* actual_item = nullptr;
            const bool get_item_ok = call_main_menu_list_get_item(
                list_impl, index, actual_item, get_item_reason);
            if (get_item_ok)
            {
                std::string focus_object_reason;
                if (call_main_menu_list_focus_item_object(
                        list_impl, actual_item, focus_object_reason))
                {
                    out_item = actual_item;
                    reason = "resolved actual item={" + get_item_reason +
                             "}; focused by object={" +
                             focus_object_reason + "}";
                    return true;
                }

                RC::Unreal::UObject* ignored_focus_output = nullptr;
                std::string focus_integer_reason;
                if (call_main_menu_list_focus_item_integer(
                        list_impl,
                        index,
                        false,
                        ignored_focus_output,
                        focus_integer_reason))
                {
                    out_item = actual_item;
                    reason = "resolved actual item={" + get_item_reason +
                             "}; focused by integer={" +
                             focus_integer_reason + "}";
                    return true;
                }

                std::string select_reason;
                if (call_main_menu_list_select_index(
                        list_impl, index, select_reason))
                {
                    out_item = actual_item;
                    reason = "resolved actual item={" + get_item_reason +
                             "}; FocusItem object rejected={" +
                             focus_object_reason +
                             "}; FocusItem integer rejected={" +
                             focus_integer_reason +
                             "}; selected by index={" + select_reason + "}";
                    return true;
                }
                reason = "GetItem succeeded but no conservative focus path "
                         "matched: get={" + get_item_reason +
                         "}; focus-object={" + focus_object_reason +
                         "}; focus-integer={" + focus_integer_reason +
                         "}; select-index={" + select_reason + "}";
                return false;
            }

            RC::Unreal::UObject* direct_item = nullptr;
            std::string direct_reason;
            if (call_main_menu_list_focus_item_integer(
                    list_impl,
                    index,
                    true,
                    direct_item,
                    direct_reason))
            {
                out_item = direct_item;
                reason = "GetItem unavailable={" + get_item_reason +
                         "}; direct FocusItem fallback={" +
                         direct_reason + "}";
                return true;
            }
            reason = "unable to resolve actual focused item: GetItem={" +
                     get_item_reason + "}; direct FocusItem={" +
                     direct_reason + "}";
            return false;
        }

        static bool call_main_menu_impl_on_decide(
            RC::Unreal::UObject* main_menu_impl,
            RC::Unreal::UObject* item,
            std::string& reason) noexcept
        {
            reason.clear();
            if (!main_menu_impl)
            {
                reason = "BP_MainMenuImpl unavailable";
                return false;
            }
            if (!item)
            {
                reason = "BP_MainMenuImpl.OnDecide item unavailable";
                return false;
            }

            static constexpr const wchar_t* kFunctionNames[] = {
                L"OnDecide(Item)",
                L"OnDecide",
            };
            static constexpr const char* kFunctionLabels[] = {
                "OnDecide(Item)",
                "OnDecide",
            };
            RC::Unreal::UFunction* function = nullptr;
            RC::Unreal::FObjectPropertyBase* item_property = nullptr;
            const char* function_name = nullptr;
            std::string item_property_name;
            std::string signature_failures;
            int32_t params_size = 0;
            static constexpr const wchar_t* kItemInputNames[] = {
                L"MainMenuListItem", L"Item"};
            for (size_t function_index = 0;
                 function_index < std::size(kFunctionNames);
                 ++function_index)
            {
                RC::Unreal::UFunction* candidate_function =
                    safe_get_function_by_name_in_chain(
                        main_menu_impl,
                        kFunctionNames[function_index]);
                if (!candidate_function) continue;
                std::string candidate_name;
                std::string candidate_failure;
                auto* candidate_object =
                    resolve_reflected_object_parameter(
                        candidate_function,
                        kItemInputNames,
                        std::size(kItemInputNames),
                        false,
                        false,
                        candidate_name,
                        candidate_failure);
                if (!candidate_object)
                {
                    if (!signature_failures.empty())
                        signature_failures += "; ";
                    signature_failures += kFunctionLabels[function_index];
                    signature_failures += "={";
                    signature_failures += candidate_failure;
                    signature_failures += "; params={";
                    signature_failures +=
                        describe_reflected_function_parameters(
                            candidate_function);
                    signature_failures += "}}";
                    continue;
                }
                function = candidate_function;
                item_property = candidate_object;
                function_name = kFunctionLabels[function_index];
                item_property_name = std::move(candidate_name);
                break;
            }
            if (!function || !item_property)
            {
                reason = "BP_MainMenuImpl OnDecide(Item)/OnDecide with "
                         "a unique or named input object param unavailable";
                if (!signature_failures.empty())
                    reason += ": " + signature_failures;
                return false;
            }
            if (!reflected_function_params_size(
                    function,
                    "BP_MainMenuImpl.OnDecide",
                    params_size,
                    reason))
            {
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(params_size), 0);
            if (!safe_set_reflected_object(
                    item_property, params.data(), item))
            {
                reason = "BP_MainMenuImpl.";
                reason += function_name;
                reason += " failed to write object param ";
                reason += item_property_name;
                return false;
            }
            if (!safe_process_event(
                    main_menu_impl, function, params.data()))
            {
                reason = "BP_MainMenuImpl.";
                reason += function_name;
                reason += " ProcessEvent failed";
                return false;
            }

            char item_address[32] {};
            std::snprintf(
                item_address,
                sizeof(item_address),
                "0x%llX",
                static_cast<unsigned long long>(
                    reinterpret_cast<uintptr_t>(item)));
            reason = "called BP_MainMenuImpl.";
            reason += function_name;
            reason += "(";
            reason += item_property_name;
            reason += "=";
            reason += item_address;
            reason += "); async privilege/login flow preserved";
            return true;
        }

        static bool dispatch_main_menu_blueprint_navigation(
            RC::Unreal::UObject* main_menu_impl,
            const MainMenuFocusSnapshot& focus,
            RollbackUiNavigationKey key,
            RC::Unreal::UObject*& out_item,
            std::string& reason) noexcept
        {
            out_item = nullptr;
            reason.clear();
            if (!focus.ok || !focus.function_backed ||
                !focus.live_dispatchable ||
                focus.source_object == 0)
            {
                reason = "semantic main-menu dispatch requires a "
                         "same-pass live TargetList/UIWidgetImpl focus "
                         "snapshot";
                return false;
            }
            if (!focus.menu_index_ok || focus.menu_index < 0)
            {
                reason = "semantic main-menu dispatch requires a valid "
                         "nonnegative menu index";
                return false;
            }

            int32_t target_index = focus.menu_index;
            const char* action_name = nullptr;
            const wchar_t* target_menu_id = nullptr;
            switch (key)
            {
            case RollbackUiNavigationKey::Up:
                if (target_index == 0)
                {
                    reason = "semantic Up would move before index zero";
                    return false;
                }
                --target_index;
                action_name = "Up";
                break;
            case RollbackUiNavigationKey::Down:
                if (target_index == INT32_MAX)
                {
                    reason = "semantic Down index overflow";
                    return false;
                }
                ++target_index;
                action_name = "Down";
                break;
            case RollbackUiNavigationKey::FocusNetwork:
                target_menu_id = L"ENETWORK";
                action_name = "FocusNetwork";
                break;
            case RollbackUiNavigationKey::FocusPlayerMatch:
                target_menu_id = L"EPLAYERMATCH";
                action_name = "FocusPlayerMatch";
                break;
            case RollbackUiNavigationKey::Decide:
                action_name = "Decide";
                break;
            default:
                reason = "semantic Blueprint dispatch supports only "
                         "Up/Down/Decide";
                return false;
            }

            auto* list_impl = reinterpret_cast<RC::Unreal::UObject*>(
                focus.source_object);
            std::string index_reason;
            if (target_menu_id &&
                !call_main_menu_list_get_index_from_menu_id(
                    list_impl, target_menu_id, target_index, index_reason))
            {
                reason = "semantic ";
                reason += action_name;
                reason += " failed: ";
                reason += index_reason;
                return false;
            }
            std::string focus_reason;
            if (!call_main_menu_list_focus_item(
                    list_impl, target_index, out_item, focus_reason))
            {
                reason = "semantic ";
                reason += action_name;
                reason += " failed: ";
                reason += focus_reason;
                return false;
            }
            if (key != RollbackUiNavigationKey::Decide)
            {
                reason = "semantic ";
                reason += action_name;
                reason += " accepted: ";
                if (!index_reason.empty())
                {
                    reason += index_reason;
                    reason += "; ";
                }
                reason += focus_reason;
                return true;
            }

            std::string decide_reason;
            if (!call_main_menu_impl_on_decide(
                    main_menu_impl, out_item, decide_reason))
            {
                reason = "semantic Decide focused current item but OnDecide "
                         "failed: focus={";
                reason += focus_reason;
                reason += "}; decide={";
                reason += decide_reason;
                reason += "}";
                return false;
            }
            reason = "semantic Decide accepted: focus={";
            reason += focus_reason;
            reason += "}; decide={";
            reason += decide_reason;
            reason += "}";
            return true;
        }

        static bool read_main_menu_text_property_from_valid_source(
            RC::Unreal::UObject* source,
            const wchar_t* property_name,
            std::string& out) noexcept
        {
            out.clear();
            if (!source || !property_name) return false;
            try
            {
                RC::Unreal::FProperty* raw =
                    source->GetPropertyByNameInChain(property_name);
                if (auto* string_property = RC::Unreal::CastField<
                        RC::Unreal::FStrProperty>(raw))
                {
                    auto* value = string_property->ContainerPtrToValuePtr<
                        RC::Unreal::FString>(source);
                    if (!value) return false;
                    out = fstring_to_utf8(*value);
                    return true;
                }
                if (auto* name_property = RC::Unreal::CastField<
                        RC::Unreal::FNameProperty>(raw))
                {
                    auto* value = name_property->ContainerPtrToValuePtr<
                        RC::Unreal::FName>(source);
                    if (!value) return false;
                    out = narrow_rc_string(value->ToString());
                    return true;
                }
            }
            catch (...)
            {
            }
            return false;
        }

        static bool read_main_menu_int_property_from_valid_source(
            RC::Unreal::UObject* source,
            const wchar_t* property_name,
            int32_t& out) noexcept
        {
            out = -1;
            if (!source || !property_name) return false;
            try
            {
                RC::Unreal::FProperty* raw =
                    source->GetPropertyByNameInChain(property_name);
                auto* numeric_property = RC::Unreal::CastField<
                    RC::Unreal::FNumericProperty>(raw);
                if (!numeric_property || !numeric_property->IsInteger())
                    return false;
                void* value = numeric_property->ContainerPtrToValuePtr<void>(
                    source);
                if (!value) return false;
                const int64_t signed_value =
                    numeric_property->GetSignedIntPropertyValue(value);
                if (signed_value < INT32_MIN || signed_value > INT32_MAX)
                    return false;
                out = static_cast<int32_t>(signed_value);
                return true;
            }
            catch (...)
            {
                return false;
            }
        }

        static void populate_main_menu_focus_source_identity(
            RC::Unreal::UObject* source,
            MainMenuFocusSnapshot& sample) noexcept
        {
            if (!source) return;
            try
            {
                sample.source_object_name = narrow_rc_string(
                    source->GetName());
                RC::Unreal::UClass* source_class =
                    source->GetClassPrivate();
                if (source_class)
                {
                    sample.source_class_name = narrow_rc_string(
                        static_cast<RC::Unreal::UObject*>(
                            source_class)->GetName());
                }
            }
            catch (...)
            {
            }
        }

        static bool query_main_menu_focus_from_valid_source(
            RC::Unreal::UObject* source,
            const char* source_name,
            MainMenuFocusSnapshot& out) noexcept
        {
            if (!source) return false;
            MainMenuFocusSnapshot sample {};
            sample.attempted = true;
            sample.function_backed = true;
            sample.source_object = reinterpret_cast<uintptr_t>(source);
            sample.source = source_name ? source_name : "unknown";
            std::string id_failure;
            std::string index_failure;
            sample.menu_id_ok = call_main_menu_text_query_from_valid_source(
                source,
                L"GetCurrentItemMenuID",
                L"MenuID",
                sample.menu_id,
                id_failure);
            sample.menu_index_ok = call_main_menu_int_query_from_valid_source(
                source,
                L"GetCurrentItemMenuIndex",
                L"MenuIndex",
                sample.menu_index,
                index_failure);
            sample.ok = sample.menu_id_ok || sample.menu_index_ok;
            if (sample.ok)
            {
                populate_main_menu_focus_source_identity(source, sample);
                sample.failure = "ok";
                out = std::move(sample);
                return true;
            }
            sample.failure = "id=" + id_failure + ";index=" + index_failure;
            out = std::move(sample);
            return false;
        }

        bool sample_main_menu_focus(
            RC::Unreal::UObject* ref_main_menu,
            RC::Unreal::UObject* main_menu_widget,
            RC::Unreal::UObject* main_menu_impl,
            MainMenuFocusSnapshot& out) noexcept
        {
            out = MainMenuFocusSnapshot {};
            out.attempted = true;

            RC::Unreal::UObject* impl = nullptr;
            if (main_menu_impl)
            {
                impl = main_menu_impl;
            }
            else if (main_menu_widget)
            {
                impl = reflected_object_property_from_valid_owner(
                    main_menu_widget, L"UIWidgetImpl");
            }
            if (!impl && ref_main_menu)
            {
                impl = reflected_object_property_from_valid_owner(
                    ref_main_menu, L"UIWidgetImpl");
            }
            if (!impl)
            {
                out.failure = "BP_MainMenuImpl-unavailable";
                return false;
            }

            const uintptr_t impl_address =
                reinterpret_cast<uintptr_t>(impl);
            if (m_main_menu_focus_cached_owner != impl_address)
            {
                m_main_menu_focus_cached_owner = impl_address;
                m_main_menu_focus_cached_source = 0;
                m_main_menu_focus_cached_tick = 0;
                m_main_menu_focus_cached_source_name.clear();
            }

            auto query_list_object =
                [&](RC::Unreal::UObject* list,
                    const char* source_name,
                    bool current_target_list) noexcept -> bool
            {
                if (!list) return false;
                if (query_main_menu_focus_from_valid_source(
                        list, source_name, out))
                {
                    out.live_dispatchable = current_target_list &&
                        out.source_class_name ==
                            "BP_MainMenuListImpl_C";
                    m_main_menu_focus_cached_source =
                        reinterpret_cast<uintptr_t>(list);
                    m_main_menu_focus_cached_tick = m_online_nav_attempts;
                    m_main_menu_focus_cached_source_name = source_name;
                    return true;
                }
                RC::Unreal::UObject* list_impl =
                    reflected_object_property_from_valid_owner(
                        list, L"UIWidgetImpl");
                if (!list_impl) return false;
                std::string impl_source = source_name;
                impl_source += ".UIWidgetImpl";
                if (!query_main_menu_focus_from_valid_source(
                        list_impl, impl_source.c_str(), out))
                {
                    return false;
                }
                out.live_dispatchable = current_target_list &&
                    out.source_class_name == "BP_MainMenuListImpl_C";
                m_main_menu_focus_cached_source =
                    reinterpret_cast<uintptr_t>(list_impl);
                m_main_menu_focus_cached_tick = m_online_nav_attempts;
                m_main_menu_focus_cached_source_name = std::move(impl_source);
                return true;
            };

            RC::Unreal::UObject* sub_list =
                reflected_object_property_from_valid_owner(
                    impl, L"SubList");
            if (!sub_list && main_menu_widget)
            {
                sub_list = reflected_object_property_from_valid_owner(
                    main_menu_widget, L"SubList");
            }
            if (!sub_list && ref_main_menu &&
                ref_main_menu != main_menu_widget)
            {
                sub_list = reflected_object_property_from_valid_owner(
                    ref_main_menu, L"SubList");
            }
            RC::Unreal::UObject* main_list =
                reflected_object_property_from_valid_owner(
                    impl, L"MainList");
            if (!main_list && main_menu_widget)
            {
                main_list = reflected_object_property_from_valid_owner(
                    main_menu_widget, L"MainList");
            }
            if (!main_list && ref_main_menu &&
                ref_main_menu != main_menu_widget)
            {
                main_list = reflected_object_property_from_valid_owner(
                    ref_main_menu, L"MainList");
            }
            m_main_menu_focus_sub_list_object =
                reinterpret_cast<uintptr_t>(sub_list);
            m_main_menu_focus_main_list_object =
                reinterpret_cast<uintptr_t>(main_list);

            // OpenSubMenu does not reliably replace the reflected
            // TargetList interface on this build even though the visible
            // hierarchy and SubList focus have changed.  Promote SubList to
            // the semantic dispatch source only after the one-shot Network
            // Decide is pending and a live, function-backed child selection
            // is independently observable.  Once promoted, keep every
            // remaining command bound to that same child list.
            const bool awaiting_network_hierarchy_commit =
                m_main_menu_navigation_driver.state() ==
                    RollbackUiNavigationState::AwaitingAcknowledgement &&
                m_main_menu_navigation_driver.current_key() ==
                    RollbackUiNavigationKey::Decide &&
                m_main_menu_navigation_driver.step_index() == 1 &&
                m_main_menu_navigation_driver.pending_action_observed();
            if (m_main_menu_semantic_submenu_active ||
                awaiting_network_hierarchy_commit)
            {
                if (query_list_object(
                        sub_list,
                        "BP_MainMenuImpl.SubList",
                        true))
                {
                    m_main_menu_sub_list_probe = out;
                    const bool proven_child_selection =
                        out.menu_id_ok &&
                        !out.menu_id.empty() &&
                        !ascii_iequals(
                            out.menu_id, "ENETWORK");
                    if (m_main_menu_semantic_submenu_active ||
                        proven_child_selection)
                    {
                        m_main_menu_semantic_submenu_active = true;
                        return true;
                    }
                }

                // Do not fall back to the stale root selection while waiting
                // for the independently observable hierarchy transition.
                if (awaiting_network_hierarchy_commit)
                {
                    if (!sub_list)
                    {
                        m_main_menu_sub_list_probe =
                            MainMenuFocusSnapshot {};
                        m_main_menu_sub_list_probe.attempted = true;
                        m_main_menu_sub_list_probe.failure =
                            "SubList object unavailable";
                    }
                    else if (!m_main_menu_sub_list_probe.attempted)
                    {
                        m_main_menu_sub_list_probe = out;
                    }
                    out.failure =
                        "Network submenu transition not yet observable";
                    return false;
                }
            }

            // BP_MainMenuImpl_C exposes the active list through TargetList.
            // The cooked BP_MainMenuListImpl_C asset proves the getter names
            // and their MenuID/MenuIndex output names.
            RC::Unreal::UObject* target_list =
                reflected_object_property_from_valid_owner(
                    impl, L"TargetList");
            m_main_menu_focus_target_list_object =
                reinterpret_cast<uintptr_t>(target_list);
            if (target_list && query_list_object(
                    target_list, "BP_MainMenuImpl.TargetList", true))
            {
                return true;
            }
            // TargetList is allowed to be temporarily null during the
            // Blueprint's focus animation. Reuse the last proven list only
            // for that gap. The SEH-guarded reflected getter lookup rejects a
            // stale cached pointer without paying UObject::IsReal's full
            // object-array scan on every sample.
            const uint64_t cached_focus_age =
                m_online_nav_attempts - m_main_menu_focus_cached_tick;
            if (!target_list && m_main_menu_focus_cached_source != 0 &&
                (m_main_menu_focus_cached_tick == 0 ||
                 cached_focus_age > 120))
            {
                m_main_menu_focus_cached_source = 0;
                m_main_menu_focus_cached_tick = 0;
                m_main_menu_focus_cached_source_name.clear();
            }
            if (!target_list && m_main_menu_focus_cached_source != 0 &&
                m_main_menu_focus_cached_tick != 0 &&
                cached_focus_age <= 120)
            {
                auto* cached = reinterpret_cast<RC::Unreal::UObject*>(
                    m_main_menu_focus_cached_source);
                if (query_main_menu_focus_from_valid_source(
                        cached,
                        m_main_menu_focus_cached_source_name.c_str(),
                        out))
                {
                    return true;
                }
                m_main_menu_focus_cached_source = 0;
                m_main_menu_focus_cached_tick = 0;
                m_main_menu_focus_cached_source_name.clear();
            }

            // The parent Blueprint also persists the logical root/submenu
            // position. This is a read-only fallback while TargetList is not
            // installed during a focus animation.
            MainMenuFocusSnapshot property_sample {};
            property_sample.attempted = true;
            property_sample.function_backed = false;
            property_sample.source_object = impl_address;
            property_sample.source = "BP_MainMenuImpl.state-properties";
            populate_main_menu_focus_source_identity(impl, property_sample);
            property_sample.menu_id_ok =
                read_main_menu_text_property_from_valid_source(
                    impl, L"MainListMenuID", property_sample.menu_id);
            property_sample.menu_index_ok =
                read_main_menu_int_property_from_valid_source(
                    impl, L"SubListMenuIndex", property_sample.menu_index);
            property_sample.ok = property_sample.menu_id_ok ||
                                 property_sample.menu_index_ok;
            property_sample.failure = property_sample.ok
                ? "ok"
                : "MainListMenuID/SubListMenuIndex-unavailable";
            if (property_sample.ok)
            {
                out = std::move(property_sample);
                return true;
            }

            // Diagnostic fallbacks for builds where TargetList is not
            // reflected as an object/interface property.
            if (query_list_object(
                    sub_list, "BP_MainMenuImpl.SubList", false) ||
                query_list_object(
                    main_list, "BP_MainMenuImpl.MainList", false))
            {
                return true;
            }
            out.failure = "active-main-menu-list-focus-unavailable";
            return false;
        }

        static bool main_menu_focus_changed(
            const MainMenuFocusSnapshot& before,
            const MainMenuFocusSnapshot& after) noexcept
        {
            if (!before.ok || !after.ok) return false;
            const bool comparable_id =
                before.menu_id_ok && after.menu_id_ok;
            const bool comparable_index =
                before.menu_index_ok && after.menu_index_ok;
            return (comparable_id && before.menu_id != after.menu_id) ||
                   (comparable_index &&
                    before.menu_index != after.menu_index) ||
                   (before.function_backed && after.function_backed &&
                    before.source_object != 0 && after.source_object != 0 &&
                     before.source_object != after.source_object);
        }

        static bool main_menu_hierarchy_changed(
            const MainMenuFocusSnapshot& before,
            const MainMenuFocusSnapshot& after) noexcept
        {
            if (!before.ok || !after.ok) return false;
            if (before.function_backed && after.function_backed &&
                before.source_object != 0 && after.source_object != 0 &&
                before.source_object != after.source_object)
            {
                return true;
            }
            // Some builds reuse the list implementation and replace its data
            // in place. Leaving the ENETWORK row for a function-backed child
            // row is the equivalent semantic hierarchy proof.
            return before.function_backed && after.function_backed &&
                   before.menu_id_ok && after.menu_id_ok &&
                   ascii_iequals(before.menu_id, "ENETWORK") &&
                   !ascii_iequals(after.menu_id, "ENETWORK");
        }

        static bool copy_find_result_snapshot(
            std::vector<uint8_t>& out,
            int32_t& count,
            int32_t& element_size) noexcept
        {
            std::lock_guard<std::mutex> lock(s_find_result_snapshot_mutex);
            count = s_find_result_snapshot_count;
            element_size = s_find_result_snapshot_element_size;
            if (count <= 0 || element_size <= 0 ||
                s_find_result_snapshot.empty())
            {
                out.clear();
                return false;
            }
            out = s_find_result_snapshot;
            return true;
        }

        static void stop_join_callback_capture(const char* reason) noexcept
        {
            s_join_capture_enabled.store(false, std::memory_order_release);
            if (reason) s_join_callback_failure = reason;
        }

        static void prepare_join_callback_capture(
            RC::Unreal::UObject* session_hub,
            const std::string& session_name,
            int32_t main_user_id) noexcept
        {
            // Install pass-through RNG observation before battle launch so
            // the first round's native srand/warm-up transaction is not
            // missed. The hook stays inactive outside explicit trace windows,
            // but its fixed-size per-thread ledger remains current.
            (void)RngTraceHook::instance().install();
            s_join_callback_requested.store(false, std::memory_order_release);
            s_join_callback_ok.store(false, std::memory_order_release);
            s_join_session_hub.store(
                reinterpret_cast<uintptr_t>(session_hub),
                std::memory_order_release);
            s_join_main_user_id.store(main_user_id, std::memory_order_release);
            s_join_callback_failure = "waiting-for-find-callback";
            s_join_session_name = session_name;
            s_session_trace_enabled.store(true, std::memory_order_release);
            s_join_capture_enabled.store(true, std::memory_order_release);
        }

        void sync_session_callback_state() noexcept
        {
            m_create_callback_seen =
                s_create_callback_seen.load(std::memory_order_acquire);
            m_create_callback_result =
                s_create_callback_result.load(std::memory_order_acquire);
            m_destroy_callback_seen =
                s_destroy_callback_seen.load(std::memory_order_acquire);
            m_destroy_callback_result =
                s_destroy_callback_result.load(std::memory_order_acquire);
            const bool join_complete_observed =
                s_join_complete_seen.load(std::memory_order_acquire);
            if (join_complete_observed)
            {
                m_join_complete_seen = true;
                m_join_complete_result =
                    s_join_complete_result.load(std::memory_order_acquire);
                m_join_complete_result_type =
                    s_join_complete_result_type.load(
                        std::memory_order_acquire);
            }
            m_session_connect_complete_seen =
                s_session_connect_complete_seen.load(
                    std::memory_order_acquire);
            m_session_connect_complete_result =
                s_session_connect_complete_result.load(
                    std::memory_order_acquire);
            m_session_connect_complete_full_member_error =
                s_session_connect_complete_full_member_error.load(
                    std::memory_order_acquire);
            m_session_member_join_seen =
                s_session_member_join_seen.load(std::memory_order_acquire);
            m_session_member_join_count =
                s_session_member_join_count.load(std::memory_order_acquire);
            if (m_session_member_join_seen &&
                m_session_member_join_first_tick == 0)
            {
                m_session_member_join_first_tick =
                    m_last_service_tick == 0 ? 1 : m_last_service_tick;
            }
            m_battle_ready_seen =
                s_battle_ready_seen.load(std::memory_order_acquire);
            m_battle_ready_result =
                s_battle_ready_result.load(std::memory_order_acquire);
            m_battle_ready_true_count =
                s_battle_ready_true_count.load(std::memory_order_acquire);
            m_battle_ready_false_count =
                s_battle_ready_false_count.load(std::memory_order_acquire);
            m_battle_comp_seen =
                s_battle_comp_seen.load(std::memory_order_acquire);
            m_battle_comp_count =
                s_battle_comp_count.load(std::memory_order_acquire);
            m_find_callback_seen =
                s_find_callback_seen.load(std::memory_order_acquire);
            m_find_callback_result =
                s_find_callback_result.load(std::memory_order_acquire);
            m_find_result_count =
                s_find_result_count.load(std::memory_order_acquire);
            m_find_result_element_size =
                s_find_result_element_size.load(std::memory_order_acquire);
            m_join_callback_requested = m_join_callback_requested ||
                s_join_callback_requested.load(std::memory_order_acquire);
            m_join_request_ok = m_join_request_ok ||
                s_join_callback_ok.load(std::memory_order_acquire);
            if (!m_guest_adopted_existing_session)
                m_join_callback_failure = s_join_callback_failure;
        }

        void sync_join_callback_state() noexcept
        {
            sync_session_callback_state();
        }

        static bool function_name_is(
            RC::Unreal::UFunction* function,
            const RC::StringType& expected) noexcept
        {
            if (!function) return false;
            try
            {
                return function->GetName() == expected;
            }
            catch (...)
            {
                return false;
            }
        }

        static std::string narrow_rc_string(const RC::StringType& in)
        {
            if constexpr (std::is_same_v<RC::StringType, std::wstring>)
            {
                if (in.empty()) return {};
                const int need = WideCharToMultiByte(
                    CP_UTF8, 0, in.c_str(), static_cast<int>(in.size()),
                    nullptr, 0, nullptr, nullptr);
                if (need <= 0) return {};
                std::string out(static_cast<size_t>(need), '\0');
                WideCharToMultiByte(
                    CP_UTF8, 0, in.c_str(), static_cast<int>(in.size()),
                    out.data(), need, nullptr, nullptr);
                return out;
            }
            else
            {
                return std::string(in.begin(), in.end());
            }
        }

        static RollbackP2PUObjectIdentity describe_uobject(
            RC::Unreal::UObject* obj) noexcept
        {
            RollbackP2PUObjectIdentity info{};
            if (!obj) return info;
            info.object_real = safe_is_real(obj);
            if (!info.object_real) return info;
            try
            {
                info.object_name = narrow_rc_string(obj->GetName());
                RC::Unreal::UClass* cls = obj->GetClassPrivate();
                if (cls && safe_is_real(
                        static_cast<RC::Unreal::UObject*>(cls)))
                {
                    info.class_real = true;
                    info.class_name = narrow_rc_string(
                        static_cast<RC::Unreal::UObject*>(cls)->GetName());
                }
            }
            catch (...)
            {
            }
            return info;
        }

        static void add_uobject_identity_fields(
            ReplayTraceFields& f,
            const char* prefix,
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            const std::string p = prefix ? prefix : "object";
            const std::string name_key = p + "_name";
            const std::string class_key = p + "_class";
            const std::string object_real_key = p + "_object_real";
            const std::string class_real_key = p + "_class_real";
            f.string(name_key.c_str(), info.object_name)
             .string(class_key.c_str(), info.class_name)
             .boolean(object_real_key.c_str(), info.object_real)
             .boolean(class_real_key.c_str(), info.class_real);
        }

        static bool scene_identity_contains(
            const RollbackP2PUObjectIdentity& info,
            const char* needle) noexcept
        {
            if (!needle || !needle[0]) return false;
            return info.class_name.find(needle) != std::string::npos ||
                   info.object_name.find(needle) != std::string::npos;
        }

        static bool is_player_match_lobby_scene(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            return scene_identity_contains(info, "PlayerMatchLobbyScene");
        }

        static bool is_online_player_match_battle_scene(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            return scene_identity_contains(info, "PlayerMatchScene") &&
                   !is_player_match_lobby_scene(info);
        }

        static bool is_direct_online_battle_scene(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            if (is_player_match_lobby_scene(info) ||
                scene_identity_contains(info, "BattleSetup") ||
                scene_identity_contains(info, "Training") ||
                scene_identity_contains(info, "Replay") ||
                scene_identity_contains(info, "MainMenu"))
            {
                return false;
            }
            return scene_identity_contains(info, "BattleScene") ||
                   is_online_player_match_battle_scene(info);
        }

        static void append_limited_name(std::string& out,
                                        const std::string& name,
                                        size_t limit) noexcept
        {
            if (name.empty() || out.size() >= limit) return;
            if (!out.empty() && out.size() + 1 < limit)
                out.push_back(';');
            const size_t remain = limit > out.size()
                ? limit - out.size() - 1
                : 0;
            if (remain == 0) return;
            out.append(name.substr(0, remain));
        }

        static std::string fstring_to_utf8(
            const RC::Unreal::FString& value) noexcept
        {
            const wchar_t* chars = *value;
            const int32_t len = value.Len();
            if (!chars || len <= 0) return {};
            const int need = WideCharToMultiByte(
                CP_UTF8, 0, chars, len, nullptr, 0, nullptr, nullptr);
            if (need <= 0) return {};
            std::string out(static_cast<size_t>(need), '\0');
            WideCharToMultiByte(
                CP_UTF8, 0, chars, len, out.data(), need, nullptr, nullptr);
            return out;
        }

        static std::string describe_function_signature(
            RC::Unreal::UFunction* fn) noexcept
        {
            if (!fn) return {};
            std::string out = narrow_rc_string(fn->GetName());
            out.push_back('(');
            bool first = true;
            try
            {
                for (RC::Unreal::FProperty* prop :
                     RC::Unreal::TFieldRange<RC::Unreal::FProperty>(
                         fn,
                         RC::Unreal::EFieldIterationFlags::
                             IncludeDeprecated))
                {
                    if (!prop) continue;
                    const std::string name = narrow_rc_string(prop->GetName());
                    if (name == "ReturnValue") continue;
                    if (!first) out.push_back(',');
                    first = false;
                    out += name;
                }
            }
            catch (...)
            {
            }
            out.push_back(')');
            return out;
        }

        void emit_scene_reflection_once(
            RC::Unreal::UObject* scene,
            const RollbackP2PUObjectIdentity* cached_identity = nullptr)
            noexcept
        {
            // The common path is an already-emitted scene.  Use the identity
            // captured by the bounded navigator cache to reject it before the
            // two O(GUObjectArray) UObject::IsReal validations below.
            if (cached_identity && !cached_identity->class_name.empty())
            {
                const std::string cached_key =
                    "|" + cached_identity->class_name + "|";
                if (m_scene_reflection_classes.find(cached_key) !=
                    std::string::npos)
                {
                    return;
                }
            }
            if (!safe_is_real(scene))
                return;
            try
            {
                RC::Unreal::UClass* cls = scene->GetClassPrivate();
                if (!cls || !safe_is_real(
                        static_cast<RC::Unreal::UObject*>(cls)))
                {
                    return;
                }
                const std::string scene_class = narrow_rc_string(
                    static_cast<RC::Unreal::UObject*>(cls)->GetName());
                const std::string scene_key = "|" + scene_class + "|";
                if (m_scene_reflection_classes.find(scene_key) !=
                    std::string::npos)
                {
                    return;
                }
                m_scene_reflection_emitted = true;
                m_scene_reflection_classes += scene_key;

                uint32_t function_count = 0;
                uint32_t property_count = 0;
                std::string functions;
                std::string function_signatures;
                std::string properties;
                for (RC::Unreal::UFunction* fn :
                     RC::Unreal::TFieldRange<RC::Unreal::UFunction>(
                         cls, RC::Unreal::EFieldIterationFlags::None))
                {
                    if (!fn) continue;
                    ++function_count;
                    append_limited_name(
                        functions, narrow_rc_string(fn->GetName()), 3500);
                    append_limited_name(
                        function_signatures,
                        describe_function_signature(fn), 6000);
                }
                for (RC::Unreal::FProperty* prop :
                     RC::Unreal::TFieldRange<RC::Unreal::FProperty>(
                         cls,
                         RC::Unreal::EFieldIterationFlags::IncludeDeprecated))
                {
                    if (!prop) continue;
                    ++property_count;
                    append_limited_name(
                        properties, narrow_rc_string(prop->GetName()),
                        3500);
                }

                ReplayTraceFields f;
                f.string("request_id", m_cfg.request_id)
                 .string("client_role", m_cfg.client_role)
                 .string("scene_name", narrow_rc_string(scene->GetName()))
                 .string("scene_class", scene_class)
                 .uinteger("function_count", function_count)
                 .uinteger("property_count", property_count)
                 .string("functions", functions)
                 .string("function_signatures", function_signatures)
                 .string("properties", properties);
                ReplayDebugTrace::instance().event(
                    "rollback_online_stage_scene_reflection", f);
            }
            catch (...)
            {
            }
        }

        static bool safe_get_fstring_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property_name,
            std::string& out) noexcept
        {
            out.clear();
            if (!obj || !property_name) return false;
            __try
            {
                auto* p = obj->GetValuePtrByPropertyNameInChain<
                    RC::Unreal::FString>(property_name);
                if (!p) return false;
                const wchar_t* chars = **p;
                const int32_t len = p->Len();
                if (!chars || len <= 0) return true;
                const int need = WideCharToMultiByte(
                    CP_UTF8, 0, chars, len, nullptr, 0, nullptr, nullptr);
                if (need <= 0) return true;
                out.assign(static_cast<size_t>(need), '\0');
                WideCharToMultiByte(
                    CP_UTF8, 0, chars, len, out.data(), need,
                    nullptr, nullptr);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                out.clear();
                return false;
            }
        }

        static bool safe_set_fstring_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property_name,
            const wchar_t* value) noexcept
        {
            if (!obj || !property_name) return false;
            try
            {
                auto* p = obj->GetValuePtrByPropertyNameInChain<
                    RC::Unreal::FString>(property_name);
                if (!p) return false;
                *p = RC::Unreal::FString(value ? value : L"");
                return true;
            }
            catch (...)
            {
                return false;
            }
        }

        static bool safe_set_int32_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property_name,
            int32_t value) noexcept
        {
            if (!obj || !property_name) return false;
            try
            {
                auto* property = RC::Unreal::CastField<
                    RC::Unreal::FNumericProperty>(
                        obj->GetPropertyByNameInChain(property_name));
                return safe_set_reflected_integer(property, obj, value);
            }
            catch (...)
            {
                return false;
            }
        }

        static bool call_fname_param_function(
            RC::Unreal::UObject* obj,
            const wchar_t* function_name,
            const wchar_t* parameter_name,
            const wchar_t* value,
            std::string& reason) noexcept
        {
            reason.clear();
            if (!safe_is_real(obj))
            {
                reason = "object unavailable";
                return false;
            }
            try
            {
                auto* function = obj->GetFunctionByNameInChain(
                    function_name);
                if (!function)
                {
                    reason = "function unavailable";
                    return false;
                }
                const int32_t param_bytes = function->GetPropertiesSize();
                if (param_bytes <= 0 || param_bytes > 512)
                {
                    reason = "param-size invalid";
                    return false;
                }
                auto* property = RC::Unreal::CastField<
                    RC::Unreal::FNameProperty>(
                        reflected_param(function, parameter_name));
                if (!property)
                {
                    reason = "FName param unavailable";
                    return false;
                }
                std::vector<uint8_t> params(
                    static_cast<size_t>(param_bytes), 0);
                *property->ContainerPtrToValuePtr<RC::Unreal::FName>(
                    params.data()) = RC::Unreal::FName(
                        value ? value : L"", RC::Unreal::FNAME_Add);
                const bool ok = safe_process_event(
                    obj, function, params.data());
                reason = ok ? "ok" : "ProcessEvent failed";
                return ok;
            }
            catch (...)
            {
                reason = "FName call exception";
                return false;
            }
        }

        static bool call_bool_param_function(
            RC::Unreal::UObject* obj,
            const wchar_t* function_name,
            const wchar_t* param_name,
            bool value,
            std::string& reason) noexcept
        {
            if (!safe_is_real(obj))
            {
                reason = "object unavailable";
                return false;
            }
            auto* fn = obj->GetFunctionByNameInChain(function_name);
            if (!fn)
            {
                reason = "function unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 512)
            {
                reason = "param-size invalid";
                return false;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            RC::Unreal::FProperty* param =
                reflected_param(fn, param_name);
            if (!param)
            {
                reason = "bool param unavailable";
                return false;
            }
            try
            {
                if (auto* bool_prop = RC::Unreal::CastField<
                        RC::Unreal::FBoolProperty>(param))
                {
                    bool_prop->SetPropertyValueInContainer(
                        params.data(), value);
                }
                else
                {
                    const int32_t bytes = param->GetSize();
                    void* slot =
                        param->ContainerPtrToValuePtr<void>(params.data());
                    if (!slot || bytes <= 0 || bytes > 4)
                    {
                        reason = "bool param slot invalid";
                        return false;
                    }
                    std::memset(slot, 0, static_cast<size_t>(bytes));
                    *reinterpret_cast<uint8_t*>(slot) = value ? 1 : 0;
                }
                const bool ok = safe_process_event(obj, fn, params.data());
                reason = ok ? "called bool-param function"
                            : "bool-param function failed";
                return ok;
            }
            catch (...)
            {
                reason = "bool-param function threw";
                return false;
            }
        }

        static bool execute_console_command(
            RC::Unreal::UObject* world_context,
            const wchar_t* command,
            std::string& reason)
        {
            reason.clear();
            auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                RC::Unreal::UObject*>(
                    nullptr, nullptr,
                    STR("/Script/Engine.Default__KismetSystemLibrary"));
            if (!safe_is_real(cdo))
            {
                reason = "Default__KismetSystemLibrary unavailable";
                return false;
            }
            auto* fn =
                cdo->GetFunctionByNameInChain(L"ExecuteConsoleCommand");
            if (!fn)
            {
                reason = "KismetSystemLibrary.ExecuteConsoleCommand unavailable";
                return false;
            }

            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 1024)
            {
                reason = "ExecuteConsoleCommand param-size invalid";
                return false;
            }

            RC::Unreal::FProperty* context_prop =
                reflected_param(fn, L"WorldContextObject");
            auto* command_prop = RC::Unreal::CastField<
                RC::Unreal::FStrProperty>(
                    reflected_param(fn, L"Command"));
            RC::Unreal::FProperty* player_prop =
                reflected_param(fn, L"SpecificPlayer");
            if (!context_prop || !command_prop)
            {
                reason = "ExecuteConsoleCommand reflected params unavailable";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            bool command_initialized = false;
            try
            {
                void* context_slot =
                    context_prop->ContainerPtrToValuePtr<void>(
                        params.data());
                if (!context_slot)
                {
                    reason = "ExecuteConsoleCommand context slot unavailable";
                    return false;
                }
                *reinterpret_cast<RC::Unreal::UObject**>(context_slot) =
                    world_context;

                if (player_prop)
                {
                    void* player_slot =
                        player_prop->ContainerPtrToValuePtr<void>(
                            params.data());
                    if (player_slot)
                    {
                        *reinterpret_cast<RC::Unreal::UObject**>(
                            player_slot) = nullptr;
                    }
                }

                command_prop->InitializeValue_InContainer(params.data());
                command_initialized = true;
                command_prop->SetPropertyValueInContainer(
                    params.data(),
                    RC::Unreal::FString(command ? command : L""));

                const bool ok = safe_process_event(cdo, fn, params.data());
                if (command_initialized)
                    command_prop->DestroyValue_InContainer(params.data());
                reason = ok ? "called ExecuteConsoleCommand"
                            : "ExecuteConsoleCommand failed";
                return ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] ExecuteConsoleCommand threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "ExecuteConsoleCommand threw";
            }
            catch (...)
            {
                reason = "ExecuteConsoleCommand threw";
            }

            if (command_initialized)
                command_prop->DestroyValue_InContainer(params.data());
            return false;
        }

        void emit_background_idle_override_trace(
            const char* phase) const noexcept
        {
            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .string("phase", phase ? phase : "")
             .boolean("attempted", m_background_idle_override_attempted)
             .boolean("value_read", m_background_idle_override_value_read)
             .integer("original_value", m_background_idle_original_value)
             .boolean("command_ok", m_background_idle_override_command_ok)
             .boolean("engaged", m_background_idle_override_engaged)
             .boolean("restore_attempted",
                      m_background_idle_override_restore_attempted)
             .boolean("restore_ok", m_background_idle_override_restore_ok)
             .string("failure", m_background_idle_override_failure);
            ReplayDebugTrace::instance().event(
                "rollback_background_idle_override", f);
        }

        bool ensure_background_idle_override(
            RC::Unreal::UObject* world_context) noexcept
        {
            if (m_background_idle_override_attempted)
                return m_background_idle_override_command_ok;

            m_background_idle_override_attempted = true;
            m_background_idle_override_failure = "starting";
            constexpr uintptr_t kRVA_IdleCvarValuePointer = 0x41457C8;
            const uintptr_t image_base = NativeBinding::imageBase();
            void* value_pointer = nullptr;
            int32_t original_value = 0;
            if (!image_base
                || !SafeReadPtr(
                    reinterpret_cast<const void*>(
                        image_base + kRVA_IdleCvarValuePointer),
                    &value_pointer)
                || !value_pointer
                || !SafeReadInt32(value_pointer, &original_value))
            {
                m_background_idle_override_failure =
                    "t.IdleWhenNotForeground value unavailable";
                emit_background_idle_override_trace("engage");
                return false;
            }

            m_background_idle_override_value_read = true;
            m_background_idle_original_value = original_value;
            if (original_value == 0)
            {
                m_background_idle_override_command_ok = true;
                m_background_idle_override_failure = "already-disabled";
                emit_background_idle_override_trace("engage");
                return true;
            }
            if (!safe_is_real(world_context))
            {
                m_background_idle_override_failure =
                    "world-context-unavailable";
                emit_background_idle_override_trace("engage");
                return false;
            }

            std::string reason;
            m_background_idle_override_command_ok = execute_console_command(
                world_context, L"t.IdleWhenNotForeground 0", reason);
            m_background_idle_override_engaged =
                m_background_idle_override_command_ok;
            m_background_idle_override_failure =
                m_background_idle_override_command_ok ? "ok" : reason;
            emit_background_idle_override_trace("engage");
            return m_background_idle_override_command_ok;
        }

        void restore_background_idle_override() noexcept
        {
            if (!m_background_idle_override_engaged
                || !m_background_idle_override_value_read)
            {
                return;
            }

            m_background_idle_override_restore_attempted = true;
            OnlineNavigatorObjects nav = resolve_online_navigator_objects();
            if (!safe_is_real(nav.current_scene))
            {
                m_background_idle_override_failure =
                    "restore-world-context-unavailable";
                emit_background_idle_override_trace("restore");
                return;
            }

            wchar_t command[64] {};
            if (swprintf_s(
                    command,
                    L"t.IdleWhenNotForeground %d",
                    m_background_idle_original_value) <= 0)
            {
                m_background_idle_override_failure =
                    "restore-command-format-failed";
                emit_background_idle_override_trace("restore");
                return;
            }

            std::string reason;
            m_background_idle_override_restore_ok = execute_console_command(
                nav.current_scene, command, reason);
            if (m_background_idle_override_restore_ok)
            {
                m_background_idle_override_engaged = false;
                m_background_idle_override_failure = "restored";
            }
            else
            {
                m_background_idle_override_failure = reason;
            }
            emit_background_idle_override_trace("restore");
        }

        static bool contains_any_substring(
            const std::string& haystack,
            const char* const* needles,
            size_t count) noexcept
        {
            for (size_t i = 0; i < count; ++i)
            {
                const char* needle = needles[i];
                if (needle && needle[0] &&
                    haystack.find(needle) != std::string::npos)
                {
                    return true;
                }
            }
            return false;
        }

        static bool observe_gameflow_relevant_process_event(
            const RollbackP2PUObjectIdentity& context_info,
            const std::string& function_name,
            const std::string& signature) noexcept
        {
            // These two events are the authoritative boundary between a
            // physical UE input key and SC6's semantic menu command.  Keep
            // them visible even when the concrete widget class is a generic
            // LuxCommonWindow_C whose name does not contain one of the
            // gameflow keywords below.
            if (function_name == "OnHandleInput" ||
                function_name == "OnRequestInputCommand")
            {
                return true;
            }
            static constexpr const char* kNeedles[] = {
                "Battle",
                "GameFlow",
                "InRoom",
                "Join",
                "Lobby",
                "MainMenu",
                "Match",
                "Menu",
                "Online",
                "Ping",
                "PlayerMatch",
                "Ready",
                "Room",
                "Search",
                "Session",
                "Signin",
                "Steam",
                "Transition",
                "UIGame",
            };
            const std::string combined =
                context_info.object_name + " " + context_info.class_name +
                " " + function_name + " " + signature;
            if (scene_identity_contains(context_info,
                                        "PlayerMatchSetupScene"))
            {
                static constexpr const char* kSetupNeedles[] = {
                    "Battle",
                    "Begin",
                    "Change",
                    "GameFlow",
                    "Scene",
                    "Start",
                    "Transition",
                };
                return contains_any_substring(
                    combined,
                    kSetupNeedles,
                    sizeof(kSetupNeedles) / sizeof(kSetupNeedles[0]));
            }
            return contains_any_substring(
                combined, kNeedles, sizeof(kNeedles) / sizeof(kNeedles[0]));
        }

        static void append_observe_param_summary(
            std::string& out,
            const char* name,
            const char* value) noexcept
        {
            if (!name || !name[0] || !value || out.size() > 3000)
                return;
            if (!out.empty())
                out += "; ";
            out += name;
            out += "=";
            out += value;
            if (out.size() > 3200)
                out.resize(3200);
        }

        static void append_observe_param_summary(
            std::string& out,
            const char* name,
            const std::string& value) noexcept
        {
            append_observe_param_summary(out, name, value.c_str());
        }

        static std::string summarize_observe_params(
            RC::Unreal::UFunction* function,
            void* params) noexcept
        {
            std::string out;
            if (!function || !params)
                return out;
            try
            {
                for (RC::Unreal::FProperty* prop :
                     RC::Unreal::TFieldRange<RC::Unreal::FProperty>(
                         function,
                         RC::Unreal::EFieldIterationFlags::
                             IncludeDeprecated))
                {
                    if (!prop)
                        continue;
                    const std::string name = narrow_rc_string(
                        prop->GetName());
                    if (name.empty() || name == "ReturnValue")
                        continue;

                    if (auto* str_prop = RC::Unreal::CastField<
                            RC::Unreal::FStrProperty>(prop))
                    {
                        auto* value = str_prop->ContainerPtrToValuePtr<void>(
                            params);
                        RawFStringNative raw {};
                        std::string sample;
                        uint64_t hash = 0;
                        if (value && safe_read_raw_fstring_header(
                                value, raw) &&
                            safe_sample_raw_fstring(
                                raw, 512, sample, hash))
                        {
                            append_observe_param_summary(
                                out, name.c_str(), sample);
                        }
                        continue;
                    }
                    if (auto* name_prop = RC::Unreal::CastField<
                            RC::Unreal::FNameProperty>(prop))
                    {
                        auto* value = name_prop->ContainerPtrToValuePtr<
                            RC::Unreal::FName>(params);
                        RC::Unreal::FName snapshot {};
                        if (value && SafeReadBytes(
                                value, &snapshot, sizeof(snapshot)))
                        {
                            try
                            {
                                append_observe_param_summary(
                                    out,
                                    name.c_str(),
                                    narrow_rc_string(snapshot.ToString()));
                            }
                            catch (...)
                            {
                            }
                        }
                        continue;
                    }
                    if (auto* bool_prop = RC::Unreal::CastField<
                            RC::Unreal::FBoolProperty>(prop))
                    {
                        append_observe_param_summary(
                            out, name.c_str(),
                            bool_prop->GetPropertyValueInContainer(params)
                                ? "true"
                                : "false");
                        continue;
                    }
                    if (auto* num_prop = RC::Unreal::CastField<
                            RC::Unreal::FNumericProperty>(prop))
                    {
                        void* slot =
                            num_prop->ContainerPtrToValuePtr<void>(params);
                        if (!slot)
                            continue;
                        if (num_prop->IsInteger())
                        {
                            append_observe_param_summary(
                                out, name.c_str(),
                                std::to_string(
                                    num_prop->GetSignedIntPropertyValue(
                                        slot)));
                        }
                        else
                        {
                            append_observe_param_summary(
                                out, name.c_str(),
                                std::to_string(
                                    num_prop->GetFloatingPointPropertyValue(
                                        slot)));
                        }
                        continue;
                    }

                    // Never call ExportTextItem from a ProcessEvent post hook.
                    // Some SC6 Blueprint structs contain transient references
                    // that are already invalid by this point. Capture a bounded
                    // byte snapshot instead; it is sufficient for layout and
                    // before/after correlation without executing UE serializers.
                    if (auto* struct_prop = RC::Unreal::CastField<
                            RC::Unreal::FStructProperty>(prop))
                    {
                        void* slot = struct_prop->ContainerPtrToValuePtr<void>(
                            params);
                        const int32_t bytes = struct_prop->GetSize();
                        constexpr size_t kMaxStructCaptureBytes = 64;
                        const size_t capture_bytes = bytes > 0
                            ? (std::min)(
                                static_cast<size_t>(bytes),
                                kMaxStructCaptureBytes)
                            : 0;
                        std::array<uint8_t, kMaxStructCaptureBytes> raw {};
                        if (slot && capture_bytes > 0 && SafeReadBytes(
                                slot, raw.data(), capture_bytes))
                        {
                            std::string struct_name = "struct";
                            try
                            {
                                if (auto* script_struct = RC::Unreal::ToRawPtr(
                                        struct_prop->GetStruct()))
                                {
                                    struct_name = narrow_rc_string(
                                        script_struct->GetName());
                                }
                            }
                            catch (...)
                            {
                            }
                            char header[96] {};
                            std::snprintf(
                                header,
                                sizeof(header),
                                "%s[%d]=",
                                struct_name.c_str(),
                                bytes);
                            std::string value(header);
                            static constexpr char kHex[] =
                                "0123456789ABCDEF";
                            value.reserve(value.size() + capture_bytes * 2);
                            for (size_t i = 0; i < capture_bytes; ++i)
                            {
                                value.push_back(kHex[(raw[i] >> 4) & 0x0f]);
                                value.push_back(kHex[raw[i] & 0x0f]);
                            }
                            if (capture_bytes < static_cast<size_t>(bytes))
                                value += "...";
                            append_observe_param_summary(
                                out, name.c_str(), value);
                        }
                        continue;
                    }

                    const int32_t bytes = prop->GetSize();
                    if (bytes == static_cast<int32_t>(sizeof(void*)))
                    {
                        void* slot =
                            prop->ContainerPtrToValuePtr<void>(params);
                        void* raw = nullptr;
                        if (!slot || !SafeReadPtr(slot, &raw) || !raw)
                            continue;
                        char buf[32] {};
                        std::snprintf(
                            buf, sizeof(buf), "0x%llX",
                            static_cast<unsigned long long>(
                                reinterpret_cast<uintptr_t>(raw)));
                        std::string value(buf);
                        auto* object =
                            reinterpret_cast<RC::Unreal::UObject*>(raw);
                        if (safe_is_real(object))
                        {
                            const RollbackP2PUObjectIdentity info =
                                describe_uobject(object);
                            if (!info.object_name.empty() ||
                                !info.class_name.empty())
                            {
                                value += ":";
                                value += info.class_name;
                                value += "/";
                                value += info.object_name;
                            }
                        }
                        append_observe_param_summary(
                            out, name.c_str(), value);
                    }
                }
            }
            catch (...)
            {
            }
            return out;
        }

        void trace_gameflow_observe_process_event(
            RC::Unreal::UObject* context,
            RC::Unreal::UFunction* function,
            void* params) noexcept
        {
            const bool process_event_diagnostic =
                (m_cfg.observe_gameflow_requested &&
                 m_cfg.observe_gameflow_process_events) ||
                m_cfg.online_stage_diagnostic_reflection;
            if (!m_cfg.enabled || !process_event_diagnostic || !function)
            {
                return;
            }
            if (m_observe_gameflow_process_event_count >=
                kObserveGameflowProcessEventLimit)
            {
                ++m_observe_gameflow_process_event_overflow_count;
                return;
            }
            const std::string function_name =
                narrow_rc_string(function->GetName());
            if (function_name == "ReceiveTick" ||
                function_name == "Tick" ||
                function_name == "IsReadyToStart" ||
                function_name == "IsEnableChangeScene" ||
                function_name == "ReadyToEndMatch" ||
                function_name == "OnRequestChangePhase" ||
                function_name == "OnRequestPlayVoice")
            {
                return;
            }
            const RollbackP2PUObjectIdentity context_info =
                describe_uobject(context);
            const std::string signature =
                describe_function_signature(function);
            if (!observe_gameflow_relevant_process_event(
                    context_info, function_name, signature))
            {
                return;
            }
            const uint64_t index = ++m_observe_gameflow_process_event_count;
            if (index > kObserveGameflowProcessEventLimit)
                return;

            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("index", index)
             .string("function", function_name)
             .string("function_signature", signature)
             .string("params_summary",
                     summarize_observe_params(function, params))
             .hex("context", reinterpret_cast<uintptr_t>(context))
             .hex("function_ptr", reinterpret_cast<uintptr_t>(function));
            add_uobject_identity_fields(f, "context", context_info);
            ReplayDebugTrace::instance().event(
                "rollback_gameflow_observe_process_event", f);
        }

        static bool name_contains_any_session_word(
            const RC::StringType& name) noexcept
        {
            return name.find(STR("Session")) != RC::StringType::npos
                || name.find(STR("Lobby")) != RC::StringType::npos
                || name.find(STR("Find")) != RC::StringType::npos
                || name.find(STR("Join")) != RC::StringType::npos
                || name.find(STR("Match")) != RC::StringType::npos
                || name.find(STR("Search")) != RC::StringType::npos
                || name.find(STR("Ready")) != RC::StringType::npos;
        }

