        static void set_session_trace_identity(
            const RollbackP2PHarnessConfig& cfg) noexcept
        {
            std::lock_guard<std::mutex> lock(s_session_trace_identity_mutex);
            s_session_trace_request_id = cfg.request_id;
            s_session_trace_client_role = cfg.client_role;
            s_session_trace_native_session_name = cfg.native_session_name;
            s_session_trace_session_name = cfg.session_name;
            s_session_trace_room_name = cfg.room_name;
        }

        static void add_session_trace_identity(
            ReplayTraceFields& f) noexcept
        {
            LARGE_INTEGER qpc {};
            (void)QueryPerformanceCounter(&qpc);
            std::lock_guard<std::mutex> lock(s_session_trace_identity_mutex);
            f.integer("qpc", qpc.QuadPart)
             .uinteger("thread_id", GetCurrentThreadId())
             .string("request_id", s_session_trace_request_id)
             .string("client_role", s_session_trace_client_role)
             .string("native_session_name",
                     s_session_trace_native_session_name)
             .string("session_name", s_session_trace_session_name)
             .string("room_name", s_session_trace_room_name);
        }

        static bool session_trace_client_role_is(
            const char* expected_role) noexcept
        {
            if (!expected_role)
                return false;
            std::lock_guard<std::mutex> lock(s_session_trace_identity_mutex);
            return s_session_trace_client_role == expected_role;
        }

