        static void emit_ready_open_snapshot(
            const char* event_name,
            const char* phase,
            uint64_t caller_rva,
            const LuxorReadyOpenSnapshot& snapshot) noexcept
        {
            if (!s_session_trace_enabled.load(std::memory_order_acquire))
                return;
            ReplayTraceFields f;
            add_session_trace_identity(f);
            f.string("phase", phase ? phase : "")
             .hex("caller_rva", caller_rva)
             .hex("session_connection", snapshot.session_connection)
             .hex("session_registry", snapshot.session_registry)
             .hex("session_registry_vtable",
                  snapshot.session_registry_vtable)
             .hex("async_queue_head", snapshot.async_queue_head)
             .uinteger("async_queue_count",
                       snapshot.async_queue_count)
             .uinteger("session_registry_tick",
                       snapshot.session_registry_tick)
             .uinteger("session_registry_count",
                       snapshot.session_registry_count)
             .uinteger("session_registry_capacity",
                       snapshot.session_registry_capacity)
             .uinteger("session_registry_status",
                       snapshot.session_registry_status)
             .uinteger("session_registry_ready",
                       snapshot.session_registry_ready)
             .uinteger("session_registry_is_host",
                       snapshot.session_registry_is_host)
             .hex("transport", snapshot.transport)
             .uinteger("transport_tick", snapshot.transport_tick)
             .uinteger("transport_status", snapshot.transport_status)
             .uinteger("transport_ready", snapshot.transport_ready)
             .uinteger("transport_is_host", snapshot.transport_is_host)
             .hex("ready_channel", snapshot.ready_channel)
             .hex("ready_channel_raw_48",
                  snapshot.ready_channel_raw_48)
             .uinteger("ready_channel_state_48",
                       snapshot.ready_channel_state_48)
             .uinteger("ready_channel_byte_49",
                       snapshot.ready_channel_byte_49)
             .uinteger("ready_channel_byte_4a",
                       snapshot.ready_channel_byte_4a)
             .uinteger("ready_channel_can_send_4c",
                       snapshot.ready_channel_can_send_4c);
            ReplayDebugTrace::instance().event(event_name, f);
        }

