            {
                result = original(
                    route_service,
                    out_writer_owner,
                    native_route_source,
                    use_routing_tag_object);
            }

            void* out_owner = nullptr;
            void* out_owner_ref = nullptr;
            sample_lux_shared_object_pair(
                out_writer_owner, out_owner, out_owner_ref);
            void* selected_writer = nullptr;
            if (out_owner)
            {
                selected_writer =
                    static_cast<uint8_t*>(out_owner) +
                    kLuxorRouteWriterSubobjectOff;
            }
            const LuxorRouteWriterRegistrySnapshot registry =
                sample_luxor_route_service_writer_registry(
                    route_service, selected_writer);
            const LuxorRouteIdentitySnapshot source_identity =
                sample_luxor_route_identity(native_route_source);

