        static void* resolve_connect_sender_for_trace() noexcept
        {
            const uintptr_t addr = native_address(kRVA_ResolveConnectSender);
            if (!addr)
                return nullptr;
            __try
            {
                return reinterpret_cast<ResolveConnectObjectFn>(addr)();
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return nullptr;
            }
        }

        static void* resolve_current_active_connect_for_trace() noexcept
        {
            const uintptr_t addr =
                native_address(kRVA_GetLuxorConnectManagerSingleton);
            if (!addr)
                return nullptr;
            void* manager = nullptr;
            __try
            {
                manager =
                    reinterpret_cast<GetLuxorConnectManagerSingletonFn>(
                        addr)();
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return nullptr;
            }
            if (!manager)
                return nullptr;
            void* active_connect = nullptr;
            if (!SafeReadPtr(
                    static_cast<const uint8_t*>(manager) + 0x60,
                    &active_connect))
            {
                return nullptr;
            }
            return active_connect;
        }

        static void store_active_opcode6_send_snapshot(
            const LuxorActiveOpcodeSnapshot& snapshot) noexcept
        {
            s_active_opcode6_send_last_active_state.store(
                snapshot.active_state, std::memory_order_release);
            s_active_opcode6_send_last_active_sub_state.store(
                snapshot.active_sub_state, std::memory_order_release);
            s_active_opcode6_send_last_transport_tick.store(
                snapshot.transport_tick, std::memory_order_release);
            s_active_opcode6_send_last_transport_status.store(
                snapshot.transport_status, std::memory_order_release);
            s_active_opcode6_send_last_transport_ready.store(
                snapshot.transport_ready, std::memory_order_release);
            s_active_opcode6_send_last_transport_is_host.store(
                snapshot.transport_is_host, std::memory_order_release);
            s_active_opcode6_send_last_transport_channel_count.store(
                snapshot.transport_channel_count,
                std::memory_order_release);
            s_active_opcode6_send_last_transport_channel_capacity.store(
                snapshot.transport_channel_capacity,
                std::memory_order_release);
        }

        static void emit_active_opcode6_send_trace(
            const char* phase,
            uint64_t caller_rva,
            uintptr_t sender,
            uintptr_t sender_vtable,
            uint32_t state_payload,
            uint64_t result,
            const LuxorActiveOpcodeSnapshot& snapshot) noexcept
        {
            if (!s_session_trace_enabled.load(std::memory_order_acquire))
                return;
            ReplayTraceFields f;
            add_session_trace_identity(f);
            f.string("phase", phase ? phase : "")
             .hex("caller_rva", caller_rva)
             .hex("active_connect", snapshot.active_connect)
             .hex("sender", sender)
             .hex("sender_vtable", sender_vtable)
             .uinteger("outer_opcode", 6)
             .uinteger("state_payload", state_payload)
             .uinteger("result", result)
             .uinteger("active_state", snapshot.active_state)
             .uinteger("active_sub_state", snapshot.active_sub_state)
             .uinteger("active_local_user", snapshot.active_local_user)
             .uinteger("active_state_flags", snapshot.active_state_flags)
             .hex("transport", snapshot.transport)
             .uinteger("transport_tick", snapshot.transport_tick)
             .uinteger("transport_channel_count",
                       snapshot.transport_channel_count)
             .uinteger("transport_channel_capacity",
                       snapshot.transport_channel_capacity)
             .uinteger("transport_status", snapshot.transport_status)
             .uinteger("transport_ready", snapshot.transport_ready)
             .uinteger("transport_is_host", snapshot.transport_is_host);
            ReplayDebugTrace::instance().event(
                "rollback_luxor_active_opcode6_send", f);
        }

        static uint8_t luxor_active_opcode6_send_detour(
            void* active_connect,
            const uint8_t* state_payload)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            uint8_t payload_value = 0xffu;
            if (state_payload)
                (void)SafeReadUInt8(state_payload, &payload_value);

            void* sender = nullptr;
            void* sender_vtable = nullptr;
            if (active_connect)
            {
                sender = static_cast<uint8_t*>(active_connect) + 0x20;
                (void)SafeReadPtr(sender, &sender_vtable);
            }
            const LuxorActiveOpcodeSnapshot before =
                sample_active_opcode_snapshot(active_connect, nullptr);
            emit_active_opcode6_send_trace(
                "before-original", caller_rva,
                reinterpret_cast<uintptr_t>(sender),
                reinterpret_cast<uintptr_t>(sender_vtable),
                payload_value, 0xffffffffffffffffull, before);

            uint8_t result = 0;
            auto* original =
                reinterpret_cast<SendLuxorActiveConnectOpcode6Fn>(
                    s_active_opcode6_send_trampoline);
            if (original)
                result = original(active_connect, state_payload);

            const LuxorActiveOpcodeSnapshot after =
                sample_active_opcode_snapshot(active_connect, nullptr);
            s_active_opcode6_send_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_active_opcode6_send_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            s_active_opcode6_send_last_active.store(
                reinterpret_cast<uintptr_t>(active_connect),
                std::memory_order_release);
            s_active_opcode6_send_last_sender.store(
                reinterpret_cast<uintptr_t>(sender),
                std::memory_order_release);
            s_active_opcode6_send_last_sender_vtable.store(
                reinterpret_cast<uintptr_t>(sender_vtable),
                std::memory_order_release);
            s_active_opcode6_send_last_state_payload.store(
                payload_value, std::memory_order_release);
            s_active_opcode6_send_last_result.store(
                result, std::memory_order_release);
            store_active_opcode6_send_snapshot(after);
            emit_active_opcode6_send_trace(
                "after-original", caller_rva,
                reinterpret_cast<uintptr_t>(sender),
                reinterpret_cast<uintptr_t>(sender_vtable),
                payload_value, result, after);
            return result;
        }

        static bool install_active_endpoint_send_hook_for_target(
            uintptr_t target) noexcept
        {
            if (!target)
                return false;
            if (s_active_endpoint_send_hook_installed.load(
                    std::memory_order_acquire))
            {
                return true;
            }
            bool expected = false;
            if (!s_active_endpoint_send_hook_attempted
                    .compare_exchange_strong(
                        expected, true, std::memory_order_acq_rel))
            {
                return s_active_endpoint_send_hook_installed.load(
                    std::memory_order_acquire);
            }
            if (install_debug_detour(
                    s_active_endpoint_send_detour,
                    target,
                    reinterpret_cast<uint64_t>(
                        &RollbackP2PHarness::
                            connect_sender_endpoint_send_detour),
                    s_active_endpoint_send_trampoline))
            {
                s_active_endpoint_send_hook_target.store(
                    target, std::memory_order_release);
                s_active_endpoint_send_hook_installed.store(
                    true, std::memory_order_release);
                return true;
            }
            return false;
        }

