        static uintptr_t
        canonical_luxor_backend_connection_packet_processor_target(
            uintptr_t target) noexcept
        {
            constexpr uint64_t kPacketProcessorRva = 0x2e0f870ull;
            constexpr uint64_t kPacketProcessorThunkRva = 0x2e10200ull;
            if (native_rva_for_address(target) != kPacketProcessorThunkRva)
                return target;
            const uintptr_t base = NativeBinding::imageBase();
            return base ? base + kPacketProcessorRva : target;
        }

