        static void** luxor_backend_connection_lookup_detour(
            void* connection_map,
            void** connection_out,
            void* destination_key)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            auto* original =
                reinterpret_cast<LuxorBackendConnectionLookupFn>(
                    s_luxor_backend_connection_lookup_trampoline);
            void** result = connection_out;
            if (original)
                result = original(
                    connection_map, connection_out, destination_key);

            void* connection = nullptr;
            void* connection_ref = nullptr;
            if (connection_out)
            {
                (void)SafeReadPtr(connection_out, &connection);
                (void)SafeReadPtr(connection_out + 1, &connection_ref);
            }
            void* connection_vtable = nullptr;
            uintptr_t raw_send_target = 0;
            uint32_t route_selector = 0xffu;
            void* route_channel = nullptr;
            void* lower_transport = nullptr;
            if (connection)
            {
                const auto* const connection_bytes =
                    static_cast<const uint8_t*>(connection);
                (void)SafeReadPtr(connection, &connection_vtable);
                if (read_vtable_target(
                        connection, 0xF0, raw_send_target))
                {
                    (void)
                        install_luxor_backend_connection_raw_send_hook_for_target(
                            raw_send_target);
                }
                (void)SafeReadPtr(
                    connection_bytes + 0x10, &lower_transport);
                read_u8_as_u32(connection_bytes, 0x2600, route_selector);
                if (route_selector != 0xffu && route_selector < 4)
                {
                    route_channel = const_cast<uint8_t*>(
                        connection_bytes + 0x80 + route_selector * 0x48);
                }
            }
            const LuxorRouteIdentitySnapshot destination_key_identity =
                sample_luxor_route_identity(destination_key);
            const LuxorBackendConnectionTableSnapshot table_snapshot =
                sample_luxor_backend_connection_table(
                    connection_map, connection);

            s_luxor_backend_connection_lookup_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_luxor_backend_connection_lookup_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            s_luxor_backend_connection_lookup_last_map.store(
                reinterpret_cast<uintptr_t>(connection_map),
                std::memory_order_release);
            s_luxor_backend_connection_lookup_last_destination_key.store(
                reinterpret_cast<uintptr_t>(destination_key),
                std::memory_order_release);
            s_luxor_backend_connection_lookup_last_connection.store(
                reinterpret_cast<uintptr_t>(connection),
                std::memory_order_release);
            s_luxor_backend_connection_lookup_last_connection_ref.store(
                reinterpret_cast<uintptr_t>(connection_ref),
                std::memory_order_release);
            s_luxor_backend_connection_lookup_last_connection_vtable.store(
                reinterpret_cast<uintptr_t>(connection_vtable),
                std::memory_order_release);
            s_luxor_backend_connection_lookup_last_raw_send_target.store(
                raw_send_target, std::memory_order_release);
            store_luxor_backend_connection_table_summary(table_snapshot);

            if (s_session_trace_enabled.load(std::memory_order_acquire))
            {
                ReplayTraceFields f;
                add_session_trace_identity(f);
                f.hex("caller_rva", caller_rva)
                 .hex("connection_map",
                      reinterpret_cast<uintptr_t>(connection_map))
                 .hex("destination_key",
                      reinterpret_cast<uintptr_t>(destination_key))
                 .hex("connection", reinterpret_cast<uintptr_t>(connection))
                 .hex("connection_ref",
                      reinterpret_cast<uintptr_t>(connection_ref))
                 .hex("connection_vtable",
                      reinterpret_cast<uintptr_t>(connection_vtable))
                 .hex("raw_send_target", raw_send_target)
                 .hex("raw_send_target_rva",
                      native_rva_for_address(raw_send_target))
                 .string(
                     "connection_route_kind",
                     luxor_backend_connection_target_kind(raw_send_target))
                 .hex("connection_lower_transport",
                      reinterpret_cast<uintptr_t>(lower_transport))
                 .uinteger("connection_route_selector", route_selector)
                 .hex("connection_route_dispatch_channel",
                      reinterpret_cast<uintptr_t>(route_channel))
                 .boolean(
                     "raw_send_hook_installed",
                     s_luxor_backend_connection_raw_send_hook_installed.load(
                         std::memory_order_acquire));
                add_luxor_route_identity_fields(
                    f, "destination_key", destination_key_identity);
                add_luxor_backend_connection_table_fields(
                    f, table_snapshot);
                ReplayDebugTrace::instance().event(
                    "rollback_luxor_backend_connection_lookup", f);
            }
            return result;
        }

