        static void emit_active_sender_endpoint_get_trace(
            uint64_t caller_rva,
            uintptr_t sender_interface,
            uintptr_t sender_interface_vtable,
            uint32_t local_user,
            uintptr_t endpoint,
            uintptr_t endpoint_vtable,
            uint32_t endpoint_local_user_slot,
            uintptr_t endpoint_send_target) noexcept
        {
            if (!s_session_trace_enabled.load(std::memory_order_acquire))
                return;
            ReplayTraceFields f;
            add_session_trace_identity(f);
            f.hex("caller_rva", caller_rva)
             .hex("sender_interface", sender_interface)
             .hex("sender_interface_vtable", sender_interface_vtable)
             .uinteger("local_user", local_user)
             .hex("endpoint", endpoint)
             .hex("endpoint_vtable", endpoint_vtable)
             .uinteger("endpoint_local_user_slot",
                       endpoint_local_user_slot)
             .hex("endpoint_send_target", endpoint_send_target)
             .boolean(
                 "endpoint_send_hook_installed",
                 s_active_endpoint_send_hook_installed.load(
                     std::memory_order_acquire));
            ReplayDebugTrace::instance().event(
                "rollback_luxor_active_sender_endpoint_get", f);
        }

        static void* luxor_active_sender_endpoint_get_detour(
            void* sender_interface,
            uint8_t local_user)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            void* endpoint = nullptr;
            auto* original =
                reinterpret_cast<GetLuxorActiveSenderEndpointByLocalUserFn>(
                    s_active_sender_endpoint_get_trampoline);
            if (original)
                endpoint = original(sender_interface, local_user);

            void* sender_interface_vtable = nullptr;
            void* endpoint_vtable = nullptr;
            uint8_t endpoint_local_user_slot = 0xffu;
            uintptr_t endpoint_send_target = 0;
            (void)SafeReadPtr(sender_interface, &sender_interface_vtable);
            if (endpoint)
            {
                (void)SafeReadPtr(endpoint, &endpoint_vtable);
                (void)SafeReadUInt8(
                    static_cast<const uint8_t*>(endpoint) + 0x08,
                    &endpoint_local_user_slot);
                if (read_vtable_target(endpoint, 0x00,
                                       endpoint_send_target))
                {
                    (void)install_active_endpoint_send_hook_for_target(
                        endpoint_send_target);
                }
            }

            s_active_sender_endpoint_get_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_active_sender_endpoint_get_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            s_active_sender_endpoint_get_last_sender_interface.store(
                reinterpret_cast<uintptr_t>(sender_interface),
                std::memory_order_release);
            s_active_sender_endpoint_get_last_sender_interface_vtable.store(
                reinterpret_cast<uintptr_t>(sender_interface_vtable),
                std::memory_order_release);
            s_active_sender_endpoint_get_last_local_user.store(
                local_user, std::memory_order_release);
            s_active_sender_endpoint_get_last_endpoint.store(
                reinterpret_cast<uintptr_t>(endpoint),
                std::memory_order_release);
            s_active_sender_endpoint_get_last_endpoint_vtable.store(
                reinterpret_cast<uintptr_t>(endpoint_vtable),
                std::memory_order_release);
            s_active_sender_endpoint_get_last_endpoint_local_user_slot.store(
                endpoint_local_user_slot, std::memory_order_release);
            s_active_sender_endpoint_get_last_endpoint_send_target.store(
                endpoint_send_target, std::memory_order_release);
            emit_active_sender_endpoint_get_trace(
                caller_rva,
                reinterpret_cast<uintptr_t>(sender_interface),
                reinterpret_cast<uintptr_t>(sender_interface_vtable),
                local_user,
                reinterpret_cast<uintptr_t>(endpoint),
                reinterpret_cast<uintptr_t>(endpoint_vtable),
                endpoint_local_user_slot,
                endpoint_send_target);
            return endpoint;
        }

