        static void record_active_request_queue(
            uint64_t caller_rva,
            void* context,
            uint32_t event_opcode,
            float timeout_seconds,
            uint64_t start_callback_rva,
            uint32_t start_requested_state,
            uint64_t response_callback_rva,
            uint64_t failure_callback_rva) noexcept
        {
            const uint32_t timeout_millis =
                millis_from_delta_seconds(timeout_seconds);
            s_active_request_queue_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_active_request_queue_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            s_active_request_queue_last_context.store(
                reinterpret_cast<uintptr_t>(context),
                std::memory_order_release);
            s_active_request_queue_last_event_opcode.store(
                event_opcode, std::memory_order_release);
            s_active_request_queue_last_timeout_millis.store(
                timeout_millis, std::memory_order_release);
            s_active_request_queue_last_start_callback_rva.store(
                start_callback_rva, std::memory_order_release);
            s_active_request_queue_last_response_callback_rva.store(
                response_callback_rva, std::memory_order_release);
            s_active_request_queue_last_failure_callback_rva.store(
                failure_callback_rva, std::memory_order_release);
            if (event_opcode == 14 && context
                && start_callback_rva
                    == kRVA_StartLuxorReadyChannelStateRequest)
            {
                uint64_t expected = 0;
                if (s_opcode14_request_context.compare_exchange_strong(
                        expected,
                        reinterpret_cast<uintptr_t>(context),
                        std::memory_order_acq_rel))
                {
                    s_opcode14_requested_active_connect.store(
                        reinterpret_cast<uintptr_t>(context),
                        std::memory_order_release);
                    s_opcode14_requested_state.store(
                        start_requested_state,
                        std::memory_order_release);
                    s_opcode14_request_timeout_millis.store(
                        timeout_millis, std::memory_order_release);
                    s_opcode14_start_callback_rva.store(
                        start_callback_rva, std::memory_order_release);
                }
            }

            if (!s_session_trace_enabled.load(std::memory_order_acquire))
                return;
            ReplayTraceFields f;
            add_session_trace_identity(f);
            f.hex("caller_rva", caller_rva)
             .hex("context", reinterpret_cast<uintptr_t>(context))
             .uinteger("event_opcode", event_opcode)
             .uinteger("timeout_millis", timeout_millis)
             .hex("start_callback_rva", start_callback_rva)
             .uinteger("start_requested_state", start_requested_state)
             .hex("response_callback_rva", response_callback_rva)
             .hex("failure_callback_rva", failure_callback_rva);
            ReplayDebugTrace::instance().event(
                "rollback_luxor_active_request_queue", f);
        }

        static void active_request_queue_detour(
            void* context,
            uint8_t* event_opcode_ptr,
            void* start_delegate,
            void* response_delegate,
            void* failure_delegate,
            float timeout_seconds)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            uint8_t event_opcode8 = 0xff;
            uint32_t event_opcode = 0xff;
            if (event_opcode_ptr &&
                SafeReadUInt8(event_opcode_ptr, &event_opcode8))
            {
                event_opcode = event_opcode8;
            }
            uint64_t start_callback = 0;
            uint64_t response_callback = 0;
            uint64_t failure_callback = 0;
            uint32_t start_requested_state = 0xffu;
            (void)SafeReadUInt64(start_delegate, &start_callback);
            (void)SafeReadUInt64(response_delegate, &response_callback);
            (void)SafeReadUInt64(failure_delegate, &failure_callback);
            if (event_opcode == 14 && start_delegate && context)
            {
                const auto* bytes =
                    static_cast<const uint8_t*>(start_delegate);
                for (uintptr_t offset = 0x08; offset <= 0x28;
                     offset += sizeof(void*))
                {
                    void* value = nullptr;
                    if (!SafeReadPtr(bytes + offset, &value) || !value)
                        continue;
                    const uint8_t* state_address = nullptr;
                    if (value == context)
                    {
                        state_address = bytes + offset + sizeof(void*);
                    }
                    else
                    {
                        void* nested_active = nullptr;
                        if (SafeReadPtr(value, &nested_active)
                            && nested_active == context)
                        {
                            state_address =
                                static_cast<const uint8_t*>(value)
                                + sizeof(void*);
                        }
                    }
                    uint8_t state = 0xffu;
                    if (state_address
                        && SafeReadUInt8(state_address, &state))
                    {
                        start_requested_state = state;
                        break;
                    }
                }
            }
            record_active_request_queue(
                caller_rva,
                context,
                event_opcode,
                timeout_seconds,
                native_rva_for_address(
                    static_cast<uintptr_t>(start_callback)),
                start_requested_state,
                native_rva_for_address(
                    static_cast<uintptr_t>(response_callback)),
                native_rva_for_address(
                    static_cast<uintptr_t>(failure_callback)));

            auto* original =
                reinterpret_cast<LuxorActiveConnectRequestQueueFn>(
                    s_active_request_queue_trampoline);
            if (original)
            {
                original(
                    context,
                    event_opcode_ptr,
                    start_delegate,
                    response_delegate,
                    failure_delegate,
                    timeout_seconds);
            }
        }

        static bool ensure_active_request_queue_observe_hook() noexcept
        {
            if (s_active_request_queue_hook_installed.load(
                    std::memory_order_acquire))
            {
                return true;
            }
            bool expected = false;
            if (!s_active_request_queue_hook_attempted
                     .compare_exchange_strong(
                         expected, true, std::memory_order_acq_rel))
            {
                return s_active_request_queue_hook_installed.load(
                    std::memory_order_acquire);
            }

            const uintptr_t target =
                native_address(kRVA_QueueLuxorActiveConnectRequest);
            if (target &&
                install_debug_detour(
                    s_active_request_queue_detour,
                    target,
                    reinterpret_cast<uint64_t>(
                        &RollbackP2PHarness::active_request_queue_detour),
                    s_active_request_queue_trampoline))
            {
                s_active_request_queue_hook_installed.store(
                    true, std::memory_order_release);
                return true;
            }
            return false;
        }

        static bool install_active_state5_wide_hook(
            uint32_t hook_bit,
            uintptr_t rva,
            std::unique_ptr<PLH::x64Detour>& detour,
            uint64_t detour_fn,
            uint64_t& trampoline) noexcept
        {
            if (s_active_state5_wide_hook_install_mask.load(
                    std::memory_order_acquire) & hook_bit)
            {
                return true;
            }
            const uint32_t previous_attempts =
                s_active_state5_wide_hook_attempt_mask.fetch_or(
                    hook_bit, std::memory_order_acq_rel);
            if (previous_attempts & hook_bit)
            {
                return (s_active_state5_wide_hook_install_mask.load(
                            std::memory_order_acquire) &
                        hook_bit) != 0;
            }

            const uintptr_t target = native_address(rva);
            if (target &&
                install_debug_detour(
                    detour, target, detour_fn, trampoline))
            {
                s_active_state5_wide_hook_install_mask.fetch_or(
                    hook_bit, std::memory_order_acq_rel);
                return true;
            }
            return false;
        }

