        bool call_ui_handle_input(RC::Unreal::UObject* input_handler,
                                  RC::Unreal::UObject* target_widget,
                                  uint8_t input_type,
                                  uint8_t key,
                                  const char* label,
                                  std::string& reason) noexcept
        {
            if (!safe_is_real(input_handler))
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput handler unavailable";
                return false;
            }
            auto* fn = input_handler->GetFunctionByNameInChain(
                L"OnHandleInput");
            if (!fn)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 512)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            RC::Unreal::FProperty* widget_prop =
                reflected_param(fn, L"Widget");
            RC::Unreal::FProperty* input_prop =
                reflected_param(fn, L"InputType");
            auto* controller_prop = RC::Unreal::CastField<
                RC::Unreal::FIntProperty>(
                    reflected_param(fn, L"ControllerId"));
            RC::Unreal::FProperty* key_prop =
                reflected_param(fn, L"Key");
            auto* default_prop = RC::Unreal::CastField<
                RC::Unreal::FBoolProperty>(
                    reflected_param(fn, L"IsDefaultPrevented"));
            auto* prevent_prop = RC::Unreal::CastField<
                RC::Unreal::FBoolProperty>(
                    reflected_param(fn, L"bPreventDefault"));
            if (!input_prop || !controller_prop || !key_prop ||
                !default_prop || !prevent_prop)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput params unavailable";
                return false;
            }

            try
            {
                if (widget_prop)
                {
                    auto** widget_ptr =
                        reinterpret_cast<RC::Unreal::UObject**>(
                            widget_prop->ContainerPtrToValuePtr<void>(
                                params.data()));
                    if (widget_ptr)
                        *widget_ptr = safe_is_real(target_widget)
                            ? target_widget
                            : nullptr;
                }
                if (!write_reflected_u8_param(
                        input_prop, params.data(), input_type) ||
                    !write_reflected_u8_param(
                        key_prop, params.data(), key))
                {
                    reason = std::string(label ? label : "UI") +
                             ".OnHandleInput enum write failed";
                    return false;
                }
                *controller_prop->ContainerPtrToValuePtr<int32_t>(
                    params.data()) = 0;
                default_prop->SetPropertyValueInContainer(
                    params.data(), false);
                prevent_prop->SetPropertyValueInContainer(
                    params.data(), false);

                const bool ok =
                    safe_process_event(input_handler, fn, params.data());
                const bool prevented =
                    prevent_prop->GetPropertyValueInContainer(params.data());
                reason = ok
                    ? (std::string("called ") +
                       (label ? label : "UI") + ".OnHandleInput")
                    : (std::string(label ? label : "UI") +
                       ".OnHandleInput failed");
                reason += "(type=";
                reason += std::to_string(static_cast<int>(input_type));
                reason += ",key=";
                reason += std::to_string(static_cast<int>(key));
                reason += ",prevent=";
                reason += prevented ? "1)" : "0)";
                return ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] UI OnHandleInput threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput threw";
            }
            catch (...)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput threw";
            }
            return false;
        }

        bool request_main_menu_input_navigation(
            OnlineNavigatorObjects& nav,
            RC::Unreal::UObject* ref_main_menu,
            RC::Unreal::UObject* main_menu_widget,
            RC::Unreal::UObject* main_menu_impl,
            RC::Unreal::UObject* active_widget,
            std::string& reason) noexcept
        {
            try
            {
                reason.clear();
                const uint64_t tick = m_online_nav_attempts;
                const RollbackUiNavigationScene scene =
                    rollback_navigation_scene(nav.current_scene_identity);
                const uint64_t scene_generation =
                    rollback_navigation_scene_generation(nav.current_scene);

                if (m_main_menu_navigation_driver.state()
                    == RollbackUiNavigationState::Idle)
                {
                    m_main_menu_focus_before = MainMenuFocusSnapshot {};
                    m_main_menu_focus_after = MainMenuFocusSnapshot {};
                    std::array<
                        RollbackUiNavigationKey,
                        RollbackUiNavigationDriver::kMaxRouteSteps> route {};
                    size_t route_count = 0;
                    if (!build_main_menu_navigation_route(
                            route, route_count, reason))
                    {
                        (void)m_main_menu_navigation_driver.begin(
                            scene_generation, nullptr, 0, tick, scene);
                    }
                    else
                    {
                        (void)m_main_menu_navigation_driver.begin(
                            scene_generation,
                            route.data(),
                            route_count,
                            tick,
                            scene);
                    }
                }

                const RollbackUiNavigationResult scene_result =
                    m_main_menu_navigation_driver.observe_scene(
                        scene_generation, tick, scene);
                m_main_menu_input_sequence_step =
                    m_main_menu_navigation_driver.step_index();
                m_main_menu_input_sequence_complete =
                    m_main_menu_navigation_driver.sequence_complete();
                m_main_menu_input_attempts =
                    m_main_menu_navigation_driver.total_dispatches();

                UiInputKey trace_key = UiInputKey::Down;
                switch (static_cast<UiInputKey>(
                    static_cast<uint8_t>(m_main_menu_input_last_key)))
                {
                case UiInputKey::Up:
                case UiInputKey::Down:
                case UiInputKey::Left:
                case UiInputKey::Right:
                case UiInputKey::Start:
                case UiInputKey::Decide:
                case UiInputKey::Cancel:
                    trace_key = static_cast<UiInputKey>(
                        static_cast<uint8_t>(
                            m_main_menu_input_last_key));
                    break;
                default:
                    break;
                }

                if (scene_result == RollbackUiNavigationResult::Succeeded
                    || m_main_menu_navigation_driver.sequence_complete())
                {
                    reason = "current Player Match scene acknowledged";
                    m_main_menu_input_last_ok = true;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        true, nullptr, active_widget, trace_key, reason,
                        false, false, true, true);
                    return true;
                }

                const bool target_scene_queued =
                    identity_is_player_match_nav_context(
                        nav.next_scene_identity) ||
                    identity_is_player_match_nav_context(
                        nav.next_scene_direct_identity);
                if (target_scene_queued &&
                    m_main_menu_navigation_driver.state() ==
                        RollbackUiNavigationState::AwaitingAcknowledgement &&
                    m_main_menu_navigation_dispatch_id != 0)
                {
                    const RollbackUiNavigationResult queued_result =
                        m_main_menu_navigation_driver
                            .acknowledge_target_scene_queued(
                                m_main_menu_navigation_driver.generation(),
                                m_main_menu_navigation_dispatch_id,
                                tick,
                                scene);
                    const bool queued_acknowledged =
                        queued_result ==
                        RollbackUiNavigationResult::WaitingForTargetScene;
                    if (queued_acknowledged)
                        m_main_menu_navigation_target_scene_queued = true;
                    reason = queued_acknowledged
                        ? "Player Match scene queued; waiting for current scene"
                        : "Player Match queue evidence rejected";
                    m_main_menu_input_last_ok = queued_acknowledged;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        queued_acknowledged,
                        nullptr,
                        active_widget,
                        trace_key,
                        reason,
                        false,
                        false,
                        false,
                        false,
                        false,
                        queued_acknowledged);
                    return queued_acknowledged;
                }
                if (m_main_menu_navigation_driver.state()
                    == RollbackUiNavigationState::Failed)
                {
                    m_main_menu_navigation_blueprint_dispatch = false;
                    if (reason.empty())
                    {
                        reason = "main-menu navigation failed: ";
                        reason += RollbackUiNavigationDriver::failure_name(
                            m_main_menu_navigation_driver.failure());
                    }
                    m_main_menu_input_last_ok = false;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        false, nullptr, active_widget, trace_key, reason,
                        false, false, false, false);
                    return false;
                }

                if (m_main_menu_navigation_driver.state()
                        == RollbackUiNavigationState::AwaitingAcknowledgement
                    && m_main_menu_navigation_dispatch_id != 0
                    && m_main_menu_navigation_blueprint_dispatch)
                {
                    constexpr uint64_t kFocusSampleIntervalTicks = 3;
                    bool sampled_focus = false;
                    if (m_main_menu_focus_last_sample_tick == 0 ||
                        tick - m_main_menu_focus_last_sample_tick >=
                            kFocusSampleIntervalTicks)
                    {
                        sampled_focus = sample_main_menu_focus(
                            ref_main_menu,
                            main_menu_widget,
                            main_menu_impl,
                            m_main_menu_focus_after);
                        m_main_menu_focus_last_sample_tick = tick;
                    }
                    const bool final_decide =
                        trace_key == UiInputKey::Decide &&
                        m_main_menu_navigation_driver.step_index() + 1 >=
                            m_main_menu_navigation_driver.route_length();
                    const bool intermediate_decide =
                        trace_key == UiInputKey::Decide && !final_decide;
                    bool focus_confirmed = false;
                    if (sampled_focus &&
                        m_main_menu_focus_before.live_dispatchable &&
                        m_main_menu_focus_after.live_dispatchable)
                    {
                        if (intermediate_decide)
                        {
                            focus_confirmed =
                                m_main_menu_focus_before.menu_id_ok &&
                                ascii_iequals(
                                    m_main_menu_focus_before.menu_id,
                                    "ENETWORK") &&
                                m_main_menu_focus_after.menu_id_ok &&
                                !ascii_iequals(
                                    m_main_menu_focus_after.menu_id,
                                    "ENETWORK") &&
                                m_main_menu_focus_after.menu_index_ok &&
                                m_main_menu_focus_after.menu_index == 0 &&
                                main_menu_hierarchy_changed(
                                    m_main_menu_focus_before,
                                    m_main_menu_focus_after);
                        }
                        else if (trace_key == UiInputKey::Down ||
                                 trace_key == UiInputKey::Up)
                        {
                            const auto navigation_key =
                                m_main_menu_navigation_driver.current_key();
                            const bool semantic_network = navigation_key ==
                                RollbackUiNavigationKey::FocusNetwork;
                            const bool semantic_player_match = navigation_key ==
                                RollbackUiNavigationKey::FocusPlayerMatch;
                            if (semantic_network || semantic_player_match)
                            {
                                focus_confirmed =
                                    m_main_menu_focus_after.menu_id_ok &&
                                    ascii_iequals(
                                        m_main_menu_focus_after.menu_id,
                                        semantic_network
                                            ? "ENETWORK"
                                            : "EPLAYERMATCH") &&
                                    m_main_menu_focus_after
                                        .live_dispatchable;
                            }
                            else
                            {
                                const int32_t delta =
                                    trace_key == UiInputKey::Down ? 1 : -1;
                                const int64_t expected_index =
                                    static_cast<int64_t>(
                                        m_main_menu_focus_before.menu_index) +
                                    delta;
                                focus_confirmed =
                                    m_main_menu_focus_before.menu_index_ok &&
                                    m_main_menu_focus_after.menu_index_ok &&
                                    expected_index >= 0 &&
                                    expected_index <= INT32_MAX &&
                                    m_main_menu_focus_after.menu_index ==
                                        expected_index &&
                                    m_main_menu_focus_before.source_object ==
                                        m_main_menu_focus_after.source_object;
                            }
                        }
                    }
                    const RollbackUiNavigationResult ack_result =
                        m_main_menu_navigation_driver
                            .acknowledge_focus_change(
                                m_main_menu_navigation_driver.generation(),
                                m_main_menu_navigation_dispatch_id,
                                tick,
                                scene,
                                focus_confirmed);
                    m_main_menu_input_sequence_step =
                        m_main_menu_navigation_driver.step_index();
                    m_main_menu_input_sequence_complete =
                        m_main_menu_navigation_driver.sequence_complete();
                    m_main_menu_input_attempts =
                        m_main_menu_navigation_driver.total_dispatches();
                    const bool destination_seen =
                        ack_result == RollbackUiNavigationResult::Succeeded;
                    const bool step_advanced =
                        ack_result ==
                        RollbackUiNavigationResult::ActionAcknowledged;
                    if (step_advanced || destination_seen)
                        m_main_menu_navigation_blueprint_dispatch = false;
                    reason = destination_seen
                        ? "Player Match scene acknowledged"
                        : step_advanced
                            ? "semantic Blueprint focus change acknowledged"
                            : final_decide
                                ? "semantic Decide started; waiting for "
                                  "queued/current Player Match scene"
                                : sampled_focus
                                    ? "semantic Blueprint dispatch accepted; "
                                      "reflected focus unchanged"
                                    : "semantic Blueprint dispatch accepted; "
                                      "waiting for bounded focus sample";
                    m_main_menu_input_last_ok =
                        step_advanced || destination_seen;
                    m_main_menu_input_last_reason = reason;
                    if (step_advanced || destination_seen)
                    {
                        emit_main_menu_input_trace(
                            true,
                            reinterpret_cast<RC::Unreal::UObject*>(
                                m_main_menu_focus_before.source_object),
                            active_widget,
                            trace_key,
                            reason,
                            false,
                            false,
                            true,
                            destination_seen);
                        return true;
                    }
                }

                const bool ready_for_command =
                    m_main_menu_navigation_driver.state() ==
                        RollbackUiNavigationState::ReadyToDispatch &&
                    tick >= m_main_menu_navigation_driver
                                .next_dispatch_not_before_tick();
                MainMenuFocusSnapshot dispatch_focus {};
                const bool dispatch_focus_ready = ready_for_command &&
                    sample_main_menu_focus(
                        ref_main_menu,
                        main_menu_widget,
                        main_menu_impl,
                        dispatch_focus);
                const bool dispatcher_available =
                    ready_for_command
                    && dispatch_focus_ready
                    && dispatch_focus.live_dispatchable
                    && main_menu_impl != nullptr;
                RollbackUiNavigationCommand command {};
                if (!m_main_menu_navigation_driver.next_command(
                        scene_generation,
                        tick,
                        scene,
                        dispatcher_available,
                        command))
                {
                    m_main_menu_input_sequence_step =
                        m_main_menu_navigation_driver.step_index();
                    m_main_menu_input_sequence_complete =
                        m_main_menu_navigation_driver.sequence_complete();
                    m_main_menu_input_attempts =
                        m_main_menu_navigation_driver.total_dispatches();
                    if (m_main_menu_navigation_driver.state()
                        == RollbackUiNavigationState::Failed)
                    {
                        m_main_menu_navigation_blueprint_dispatch = false;
                        reason = "main-menu navigation failed: ";
                        reason += RollbackUiNavigationDriver::failure_name(
                            m_main_menu_navigation_driver.failure());
                    }
                    else if (ready_for_command && !dispatch_focus_ready)
                    {
                        reason = "reflected MainMenu focus unavailable; input "
                                 "dispatch held";
                    }
                    else if (!ready_for_command &&
                             m_main_menu_navigation_driver.state() ==
                                 RollbackUiNavigationState::ReadyToDispatch)
                    {
                        reason = "navigation retry waiting for fresh focus "
                                 "baseline";
                    }
                    else if (ready_for_command && !dispatcher_available)
                    {
                        reason = "semantic MainMenu Blueprint dispatcher "
                                 "unavailable";
                    }
                    else if (reason.empty())
                    {
                        reason = "main-menu navigation command pending";
                    }
                    m_main_menu_input_last_ok = false;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        false, nullptr, active_widget, trace_key, reason,
                        false, false, false, false);
                    return false;
                }

                m_main_menu_focus_before = std::move(dispatch_focus);
                m_main_menu_focus_after = MainMenuFocusSnapshot {};
                m_main_menu_focus_last_sample_tick = 0;
                m_main_menu_navigation_dispatch_id = command.dispatch_id;
                m_main_menu_navigation_pulse_generation = 0;
                m_main_menu_navigation_blueprint_dispatch = false;
                m_main_menu_navigation_target_scene_queued = false;
                const bool final_decide =
                    command.key == RollbackUiNavigationKey::Decide &&
                    command.step_index + 1 >=
                        m_main_menu_navigation_driver.route_length();
                const char* expected_decide_menu_id = final_decide
                    ? "EPLAYERMATCH"
                    : command.key == RollbackUiNavigationKey::Decide
                        ? "ENETWORK"
                        : nullptr;
                if (expected_decide_menu_id &&
                    (!m_main_menu_focus_before.menu_id_ok ||
                     !ascii_iequals(
                         m_main_menu_focus_before.menu_id,
                         expected_decide_menu_id)))
                {
                    (void)m_main_menu_navigation_driver.on_dispatch_result(
                        command.generation,
                        command.dispatch_id,
                        tick,
                        false);
                    m_main_menu_navigation_blueprint_dispatch = false;
                    reason = "Decide held: reflected selection is ";
                    reason += m_main_menu_focus_before.menu_id_ok
                        ? m_main_menu_focus_before.menu_id
                        : "unavailable";
                    reason += ", expected ";
                    reason += expected_decide_menu_id;
                    m_main_menu_input_last_ok = false;
                    m_main_menu_input_last_reason = reason;
                    trace_key = from_rollback_navigation_key(command.key);
                    m_main_menu_input_last_key =
                        static_cast<uint8_t>(trace_key);
                    emit_main_menu_input_trace(
                        false,
                        nullptr,
                        active_widget,
                        trace_key,
                        reason,
                        false,
                        false,
                        false,
                        false);
                    return false;
                }
                RC::Unreal::UObject* dispatched_item = nullptr;
                std::string semantic_reason;
                const bool delivered =
                    dispatch_main_menu_blueprint_navigation(
                        main_menu_impl,
                        m_main_menu_focus_before,
                        command.key,
                        dispatched_item,
                        semantic_reason);
                m_main_menu_navigation_blueprint_dispatch = delivered;
                (void)m_main_menu_navigation_driver.on_dispatch_result(
                    command.generation,
                    command.dispatch_id,
                    tick,
                    delivered);
                bool semantic_action_started = false;
                if (delivered &&
                    command.key == RollbackUiNavigationKey::Decide)
                {
                    const RollbackUiNavigationResult semantic_result =
                        m_main_menu_navigation_driver
                            .acknowledge_semantic_action_started(
                                command.generation,
                                command.dispatch_id,
                                tick,
                                scene);
                    semantic_action_started =
                        semantic_result ==
                            RollbackUiNavigationResult::WaitingForTargetScene ||
                        semantic_result ==
                            RollbackUiNavigationResult::Succeeded;
                }

                trace_key = from_rollback_navigation_key(command.key);
                m_main_menu_input_last_key =
                    static_cast<uint8_t>(trace_key);
                m_main_menu_input_sequence_step =
                    m_main_menu_navigation_driver.step_index();
                m_main_menu_input_sequence_complete =
                    m_main_menu_navigation_driver.sequence_complete();
                m_main_menu_input_attempts =
                    m_main_menu_navigation_driver.total_dispatches();
                m_main_menu_input_last_ok = delivered;
                reason = semantic_reason;
                if (semantic_action_started)
                {
                    reason += "; semantic action started; waiting for "
                              "queued/current Player Match scene";
                }
                m_main_menu_input_last_reason = reason;
                emit_main_menu_input_trace(
                    delivered,
                    reinterpret_cast<RC::Unreal::UObject*>(
                        m_main_menu_focus_before.source_object),
                    active_widget,
                    trace_key,
                    reason,
                    delivered,
                    false,
                    false,
                    false,
                    semantic_action_started,
                    false);
                return delivered;
            }
            catch (const std::exception& e)
            {
                m_main_menu_navigation_blueprint_dispatch = false;
                reason = "main-menu navigation exception: ";
                reason += e.what();
            }
            catch (...)
            {
                m_main_menu_navigation_blueprint_dispatch = false;
                reason = "main-menu navigation unknown exception";
            }
            m_main_menu_input_last_ok = false;
            m_main_menu_input_last_reason = reason;
            return false;
        }

        static const wchar_t* player_match_join_command(
            int32_t index) noexcept
        {
            static constexpr const wchar_t* kCommands[] = {
                L"Decide",
                L"Submit",
                L"OK",
                L"Ok",
                L"Join",
                L"Select",
                L"Enter",
            };
            if (index < 0 ||
                index >= static_cast<int32_t>(
                    sizeof(kCommands) / sizeof(kCommands[0])))
            {
                return nullptr;
            }
            return kCommands[index];
        }

        bool send_player_match_join_menu_command(
            RC::Unreal::UObject* player_match_scene,
            int32_t command_index,
            std::string& reason,
            bool require_room_select_menu = false) noexcept
        {
            const wchar_t* command =
                player_match_join_command(command_index);
            if (!command)
            {
                reason = "join menu command list exhausted";
                return false;
            }

            std::wstring active_menu_w;
            std::string active_menu;
            RC::Unreal::UObject* active_widget = nullptr;
            std::string active_reason;
            const bool active_ok = resolve_room_select_menu_for_join(
                player_match_scene,
                active_menu_w,
                active_menu,
                active_widget,
                active_reason);
            m_join_scene_active_menu_name = active_menu;
            m_join_scene_active_menu_widget =
                reinterpret_cast<uintptr_t>(active_widget);
            if (active_ok && m_cfg.online_stage_diagnostic_reflection)
                emit_scene_reflection_once(active_widget);
            if (require_room_select_menu &&
                (!active_ok || active_menu != "RoomSelectMenu"))
            {
                reason = "waiting-for-RoomSelectMenu active=" +
                         (active_menu.empty() ? std::string("<none>") :
                                                active_menu) +
                         " reason=" + active_reason;
                m_join_scene_ui_command_requested = false;
                m_join_scene_ui_command_ok = false;
                m_join_scene_ui_command_failure = reason;
                return false;
            }
            m_join_scene_ui_command_index = command_index;
            m_join_scene_ui_command = narrow_wide_utf8(command);

            std::string focus_reason;
            std::string refresh_reason;
            if (active_ok && active_menu == "RoomSelectMenu")
            {
                (void)call_room_select_change_focus(
                    active_widget, 0, focus_reason);
                (void)call_room_select_refresh_data(
                    active_widget,
                    player_match_scene,
                    refresh_reason);
            }

            std::string handle_reason;
            bool ok = false;
            if (active_ok && active_menu == "RoomSelectMenu" &&
                command_index == 0)
            {
                ok = call_room_select_handle_input(
                    active_widget,
                    player_match_scene,
                    static_cast<uint8_t>(UiInputType::KeyDown),
                    static_cast<uint8_t>(UiInputKey::Decide),
                    handle_reason);
            }

            std::string widget_reason;
            if (active_ok)
            {
                if (!ok)
                {
                    ok = call_widget_request_input_command(
                        active_widget, command, widget_reason);
                }
                else
                {
                    widget_reason = "skipped after OnHandleInput";
                }
            }
            else
            {
                widget_reason = active_reason;
            }

            std::string scene_reason;
            if (!ok)
            {
                const wchar_t* menu_name =
                    active_menu_w.empty() ? L"" : active_menu_w.c_str();
                ok = call_player_match_input_command(
                    player_match_scene,
                    menu_name,
                    command,
                    active_widget,
                    active_widget,
                    scene_reason);
            }
            m_join_scene_ui_command_requested = true;
            m_join_scene_ui_command_ok = ok;
            m_join_scene_ui_command_tick = m_join_scene_last_step_tick;
            reason = "menu=" +
                     (active_menu.empty() ? std::string("<none>")
                                          : active_menu) +
                     " command=" + m_join_scene_ui_command +
                     " active=" + active_reason +
                     " widget=" + widget_reason;
            if (!focus_reason.empty())
            {
                reason += " focus=";
                reason += focus_reason;
            }
            if (!refresh_reason.empty())
            {
                reason += " refresh=";
                reason += refresh_reason;
            }
            if (!handle_reason.empty())
            {
                reason += " handle=";
                reason += handle_reason;
            }
            if (!scene_reason.empty())
            {
                reason += " scene=";
                reason += scene_reason;
            }
            m_join_scene_ui_command_failure = reason;
            return ok;
        }

