        bool resolve_player_match_creation_window(
            RC::Unreal::UObject* player_match_scene,
            std::wstring& menu_name,
            std::string& menu_name_utf8,
            RC::Unreal::UObject*& menu_widget,
            std::string& reason) noexcept
        {
            menu_name.clear();
            menu_name_utf8.clear();
            menu_widget = nullptr;

            std::wstring active_menu_w;
            std::string active_menu;
            RC::Unreal::UObject* active_widget = nullptr;
            std::string active_reason;
            const bool active_ok = get_active_gameflow_menu(
                player_match_scene,
                active_menu_w,
                active_menu,
                active_widget,
                active_reason);
            if (active_ok &&
                active_menu.find("PlayerMatchRoomCreationWindow") !=
                    std::string::npos)
            {
                menu_name = active_menu_w;
                menu_name_utf8 = active_menu;
                menu_widget = active_widget;
                reason = active_reason;
                return true;
            }

            RC::Unreal::UObject* player_match_menu =
                reflected_object_property(
                    player_match_scene, L"RefPlayerMatchMenu");
            if (safe_is_real(player_match_menu))
            {
                if (m_cfg.online_stage_diagnostic_reflection)
                    emit_scene_reflection_once(player_match_menu);
                std::string owned_window_reason;
                RC::Unreal::UObject* owned_window =
                    call_get_window_by_name(
                        player_match_menu,
                        L"PlayerMatchRoomCreationWindow",
                        owned_window_reason);
                if (safe_is_real(owned_window))
                {
                    menu_name = L"PlayerMatchRoomCreationWindow";
                    menu_name_utf8 = "PlayerMatchRoomCreationWindow";
                    menu_widget = owned_window;
                    reason = active_reason + "; RefPlayerMatchMenu." +
                             owned_window_reason;
                    return true;
                }
                if (!owned_window_reason.empty())
                {
                    active_reason += "; RefPlayerMatchMenu.";
                    active_reason += owned_window_reason;
                }
                std::wstring child_menu_w;
                std::string child_menu;
                RC::Unreal::UObject* child_widget = nullptr;
                std::string child_reason;
                const bool child_ok = get_active_gameflow_menu(
                    player_match_menu,
                    child_menu_w,
                    child_menu,
                    child_widget,
                    child_reason);
                if (child_ok &&
                    child_menu.find("PlayerMatchRoomCreationWindow") !=
                        std::string::npos)
                {
                    menu_name = child_menu_w;
                    menu_name_utf8 = child_menu;
                    menu_widget = child_widget;
                    reason = active_reason + "; RefPlayerMatchMenu " +
                        child_reason;
                    return true;
                }
                if (!child_reason.empty())
                {
                    active_reason += "; RefPlayerMatchMenu ";
                    active_reason += child_reason;
                }
            }

            menu_name = active_menu_w;
            menu_name_utf8 = active_menu;
            menu_widget = active_widget;
            reason = active_reason;
            return false;
        }

        // Controller/OS input room creation was intentionally removed.
        // The stock-online driver uses reflected Player Match state commands
        // and GameDataUnit values exclusively.
        RC::Unreal::UObject* find_player_match_creation_data_proxy(
            std::string& reason) noexcept
        {
            reason.clear();
            auto matches = [&](RC::Unreal::UObject* obj) noexcept
            {
                if (!obj) return false;
                std::string class_name;
                std::string object_name;
                try
                {
                    auto* cls = obj->GetClassPrivate();
                    if (!cls) return false;
                    class_name = narrow_rc_string(
                        static_cast<RC::Unreal::UObject*>(cls)->GetName());
                    object_name = narrow_rc_string(obj->GetName());
                }
                catch (...)
                {
                    return false;
                }
                if (class_name.find("GameDataProxy_C") ==
                        std::string::npos ||
                    object_name.find("Default__") == 0)
                {
                    return false;
                }
                std::string store_name;
                return safe_get_fstring_property(
                           obj, L"objectStoreName", store_name) &&
                       store_name == "PlayerMatchRoomCreationConfigData";
            };

            auto* cached = reinterpret_cast<RC::Unreal::UObject*>(
                m_host_room_creation_config_data);
            if (safe_is_real(cached) && matches(cached))
            {
                reason = "cached PlayerMatchRoomCreationConfigData proxy";
                return cached;
            }

            RC::Unreal::UObject* found = nullptr;
            try
            {
                RC::Unreal::UObjectGlobals::ForEachUObject(
                    [&](RC::Unreal::UObject* obj, int32_t, int32_t) {
                        if (!matches(obj))
                            return RC::LoopAction::Continue;
                        found = obj;
                        return RC::LoopAction::Break;
                    });
            }
            catch (...)
            {
                found = nullptr;
            }
            m_host_room_creation_config_data =
                reinterpret_cast<uintptr_t>(found);
            reason = found
                ? "found PlayerMatchRoomCreationConfigData proxy"
                : "PlayerMatchRoomCreationConfigData proxy unavailable";
            return found;
        }

        bool call_create_game_data_unit(
            RC::Unreal::UObject* proxy,
            const wchar_t* key,
            RC::Unreal::UObject*& unit,
            std::string& reason) noexcept
        {
            unit = nullptr;
            if (!safe_is_real(proxy))
            {
                reason = "GameDataProxy unavailable";
                return false;
            }
            auto* fn = proxy->GetFunctionByNameInChain(L"CreateGameDataUnit");
            if (!fn)
            {
                reason = "GameDataProxy.CreateGameDataUnit unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 1024)
            {
                reason = "CreateGameDataUnit param-size invalid";
                return false;
            }
            auto* key_prop = RC::Unreal::CastField<RC::Unreal::FStrProperty>(
                reflected_param_any(fn, L"targetKey", L"TargetKey"));
            RC::Unreal::FProperty* unit_prop =
                reflected_param_any(fn, L"GameDataUnit", L"gameDataUnit");
            if (!key_prop || !unit_prop)
            {
                reason = "CreateGameDataUnit reflected params unavailable";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            bool key_initialized = false;
            try
            {
                key_prop->InitializeValue_InContainer(params.data());
                key_initialized = true;
                key_prop->SetPropertyValueInContainer(
                    params.data(), RC::Unreal::FString(key ? key : L""));
                const bool called = safe_process_event(proxy, fn, params.data());
                void* slot = unit_prop->ContainerPtrToValuePtr<void>(
                    params.data());
                if (called && slot)
                    unit = *reinterpret_cast<RC::Unreal::UObject**>(slot);
                if (key_initialized)
                    key_prop->DestroyValue_InContainer(params.data());
                reason = safe_is_real(unit)
                    ? "created GameDataUnit"
                    : "CreateGameDataUnit returned no unit";
                return safe_is_real(unit);
            }
            catch (...)
            {
                if (key_initialized)
                    key_prop->DestroyValue_InContainer(params.data());
                unit = nullptr;
                reason = "CreateGameDataUnit threw";
                return false;
            }
        }

        bool set_player_match_private_room_value(
            std::string& reason) noexcept
        {
            std::string proxy_reason;
            RC::Unreal::UObject* proxy =
                find_player_match_creation_data_proxy(proxy_reason);
            if (!proxy)
            {
                reason = proxy_reason;
                return false;
            }

            RC::Unreal::UObject* unit = nullptr;
            std::string unit_reason;
            if (!call_create_game_data_unit(
                    proxy, L"privateSlot", unit, unit_reason))
            {
                reason = proxy_reason + "; " + unit_reason;
                return false;
            }
            auto* fn = unit->GetFunctionByNameInChain(L"SetValue");
            if (!fn)
            {
                reason = "GameDataUnit.SetValue unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            RC::Unreal::FProperty* value_prop =
                reflected_param_any(fn, L"value", L"Value");
            auto* success_prop = RC::Unreal::CastField<
                RC::Unreal::FBoolProperty>(
                    reflected_param_any(fn, L"bSuccess", L"Success"));
            if (param_bytes <= 0 || param_bytes > 1024 ||
                !value_prop || !success_prop ||
                value_prop->GetSize() <= 0 ||
                value_prop->GetSize() >
                    static_cast<int32_t>(sizeof(LuxDataTablePathNative)))
            {
                reason = "GameDataUnit.SetValue reflected params invalid";
                return false;
            }
            if (!resolve_gameflow_natives())
            {
                reason = "native FUIDataObject helpers unavailable";
                return false;
            }

            LuxDataTablePathNative value {};
            std::string value_reason;
            // The authoritative native structure names this field
            // PublicFlag. A live public-room incident proved that the prior
            // privateSlot=1 interpretation propagated PublicFlag=true and
            // exposed the room to browsing. Private creation requires the
            // native flag to remain false.
            if (!create_ui_data_object_from_int(0, value, value_reason))
            {
                reason = value_reason;
                return false;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            bool success = false;
            try
            {
                void* value_slot = value_prop->ContainerPtrToValuePtr<void>(
                    params.data());
                if (!value_slot)
                {
                    destroy_ui_data_object(value);
                    reason = "GameDataUnit.SetValue value slot unavailable";
                    return false;
                }
                std::memcpy(
                    value_slot, &value,
                    static_cast<size_t>(value_prop->GetSize()));
                const bool called = safe_process_event(unit, fn, params.data());
                success = called &&
                    success_prop->GetPropertyValueInContainer(params.data());
                destroy_ui_data_object(value);
                reason = success
                    ? "privateSlot=0 accepted by GameDataUnit.SetValue"
                    : "GameDataUnit.SetValue did not confirm privateSlot=0";
                return success;
            }
            catch (...)
            {
                destroy_ui_data_object(value);
                reason = "GameDataUnit.SetValue threw";
                return false;
            }
        }

        bool send_player_match_create_room_command(
            OnlineNavigatorObjects& nav,
            RC::Unreal::UObject* player_match_scene,
            uint64_t tick,
            std::string& reason) noexcept
        {
            // BlueprintToCpp evidence from
            // PlayerMatchRoomCreationWindowConfig_ui:
            //   commandName="Decide", commandParam="StartCreateRoom".
            // PlayerMatchMakeRoomState::OnRequestInputCommand handles that
            // exact command by requesting MakeConnecting and closing the
            // creation window.  The stock path begins with the physical
            // Decide key; send it only after this process owns foreground UI
            // focus, then require the independently hooked
            // CreateLuxorPlayerSession boundary before accepting progress.
            (void)nav;
            (void)tick;
            std::string state_reason;
            RC::Unreal::UObject* make_room_state =
                find_active_player_match_lobby_state(
                    player_match_scene,
                    "PlayerMatchMakeRoomState",
                    &state_reason);
            if (!make_room_state)
            {
                reason = "active PlayerMatchMakeRoomState unavailable: " +
                    state_reason;
                return false;
            }

            const bool ok = call_player_match_input_command(
                make_room_state,
                L"PlayerMatchRoomCreationWindow",
                L"Decide",
                nullptr,
                make_room_state,
                reason,
                player_match_scene,
                L"StartCreateRoom",
                "PlayerMatchMakeRoomState");
            reason = std::string(ok
                ? "semantic MakeRoom Decide dispatched: "
                : "semantic MakeRoom Decide failed: ") +
                reason + " state=" + state_reason;
            return ok;
        }

        bool use_targeted_native_player_session_create() const noexcept
        {
            // Owner targeting is a guest-side search constraint; it must not
            // bypass the host's visible Make Room flow. Keep direct native
            // creation only for explicitly named diagnostic sessions.
            return false;
        }

        RollbackOnlineNamedSessionEvidence
        current_named_session_evidence() const noexcept
        {
            RollbackOnlineNamedSessionEvidence evidence {};
            evidence.sampled_ok = m_native_named_session_ok;
            evidence.named_session = m_native_named_session_ptr;
            evidence.session_info = m_native_named_session_info;
            evidence.lobby_id = m_native_named_session_lobby_id;
            evidence.public_connections =
                m_native_named_session_public_connections;
            evidence.hosting_player_num =
                m_native_named_session_hosting_player_num;
            evidence.online_state = m_native_named_session_state;
            evidence.lobby_owner_sampled =
                m_native_named_session_lobby_owner_sampled;
            evidence.lobby_owner_id =
                m_native_named_session_lobby_owner_id;
            return evidence;
        }

        bool has_reusable_host_named_session() const noexcept
        {
            return CanAdoptRollbackHostSession(
                current_named_session_evidence(),
                m_session_main_user_id,
                m_steam_local_id);
        }

        bool has_reusable_guest_named_session() const noexcept
        {
            return CanAdoptRollbackGuestSession(
                current_named_session_evidence(),
                m_stock_remote_offer.owner_steam_id);
        }

        bool service_host_native_create_pipeline(
            OnlineNavigatorObjects& nav,
            uint64_t tick) noexcept
        {
            // SC6 may report a provisional OnCreateSession(false) before a
            // later OnCreateSession(true) for the same native request. The
            // July 8 two-process trace observed that exact sequence, so latch
            // any success and let false-only callbacks wait for the bounded
            // create timeout instead of retrying or failing immediately.
            const int32_t create_true_count =
                s_create_callback_true_count.load(std::memory_order_acquire);
            const int32_t create_false_count =
                s_create_callback_false_count.load(std::memory_order_acquire);
            const uint64_t create_elapsed =
                m_host_room_create_start_tick != 0
                    && tick >= m_host_room_create_start_tick
                ? tick - m_host_room_create_start_tick
                : 0;
            const RollbackOnlineCreateDecision create_decision =
                EvaluateRollbackOnlineCreate(
                    create_true_count,
                    create_false_count,
                    m_create_callback_seen,
                    m_create_callback_result,
                    create_elapsed,
                    kHostRoomCreateWaitTicks);
            if (create_decision.status ==
                RollbackOnlineCreateStatus::Succeeded)
            {
                m_create_requested = true;
                m_create_request_ok = true;
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineComplete;
                m_host_room_create_failure = "ok";
                emit_host_room_create_pipeline_trace(
                    "native-create-callback-complete", true,
                    nav.current_scene, tick);
                return true;
            }
            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineComplete)
            {
                return m_create_request_ok;
            }
            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineFailed)
            {
                return false;
            }
            if (m_host_room_create_start_tick == 0)
                m_host_room_create_start_tick = tick;

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineNone)
            {
                // Acceptance requests are intentionally layered, but the
                // native PlayerMatch named session survives between them.
                // Sample once before creating so the next phase adopts the
                // valid room instead of issuing a duplicate request.
                m_native_session_sample_tick = tick;
                sample_named_online_session_state(tick, false);
                if (has_reusable_host_named_session())
                {
                    m_host_adopted_existing_session = true;
                    m_create_requested = true;
                    m_create_request_ok = true;
                    m_host_room_create_make_room_requested = false;
                    m_host_room_create_make_room_ok = true;
                    m_host_room_create_pipeline_step =
                        kHostRoomCreatePipelineComplete;
                    m_host_room_create_failure =
                        "ok-existing-native-session";
                    emit_host_room_create_pipeline_trace(
                        "native-create-adopted-existing-session", true,
                        nav.current_scene, tick);
                    return true;
                }
                if (!nav.session_hub)
                {
                    m_host_room_create_failure =
                        "session-hub-unavailable";
                    emit_host_room_create_pipeline_trace(
                        "native-create-session-hub-unavailable", false,
                        nav.current_scene, tick);
                    return false;
                }
                if (m_host_room_create_last_step_tick == tick)
                    return false;

                ++m_host_room_create_attempts;
                m_create_requested = true;
                m_host_room_create_make_room_requested = true;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_command_failure =
                    "native CreatePlayerSession";
                m_host_room_create_make_room_ok =
                    call_create_player_session(
                        nav.session_hub, m_session_main_user_id);
                if (!m_host_room_create_make_room_ok)
                {
                    m_host_room_create_failure =
                        "native CreatePlayerSession returned false";
                    if (tick >= m_host_room_create_start_tick &&
                        tick - m_host_room_create_start_tick >=
                            kHostRoomCreateWaitTicks)
                    {
                        m_host_room_create_pipeline_step =
                            kHostRoomCreatePipelineFailed;
                    }
                    emit_host_room_create_pipeline_trace(
                        "native-create-request-failed", false,
                        nav.current_scene, tick);
                    return false;
                }

                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineWaitingForCreateSession;
                m_host_room_create_failure =
                    "waiting-for-native-OnCreateSession";
                emit_host_room_create_pipeline_trace(
                    "native-create-requested", true,
                    nav.current_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineWaitingForCreateSession)
            {
                const bool provisional_false_seen =
                    create_decision.provisional_false_seen;
                if (create_decision.status ==
                    RollbackOnlineCreateStatus::TimedOut)
                {
                    m_host_room_create_pipeline_step =
                        kHostRoomCreatePipelineFailed;
                    m_host_room_create_failure = provisional_false_seen
                        ? "native OnCreateSession timeout after provisional false"
                        : "native OnCreateSession timeout";
                    emit_host_room_create_pipeline_trace(
                        provisional_false_seen
                            ? "native-create-timeout-after-provisional-false"
                            : "native-create-timeout",
                        false,
                        nav.current_scene, tick);
                    return false;
                }
                const bool first_provisional_false =
                    provisional_false_seen &&
                    m_host_room_create_failure !=
                        "waiting-after-provisional-native-OnCreateSession-false";
                m_host_room_create_failure = provisional_false_seen
                    ? "waiting-after-provisional-native-OnCreateSession-false"
                    : "waiting-for-native-OnCreateSession";
                if (first_provisional_false ||
                    tick == m_host_room_create_start_tick + 1 ||
                    (tick % 30u) == 0u)
                {
                    emit_host_room_create_pipeline_trace(
                        provisional_false_seen
                            ? "native-create-provisional-false-waiting"
                            : "native-create-waiting",
                        false,
                        nav.current_scene, tick);
                }
                return false;
            }

            m_host_room_create_pipeline_step =
                kHostRoomCreatePipelineFailed;
            m_host_room_create_failure =
                "native-create-pipeline-invalid-step";
            emit_host_room_create_pipeline_trace(
                "native-create-invalid-step", false,
                nav.current_scene, tick);
            return false;
        }

        bool service_host_room_create_pipeline(
            OnlineNavigatorObjects& nav,
            uint64_t tick) noexcept
        {
            if (m_create_callback_seen && m_create_callback_result)
            {
                m_create_requested = true;
                m_create_request_ok = true;
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineComplete;
                m_host_room_create_failure = "ok";
                emit_host_room_create_pipeline_trace(
                    "create-session-callback-complete", true,
                    nav.current_scene, tick);
                return true;
            }

            RC::Unreal::UObject* player_match_scene = nav.current_scene;
            if (!player_match_scene)
            {
                m_host_room_create_failure =
                    "PlayerMatchLobbyScene unavailable";
                emit_host_room_create_pipeline_trace(
                    "scene-unavailable", false, player_match_scene, tick);
                return false;
            }

            if (!identity_contains_scene(
                    nav.current_scene_identity,
                    "PlayerMatchLobbyScene"))
            {
                m_host_room_create_failure =
                    "waiting-for-PlayerMatchLobbyScene";
                emit_host_room_create_pipeline_trace(
                    "waiting-scene", false, player_match_scene, tick);
                return false;
            }

            // The session receiver callbacks are cooked Blueprint events and
            // are not guaranteed to cross the global ProcessEvent observer.
            // Accept stock creation when the native create boundary fired and
            // the authoritative lobby FSM reached InRoom. This is stronger
            // evidence than an observer callback and avoids treating a real
            // room as a timeout.
            if (s_create_player_session_observe_calls.load(
                    std::memory_order_acquire) != 0 &&
                find_active_player_match_in_room_state(player_match_scene))
            {
                m_create_requested = true;
                m_create_request_ok = true;
                m_player_match_in_room_ok = true;
                m_player_match_in_room_failure = "ok-authoritative-lobby-FSM";
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineComplete;
                m_host_room_create_failure = "ok";
                emit_host_room_create_pipeline_trace(
                    "native-create-and-in-room-complete", true,
                    player_match_scene, tick);
                return true;
            }

            if (use_targeted_native_player_session_create())
            {
                return service_host_native_create_pipeline(nav, tick);
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineComplete)
            {
                return m_create_request_ok;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineFailed)
            {
                return false;
            }

            if (m_host_room_create_start_tick == 0)
                m_host_room_create_start_tick = tick;

            if (m_host_room_create_last_step_tick == tick)
                return false;

            m_create_requested = true;
            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineNone)
            {
                std::string state_reason;
                ++m_host_room_create_attempts;
                m_host_room_create_make_room_requested = true;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_make_room_ok =
                    request_player_match_lobby_state(
                        player_match_scene, L"MakeRoom",
                        state_reason, tick);
                m_host_room_create_failure = state_reason;
                if (!m_host_room_create_make_room_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "make-room-request-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineMakeRoomRequested;
                emit_host_room_create_pipeline_trace(
                    "make-room-requested", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineMakeRoomRequested)
            {
                m_host_room_create_last_step_tick = tick;
                m_player_match_poll_requested = true;
                ++m_player_match_poll_count;
                m_host_room_create_make_room_poll_ok =
                    call_player_match_polling_change_state(
                        player_match_scene);
                m_player_match_poll_ok = m_host_room_create_make_room_poll_ok;
                m_host_room_create_failure =
                    m_host_room_create_make_room_poll_ok
                        ? "MakeRoom PollingChangeState ok"
                        : "MakeRoom PollingChangeState failed";
                if (!m_host_room_create_make_room_poll_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "make-room-poll-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineMakeRoomPolled;
                emit_host_room_create_pipeline_trace(
                    "make-room-polled", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineMakeRoomPolled)
            {
                if (!m_host_room_create_private_room_enabled)
                {
                    std::string private_reason;
                    m_host_room_create_last_step_tick = tick;
                    m_host_room_create_private_room_readback_attempted = true;
                    const bool private_ok =
                        set_player_match_private_room_value(private_reason);
                    m_host_room_create_private_room_readback_ok = private_ok;
                    m_host_room_create_private_room_readback_value =
                        private_ok ? 0 : -1;
                    m_host_room_create_private_room_readback_path =
                        "GameDataUnit(privateSlot).SetValue(0)";
                    m_host_room_create_private_room_readback_failure =
                        private_ok ? "ok" : private_reason;
                    m_host_room_create_failure = private_reason;
                    if (!private_ok)
                    {
                        emit_host_room_create_pipeline_trace(
                            "semantic-private-room-waiting", false,
                            player_match_scene, tick);
                        return false;
                    }
                    m_host_room_create_private_room_enabled = true;
                    emit_host_room_create_pipeline_trace(
                        "semantic-private-room-set", true,
                        player_match_scene, tick);
                    return false;
                }

                std::string decide_reason;
                m_host_room_create_decide_requested = true;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_decide_ok =
                    send_player_match_create_room_command(
                        nav, player_match_scene, tick, decide_reason);
                m_host_room_create_failure = decide_reason;
                if (!m_host_room_create_decide_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "semantic-creation-decide-waiting", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_last_decide_tick = tick;
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineDecideSent;
                emit_host_room_create_pipeline_trace(
                    "semantic-creation-decide-sent", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineDecideSent)
            {
                m_host_room_create_last_step_tick = tick;
                m_player_match_poll_requested = true;
                ++m_player_match_poll_count;
                m_host_room_create_make_connecting_poll_ok =
                    call_player_match_polling_change_state(
                        player_match_scene);
                m_player_match_poll_ok =
                    m_host_room_create_make_connecting_poll_ok;
                m_host_room_create_failure =
                    m_host_room_create_make_connecting_poll_ok
                        ? "post-Decide PollingChangeState ok; "
                          "waiting-for-OnCreateSession"
                        : "post-Decide PollingChangeState failed";
                if (!m_host_room_create_make_connecting_poll_ok)
                {
                    if (tick >= m_host_room_create_start_tick &&
                        tick - m_host_room_create_start_tick >=
                            kHostRoomCreateWaitTicks)
                    {
                        m_host_room_create_pipeline_step =
                            kHostRoomCreatePipelineFailed;
                        m_host_room_create_failure =
                            "post-Decide PollingChangeState timeout";
                    }
                    emit_host_room_create_pipeline_trace(
                        "post-decide-poll-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineWaitingForCreateSession;
                emit_host_room_create_pipeline_trace(
                    "post-decide-polled-waiting-for-create-session", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineMakeConnectingRequested)
            {
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_make_connecting_poll_ok =
                    call_player_match_polling_change_state(
                        player_match_scene);
                m_host_room_create_failure =
                    m_host_room_create_make_connecting_poll_ok
                        ? "MakeConnecting PollingChangeState ok"
                        : "MakeConnecting PollingChangeState failed";
                if (!m_host_room_create_make_connecting_poll_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "make-connecting-poll-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineMakeConnectingPolled;
                emit_host_room_create_pipeline_trace(
                    "make-connecting-polled", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineMakeConnectingPolled)
            {
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineWaitingForCreateSession;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_failure =
                    "waiting-for-OnCreateSession";
                emit_host_room_create_pipeline_trace(
                    "waiting-for-create-session", false,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineWaitingForCreateSession)
            {
                if (m_create_callback_seen && !m_create_callback_result)
                {
                    m_host_room_create_pipeline_step =
                        kHostRoomCreatePipelineFailed;
                    m_host_room_create_failure =
                        "OnCreateSession result false";
                    emit_host_room_create_pipeline_trace(
                        "create-session-result-false", false,
                        player_match_scene, tick);
                    return false;
                }
                // A consumed stock UI Decide does not prove that the UMG
                // owner committed StartCreateRoom.  Fresh two-process traces
                // have observed the creation window remain active with zero
                // CreatePlayerSession calls and no callback.  Retry only that
                // same stock command, and only while the native create hook
                // proves no request has escaped.  Once native creation is
                // observed, never inject another Decide.
                const uint64_t create_observe_calls =
                    s_create_player_session_observe_calls.load(
                        std::memory_order_acquire);
                const bool decide_retry_due =
                    ShouldRetryRollbackHostCreateDecide(
                        create_observe_calls,
                        m_host_room_create_decide_retry_count,
                        m_host_room_create_decide_retry_active,
                        m_host_room_create_last_decide_tick,
                        tick,
                        kHostRoomCreateDecideRetryTicks,
                        kHostRoomCreateMaxDecideRetries);
                if (decide_retry_due)
                {
                    m_host_room_create_decide_retry_active = true;
                    std::string retry_reason;
                    const bool retry_ok =
                        send_player_match_create_room_command(
                            nav, player_match_scene, tick, retry_reason);
                    m_host_room_create_failure =
                        "stock Decide retry: " + retry_reason;
                    if (!retry_ok)
                    {
                        emit_host_room_create_pipeline_trace(
                            "creation-decide-retry-pending", false,
                            player_match_scene, tick);
                        return false;
                    }

                    m_host_room_create_decide_retry_active = false;
                    ++m_host_room_create_decide_retry_count;
                    m_host_room_create_last_decide_tick = tick;
                    m_host_room_create_decide_ok = true;
                    m_host_room_create_last_step_tick = tick;
                    m_player_match_poll_requested = true;
                    ++m_player_match_poll_count;
                    m_host_room_create_make_connecting_poll_ok =
                        call_player_match_polling_change_state(
                            player_match_scene);
                    m_player_match_poll_ok =
                        m_host_room_create_make_connecting_poll_ok;
                    emit_host_room_create_pipeline_trace(
                        "creation-decide-retried", true,
                        player_match_scene, tick);
                    return false;
                }
                if (tick >= m_host_room_create_start_tick &&
                    tick - m_host_room_create_start_tick >=
                        kHostRoomCreateWaitTicks)
                {
                    m_host_room_create_pipeline_step =
                        kHostRoomCreatePipelineFailed;
                    m_host_room_create_failure =
                        "OnCreateSession timeout";
                    emit_host_room_create_pipeline_trace(
                        "create-session-timeout", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_failure =
                    "waiting-for-OnCreateSession";
                emit_host_room_create_pipeline_trace(
                    "waiting-for-create-session", false,
                    player_match_scene, tick);
                return false;
            }

            m_host_room_create_pipeline_step =
                kHostRoomCreatePipelineFailed;
            m_host_room_create_failure =
                "host-room-create-pipeline-invalid-step";
            emit_host_room_create_pipeline_trace(
                "invalid-step", false, player_match_scene, tick);
            return false;
        }
