        static bool resolve_active_game_instance(
            RC::Unreal::UObject*& out,
            std::string& reason) noexcept
        {
            out = nullptr;
            void* engine_raw = nullptr;
            if (!ReplayScrubDiag::read_gengine_ptr(&engine_raw))
            {
                reason = "GEngine unavailable";
                return false;
            }

            void* viewport_raw = nullptr;
            if (!SafeReadPtr(static_cast<uint8_t*>(engine_raw) +
                                 ReplayScrubDiag::kUEngine_GameViewport_Off,
                             &viewport_raw) || !viewport_raw)
            {
                reason = "GameViewport unavailable";
                return false;
            }

            void* world_raw = nullptr;
            if (!ReplayScrubDiag::safe_get_world_vfunc_138(viewport_raw,
                                                           &world_raw) &&
                !ReplayScrubDiag::safe_get_world(
                    reinterpret_cast<RC::Unreal::UObject*>(viewport_raw),
                    &world_raw))
            {
                reason = "UWorld unavailable";
                return false;
            }

            __try
            {
                auto* world_obj =
                    reinterpret_cast<RC::Unreal::UObject*>(world_raw);
                auto** gi = world_obj
                    ? world_obj->GetValuePtrByPropertyNameInChain<
                          RC::Unreal::UObject*>(L"OwningGameInstance")
                    : nullptr;
                if (gi && *gi)
                {
                    out = *gi;
                    return true;
                }
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
            }

            reason = "OwningGameInstance unavailable";
            return false;
        }

        static RC::Unreal::UObject* call_static_uobject_return(
            const wchar_t* object_path,
            const wchar_t* function_name) noexcept
        {
            if (!object_path || !function_name) return nullptr;
            auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                RC::Unreal::UObject*>(nullptr, nullptr, object_path);
            if (!safe_is_real(cdo)) return nullptr;
            auto* fn = cdo->GetFunctionByNameInChain(function_name);
            if (!fn) return nullptr;
            struct Params
            {
                RC::Unreal::UObject* ReturnValue {nullptr};
            } params{};
            if (!safe_process_event(cdo, fn, &params)) return nullptr;
            return safe_is_real(params.ReturnValue) ? params.ReturnValue
                                                    : nullptr;
        }

