        static RC::Unreal::UObject* resolve_or_create_gameflow_automation(
            RC::Unreal::UObject* outer,
            std::string& source) noexcept
        {
            (void)outer;
            source.clear();
            for (const wchar_t* name :
                 {L"BP_UIAutomation_C", L"UIGameFlowAutomation"})
            {
                RC::Unreal::UObject* obj = nullptr;
                try
                {
                    obj = RC::Unreal::UObjectGlobals::FindFirstOf(name);
                }
                catch (...)
                {
                    obj = nullptr;
                }
                if (safe_is_real(obj) && !object_is_uclass(obj))
                {
                    source = std::string("instance-findfirst:") +
                             (name && name[0] == L'B'
                                  ? "BP_UIAutomation_C"
                                  : "UIGameFlowAutomation");
                    return obj;
                }
            }

            std::string class_source;
            RC::Unreal::UClass* klass =
                resolve_bp_ui_automation_class(class_source);
            (void)klass;
            source = class_source.empty()
                ? "unavailable"
                : "diagnostic-reflection-disabled:" + class_source;
            return nullptr;
        }

