        bool resolve_gameflow_natives() noexcept
        {
            if (m_lux_datatable_path_init_as_null &&
                m_lux_datatable_path_dtor &&
                m_copy_current_gameflow_scene_data_path &&
                m_lookup_lux_datatable_object_field_path &&
                m_read_lux_datatable_path_string_field &&
                m_gameflow_current_scene_stop_complete)
            {
                return true;
            }
            const uintptr_t base = NativeBinding::imageBase();
            if (!base) return false;
            m_lux_datatable_path_init_as_null =
                reinterpret_cast<LuxDataTablePathInitAsNullFn>(
                    base + kRVA_LuxDataTablePathInitAsNull);
            m_lux_datatable_path_dtor =
                reinterpret_cast<LuxDataTablePathDtorFn>(
                    base + kRVA_LuxDataTablePathDtor);
            m_copy_current_gameflow_scene_data_path =
                reinterpret_cast<CopyCurrentGameFlowSceneDataPathFn>(
                    base + kRVA_CopyCurrentGameFlowSceneDataPath);
            m_lookup_lux_datatable_object_field_path =
                reinterpret_cast<LookupLuxDataTableObjectFieldPathFn>(
                    base + kRVA_LookupLuxDataTableObjectFieldPath);
            m_read_lux_datatable_path_string_field =
                reinterpret_cast<ReadLuxDataTablePathStringFieldFn>(
                    base + kRVA_ReadLuxDataTablePathStringField);
            m_gameflow_current_scene_stop_complete =
                reinterpret_cast<UIGameFlowManagerCurrentSceneStopCompleteFn>(
                    base + kRVA_UIGameFlowManagerCurrentSceneStopComplete);
            return m_lux_datatable_path_init_as_null != nullptr &&
                   m_lux_datatable_path_dtor != nullptr &&
                   m_copy_current_gameflow_scene_data_path != nullptr &&
                   m_lookup_lux_datatable_object_field_path != nullptr &&
                   m_read_lux_datatable_path_string_field != nullptr &&
                   m_gameflow_current_scene_stop_complete != nullptr;
        }


        template <typename Resolver>
        RC::Unreal::UObject* resolve_cached_navigation_object(
            OnlineNavigatorObjectCache& cache,
            std::chrono::milliseconds interval,
            Resolver&& resolver) noexcept
        {
            const auto now = std::chrono::steady_clock::now();
            if (cache.attempted
                && now - cache.last_validation < interval)
            {
                ++cache.cache_hits;
                return cache.object;
            }

            cache.attempted = true;
            cache.last_validation = now;
            ++cache.validations;
            if (cache.object && safe_is_real(cache.object))
                return cache.object;

            cache.object = nullptr;
            ++cache.searches;
            try
            {
                cache.object = resolver();
            }
            catch (...)
            {
                cache.object = nullptr;
            }
            return cache.object;
        }

        static void remember_navigation_object(
            OnlineNavigatorObjectCache& cache,
            RC::Unreal::UObject* object) noexcept
        {
            if (!object) return;
            if (cache.object != object)
            {
                cache.object = object;
                cache.last_validation = std::chrono::steady_clock::now();
                cache.attempted = true;
            }
        }

        RollbackP2PUObjectIdentity describe_navigation_object(
            RC::Unreal::UObject* object) noexcept
        {
            if (!object) return {};
            const auto now = std::chrono::steady_clock::now();
            for (auto& entry : m_online_nav_identity_cache)
            {
                if (entry.object == object)
                {
                    if (now - entry.last_validation
                        < kOnlineNavigatorIdentityRevalidateInterval)
                    {
                        ++m_online_nav_identity_cache_hits;
                        return entry.identity;
                    }
                    ++m_online_nav_identity_cache_misses;
                    entry.last_validation = now;
                    entry.identity = describe_uobject(object);
                    return entry.identity;
                }
            }

            ++m_online_nav_identity_cache_misses;
            auto& entry = m_online_nav_identity_cache[
                m_online_nav_identity_cache_cursor
                    % m_online_nav_identity_cache.size()];
            ++m_online_nav_identity_cache_cursor;
            entry.object = object;
            entry.last_validation = now;
            entry.identity = describe_uobject(object);
            return entry.identity;
        }

        void reset_online_navigator_caches() noexcept
        {
            m_online_nav_umg_util_cache = {};
            m_online_nav_game_flow_manager_cache = {};
            m_online_nav_session_hub_cache = {};
            m_online_nav_ui_game_content_cache = {};
            m_online_nav_automation_cache = {};
            m_online_nav_automation_source.clear();
            m_online_nav_identity_cache = {};
            m_online_nav_identity_cache_cursor = 0;
            m_online_nav_identity_cache_hits = 0;
            m_online_nav_identity_cache_misses = 0;
        }

        OnlineNavigatorObjects resolve_online_navigator_objects(
            bool discover_game_flow_automation = false) noexcept
        {
            OnlineNavigatorObjects nav{};
            nav.umg_util = resolve_cached_navigation_object(
                m_online_nav_umg_util_cache,
                kOnlineNavigatorObjectRevalidateInterval,
                []() -> RC::Unreal::UObject* {
                    RC::Unreal::UObject* object =
                        RC::Unreal::UObjectGlobals::FindFirstOf(L"UMGUtil");
                    return object ? object : resolve_umg_util_via_library();
                });
            if (nav.umg_util)
            {
                (void)safe_get_uobject_property(
                    nav.umg_util, L"UIGameFlowManager",
                    nav.game_flow_manager);
                (void)safe_get_uobject_property(
                    nav.umg_util, L"UIGameFlowAutomation",
                    nav.game_flow_automation);
                if (nav.game_flow_manager)
                {
                    remember_navigation_object(
                        m_online_nav_game_flow_manager_cache,
                        nav.game_flow_manager);
                }
                if (nav.game_flow_automation)
                {
                    remember_navigation_object(
                        m_online_nav_automation_cache,
                        nav.game_flow_automation);
                    nav.game_flow_automation_source = "umg-property";
                }
            }
            if (!nav.game_flow_manager)
            {
                nav.game_flow_manager = resolve_cached_navigation_object(
                    m_online_nav_game_flow_manager_cache,
                    kOnlineNavigatorObjectRevalidateInterval,
                    []() -> RC::Unreal::UObject* {
                        RC::Unreal::UObject* object =
                            resolve_gameflow_manager_via_library();
                        return object ? object
                            : RC::Unreal::UObjectGlobals::FindFirstOf(
                                  L"LuxUIGameFlowManager");
                    });
            }
            if (!nav.game_flow_automation
                && discover_game_flow_automation)
            {
                nav.game_flow_automation = resolve_cached_navigation_object(
                    m_online_nav_automation_cache,
                    kOnlineNavigatorAutomationRetryInterval,
                    [this, &nav]() -> RC::Unreal::UObject* {
                        std::string source;
                        RC::Unreal::UObject* object =
                            resolve_or_create_gameflow_automation(
                                nav.umg_util, source);
                        m_online_nav_automation_source = std::move(source);
                        return object;
                    });
                nav.game_flow_automation_source =
                    m_online_nav_automation_source.empty()
                        ? "automation-probe-cached-negative"
                        : m_online_nav_automation_source;
            }
            else if (!nav.game_flow_automation)
            {
                // The stock driver uses semantic scene/session calls. Do not
                // scan the whole object array for an optional diagnostic
                // automation object on every engine tick.
                nav.game_flow_automation_source =
                    "automation-discovery-not-requested";
            }
            if (nav.game_flow_manager)
            {
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"CurrentScene",
                    nav.current_scene);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"NextScene", nav.next_scene);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"CeBankManager",
                    nav.ce_bank_manager);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"SigninManager",
                    nav.signin_manager);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"SessionHub", nav.session_hub);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"BattleLauncher",
                    nav.battle_launcher);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"UIGameContent",
                    nav.ui_game_content);

                auto* gfm = reinterpret_cast<uint8_t*>(
                    nav.game_flow_manager);
                void* raw = nullptr;
                if (SafeReadPtr(gfm + 0x270, &raw) && raw)
                {
                    nav.match_lobby =
                        reinterpret_cast<RC::Unreal::UObject*>(raw);
                }
                raw = nullptr;
                if (SafeReadPtr(gfm + 0x150, &raw))
                    nav.current_scene_direct =
                        reinterpret_cast<RC::Unreal::UObject*>(raw);
                raw = nullptr;
                if (SafeReadPtr(gfm + 0x158, &raw))
                    nav.next_scene_direct =
                        reinterpret_cast<RC::Unreal::UObject*>(raw);
                uint8_t flag = 0;
                nav.manager_ready_flag_ok =
                    SafeReadBytes(gfm + 0xF8, &flag, sizeof(flag));
                nav.manager_ready_flag =
                    nav.manager_ready_flag_ok && flag != 0;
                flag = 0;
                nav.manager_start_latch_flag_ok =
                    SafeReadBytes(gfm + 0xF9, &flag, sizeof(flag));
                nav.manager_start_latch_flag =
                    nav.manager_start_latch_flag_ok && flag != 0;
                flag = 0;
                nav.manager_enable_change_flag_ok =
                    SafeReadBytes(gfm + 0xFA, &flag, sizeof(flag));
                nav.manager_enable_change_flag =
                    nav.manager_enable_change_flag_ok && flag != 0;
                if (!nav.current_scene &&
                    safe_is_real(nav.current_scene_direct))
                {
                    nav.current_scene = nav.current_scene_direct;
                }
                if (!nav.next_scene && safe_is_real(nav.next_scene_direct))
                    nav.next_scene = nav.next_scene_direct;
            }
            if (!nav.session_hub)
            {
                nav.session_hub = resolve_cached_navigation_object(
                    m_online_nav_session_hub_cache,
                    kOnlineNavigatorObjectRevalidateInterval,
                    []() -> RC::Unreal::UObject* {
                        return RC::Unreal::UObjectGlobals::FindFirstOf(
                            L"LuxorSessionHub");
                    });
            }
            else
            {
                remember_navigation_object(
                    m_online_nav_session_hub_cache, nav.session_hub);
            }
            if (!nav.ui_game_content)
            {
                nav.ui_game_content = resolve_cached_navigation_object(
                    m_online_nav_ui_game_content_cache,
                    kOnlineNavigatorObjectRevalidateInterval,
                    []() -> RC::Unreal::UObject* {
                        return RC::Unreal::UObjectGlobals::FindFirstOf(
                            L"LuxUIGameContent");
                    });
            }
            else
            {
                remember_navigation_object(
                    m_online_nav_ui_game_content_cache,
                    nav.ui_game_content);
            }
            if (nav.game_flow_automation)
            {
                (void)safe_get_fstring_property(
                    nav.game_flow_automation, L"CurrentSceneName",
                    nav.current_scene_name);
                (void)safe_get_fstring_property(
                    nav.game_flow_automation, L"PrevScenename",
                    nav.prev_scene_name);
            }
            nav.ready_to_start_ok = call_bool_query(
                nav.game_flow_manager, L"IsReadyToStart",
                nav.ready_to_start);
            nav.enable_change_scene_ok = call_bool_query(
                nav.game_flow_manager, L"IsEnableChangeScene",
                nav.enable_change_scene);
            nav.current_scene_identity =
                describe_navigation_object(nav.current_scene);
            nav.next_scene_identity =
                describe_navigation_object(nav.next_scene);
            nav.next_scene_direct_identity =
                describe_navigation_object(nav.next_scene_direct);
            nav.match_lobby_identity =
                describe_navigation_object(nav.match_lobby);
            nav.battle_launcher_identity =
                describe_navigation_object(nav.battle_launcher);
            return nav;
        }

        bool change_gameflow_scene(RC::Unreal::UObject* owner,
                                   const wchar_t* transition_tag,
                                   const char* owner_name,
                                   std::string& reason) noexcept
        {
            if (!safe_is_real(owner))
            {
                reason = std::string(owner_name ? owner_name : "owner") +
                         " unavailable";
                return false;
            }
            auto* fn = owner->GetFunctionByNameInChain(L"ChangeScene");
            if (!fn)
            {
                reason = std::string(owner_name ? owner_name : "owner") +
                         ".ChangeScene unavailable";
                return false;
            }
            if (!resolve_gameflow_natives())
            {
                reason = "native UIDataObject initializer unavailable";
                return false;
            }

            struct ChangeSceneParams
            {
                RC::Unreal::FString TransitionTag;
                LuxDataTablePathNative InheritedData {};
                NullScriptDelegateNative ChangeSceneParam {};

                explicit ChangeSceneParams(const wchar_t* tag)
                    : TransitionTag(tag ? tag : L"")
                {}
            };
            static_assert(sizeof(ChangeSceneParams) == 0x38,
                          "GameFlow ChangeScene params drifted");

            ChangeSceneParams params{transition_tag};
            if (!safe_native_lux_datatable_path_init_as_null(
                    m_lux_datatable_path_init_as_null,
                    &params.InheritedData))
            {
                reason = "native UIDataObject init failed";
                return false;
            }

            const bool ok = safe_process_event(owner, fn, &params);
            safe_native_lux_datatable_path_dtor(
                m_lux_datatable_path_dtor, &params.InheritedData);
            if (!ok)
            {
                reason = std::string(owner_name ? owner_name : "owner") +
                         ".ChangeScene failed";
                return false;
            }
            reason = std::string("called ") +
                     (owner_name ? owner_name : "owner") +
                     ".ChangeScene";
            return true;
        }

        static RC::Unreal::FProperty* reflected_param_any(
            RC::Unreal::UFunction* function,
            const wchar_t* first,
            const wchar_t* second = nullptr) noexcept
        {
            RC::Unreal::FProperty* prop = reflected_param(function, first);
            if (!prop && second)
                prop = reflected_param(function, second);
            return prop;
        }

        static bool reflected_write_i32(
            RC::Unreal::FProperty* prop,
            void* params,
            int32_t value) noexcept
        {
            if (!prop || !params) return false;
            void* slot = prop->ContainerPtrToValuePtr<void>(params);
            if (!slot || prop->GetSize() < static_cast<int32_t>(sizeof(value)))
                return false;
            return SafeWriteBytes(slot, &value, sizeof(value));
        }

        static bool safe_read_raw_fstring_header(
            const void* p,
            RawFStringNative& out) noexcept
        {
            out = {};
            return p && SafeReadBytes(p, &out, sizeof(out));
        }

        static bool safe_read_wchar_at(const wchar_t* p,
                                       int32_t index,
                                       wchar_t& out) noexcept
        {
            out = L'\0';
            if (!p || index < 0) return false;
            __try
            {
                out = p[index];
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                out = L'\0';
                return false;
            }
        }

        static std::string narrow_wide_utf8(const std::wstring& wide)
        {
            if (wide.empty()) return {};
            const int need = WideCharToMultiByte(
                CP_UTF8, 0, wide.c_str(), static_cast<int>(wide.size()),
                nullptr, 0, nullptr, nullptr);
            if (need <= 0) return {};
            std::string out(static_cast<size_t>(need), '\0');
            WideCharToMultiByte(CP_UTF8, 0, wide.c_str(),
                                static_cast<int>(wide.size()), out.data(),
                                need, nullptr, nullptr);
            return out;
        }

        static bool safe_sample_raw_fstring(
            const RawFStringNative& s,
            int32_t max_chars,
            std::string& sample,
            uint64_t& hash) noexcept
        {
            sample.clear();
            hash = 0;
            if (!s.data || s.num <= 0 || s.max < s.num ||
                s.num > max_chars)
            {
                return false;
            }

            std::wstring wide;
            wide.reserve(static_cast<size_t>(s.num));
            uint64_t h = 1469598103934665603ull;
            for (int32_t i = 0; i < s.num && i < max_chars; ++i)
            {
                wchar_t ch = L'\0';
                if (!safe_read_wchar_at(s.data, i, ch))
                    return false;
                if (ch == L'\0')
                    break;
                wide.push_back(ch);
                const uint16_t code = static_cast<uint16_t>(ch);
                const uint8_t lo = static_cast<uint8_t>(code & 0xffu);
                const uint8_t hi = static_cast<uint8_t>(code >> 8);
                h ^= lo;
                h *= 1099511628211ull;
                h ^= hi;
                h *= 1099511628211ull;
            }
            sample = narrow_wide_utf8(wide);
            hash = wide.empty() ? 0 : h;
            return !wide.empty();
        }

        static bool safe_write_bool_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property,
            bool value,
            bool& read_ok,
            bool& observed) noexcept
        {
            read_ok = false;
            observed = !value;
            if (!safe_is_real(obj) || !property) return false;
            __try
            {
                bool* slot =
                    obj->GetValuePtrByPropertyNameInChain<bool>(property);
                if (!slot) return false;
                if (!SafeWriteBytes(slot, &value, sizeof(value)))
                    return false;
                read_ok = SafeReadBytes(slot, &observed, sizeof(observed));
                return read_ok && observed == value;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool safe_read_bool_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property,
            bool& observed) noexcept
        {
            observed = false;
            if (!safe_is_real(obj) || !property) return false;
            __try
            {
                bool* slot =
                    obj->GetValuePtrByPropertyNameInChain<bool>(property);
                if (!slot) return false;
                return SafeReadBytes(slot, &observed, sizeof(observed));
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool call_no_param_function(RC::Unreal::UObject* obj,
                                           const wchar_t* name) noexcept
        {
            if (!safe_is_real(obj) || !name) return false;
            auto* fn = obj->GetFunctionByNameInChain(name);
            if (!fn) return false;
            char no_params[1] {};
            return safe_process_event(obj, fn, no_params);
        }

        struct StockBattleReadyCall
        {
            RC::Unreal::UObject* object {nullptr};
            RC::Unreal::UFunction* function {nullptr};
        };

        static bool stock_battle_asset_release_ready_callback(
            void* context) noexcept
        {
            auto* call = reinterpret_cast<StockBattleReadyCall*>(context);
            if (!call || !safe_is_real(call->object) ||
                !safe_is_real(call->function))
            {
                return false;
            }
            char no_params[1] {};
            return safe_process_event(
                call->object, call->function, no_params);
        }

        static bool call_string_param_function(
            RC::Unreal::UObject* obj,
            const wchar_t* function_name,
            const wchar_t* parameter_name,
            const wchar_t* value) noexcept
        {
            if (!safe_is_real(obj) || !function_name || !parameter_name)
                return false;
            auto* fn = obj->GetFunctionByNameInChain(function_name);
            if (!fn) return false;
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 1024) return false;
            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            auto* property = RC::Unreal::CastField<
                RC::Unreal::FStrProperty>(
                    reflected_param(fn, parameter_name));
            if (!property) return false;
            property->InitializeValue_InContainer(params.data());
            bool ok = false;
            try
            {
                property->SetPropertyValueInContainer(
                    params.data(), RC::Unreal::FString(value ? value : L""));
                ok = safe_process_event(obj, fn, params.data());
            }
            catch (...)
            {
                ok = false;
            }
            property->DestroyValue_InContainer(params.data());
            return ok;
        }

