        static void steam_invite_delegate_dispatch_detour(
            void* task) noexcept
        {
            const uint64_t call = s_steam_invite_delegate_calls.fetch_add(
                1, std::memory_order_acq_rel) + 1;
            const auto* task_bytes =
                reinterpret_cast<const uint8_t*>(task);
            uint8_t task_success = 0;
            void* search = nullptr;
            int32_t search_result_count = -1;
            void* lobby_array = nullptr;
            int32_t lobby_count = -1;
            uint64_t first_lobby_id = 0;
            uint64_t local_user_id = 0;
            const bool task_success_read = task_bytes &&
                SafeReadUInt8(task_bytes + 0x19, &task_success);
            const bool search_read = task_bytes &&
                SafeReadPtr(task_bytes + 0x30, &search);
            const bool search_count_read = search && SafeReadInt32(
                static_cast<const uint8_t*>(search) + 0x10,
                &search_result_count);
            const bool lobby_array_read = task_bytes &&
                SafeReadPtr(task_bytes + 0x48, &lobby_array);
            const bool lobby_count_read = task_bytes &&
                SafeReadInt32(task_bytes + 0x50, &lobby_count);
            const bool first_lobby_read = lobby_array && lobby_count > 0 &&
                SafeReadUInt64(lobby_array, &first_lobby_id);
            const bool local_user_read = task_bytes &&
                SafeReadUInt64(task_bytes + 0x78, &local_user_id);
            RollbackP2PHarness* active =
                s_active_instance.load(std::memory_order_acquire);
            if (active && (active->m_cfg.observe_gameflow_requested ||
                           active->m_cfg.online_stage_requested))
            {
                ReplayTraceFields f;
                add_session_trace_identity(f);
                f.uinteger("call", call)
                 .boolean("passive_capture",
                          active->m_cfg.observe_gameflow_requested &&
                          !active->m_cfg.online_stage_requested)
                 .boolean("arguments_forwarded_unchanged", true)
                 .hex("async_task", reinterpret_cast<uintptr_t>(task))
                 .boolean("task_success_read", task_success_read)
                 .boolean("task_success", task_success != 0)
                 .boolean("search_read", search_read)
                 .hex("search", reinterpret_cast<uintptr_t>(search))
                 .boolean("search_count_read", search_count_read)
                 .integer("search_result_count", search_result_count)
                 .boolean("lobby_array_read", lobby_array_read)
                 .hex("lobby_array", reinterpret_cast<uintptr_t>(lobby_array))
                 .boolean("lobby_count_read", lobby_count_read)
                 .integer("lobby_count", lobby_count)
                 .boolean("first_lobby_read", first_lobby_read)
                 .uinteger("first_lobby_id", first_lobby_id)
                 .boolean("local_user_read", local_user_read)
                 .uinteger("local_user_id", local_user_id);
                ReplayDebugTrace::instance().event(
                    "rollback_steam_invite_delegate_observed", f);
            }
            auto* original = reinterpret_cast<
                SteamInviteDelegateDispatchFn>(
                    s_steam_invite_delegate_trampoline);
            if (original) original(task);
        }

