        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            uint32_t count_before = 0;
            (void)SafeReadUInt32(
                static_cast<const uint8_t*>(online_session) + 0xa60,
                &count_before);
            auto* original = reinterpret_cast<SteamAddNamedSessionFn>(
                s_steam_add_named_session_trampoline);
            const uint64_t result = original
                ? original(online_session, session_name, settings) : 0;
            uint32_t count_after = 0;
            (void)SafeReadUInt32(
                static_cast<const uint8_t*>(online_session) + 0xa60,
                &count_after);
            trace_steam_named_session_lifetime(
                "add", online_session, session_name, count_before,
                count_after, result, caller_rva);
            return result;
        }

