        static uint8_t luxor_network_available_check_detour(
            void* connect_system) noexcept
        {
            auto* original =
                reinterpret_cast<LuxorNetworkAvailableCheckFn>(
                    s_luxor_network_check_compat_trampoline);
            const uint8_t original_result =
                original ? original(connect_system) : 0;
            s_luxor_network_check_compat_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_luxor_network_check_compat_last_original.store(
                original_result, std::memory_order_release);
            if (original_result != 0)
            {
                s_luxor_network_check_compat_original_true.fetch_add(
                    1, std::memory_order_acq_rel);
                s_luxor_network_check_compat_last_returned.store(
                    original_result, std::memory_order_release);
                return original_result;
            }

            s_luxor_network_check_compat_original_false.fetch_add(
                1, std::memory_order_acq_rel);
            if (s_luxor_network_check_compat_enabled.load(
                    std::memory_order_acquire))
            {
                s_luxor_network_check_compat_forced_true.fetch_add(
                    1, std::memory_order_acq_rel);
                s_luxor_network_check_compat_last_returned.store(
                    1, std::memory_order_release);
                return 1;
            }

            s_luxor_network_check_compat_last_returned.store(
                0, std::memory_order_release);
            return 0;
        }

