        static bool read_vtable_target(
            void* object,
            size_t offset,
            uintptr_t& out) noexcept
        {
            out = 0;
            if (!object) return false;
            void* vtable = nullptr;
            void* target = nullptr;
            if (!SafeReadPtr(object, &vtable) || !vtable)
                return false;
            if (!SafeReadPtr(
                    reinterpret_cast<uint8_t*>(vtable) + offset,
                    &target) || !target)
            {
                return false;
            }
            out = reinterpret_cast<uintptr_t>(target);
            return true;
        }

        static bool install_debug_detour(
            std::unique_ptr<PLH::x64Detour>& storage,
            uintptr_t target,
            uint64_t detour,
            uint64_t& trampoline) noexcept
        {
            if (!target) return false;
            trampoline = 0;
            storage = std::make_unique<PLH::x64Detour>(
                static_cast<uint64_t>(target), detour, &trampoline);
            if (!storage->hook())
            {
                storage.reset();
                trampoline = 0;
                return false;
            }
            return true;
        }

