        template <typename Fn>
        static Fn steam_proc(HMODULE module, const char* name) noexcept
        {
            return module && name
                ? reinterpret_cast<Fn>(GetProcAddress(module, name))
                : nullptr;
        }

        static std::string steam_invite_metadata(
            const SteamInviteMetadataFns& fns,
            void* matchmaking,
            uint64_t lobby_id,
            const char* key) noexcept
        {
            if (!fns.GetLobbyData || !matchmaking || !lobby_id || !key)
                return {};
            const char* value =
                fns.GetLobbyData(matchmaking, lobby_id, key);
            if (!value) return {};
            const size_t len = strnlen_s(value, 512);
            return std::string(value, value + len);
        }

        static uint64_t steam_invite_metadata_u64(
            const SteamInviteMetadataFns& fns,
            void* matchmaking,
            uint64_t lobby_id,
            const char* key) noexcept
        {
            return parse_u64_ascii(steam_invite_metadata(
                fns, matchmaking, lobby_id, key));
        }

        bool load_steam_invite_metadata_fns() noexcept
        {
            HMODULE steam = GetModuleHandleW(L"steam_api64.dll");
            if (!steam)
                steam = LoadLibraryW(L"steam_api64.dll");
            if (!steam)
                return false;

            m_steam_fns.SteamClient =
                steam_proc<SteamInviteMetadataFns::SteamClientFn>(
                    steam, "SteamClient");
            m_steam_fns.CreateInterface =
                steam_proc<SteamInviteMetadataFns::SteamCreateInterfaceFn>(
                    steam, "SteamInternal_CreateInterface");
            m_steam_fns.GetHSteamUser =
                steam_proc<SteamInviteMetadataFns::GetHSteamUserFn>(
                    steam, "SteamAPI_GetHSteamUser");
            m_steam_fns.GetHSteamPipe =
                steam_proc<SteamInviteMetadataFns::GetHSteamPipeFn>(
                    steam, "SteamAPI_GetHSteamPipe");
            m_steam_fns.CreateSteamPipe =
                steam_proc<SteamInviteMetadataFns::CreateSteamPipeFn>(
                    steam, "SteamAPI_ISteamClient_CreateSteamPipe");
            m_steam_fns.ConnectToGlobalUser =
                steam_proc<SteamInviteMetadataFns::ConnectToGlobalUserFn>(
                    steam, "SteamAPI_ISteamClient_ConnectToGlobalUser");
            m_steam_fns.GetMatchmaking =
                steam_proc<SteamInviteMetadataFns::GetMatchmakingFn>(
                    steam, "SteamAPI_ISteamClient_GetISteamMatchmaking");
            m_steam_fns.GetUser =
                steam_proc<SteamInviteMetadataFns::GetUserFn>(
                    steam, "SteamAPI_ISteamClient_GetISteamUser");
            m_steam_fns.UserBLoggedOn =
                steam_proc<SteamInviteMetadataFns::UserBLoggedOnFn>(
                    steam, "SteamAPI_ISteamUser_BLoggedOn");
            m_steam_fns.UserGetSteamID =
                steam_proc<SteamInviteMetadataFns::UserGetSteamIDFn>(
                    steam, "SteamAPI_ISteamUser_GetSteamID");
            m_steam_fns.RequestLobbyData =
                steam_proc<SteamInviteMetadataFns::RequestLobbyDataFn>(
                    steam, "SteamAPI_ISteamMatchmaking_RequestLobbyData");
            m_steam_fns.GetLobbyData =
                steam_proc<SteamInviteMetadataFns::GetLobbyDataFn>(
                    steam, "SteamAPI_ISteamMatchmaking_GetLobbyData");
            m_steam_fns.GetLobbyDataCount =
                steam_proc<SteamInviteMetadataFns::GetLobbyDataCountFn>(
                    steam, "SteamAPI_ISteamMatchmaking_GetLobbyDataCount");
            m_steam_fns.GetNumLobbyMembers =
                steam_proc<SteamInviteMetadataFns::GetNumLobbyMembersFn>(
                    steam, "SteamAPI_ISteamMatchmaking_GetNumLobbyMembers");
            m_steam_fns.SetLobbyType =
                steam_proc<SteamInviteMetadataFns::SetLobbyTypeFn>(
                    steam, "SteamAPI_ISteamMatchmaking_SetLobbyType");

            return (m_steam_fns.SteamClient || m_steam_fns.CreateInterface)
                && m_steam_fns.GetHSteamUser
                && m_steam_fns.GetHSteamPipe
                && m_steam_fns.GetMatchmaking
                && m_steam_fns.GetUser
                && m_steam_fns.UserGetSteamID
                && m_steam_fns.RequestLobbyData
                && m_steam_fns.GetLobbyData
                && m_steam_fns.GetNumLobbyMembers
                && m_steam_fns.SetLobbyType;
        }

        void* resolve_steam_matchmaking(
            void* steam_client,
            int user,
            int pipe) noexcept
        {
            static constexpr const char* kVersions[] = {
                "SteamMatchMaking009",
                "SteamMatchMaking008",
            };
            for (const char* version : kVersions)
            {
                void* matchmaking = m_steam_fns.GetMatchmaking(
                    steam_client, user, pipe, version);
                if (matchmaking)
                {
                    m_steam_matchmaking_version = version;
                    return matchmaking;
                }
            }
            return nullptr;
        }

        void* resolve_steam_user(
            void* steam_client,
            int user,
            int pipe) noexcept
        {
            static constexpr const char* kVersions[] = {
                "SteamUser023", "SteamUser022", "SteamUser021",
                "SteamUser020", "SteamUser019", "SteamUser018",
                "SteamUser017",
            };
            for (const char* version : kVersions)
            {
                void* steam_user = m_steam_fns.GetUser(
                    steam_client, user, pipe, version);
                if (steam_user)
                {
                    m_steam_user_version = version;
                    return steam_user;
                }
            }
            return nullptr;
        }

        void* resolve_steam_client() noexcept
        {
            if (m_steam_fns.SteamClient)
            {
                void* steam_client = m_steam_fns.SteamClient();
                if (steam_client)
                {
                    m_steam_client_version = "SteamClient";
                    return steam_client;
                }
            }
            if (!m_steam_fns.CreateInterface)
                return nullptr;

            static constexpr const char* kVersions[] = {
                "SteamClient020", "SteamClient019", "SteamClient018",
                "SteamClient017", "SteamClient016", "SteamClient015",
            };
            for (const char* version : kVersions)
            {
                void* steam_client = m_steam_fns.CreateInterface(version);
                if (steam_client)
                {
                    m_steam_client_version = version;
                    return steam_client;
                }
            }
            return nullptr;
        }
        void capture_steam_identity_for_stock_fallback() noexcept
        {
            if (m_steam_local_id != 0) return;
            if (!load_steam_invite_metadata_fns()) return;
            void* steam_client = resolve_steam_client();
            if (!steam_client) return;
            int user = m_steam_fns.GetHSteamUser();
            int pipe = m_steam_fns.GetHSteamPipe();
            if (pipe == 0 && m_steam_fns.CreateSteamPipe)
                pipe = m_steam_fns.CreateSteamPipe(steam_client);
            if (user == 0 && pipe != 0 && m_steam_fns.ConnectToGlobalUser)
                user = m_steam_fns.ConnectToGlobalUser(steam_client, pipe);
            m_steam_user = resolve_steam_user(steam_client, user, pipe);
            m_steam_matchmaking = resolve_steam_matchmaking(
                steam_client, user, pipe);
            if (m_steam_user)
            {
                if (m_steam_fns.UserGetSteamID)
                    m_steam_local_id =
                        m_steam_fns.UserGetSteamID(m_steam_user);
                if (m_steam_fns.UserBLoggedOn)
                    m_steam_user_logged_on =
                        m_steam_fns.UserBLoggedOn(m_steam_user);
            }
        }

        void service_steam_private_lobby_if_needed(bool is_host) noexcept
        {
            if (!is_host ||
                !RollbackStockJoinRouteUsesAuthenticatedOffer(
                    m_cfg.stock_join_route))
                return;
            if (m_steam_private_lobby_attempted)
            {
                if (m_steam_private_lobby_id != 0
                    && m_native_named_session_lobby_id ==
                        m_steam_private_lobby_id
                    && m_steam_matchmaking
                    && m_steam_fns.GetNumLobbyMembers)
                {
                    m_steam_private_lobby_member_count =
                        m_steam_fns.GetNumLobbyMembers(
                            m_steam_matchmaking,
                            m_steam_private_lobby_id);
                    if (m_steam_private_lobby_member_count > 2)
                    {
                        m_steam_private_lobby_ok = false;
                        m_steam_private_lobby_failure =
                            "unexpected-third-lobby-member";
                    }
                }
                return;
            }
            const bool injected_route =
                RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route);
            const bool route_creation_evidence = injected_route
                ? (m_host_room_create_decide_ok
                   && s_create_player_session_observe_calls.load(
                        std::memory_order_acquire) == 1
                   && s_create_player_session_private_overrides.load(
                        std::memory_order_acquire) == 0
                   && s_create_player_session_last_incoming_public_flag.load(
                        std::memory_order_acquire) == 0
                   && s_create_player_session_name_is_player_match.load(
                        std::memory_order_acquire))
                : (m_host_room_create_private_room_enabled
                   && m_host_room_create_private_room_down_count == 9
                   && m_host_room_create_private_room_right_count == 1
                   && m_host_room_create_private_room_up_count == 9
                   && m_host_room_create_decide_ok);
            if (m_native_named_session_lobby_id == 0
                || !route_creation_evidence)
                return;
            capture_steam_identity_for_stock_fallback();
            if (m_steam_local_id == 0
                || m_native_named_session_lobby_owner_id !=
                    m_steam_local_id)
                return;
            m_steam_private_lobby_attempted = true;
            m_steam_private_lobby_id = m_native_named_session_lobby_id;
            m_steam_private_lobby_type_attempted = true;
            // Steamworks ELobbyType::k_ELobbyTypePrivate is zero. Enforce it
            // at the Steam lobby itself before publishing the authenticated
            // offer; the native PublicFlag observation alone cannot prove
            // that the lobby is absent from public browsing.
            m_steam_private_lobby_type_set =
                m_steam_matchmaking && m_steam_fns.SetLobbyType
                && m_steam_fns.SetLobbyType(
                    m_steam_matchmaking,
                    m_steam_private_lobby_id,
                    0);
            m_steam_private_lobby_member_count =
                m_steam_matchmaking && m_steam_fns.GetNumLobbyMembers
                    ? m_steam_fns.GetNumLobbyMembers(
                        m_steam_matchmaking,
                        m_steam_private_lobby_id)
                    : -1;
            m_steam_private_lobby_pre_invite_member_count =
                m_steam_private_lobby_member_count;
            const uint64_t create_observe_calls =
                s_create_player_session_observe_calls.load(
                    std::memory_order_acquire);
            const uint32_t create_public_flag =
                s_create_player_session_last_public_flag.load(
                    std::memory_order_acquire);
            RollbackPrivateLobbyEvidence privacy {};
            privacy.player_match_session_observed =
                create_observe_calls != 0
                && s_create_player_session_name_is_player_match.load(
                    std::memory_order_acquire)
                && s_create_player_session_private_overrides.load(
                    std::memory_order_acquire) == 0;
            privacy.native_public_flag =
                create_public_flag == 0xff
                    ? -1 : static_cast<int32_t>(create_public_flag);
            privacy.steam_lobby_type_attempted =
                m_steam_private_lobby_type_attempted;
            privacy.steam_lobby_type_private =
                m_steam_private_lobby_type_set;
            privacy.lobby_id = m_steam_private_lobby_id;
            privacy.lobby_owner_id =
                m_native_named_session_lobby_owner_id;
            privacy.local_steam_id = m_steam_local_id;
            privacy.pre_invite_member_count =
                m_steam_private_lobby_pre_invite_member_count;
            m_steam_private_lobby_ok =
                RollbackPrivateLobbyReady(privacy);
            m_steam_private_lobby_failure = m_steam_private_lobby_ok
                ? "ok"
                : (create_observe_calls == 0
                    ? "CreatePlayerSession-setting-not-observed"
                    : (create_public_flag != 0
                        ? "CreatePlayerSession-PublicFlag-true"
                        : (s_create_player_session_private_overrides.load(
                               std::memory_order_acquire) != 0
                            ? "CreatePlayerSession-arguments-modified"
                        : (!m_steam_private_lobby_type_set
                            ? "Steam-SetLobbyType-private-failed"
                        : (m_steam_private_lobby_member_count != 1
                            ? "pre-invite-lobby-member-count-not-one"
                            : "stock-private-room-not-proven")))));
            m_host_room_create_private_room_readback_attempted = true;
            m_host_room_create_private_room_readback_ok =
                m_steam_private_lobby_ok;
            m_host_room_create_private_room_readback_value =
                create_public_flag == 0xff
                    ? -1 : static_cast<int32_t>(create_public_flag);
            m_host_room_create_private_room_readback_path =
                "native PublicFlag plus Steam SetLobbyType(private)";
            m_host_room_create_private_room_readback_failure =
                m_steam_private_lobby_failure;
            const int lobby_data_count =
                m_steam_fns.GetLobbyDataCount
                    ? m_steam_fns.GetLobbyDataCount(
                        m_steam_matchmaking,
                        m_steam_private_lobby_id)
                    : -1;
            ReplayTraceFields f;
            f.boolean("ok", m_steam_private_lobby_ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .hex("lobby_id", m_steam_private_lobby_id)
             .hex("owner_steam_id", m_steam_local_id)
             .integer("pre_invite_member_count",
                      m_steam_private_lobby_pre_invite_member_count)
             .uinteger("create_player_session_observe_calls",
                       create_observe_calls)
             .uinteger("create_player_session_public_flag",
                       create_public_flag)
             .uinteger("create_player_session_incoming_public_flag",
                       s_create_player_session_last_incoming_public_flag.load(
                           std::memory_order_acquire))
             .uinteger("create_player_session_private_overrides",
                       s_create_player_session_private_overrides.load(
                           std::memory_order_acquire))
             .boolean("steam_set_lobby_type_private_attempted",
                      m_steam_private_lobby_type_attempted)
             .boolean("steam_set_lobby_type_private_ok",
                      m_steam_private_lobby_type_set)
             .integer("lobby_data_count", lobby_data_count)
             .string("lobby_build_id", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_steam_private_lobby_id, "buildid"))
             .string("lobby_session_flags", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_steam_private_lobby_id, "SESSIONFLAGS"))
             .string("lobby_owning_id", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_steam_private_lobby_id, "OWNINGID"))
             .string("lobby_p2p_addr", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_steam_private_lobby_id, "P2PADDR"))
             .string("lobby_p2p_port", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_steam_private_lobby_id, "P2PPORT"))
             .uinteger("native_public_flag", create_public_flag)
             .string("failure", m_steam_private_lobby_failure);
            ReplayDebugTrace::instance().event(
                "rollback_steam_lobby_private", f);
        }

        static bool safe_construct_steam_invite_event(
            ConstructSteamInviteAcceptedEventFn constructor,
            SteamLobbyInviteAcceptedEventNative* event,
            void* online_subsystem_steam,
            const SteamUniqueIdInlineNative* friend_id,
            const SteamUniqueIdInlineNative* lobby_id) noexcept
        {
            if (!constructor || !event || !online_subsystem_steam
                || !friend_id || !lobby_id)
                return false;
            __try
            {
                return constructor(event, online_subsystem_steam,
                                   friend_id, lobby_id) == event;
            }
            __except (capture_steam_invite_event_exception(
                GetExceptionInformation()))
            {
                return false;
            }
        }

        static bool safe_queue_steam_invite_event(
            QueueSteamAsyncItemFn queue,
            void* online_subsystem_steam,
            SteamLobbyInviteAcceptedEventNative* event) noexcept
        {
            if (!queue || !online_subsystem_steam || !event) return false;
            __try
            {
                void* manager = *reinterpret_cast<void**>(
                    static_cast<uint8_t*>(online_subsystem_steam) + 0x280);
                if (!manager) return false;
                s_steam_invite_queued_event.store(
                    reinterpret_cast<uintptr_t>(event),
                    std::memory_order_release);
                queue(manager, event);
                return true;
            }
            __except (capture_steam_invite_event_exception(
                GetExceptionInformation()))
            {
                s_steam_invite_queued_event.store(
                    0, std::memory_order_release);
                return false;
            }
        }

        static void* safe_get_steam_subsystem_from_session(
            void* online_session_steam) noexcept
        {
            if (!online_session_steam) return nullptr;
            __try
            {
                // FOnlineSessionSteam's constructor stores its owning
                // FOnlineSubsystemSteam at +0xA20. The invite event's +0x10
                // field is this subsystem pointer; the event handler calls
                // subsystem virtual slot +0x18 to recover the shared session.
                auto* bytes = static_cast<uint8_t*>(online_session_steam);
                void* subsystem =
                    *reinterpret_cast<void**>(bytes + 0xA20);
                if (!subsystem) return nullptr;
                auto** vtable = *reinterpret_cast<void***>(subsystem);
                if (!vtable || !vtable[3]) return nullptr;
                return subsystem;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return nullptr;
            }
        }

        static int capture_steam_invite_event_exception(
            EXCEPTION_POINTERS* info) noexcept
        {
            if (info && info->ExceptionRecord)
            {
                s_steam_invite_event_exception_code.store(
                    info->ExceptionRecord->ExceptionCode,
                    std::memory_order_release);
                s_steam_invite_event_exception_address.store(
                    reinterpret_cast<uintptr_t>(
                        info->ExceptionRecord->ExceptionAddress),
                    std::memory_order_release);
            }
            return EXCEPTION_EXECUTE_HANDLER;
        }

        void service_native_invite_bridge_if_needed(
            bool is_sandbox,
            const OnlineNavigatorObjects& nav) noexcept
        {
            const bool injected_route =
                RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route);
            if (!is_sandbox || !m_stock_fallback_active
                || !m_stock_offer_valid
                || (!injected_route && !m_steam_join_lobby_ok))
                return;
            if (injected_route &&
                m_cfg.online_stage_wait_host_room_ready_marker &&
                !m_host_room_ready_marker_observed)
            {
                m_stock_native_bridge_failure =
                    "waiting-for-verified-host-room";
                return;
            }

            if (injected_route && !m_stock_native_event_dispatched)
            {
                if (m_steam_join_lobby_direct_call_count != 0
                    || m_steam_join_lobby_attempted)
                {
                    m_stock_native_bridge_failure =
                        "direct-JoinLobby-observed";
                    return;
                }
                if (!identity_contains_scene(
                        nav.current_scene_identity, "MainMenuScene"))
                {
                    m_stock_native_bridge_failure =
                        "guest-not-in-MainMenuScene";
                    return;
                }
                if (m_steam_local_id == 0
                    || m_stock_remote_offer.invitee_steam_id !=
                        m_steam_local_id)
                {
                    m_stock_native_bridge_failure =
                        "authenticated-invitee-mismatch";
                    return;
                }
                if (m_stock_remote_offer.owner_steam_id !=
                        m_stock_remote_offer.host_steam_id
                    || m_stock_remote_offer.owner_steam_id == 0)
                {
                    m_stock_native_bridge_failure =
                        "authenticated-lobby-owner-mismatch";
                    return;
                }
                if (m_native_named_session_lobby_id != 0)
                {
                    m_stock_native_bridge_failure =
                        "PlayerMatch-named-session-already-active";
                    return;
                }
            }

            if (!m_stock_metadata_requested)
            {
                m_stock_metadata_requested = true;
                m_stock_metadata_request_ok = m_steam_matchmaking
                    && m_steam_fns.RequestLobbyData
                    && m_steam_fns.RequestLobbyData(
                        m_steam_matchmaking,
                        m_stock_remote_offer.lobby_id);
                if (!m_stock_metadata_request_ok)
                {
                    m_stock_native_bridge_failure =
                        "RequestLobbyData-returned-false";
                    return;
                }
                m_stock_native_bridge_failure =
                    "waiting-for-lobby-metadata";
                return;
            }

            if (!m_stock_native_event_dispatched)
            {
                // Live-proven 2026-07-14: RequestLobbyData returning true is
                // only an async request acknowledgement. Dispatching SC6's
                // invite handler in that same tick gave it zero lobby fields;
                // Steam joined, then OnJoinSession failed with
                // SessionDoesNotExist. Do not dispatch until the stock
                // connection metadata is actually cached.
                const int data_count =
                    m_steam_matchmaking && m_steam_fns.GetLobbyDataCount
                        ? m_steam_fns.GetLobbyDataCount(
                            m_steam_matchmaking,
                            m_stock_remote_offer.lobby_id)
                        : 0;
                const bool metadata_ready = data_count > 0
                    && !steam_invite_metadata(
                        m_steam_fns, m_steam_matchmaking,
                        m_stock_remote_offer.lobby_id, "buildid").empty()
                    && !steam_invite_metadata(
                        m_steam_fns, m_steam_matchmaking,
                        m_stock_remote_offer.lobby_id,
                        "SESSIONFLAGS").empty()
                    && !steam_invite_metadata(
                        m_steam_fns, m_steam_matchmaking,
                        m_stock_remote_offer.lobby_id, "OWNINGID").empty()
                    && !steam_invite_metadata(
                        m_steam_fns, m_steam_matchmaking,
                        m_stock_remote_offer.lobby_id, "P2PADDR").empty()
                    && !steam_invite_metadata(
                        m_steam_fns, m_steam_matchmaking,
                        m_stock_remote_offer.lobby_id, "P2PPORT").empty();
                if (!metadata_ready)
                {
                    m_stock_native_bridge_failure =
                        "waiting-for-lobby-metadata";
                    return;
                }
            }

            if (m_stock_native_event_dispatched)
            {
                if (m_steam_matchmaking &&
                    m_steam_fns.GetNumLobbyMembers)
                {
                    m_steam_join_lobby_member_count =
                        m_steam_fns.GetNumLobbyMembers(
                            m_steam_matchmaking,
                            m_stock_remote_offer.lobby_id);
                }
                const bool conversion_observed =
                    s_steam_lobby_conversion_calls.load(
                        std::memory_order_acquire)
                        > m_stock_conversion_calls_before
                    && s_steam_lobby_conversion_last_lobby_id.load(
                        std::memory_order_acquire)
                        == m_stock_remote_offer.lobby_id
                    && s_steam_lobby_conversion_last_result.load(
                        std::memory_order_acquire) != 0;
                const bool delegate_observed =
                    s_steam_invite_delegate_calls.load(
                        std::memory_order_acquire)
                        > m_stock_delegate_calls_before;
                if (delegate_observed &&
                    m_stock_milestone_invite_delegate == 0)
                {
                    m_stock_milestone_invite_delegate =
                        ++m_stock_milestone_next;
                }
                const bool exact_native_join =
                    m_join_complete_seen && m_join_complete_result
                    && m_native_named_session_lobby_id != 0
                    && m_native_named_session_lobby_id ==
                        m_stock_remote_offer.lobby_id;
                // The conversion helper hook is diagnostic: this SC6 path
                // can dispatch the authoritative invite delegate without
                // traversing that helper. Completion requires the delegate,
                // successful stock JoinSession, and the exact authenticated
                // lobby id in the native named session.
                m_stock_native_event_dispatch_ok =
                    delegate_observed && exact_native_join;
                m_stock_native_bridge_failure =
                    m_stock_native_event_dispatch_ok
                        ? "ok"
                        : (!delegate_observed
                            ? "native-invite-delegate-pending"
                            : (!m_join_complete_seen
                                ? "native-join-session-pending"
                                : (!m_join_complete_result
                                    ? "native-join-session-failed"
                                    : (conversion_observed
                                        ? "native-named-lobby-pending"
                                        : "native-named-lobby-mismatch"))));
                return;
            }

            if (!ensure_steam_lobby_conversion_hook())
            {
                m_stock_native_bridge_failure =
                    "conversion-observe-hook-unavailable";
                return;
            }
            if (!ensure_steam_invite_event_hook())
            {
                m_stock_native_bridge_failure =
                    "invite-handler-observe-hook-unavailable";
                return;
            }
            if (!ensure_steam_invite_delegate_hook())
            {
                m_stock_native_bridge_failure =
                    "invite-delegate-observe-hook-unavailable";
                return;
            }
            if (!ensure_steam_join_lobby_task_hook())
            {
                m_stock_native_bridge_failure =
                    "join-lobby-task-observe-hook-unavailable";
                return;
            }

            const uintptr_t resolver = native_address(
                kRVA_GetOnlineSessionInterfaceShared);
            const uintptr_t constructor = native_address(
                kRVA_ConstructSteamInviteAcceptedEvent);
            const uintptr_t queue_address = native_address(
                kRVA_QueueSteamAsyncItem);
            const uintptr_t unique_id_vtable = native_address(
                kRVA_SteamUniqueIdVtable);
            if (!resolver || !constructor || !queue_address ||
                !unique_id_vtable)
            {
                m_stock_native_bridge_failure =
                    "native-invite-address-unavailable";
                return;
            }

            SharedInterfaceNative shared {};
            if (!safe_get_online_session_interface(
                    reinterpret_cast<GetOnlineSessionInterfaceSharedFn>(
                        resolver), 0, &shared)
                || !shared.object)
            {
                shared = {};
            }
            OnlineSessionSlotSnapshot session =
                inspect_online_session_shared(
                    shared,
                    native_address(kRVA_SteamOnlineSessionFindSessions));
            if (!session.ok || !session.find_sessions_slot_is_steam)
            {
                RC::Unreal::FName steam_subsystem(
                    STR("STEAM"), RC::Unreal::FNAME_Find);
                SharedInterfaceNative explicit_steam {};
                if (steam_subsystem.ToUnstableInt() != 0
                    && safe_get_online_session_interface(
                        reinterpret_cast<
                            GetOnlineSessionInterfaceSharedFn>(resolver),
                        steam_subsystem.ToUnstableInt(),
                        &explicit_steam)
                    && explicit_steam.object)
                {
                    const OnlineSessionSlotSnapshot explicit_session =
                        inspect_online_session_shared(
                            explicit_steam,
                            native_address(
                                kRVA_SteamOnlineSessionFindSessions));
                    if (explicit_session.ok
                        && explicit_session.find_sessions_slot_is_steam)
                    {
                        shared = explicit_steam;
                        session = explicit_session;
                    }
                }
            }
            if (!session.ok || !session.find_sessions_slot_is_steam)
            {
                m_stock_native_bridge_failure =
                    "steam-online-session-interface-unavailable";
                return;
            }

            void* online_subsystem_steam =
                safe_get_steam_subsystem_from_session(shared.object);
            if (!online_subsystem_steam)
            {
                m_stock_native_bridge_failure =
                    "steam-online-subsystem-owner-unavailable";
                return;
            }

            SteamUniqueIdInlineNative friend_id {};
            friend_id.vtable = unique_id_vtable;
            friend_id.steam_id =
                m_stock_remote_offer.host_steam_id;
            SteamUniqueIdInlineNative lobby_id {};
            lobby_id.vtable = unique_id_vtable;
            lobby_id.steam_id = m_stock_remote_offer.lobby_id;
            using RC::Unreal::GMalloc;
            if (!GMalloc || !*GMalloc)
            {
                m_stock_native_bridge_failure =
                    "native-invite-allocator-unavailable";
                return;
            }
            auto* event = static_cast<SteamLobbyInviteAcceptedEventNative*>(
                (*GMalloc)->Malloc(
                    sizeof(SteamLobbyInviteAcceptedEventNative),
                    alignof(SteamLobbyInviteAcceptedEventNative)));
            if (!event)
            {
                m_stock_native_bridge_failure =
                    "native-invite-allocation-failed";
                return;
            }
            std::memset(event, 0,
                        sizeof(SteamLobbyInviteAcceptedEventNative));
            if (!safe_construct_steam_invite_event(
                    reinterpret_cast<
                        ConstructSteamInviteAcceptedEventFn>(constructor),
                    event, online_subsystem_steam,
                    &friend_id, &lobby_id))
            {
                (*GMalloc)->Free(event);
                m_stock_native_bridge_failure =
                    "native-invite-constructor-failed";
                return;
            }
            m_stock_conversion_calls_before =
                s_steam_lobby_conversion_calls.load(
                    std::memory_order_acquire);
            m_stock_delegate_calls_before =
                s_steam_invite_delegate_calls.load(
                    std::memory_order_acquire);
            const uintptr_t event_vtable = event->vtable;
            const uint32_t event_local_user_num = event->local_user_num;
            m_stock_native_event_dispatched =
                safe_queue_steam_invite_event(
                    reinterpret_cast<QueueSteamAsyncItemFn>(queue_address),
                    online_subsystem_steam, event);
            if (!m_stock_native_event_dispatched)
                (*GMalloc)->Free(event);
            m_stock_native_bridge_failure =
                m_stock_native_event_dispatched
                    ? "native-event-queued"
                    : "native-event-queue-failed";

            const int lobby_data_count =
                m_steam_fns.GetLobbyDataCount
                    ? m_steam_fns.GetLobbyDataCount(
                        m_steam_matchmaking,
                        m_stock_remote_offer.lobby_id)
                    : -1;

            ReplayTraceFields f;
            f.boolean("ok", m_stock_native_event_dispatched)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .hex("lobby_id", m_stock_remote_offer.lobby_id)
             .hex("host_steam_id", m_stock_remote_offer.host_steam_id)
             .hex("online_session_steam",
                  reinterpret_cast<uintptr_t>(shared.object))
             .hex("online_subsystem_steam",
                  reinterpret_cast<uintptr_t>(online_subsystem_steam))
             .hex("event_vtable", event_vtable)
             .uinteger("local_user_num", event_local_user_num)
             .boolean("metadata_requested", m_stock_metadata_requested)
             .boolean("metadata_request_ok", m_stock_metadata_request_ok)
             .integer("lobby_data_count", lobby_data_count)
             .string("lobby_build_id", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_stock_remote_offer.lobby_id, "buildid"))
             .string("lobby_session_flags", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_stock_remote_offer.lobby_id, "SESSIONFLAGS"))
             .string("lobby_owning_id", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_stock_remote_offer.lobby_id, "OWNINGID"))
             .string("lobby_p2p_addr", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_stock_remote_offer.lobby_id, "P2PADDR"))
             .string("lobby_p2p_port", steam_invite_metadata(
                 m_steam_fns, m_steam_matchmaking,
                 m_stock_remote_offer.lobby_id, "P2PPORT"))
             .boolean("native_event_dispatched",
                      m_stock_native_event_dispatched)
             .uinteger("direct_join_lobby_count",
                       m_steam_join_lobby_direct_call_count)
             .string("invite_boundary", injected_route
                 ? "injected-stock-handler"
                 : "steam-join-lobby-assisted-handler")
             .string("failure", m_stock_native_bridge_failure)
             .boolean("forced_completion_handlers", false);
            ReplayDebugTrace::instance().event(
                "rollback_stock_invite_native_bridge", f);
        }
        static std::string classify_online_session_slot(
            uintptr_t slot,
            uintptr_t expected_steam_slot) noexcept
        {
            if (!slot) return "null";
            if (expected_steam_slot && slot == expected_steam_slot)
                return "steam";
            if (expected_steam_slot) return "non-steam";
            return "unknown";
        }

        static OnlineSessionSlotSnapshot inspect_online_session_shared(
            const SharedInterfaceNative& shared,
            uintptr_t expected_steam_slot) noexcept
        {
            OnlineSessionSlotSnapshot snap {};
            snap.object = reinterpret_cast<uintptr_t>(shared.object);
            snap.ref_controller =
                reinterpret_cast<uintptr_t>(shared.ref_controller);
            if (!shared.object)
            {
                snap.failure = "online-session-null";
                return snap;
            }

            void* vtable = nullptr;
            if (!SafeReadPtr(shared.object, &vtable) || !vtable)
            {
                snap.failure = "online-session-vtable-unreadable";
                return snap;
            }

            snap.vtable = reinterpret_cast<uintptr_t>(vtable);
            void* find_sessions_slot = nullptr;
            if (!SafeReadPtr(
                    reinterpret_cast<const void*>(
                        snap.vtable
                        + kOnlineSessionFindSessionsVtableOffset),
                    &find_sessions_slot))
            {
                snap.failure = "find-sessions-slot-unreadable";
                return snap;
            }

            snap.find_sessions_slot =
                reinterpret_cast<uintptr_t>(find_sessions_slot);
            const uintptr_t base = NativeBinding::imageBase();
            snap.find_sessions_slot_rva =
                base && snap.find_sessions_slot >= base
                    ? snap.find_sessions_slot - base
                    : 0;
            snap.find_sessions_slot_is_steam =
                expected_steam_slot != 0
                && snap.find_sessions_slot == expected_steam_slot;
            snap.find_sessions_slot_kind =
                classify_online_session_slot(
                    snap.find_sessions_slot,
                    expected_steam_slot);
            snap.ok = find_sessions_slot != nullptr;
            snap.failure = snap.ok ? "ok" : "find-sessions-slot-null";
            return snap;
        }
        static bool safe_get_online_session_interface(
            GetOnlineSessionInterfaceSharedFn fn,
            uint64_t subsystem_name,
            SharedInterfaceNative* out) noexcept
        {
            if (!fn || !out) return false;
            __try
            {
                fn(out, subsystem_name);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        bool should_sample_online_native_session_state(
            bool is_host,
            bool is_sandbox,
            uint64_t tick) const noexcept
        {
            if (!is_host && !is_sandbox)
                return false;
            if (is_host && m_session_connect_complete_seen &&
                RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route))
            {
                // The private named session and owner were already verified
                // before releasing the guest.  Re-entering GetNamedSession
                // from the host's OnSessionConnectComplete follow-up can
                // deadlock against SC6's own session transition.
                return false;
            }
            // The authenticated invite creates the native guest session
            // before the cooked Blueprint OnJoinSession observer is visible.
            // Start sampling at dispatch so that native session evidence can
            // break that observer dependency instead of waiting on it.
            const bool online_work_started =
                m_create_request_ok
                || m_join_request_ok
                || m_join_complete_seen
                || m_session_connect_complete_seen
                || (is_sandbox && m_stock_native_event_dispatched);
            if (!online_work_started)
                return false;
            return m_native_session_sample_tick == 0
                || tick - m_native_session_sample_tick >= 15;
        }

        void sample_online_native_session_state(
            uint64_t tick,
            bool is_host,
            bool is_sandbox) noexcept
        {
            if (!should_sample_online_native_session_state(
                    is_host, is_sandbox, tick))
            {
                return;
            }
            m_native_session_sample_tick = tick;
            sample_named_online_session_state(tick, is_sandbox);
            m_connect_manager_sample_tick = tick;
            sample_luxor_connect_manager_state(is_sandbox);
        }

        void sample_named_online_session_state(
            uint64_t tick,
            bool is_sandbox) noexcept
        {
            m_native_named_session_sampled = true;
            m_native_named_session_ok = false;
            m_native_named_session_failure = "starting";
            m_native_named_session_online_session = 0;
            m_native_named_session_ref_controller = 0;
            m_native_named_session_vtable = 0;
            m_native_named_session_ptr = 0;
            m_native_named_session_info = 0;
            m_native_named_session_info_ref_controller = 0;
            m_native_named_session_lobby_id = 0;
            m_native_named_session_public_connections = -1;
            m_native_named_session_luxor_connections = -1;
            m_native_named_session_hosting_player_num = 0xffffffffu;
            m_native_named_session_state = 0xffffffffu;
            m_native_named_session_state_byte = 0xffu;

            const uintptr_t addr =
                native_address(kRVA_GetOnlineSessionInterfaceShared);
            if (!addr)
            {
                m_native_named_session_failure =
                    "online-session-resolver-unavailable";
                return;
            }

            SharedInterfaceNative shared {};
            if (!safe_get_online_session_interface(
                    reinterpret_cast<GetOnlineSessionInterfaceSharedFn>(addr),
                    0,
                    &shared))
            {
                m_native_named_session_failure =
                    "online-session-resolver-threw";
                return;
            }
            m_native_named_session_online_session =
                reinterpret_cast<uintptr_t>(shared.object);
            m_native_named_session_ref_controller =
                reinterpret_cast<uintptr_t>(shared.ref_controller);
            if (!shared.object)
            {
                m_native_named_session_failure =
                    "online-session-unavailable";
                return;
            }

            void* vtable = nullptr;
            if (!SafeReadPtr(shared.object, &vtable) || !vtable)
            {
                m_native_named_session_failure =
                    "online-session-vtable-unreadable";
                return;
            }
            m_native_named_session_vtable =
                reinterpret_cast<uintptr_t>(vtable);

            void* get_named_raw = nullptr;
            if (!SafeReadPtr(
                    static_cast<uint8_t*>(vtable) + 0x18,
                    &get_named_raw) ||
                !get_named_raw)
            {
                m_native_named_session_failure =
                    "get-named-session-slot-unavailable";
                return;
            }

            void* named_session = nullptr;
            const uint64_t session_name =
                (is_sandbox ? make_join_session_fname()
                            : make_session_fname()).ToUnstableInt();
            __try
            {
                named_session =
                    reinterpret_cast<OnlineSessionGetNamedSessionFn>(
                        get_named_raw)(shared.object, session_name);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                m_native_named_session_failure =
                    "get-named-session-threw";
                return;
            }
            m_native_named_session_ptr =
                reinterpret_cast<uintptr_t>(named_session);
            if (!named_session)
            {
                m_native_named_session_failure =
                    "named-session-unavailable";
                return;
            }

            auto* const bytes = static_cast<const uint8_t*>(named_session);
            uint32_t session_state = 0xffffffffu;
            uint32_t hosting_player_num = 0xffffffffu;
            uint8_t state_byte = 0xffu;
            void* session_info = nullptr;
            void* session_info_ref = nullptr;
            uint64_t lobby_id = 0;
            const bool reads_ok =
                SafeReadInt32(
                    bytes + kNamedSessionPublicConnectionsOff,
                    &m_native_named_session_public_connections)
                && SafeReadInt32(
                    bytes + kNamedSessionLuxorConnectionsOff,
                    &m_native_named_session_luxor_connections)
                && SafeReadUInt8(
                    bytes + kNamedSessionStateByteOff,
                    &state_byte);
            (void)SafeReadPtr(bytes + kNamedSessionInfoOff, &session_info);
            (void)SafeReadPtr(
                bytes + kNamedSessionInfoRefOff,
                &session_info_ref);
            (void)SafeReadUInt32(
                bytes + kNamedSessionHostingPlayerNumOff,
                &hosting_player_num);
            (void)SafeReadUInt32(
                bytes + kNamedSessionOnlineStateOff,
                &session_state);
            if (session_info)
            {
                (void)SafeReadUInt64(
                    static_cast<const uint8_t*>(session_info) +
                        kOnlineSessionInfoLobbyIdOff,
                    &lobby_id);
            }

            m_native_named_session_info =
                reinterpret_cast<uintptr_t>(session_info);
            m_native_named_session_info_ref_controller =
                reinterpret_cast<uintptr_t>(session_info_ref);
            m_native_named_session_lobby_id = lobby_id;
            m_native_named_session_hosting_player_num = hosting_player_num;
            if (reads_ok)
            {
                if (m_native_named_session_first_sample_tick == 0)
                {
                    m_native_named_session_first_sample_tick = tick;
                    m_native_named_session_first_state = session_state;
                    m_native_named_session_first_state_byte = state_byte;
                }
                else if (m_native_named_session_state != session_state ||
                         m_native_named_session_state_byte != state_byte)
                {
                    ++m_native_named_session_state_transition_count;
                }
                if (session_state == 7 &&
                    m_native_named_session_state7_first_tick == 0)
                {
                    m_native_named_session_state7_first_tick = tick;
                }
                if (state_byte == 1 &&
                    m_native_named_session_state_byte_ready_first_tick == 0)
                {
                    m_native_named_session_state_byte_ready_first_tick = tick;
                }
            }
            m_native_named_session_state = session_state;
            m_native_named_session_state_byte = state_byte;
            m_native_named_session_ok = reads_ok;
            if (reads_ok && lobby_id != 0 && m_steam_matchmaking)
            {
                m_native_named_session_lobby_owner_id =
                    steam_invite_metadata_u64(
                        m_steam_fns, m_steam_matchmaking,
                        lobby_id, "OWNINGID");
                m_native_named_session_lobby_owner_sampled =
                    m_native_named_session_lobby_owner_id != 0;
            }
            if (!reads_ok)
            {
                m_native_named_session_failure =
                    "named-session-field-read-failed";
            }
            else if (is_sandbox && state_byte != 1)
            {
                m_native_named_session_failure =
                    "named-session-state-byte-not-ready";
            }
            else if (!session_info)
            {
                m_native_named_session_failure =
                    "named-session-info-unavailable";
            }
            else
            {
                m_native_named_session_failure = "ok";
            }
        }

        void sample_luxor_connect_manager_state(bool is_sandbox) noexcept
        {
            m_connect_manager_sampled = true;
            m_connect_manager_ok = false;
            m_connect_manager_failure = "starting";
            m_luxor_connect_manager = 0;
            m_luxor_connect_delegate_handle_array = 0;
            m_luxor_connect_delegate_handle_array_ref = 0;
            m_luxor_delegate_create_session_complete_handle = 0;
            m_luxor_delegate_slot_08_handle = 0;
            m_luxor_delegate_start_session_complete_handle = 0;
            m_luxor_delegate_destroy_session_complete_handle = 0;
            m_luxor_delegate_slot_20_handle = 0;
            m_luxor_delegate_join_session_complete_handle = 0;
            m_luxor_delegate_deferred_session_connection_handle = 0;
            m_luxor_delegate_external_ui_handle = 0;
            m_luxor_delegate_sender_handle = 0;
            m_luxor_delegate_slot_48_handle = 0;
            m_luxor_connect_binding_handle_a = 0;
            m_luxor_connect_binding_handle_b = 0;
            m_luxor_connect_sender_message_binding = 0;
            m_luxor_connect_message_binding = 0;
            m_luxor_connect_online_session_object = 0;
            m_luxor_connect_online_session_ref = 0;
            m_luxor_active_connect_object = 0;
            m_luxor_active_connect_ref = 0;
            m_luxor_active_connect_system_slot = 0;
            m_luxor_active_connect_system_ref = 0;
            m_luxor_active_connect_system_offset = 0xffffffffu;
            m_luxor_active_connect_system_known_interface = false;
            m_luxor_active_connect_state = 0xffu;
            m_luxor_active_connect_local_user_byte = 0xffu;
            m_luxor_active_connect_sub_state = 0xffu;
            m_luxor_active_state_flags = 0xffffffffu;
            m_luxor_active_session_name_raw = 0;
            m_luxor_active_session_state_update_task = 0;
            m_luxor_active_session_state_update_task_ref = 0;
            m_luxor_active_session_notify_task = 0;
            m_luxor_active_session_notify_task_ref = 0;
            m_luxor_active_session_event_handle = 0;
            m_luxor_session_connection_object = 0;
            m_luxor_session_connection_ref = 0;
            m_luxor_session_async_queue_head = 0;
            m_luxor_session_async_queue_next = 0;
            m_luxor_session_async_queue_prev = 0;
            m_luxor_session_async_queue_count = 0;
            m_luxor_session_async_queue_first_callback = 0;
            m_luxor_session_async_queue_first_callback_rva = 0;
            m_luxor_session_async_queue_tail_callback = 0;
            m_luxor_session_async_queue_tail_callback_rva = 0;
            m_luxor_session_async_queue_first_payload_count =
                0xffffffffu;
            m_luxor_session_async_queue_tail_payload_count =
                0xffffffffu;
            m_luxor_connect_main_user_sentinel = 0xffu;
            m_luxor_connect_scratch_object = 0;
            m_luxor_connect_scratch_ref = 0;
            m_luxor_active_transport = 0;
            m_luxor_active_transport_tick = 0;
            m_luxor_active_transport_status_code = 0xffu;
            m_luxor_active_transport_ready_state = 0xffu;
            m_luxor_active_transport_is_host = 0xffu;
            m_luxor_active_transport_channel_count = 0xffffffffu;
            m_luxor_active_transport_channel_capacity = 0xffffffffu;
            m_luxor_active_transport_ready_sampled = false;
            m_luxor_active_transport_ready = false;

            const uintptr_t addr =
                native_address(kRVA_GetLuxorConnectManagerSingleton);
            if (!addr)
            {
                m_connect_manager_failure =
                    "connect-manager-resolver-unavailable";
                return;
            }

            void* manager = nullptr;
            __try
            {
                manager = reinterpret_cast<GetLuxorConnectManagerSingletonFn>(
                    addr)();
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                m_connect_manager_failure = "connect-manager-resolver-threw";
                return;
            }
            m_luxor_connect_manager = reinterpret_cast<uintptr_t>(manager);
            if (!manager)
            {
                m_connect_manager_failure = "connect-manager-unavailable";
                return;
            }

            auto* const bytes = static_cast<const uint8_t*>(manager);
            void* delegate_handle_array = nullptr;
            void* delegate_handle_array_ref = nullptr;
            void* online_session_object = nullptr;
            void* online_session_ref = nullptr;
            void* active_connect = nullptr;
            void* active_connect_ref = nullptr;
            void* active_connect_system = nullptr;
            void* active_connect_system_ref = nullptr;
            void* session_connection = nullptr;
            void* session_connection_ref = nullptr;
            void* scratch_object = nullptr;
            void* scratch_ref = nullptr;
            uint64_t binding_handle_a = 0;
            uint64_t binding_handle_b = 0;
            uint64_t sender_message_binding = 0;
            uint64_t message_binding = 0;
            uint8_t main_user_sentinel = 0xffu;
            const bool fields_ok =
                SafeReadPtr(bytes + 0x20, &delegate_handle_array)
                && SafeReadPtr(bytes + 0x28, &delegate_handle_array_ref)
                && SafeReadUInt64(bytes + 0x30, &binding_handle_a)
                && SafeReadUInt64(bytes + 0x38, &binding_handle_b)
                && SafeReadUInt64(bytes + 0x40, &sender_message_binding)
                && SafeReadUInt64(bytes + 0x48, &message_binding)
                && SafeReadPtr(bytes + 0x50, &online_session_object)
                && SafeReadPtr(bytes + 0x58, &online_session_ref)
                && SafeReadPtr(bytes + 0x60, &active_connect)
                && SafeReadPtr(bytes + 0x68, &active_connect_ref)
                && SafeReadPtr(bytes + 0x70, &active_connect_system)
                && SafeReadPtr(bytes + 0x78, &active_connect_system_ref)
                && SafeReadPtr(bytes + 0x80, &session_connection)
                && SafeReadPtr(bytes + 0x88, &session_connection_ref)
                && SafeReadUInt8(bytes + 0x90, &main_user_sentinel)
                && SafeReadPtr(bytes + 0x98, &scratch_object)
                && SafeReadPtr(bytes + 0xa0, &scratch_ref);
            m_luxor_connect_delegate_handle_array =
                reinterpret_cast<uintptr_t>(delegate_handle_array);
            m_luxor_connect_delegate_handle_array_ref =
                reinterpret_cast<uintptr_t>(delegate_handle_array_ref);
            if (delegate_handle_array)
            {
                const auto* const delegate_bytes =
                    static_cast<const uint8_t*>(delegate_handle_array);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x00,
                    &m_luxor_delegate_create_session_complete_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x08,
                    &m_luxor_delegate_slot_08_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x10,
                    &m_luxor_delegate_start_session_complete_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x18,
                    &m_luxor_delegate_destroy_session_complete_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x20,
                    &m_luxor_delegate_slot_20_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x28,
                    &m_luxor_delegate_join_session_complete_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x30,
                    &m_luxor_delegate_deferred_session_connection_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x38,
                    &m_luxor_delegate_external_ui_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x40,
                    &m_luxor_delegate_sender_handle);
                (void)SafeReadUInt64(
                    delegate_bytes + 0x48,
                    &m_luxor_delegate_slot_48_handle);
            }
            m_luxor_connect_binding_handle_a = binding_handle_a;
            m_luxor_connect_binding_handle_b = binding_handle_b;
            m_luxor_connect_sender_message_binding = sender_message_binding;
            m_luxor_connect_message_binding = message_binding;
            m_luxor_connect_online_session_object =
                reinterpret_cast<uintptr_t>(online_session_object);
            m_luxor_connect_online_session_ref =
                reinterpret_cast<uintptr_t>(online_session_ref);
            m_luxor_active_connect_object =
                reinterpret_cast<uintptr_t>(active_connect);
            m_luxor_active_connect_ref =
                reinterpret_cast<uintptr_t>(active_connect_ref);
            m_luxor_active_connect_system_slot =
                reinterpret_cast<uintptr_t>(active_connect_system);
            m_luxor_active_connect_system_ref =
                reinterpret_cast<uintptr_t>(active_connect_system_ref);
            if (active_connect && active_connect_system)
            {
                const uintptr_t active =
                    reinterpret_cast<uintptr_t>(active_connect);
                const uintptr_t system =
                    reinterpret_cast<uintptr_t>(active_connect_system);
                if (system >= active && system - active <= 0x40u)
                {
                    m_luxor_active_connect_system_offset =
                        static_cast<uint32_t>(system - active);
                    m_luxor_active_connect_system_known_interface =
                        m_luxor_active_connect_system_offset == 0x10u ||
                        m_luxor_active_connect_system_offset == 0x18u ||
                        m_luxor_active_connect_system_offset == 0x20u ||
                        m_luxor_active_connect_system_offset == 0x28u;
                }
            }
            m_luxor_session_connection_object =
                reinterpret_cast<uintptr_t>(session_connection);
            m_luxor_session_connection_ref =
                reinterpret_cast<uintptr_t>(session_connection_ref);
            sample_luxor_session_async_queue(session_connection);
            m_luxor_connect_main_user_sentinel = main_user_sentinel;
            m_luxor_connect_scratch_object =
                reinterpret_cast<uintptr_t>(scratch_object);
            m_luxor_connect_scratch_ref =
                reinterpret_cast<uintptr_t>(scratch_ref);
            if (!fields_ok)
            {
                m_connect_manager_failure =
                    "connect-manager-field-read-failed";
                return;
            }

            sample_active_connect_transport(active_connect);
            update_native_connection_lifecycle_serial(fields_ok);
            m_connect_manager_ok = true;
            if (is_sandbox && m_session_connect_complete_seen &&
                !m_session_connect_complete_result &&
                !m_luxor_session_connection_object)
            {
                m_connect_manager_failure =
                    "session-connect-false-no-session-connection";
            }
            else if (is_sandbox && m_session_connect_complete_seen &&
                     !m_session_connect_complete_result &&
                     m_luxor_active_transport_ready_sampled &&
                     !m_luxor_active_transport_ready)
            {
                m_connect_manager_failure =
                    "session-connect-false-transport-not-ready";
            }
            else
            {
                m_connect_manager_failure = "ok";
            }
        }

        void emit_join_complete_compat_trace(
            uint64_t tick,
            const char* phase) noexcept
        {
            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("tick", tick)
             .string("phase", phase ? phase : "")
             .boolean("call_ok", m_join_complete_compat_call_ok)
             .string("failure", m_join_complete_compat_failure)
             .hex("connect_manager", m_luxor_connect_manager)
             .hex("active_connect", m_luxor_active_connect_object)
             .uinteger("active_state_before",
                       m_join_complete_compat_active_state_before)
             .uinteger("active_state_after",
                       m_join_complete_compat_active_state_after)
             .hex("session_connection_before",
                  m_join_complete_compat_session_connection_before)
             .hex("session_connection_after",
                  m_join_complete_compat_session_connection_after)
             .uinteger("named_session_state_byte",
                       m_native_named_session_state_byte);
            ReplayDebugTrace::instance().event(
                "rollback_online_stage_join_complete_compat", f);
        }

        void service_join_complete_compat_if_needed(
            uint64_t tick,
            bool is_sandbox) noexcept
        {
            if (!m_cfg.online_stage_join_complete_compat)
            {
                m_join_complete_compat_failure = "disabled";
                return;
            }
            if (!is_sandbox)
            {
                m_join_complete_compat_failure = "role-not-sandbox";
                return;
            }
            if (m_join_complete_compat_count > 0 &&
                m_join_complete_compat_call_ok)
            {
                m_join_complete_compat_failure =
                    m_luxor_active_connect_state == 1
                        ? "ok"
                        : "handler-called-active-connect-not-started";
                return;
            }
            if (!m_join_request_ok || !m_join_complete_seen ||
                !m_join_complete_result)
            {
                m_join_complete_compat_failure = "join-not-complete";
                return;
            }
            if (m_join_complete_result_type != 0)
            {
                m_join_complete_compat_failure =
                    "join-result-type-not-success";
                return;
            }
            if (m_session_connect_complete_seen ||
                m_session_connect_complete_full_member_error)
            {
                m_join_complete_compat_failure =
                    "session-connect-already-observed";
                return;
            }
            if (!m_find_result_target_found ||
                m_find_result_selected_index < 0)
            {
                m_join_complete_compat_failure =
                    "selected-search-result-not-proven";
                return;
            }
            if (!m_native_named_session_ptr)
            {
                m_join_complete_compat_failure =
                    "named-session-unavailable";
                return;
            }
            if (!m_native_named_session_sampled ||
                !m_native_named_session_info ||
                m_native_named_session_lobby_id == 0 ||
                m_native_named_session_state_byte == 0xffu)
            {
                m_join_complete_compat_failure =
                    "named-session-evidence-incomplete";
                return;
            }
            if (m_steam_lobby_probe_target_visible &&
                m_steam_lobby_target_id != 0 &&
                m_native_named_session_lobby_id != m_steam_lobby_target_id)
            {
                m_join_complete_compat_failure =
                    "named-session-lobby-target-mismatch";
                return;
            }
            if (!m_luxor_connect_manager)
            {
                m_join_complete_compat_failure =
                    "connect-manager-unavailable";
                return;
            }
            if (!m_luxor_active_connect_object)
            {
                m_join_complete_compat_failure =
                    "active-connect-unavailable";
                return;
            }
            if (m_luxor_active_connect_state == 1)
            {
                m_join_complete_compat_failure =
                    "active-connect-already-started";
                return;
            }
            if (m_luxor_active_connect_state != 0)
            {
                m_join_complete_compat_failure =
                    "active-connect-state-not-idle";
                return;
            }
            if (m_luxor_session_connection_object)
            {
                m_join_complete_compat_failure =
                    "session-connection-already-present";
                return;
            }
            if (!m_luxor_active_transport)
            {
                m_join_complete_compat_failure =
                    "active-transport-unavailable";
                return;
            }
            if (m_luxor_active_transport !=
                m_luxor_active_connect_object + 0xA8u)
            {
                m_join_complete_compat_failure =
                    "active-transport-not-embedded";
                return;
            }
            if (m_luxor_active_transport_status_code != 1)
            {
                m_join_complete_compat_failure =
                    "active-transport-status-not-started";
                return;
            }
            if (m_luxor_active_transport_is_host != 0)
            {
                m_join_complete_compat_failure =
                    "active-transport-is-host";
                return;
            }
            if (!m_luxor_active_transport_ready_sampled)
            {
                m_join_complete_compat_failure =
                    "active-transport-ready-query-unavailable";
                return;
            }
            if (m_luxor_active_transport_ready ||
                m_luxor_active_transport_ready_state == 0xffu)
            {
                m_join_complete_compat_failure =
                    "active-transport-already-ready";
                return;
            }
            if (m_join_complete_compat_last_tick != 0 &&
                tick - m_join_complete_compat_last_tick <
                    kOnlineStageReadyRetryTicks)
            {
                return;
            }
            if (m_process_event_followup_in_progress ||
                (m_process_event_followup_last_tick != 0 &&
                 tick <= m_process_event_followup_last_tick))
            {
                m_join_complete_compat_failure =
                    "pending-non-callback-service";
                return;
            }

            const uintptr_t addr =
                native_address(kRVA_HandleLuxorJoinSessionComplete);
            if (!addr)
            {
                m_join_complete_compat_failure =
                    "join-complete-handler-unavailable";
                return;
            }

            m_join_complete_compat_attempted = true;
            ++m_join_complete_compat_count;
            m_join_complete_compat_last_tick = tick;
            m_join_complete_compat_call_ok = false;
            m_join_complete_compat_active_state_before =
                m_luxor_active_connect_state;
            m_join_complete_compat_active_state_after = 0xffu;
            m_join_complete_compat_session_connection_before =
                m_luxor_session_connection_object;
            m_join_complete_compat_session_connection_after = 0;
            m_join_complete_compat_trigger_reason =
                "missing-luxor-join-complete-delegate";
            m_join_complete_compat_failure = "starting";

            const uint64_t session_name =
                make_join_session_fname().ToUnstableInt();
            emit_join_complete_compat_trace(tick, "begin");
            __try
            {
                reinterpret_cast<HandleLuxorJoinSessionCompleteFn>(addr)(
                    reinterpret_cast<void*>(m_luxor_connect_manager),
                    session_name,
                    0);
                m_join_complete_compat_call_ok = true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                m_join_complete_compat_call_ok = false;
                m_join_complete_compat_failure =
                    "join-complete-handler-threw";
                return;
            }

            sample_luxor_connect_manager_state(is_sandbox);
            m_join_complete_compat_active_state_after =
                m_luxor_active_connect_state;
            m_join_complete_compat_session_connection_after =
                m_luxor_session_connection_object;
            if (m_luxor_active_connect_state != 1)
            {
                m_join_complete_compat_failure =
                    "handler-did-not-start-active-connect";
                emit_join_complete_compat_trace(tick, "end");
                return;
            }
            m_join_complete_compat_failure = "ok";
            emit_join_complete_compat_trace(tick, "end");
        }

        void sample_luxor_session_async_queue(
            void* session_connection) noexcept
        {
            m_luxor_session_async_queue_head = 0;
            m_luxor_session_async_queue_next = 0;
            m_luxor_session_async_queue_prev = 0;
            m_luxor_session_async_queue_count = 0;
            m_luxor_session_async_queue_first_callback = 0;
            m_luxor_session_async_queue_first_callback_rva = 0;
            m_luxor_session_async_queue_tail_callback = 0;
            m_luxor_session_async_queue_tail_callback_rva = 0;
            m_luxor_session_async_queue_first_payload_count =
                0xffffffffu;
            m_luxor_session_async_queue_tail_payload_count =
                0xffffffffu;
            if (!session_connection)
                return;

            const auto* const bytes =
                static_cast<const uint8_t*>(session_connection);
            void* head = nullptr;
            if (!SafeReadPtr(bytes + 0xD0, &head))
                return;
            m_luxor_session_async_queue_head =
                reinterpret_cast<uintptr_t>(head);
            (void)SafeReadUInt64(
                bytes + 0xD8, &m_luxor_session_async_queue_count);
            if (!head)
                return;

            const auto* const head_bytes =
                static_cast<const uint8_t*>(head);
            void* next = nullptr;
            void* prev = nullptr;
            (void)SafeReadPtr(head_bytes + 0x00, &next);
            (void)SafeReadPtr(head_bytes + 0x08, &prev);
            m_luxor_session_async_queue_next =
                reinterpret_cast<uintptr_t>(next);
            m_luxor_session_async_queue_prev =
                reinterpret_cast<uintptr_t>(prev);

            auto sample_node = [](void* node,
                                  uintptr_t& callback,
                                  uint64_t& callback_rva,
                                  uint32_t& payload_count) noexcept
            {
                callback = 0;
                callback_rva = 0;
                payload_count = 0xffffffffu;
                if (!node)
                    return;
                void* callback_raw = nullptr;
                const auto* const entry =
                    static_cast<const uint8_t*>(node) + 0x10;
            if (SafeReadPtr(entry, &callback_raw))
            {
                callback = reinterpret_cast<uintptr_t>(callback_raw);
                    callback_rva =
                        RollbackP2PHarness::native_rva_for_address(
                            callback);
            }
                int32_t count = -1;
                if (SafeReadBytes(entry + 0x40, &count, sizeof(count)))
                {
                    payload_count = count < 0
                        ? 0xffffffffu
                        : static_cast<uint32_t>(count);
                }
            };

            if (next && next != head)
            {
                sample_node(next,
                            m_luxor_session_async_queue_first_callback,
                            m_luxor_session_async_queue_first_callback_rva,
                            m_luxor_session_async_queue_first_payload_count);
            }
            if (prev && prev != head)
            {
                sample_node(prev,
                            m_luxor_session_async_queue_tail_callback,
                            m_luxor_session_async_queue_tail_callback_rva,
                            m_luxor_session_async_queue_tail_payload_count);
            }
        }

        void emit_transport_ready_compat_trace(
            uint64_t tick,
            const char* phase) noexcept
        {
            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("tick", tick)
             .string("phase", phase ? phase : "")
             .boolean("call_ok", m_transport_ready_compat_call_ok)
             .string("trigger",
                     m_transport_ready_compat_trigger_reason)
             .string("failure", m_transport_ready_compat_failure)
             .boolean("callback_followup",
                      m_process_event_followup_in_progress)
             .hex("connect_manager", m_luxor_connect_manager)
             .hex("active_connect", m_luxor_active_connect_object)
             .uinteger("active_state_before",
                       m_transport_ready_compat_active_state_before)
             .uinteger("transport_status_before",
                       m_transport_ready_compat_transport_status_before)
              .uinteger("transport_is_host_before",
                        m_transport_ready_compat_transport_is_host_before)
              .uinteger("transport_channel_count",
                        m_luxor_active_transport_channel_count)
              .uinteger("transport_channel_capacity",
                        m_luxor_active_transport_channel_capacity)
              .uinteger("ready_state_before",
                        m_transport_ready_compat_before_ready_state)
             .uinteger("ready_state_after",
                       m_transport_ready_compat_after_ready_state)
             .boolean("ready_query_before",
                      m_transport_ready_compat_before_ready_query)
             .boolean("ready_query_after",
                      m_transport_ready_compat_after_ready_query)
             .hex("session_connection_before",
                  m_transport_ready_compat_session_connection_before)
             .hex("session_connection_after_mark",
                  m_transport_ready_compat_session_connection_after)
             .hex("session_connection_after_deferred",
                  m_transport_ready_compat_session_connection_after_deferred)
             .boolean("deferred_called_after_force",
                      m_transport_ready_compat_deferred_called_after_force)
             .uinteger("deferred_attempts",
                       m_deferred_session_connect_attempts)
             .string("deferred_failure",
                     m_deferred_session_connect_failure);
            ReplayDebugTrace::instance().event(
                "rollback_online_stage_transport_ready_compat", f);
        }

        void service_transport_ready_compat_if_needed(
            uint64_t tick,
            bool is_sandbox) noexcept
        {
            if (!m_cfg.online_stage_transport_ready_compat)
            {
                m_transport_ready_compat_failure = "disabled";
                return;
            }
            if (!is_sandbox)
            {
                m_transport_ready_compat_failure = "role-not-sandbox";
                return;
            }
            if (m_transport_ready_compat_count > 0 &&
                m_transport_ready_compat_call_ok &&
                m_transport_ready_compat_after_ready_query)
            {
                if (m_luxor_session_connection_object)
                {
                    m_transport_ready_compat_session_connection_after_deferred =
                        m_luxor_session_connection_object;
                    m_transport_ready_compat_failure = "ok";
                }
                else if (m_transport_ready_compat_deferred_called_after_force)
                {
                    m_transport_ready_compat_failure =
                        "ready-forced-deferred-no-session-connection";
                }
                else
                {
                    m_transport_ready_compat_failure =
                        "ready-forced-deferred-pending";
                }
                return;
            }
            if (!m_join_request_ok || !m_join_complete_seen ||
                !m_join_complete_result)
            {
                m_transport_ready_compat_failure = "join-not-complete";
                return;
            }
            if (m_join_complete_result_type != 0)
            {
                m_transport_ready_compat_failure =
                    "join-result-type-not-success";
                return;
            }
            if (m_session_connect_complete_result)
            {
                m_transport_ready_compat_failure =
                    "session-connect-already-succeeded";
                return;
            }
            const bool session_connect_failed =
                m_session_connect_complete_seen &&
                !m_session_connect_complete_result;
            const bool deferred_transport_ready_noop =
                !m_session_connect_complete_seen
                && m_deferred_session_connect_attempts >=
                       kTransportReadyCompatDeferredNoopThreshold
                && m_deferred_session_connect_call_ok;
            if (!session_connect_failed && !deferred_transport_ready_noop)
            {
                m_transport_ready_compat_failure =
                    "session-connect-complete-pending";
                return;
            }
            if (!m_native_named_session_ptr)
            {
                m_transport_ready_compat_failure =
                    "named-session-unavailable";
                return;
            }
            if (!m_native_named_session_sampled ||
                !m_native_named_session_info ||
                m_native_named_session_lobby_id == 0 ||
                m_native_named_session_state_byte == 0xffu)
            {
                m_transport_ready_compat_failure =
                    "named-session-evidence-incomplete";
                return;
            }
            if (m_native_named_session_state_byte == 1)
            {
                m_transport_ready_compat_failure =
                    "named-session-state-already-ready";
                return;
            }
            if (!m_luxor_connect_manager)
            {
                m_transport_ready_compat_failure =
                    "connect-manager-unavailable";
                return;
            }
            if (m_luxor_session_connection_object)
            {
                m_transport_ready_compat_failure =
                    "session-connection-already-present";
                return;
            }
            const bool active_connect_waiting_for_session =
                m_luxor_active_connect_state == 1;
            const bool active_connect_idle_deferred_probe_ok =
                m_luxor_active_connect_state == 0 &&
                m_luxor_active_connect_system_known_interface &&
                m_luxor_active_connect_system_offset == 0x20u &&
                m_luxor_delegate_join_session_complete_handle != 0 &&
                m_luxor_delegate_deferred_session_connection_handle != 0;
            if (!active_connect_waiting_for_session &&
                !active_connect_idle_deferred_probe_ok)
            {
                m_transport_ready_compat_failure =
                    "active-connect-state-not-wait-session-connect";
                return;
            }
            if (!m_luxor_active_transport)
            {
                m_transport_ready_compat_failure =
                    "active-transport-unavailable";
                return;
            }
            if (m_luxor_active_connect_object == 0 ||
                m_luxor_active_transport !=
                    m_luxor_active_connect_object + 0xA8u)
            {
                m_transport_ready_compat_failure =
                    "active-transport-not-embedded";
                return;
            }
            if (m_luxor_active_transport_status_code != 1)
            {
                m_transport_ready_compat_failure =
                    "active-transport-status-not-started";
                return;
            }
            if (m_luxor_active_transport_is_host != 0)
            {
                m_transport_ready_compat_failure =
                    "active-transport-is-host";
                return;
            }
            if (m_luxor_active_transport_channel_count == 0 ||
                m_luxor_active_transport_channel_count == 0xffffffffu)
            {
                m_transport_ready_compat_failure =
                    "active-transport-channels-pending";
                return;
            }
            if (!m_luxor_active_transport_ready_sampled)
            {
                m_transport_ready_compat_failure =
                    "active-transport-ready-query-unavailable";
                return;
            }
            if (m_luxor_active_transport_ready ||
                m_luxor_active_transport_ready_state == 0xffu)
            {
                m_transport_ready_compat_failure =
                    "active-transport-already-ready";
                return;
            }
            if (m_transport_ready_compat_last_tick != 0 &&
                tick - m_transport_ready_compat_last_tick <
                    kOnlineStageReadyRetryTicks)
            {
                return;
            }
            const uintptr_t addr =
                native_address(kRVA_MarkLuxorSessionTransportReady);
            if (!addr)
            {
                m_transport_ready_compat_failure =
                    "mark-ready-helper-unavailable";
                return;
            }

            m_transport_ready_compat_attempted = true;
            ++m_transport_ready_compat_count;
            m_transport_ready_compat_last_tick = tick;
            m_transport_ready_compat_call_ok = false;
            m_transport_ready_compat_deferred_called_after_force = false;
            m_transport_ready_compat_before_ready_state =
                m_luxor_active_transport_ready_state;
            m_transport_ready_compat_after_ready_state = 0xffu;
            m_transport_ready_compat_before_ready_query =
                m_luxor_active_transport_ready_sampled &&
                m_luxor_active_transport_ready;
            m_transport_ready_compat_after_ready_query = false;
            m_transport_ready_compat_active_state_before =
                m_luxor_active_connect_state;
            m_transport_ready_compat_transport_status_before =
                m_luxor_active_transport_status_code;
            m_transport_ready_compat_transport_is_host_before =
                m_luxor_active_transport_is_host;
            m_transport_ready_compat_session_connection_before =
                m_luxor_session_connection_object;
            m_transport_ready_compat_session_connection_after = 0;
            m_transport_ready_compat_session_connection_after_deferred = 0;
            m_transport_ready_compat_trigger_reason =
                session_connect_failed
                    ? (m_process_event_followup_in_progress
                           ? "callback-followup-session-connect-false"
                           : "session-connect-false")
                    : (active_connect_idle_deferred_probe_ok
                           ? (m_process_event_followup_in_progress
                                  ? "callback-followup-deferred-noop-idle-active-connect"
                                  : "deferred-noop-idle-active-connect")
                           : (m_process_event_followup_in_progress
                                  ? "callback-followup-deferred-noop-threshold"
                                  : "deferred-noop-threshold"));
            m_transport_ready_compat_failure = "starting";

            emit_transport_ready_compat_trace(tick, "begin");
            __try
            {
                reinterpret_cast<MarkLuxorSessionTransportReadyFn>(
                    addr)(reinterpret_cast<void*>(m_luxor_active_transport));
                m_transport_ready_compat_call_ok = true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                m_transport_ready_compat_call_ok = false;
                m_transport_ready_compat_failure =
                    "mark-ready-helper-threw";
                emit_transport_ready_compat_trace(tick, "mark-threw");
                return;
            }

            sample_luxor_connect_manager_state(is_sandbox);
            m_transport_ready_compat_after_ready_state =
                m_luxor_active_transport_ready_state;
            m_transport_ready_compat_after_ready_query =
                m_luxor_active_transport_ready_sampled &&
                m_luxor_active_transport_ready;
            m_transport_ready_compat_session_connection_after =
                m_luxor_session_connection_object;

            if (m_transport_ready_compat_after_ready_state != 0xffu)
            {
                m_transport_ready_compat_failure =
                    "mark-ready-state-not-set";
                emit_transport_ready_compat_trace(tick, "after-mark");
                return;
            }
            if (!m_transport_ready_compat_after_ready_query)
            {
                m_transport_ready_compat_failure =
                    "mark-ready-query-still-false";
                emit_transport_ready_compat_trace(tick, "after-mark");
                return;
            }
            m_transport_ready_compat_failure = "ok";
            emit_transport_ready_compat_trace(tick, "after-mark");
        }

        void service_deferred_session_connection_if_needed(
            uint64_t tick,
            bool is_sandbox) noexcept
        {
            if (!is_sandbox)
                return;
            if (!m_join_request_ok || !m_join_complete_seen ||
                !m_join_complete_result)
            {
                m_deferred_session_connect_failure =
                    "join-not-complete";
                return;
            }
            if (!m_native_named_session_ptr)
            {
                m_deferred_session_connect_failure =
                    "named-session-unavailable";
                return;
            }
            if (!m_luxor_connect_manager)
            {
                m_deferred_session_connect_failure =
                    "connect-manager-unavailable";
                return;
            }
            if (m_luxor_session_connection_object)
            {
                m_deferred_session_connect_failure =
                    "session-connection-already-present";
                return;
            }
            const bool transport_ready_forced_this_tick =
                m_cfg.online_stage_transport_ready_compat
                && m_transport_ready_compat_last_tick == tick
                && m_transport_ready_compat_call_ok
                && m_transport_ready_compat_after_ready_query;
            if (m_deferred_session_connect_last_tick != 0 &&
                tick - m_deferred_session_connect_last_tick <
                    kOnlineStageReadyRetryTicks &&
                !transport_ready_forced_this_tick)
            {
                return;
            }

            const uintptr_t addr = native_address(
                kRVA_HandleLuxorDeferredSessionConnection);
            if (!addr)
            {
                m_deferred_session_connect_failure =
                    "deferred-handler-unavailable";
                return;
            }

            ++m_deferred_session_connect_attempts;
            m_deferred_session_connect_last_tick = tick;
            const uint64_t session_name =
                make_join_session_fname().ToUnstableInt();
            if (m_transport_ready_compat_last_tick == tick &&
                m_transport_ready_compat_attempted)
            {
                emit_transport_ready_compat_trace(tick, "deferred-begin");
            }
            __try
            {
                reinterpret_cast<HandleLuxorDeferredSessionConnectionFn>(
                    addr)(reinterpret_cast<void*>(m_luxor_connect_manager),
                          session_name);
                m_deferred_session_connect_call_ok = true;
                m_deferred_session_connect_failure = "ok";
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                m_deferred_session_connect_call_ok = false;
                m_deferred_session_connect_failure =
                    "deferred-handler-threw";
            }

            if (m_transport_ready_compat_last_tick == tick &&
                m_transport_ready_compat_attempted)
            {
                m_transport_ready_compat_deferred_called_after_force = true;
            }
            sample_luxor_connect_manager_state(is_sandbox);
            if (m_transport_ready_compat_last_tick == tick &&
                m_transport_ready_compat_attempted)
            {
                m_transport_ready_compat_session_connection_after_deferred =
                    m_luxor_session_connection_object;
                if (m_luxor_session_connection_object)
                {
                    m_transport_ready_compat_failure = "ok";
                }
                else if (m_transport_ready_compat_call_ok &&
                         m_transport_ready_compat_after_ready_query)
                {
                    m_transport_ready_compat_failure =
                        "ready-forced-deferred-no-session-connection";
                }
                emit_transport_ready_compat_trace(tick, "deferred-end");
            }
        }

        void sample_active_connect_transport(void* active_connect) noexcept
        {
            if (!active_connect)
                return;
            const auto* const active_bytes =
                static_cast<const uint8_t*>(active_connect);
            uint64_t session_name_raw = 0;
            uint8_t local_user = 0xffu;
            uint8_t connect_state = 0;
            uint8_t connect_sub_state = 0xffu;
            uint32_t state_flags = 0xffffffffu;
            void* state_update_task = nullptr;
            void* state_update_task_ref = nullptr;
            void* notify_task = nullptr;
            void* notify_task_ref = nullptr;
            uint64_t session_event_handle = 0;
            (void)SafeReadUInt64(active_bytes + 0x30, &session_name_raw);
            (void)SafeReadUInt8(active_bytes + 0x3C, &local_user);
            if (SafeReadUInt8(active_bytes + 0x3D, &connect_state))
                m_luxor_active_connect_state = connect_state;
            (void)SafeReadUInt8(active_bytes + 0x3E, &connect_sub_state);
            (void)SafeReadUInt32(active_bytes + 0x40, &state_flags);
            (void)SafeReadPtr(active_bytes + 0x128, &state_update_task);
            (void)SafeReadPtr(
                active_bytes + 0x130, &state_update_task_ref);
            (void)SafeReadPtr(active_bytes + 0x138, &notify_task);
            (void)SafeReadPtr(active_bytes + 0x140, &notify_task_ref);
            (void)SafeReadUInt64(
                active_bytes + 0x148, &session_event_handle);
            m_luxor_active_session_name_raw = session_name_raw;
            m_luxor_active_connect_local_user_byte = local_user;
            m_luxor_active_connect_sub_state = connect_sub_state;
            m_luxor_active_state_flags = state_flags;
            m_luxor_active_session_state_update_task =
                reinterpret_cast<uintptr_t>(state_update_task);
            m_luxor_active_session_state_update_task_ref =
                reinterpret_cast<uintptr_t>(state_update_task_ref);
            m_luxor_active_session_notify_task =
                reinterpret_cast<uintptr_t>(notify_task);
            m_luxor_active_session_notify_task_ref =
                reinterpret_cast<uintptr_t>(notify_task_ref);
            m_luxor_active_session_event_handle = session_event_handle;

            void* vtable = nullptr;
            if (!SafeReadPtr(active_connect, &vtable) || !vtable)
                return;
            void* get_transport_raw = nullptr;
            if (!SafeReadPtr(
                    static_cast<uint8_t*>(vtable) + 0xF8,
                    &get_transport_raw) ||
                !get_transport_raw)
            {
                return;
            }

            void* transport = nullptr;
            __try
            {
                transport =
                    reinterpret_cast<ActiveConnectGetObjectFn>(
                        get_transport_raw)(active_connect);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return;
            }
            m_luxor_active_transport = reinterpret_cast<uintptr_t>(transport);
            if (!transport)
                return;

            const auto* const transport_bytes =
                static_cast<const uint8_t*>(transport);
            uint64_t transport_tick = 0;
            uint32_t channel_count = 0xffffffffu;
            uint32_t channel_capacity = 0xffffffffu;
            uint8_t status_code = 0;
            uint8_t ready_state = 0;
            uint8_t is_host = 0;
            if (SafeReadUInt64(transport_bytes + 0x08, &transport_tick))
                m_luxor_active_transport_tick = transport_tick;
            if (SafeReadUInt32(transport_bytes + 0x18, &channel_count))
                m_luxor_active_transport_channel_count = channel_count;
            if (SafeReadUInt32(transport_bytes + 0x1C, &channel_capacity))
                m_luxor_active_transport_channel_capacity =
                    channel_capacity;
            if (SafeReadUInt8(transport_bytes + 0x20, &status_code))
                m_luxor_active_transport_status_code = status_code;
            if (SafeReadUInt8(transport_bytes + 0x21, &ready_state))
                m_luxor_active_transport_ready_state = ready_state;
            if (SafeReadUInt8(transport_bytes + 0x22, &is_host))
                m_luxor_active_transport_is_host = is_host;

            void* transport_vtable = nullptr;
            void* ready_raw = nullptr;
            if (!SafeReadPtr(transport, &transport_vtable) ||
                !transport_vtable ||
                !SafeReadPtr(
                    static_cast<uint8_t*>(transport_vtable) + 0x88,
                    &ready_raw) ||
                !ready_raw)
            {
                return;
            }
            __try
            {
                m_luxor_active_transport_ready =
                    reinterpret_cast<ActiveConnectByteQueryFn>(ready_raw)(
                        transport) != 0;
                m_luxor_active_transport_ready_sampled = true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
            }
        }

        const char* repeated_session_connect_failure() const noexcept
        {
            if (m_native_named_session_sampled)
            {
                if (!m_native_named_session_ptr)
                    return "session-connect-failed-named-session-missing";
                if (m_native_named_session_state_byte != 1)
                    return "session-connect-failed-named-session-state-not-ready";
            }
            if (m_connect_manager_sampled)
            {
                if (!m_luxor_session_connection_object)
                    return "session-connect-failed-session-connection-missing";
                if (m_luxor_active_transport_ready_sampled &&
                    !m_luxor_active_transport_ready)
                {
                    return "session-connect-failed-transport-not-ready";
                }
            }
            return "session-connect-complete-failed-repeated";
        }

