        static bool ascii_iequals(const std::string& lhs,
                                  const char* rhs) noexcept
        {
            if (!rhs) return lhs.empty();
            return _stricmp(lhs.c_str(), rhs) == 0;
        }

        static uint64_t parse_u64_ascii(const std::string& value) noexcept
        {
            if (value.empty()) return 0;
            char* end = nullptr;
            const unsigned long long parsed =
                std::strtoull(value.c_str(), &end, 0);
            if (end == value.c_str()) return 0;
            return static_cast<uint64_t>(parsed);
        }

        static bool ascii_is_digit(char ch) noexcept
        {
            return ch >= '0' && ch <= '9';
        }

        static bool ascii_is_hex_digit(char ch) noexcept
        {
            return (ch >= '0' && ch <= '9')
                || (ch >= 'a' && ch <= 'f')
                || (ch >= 'A' && ch <= 'F');
        }

        static bool ascii_text_contains_u64_value(
            const std::string& text, uint64_t wanted) noexcept
        {
            if (wanted == 0 || text.empty()) return false;
            size_t pos = 0;
            while (pos < text.size())
            {
                while (pos < text.size()
                       && !ascii_is_digit(text[pos]))
                    ++pos;
                if (pos >= text.size()) break;

                const size_t start = pos;
                size_t end = pos;
                if (text[pos] == '0'
                    && pos + 1 < text.size()
                    && (text[pos + 1] == 'x' || text[pos + 1] == 'X'))
                {
                    end = pos + 2;
                    while (end < text.size()
                           && ascii_is_hex_digit(text[end]))
                        ++end;
                    if (end == pos + 2)
                    {
                        pos = end;
                        continue;
                    }
                }
                else
                {
                    while (end < text.size()
                           && ascii_is_digit(text[end]))
                        ++end;
                }

                const std::string token = text.substr(start, end - start);
                char* parse_end = nullptr;
                const unsigned long long parsed =
                    std::strtoull(token.c_str(), &parse_end, 0);
                if (parse_end != token.c_str()
                    && static_cast<uint64_t>(parsed) == wanted)
                    return true;
                pos = end;
            }
            return false;
        }

        bool session_result_owner_matches(
            const std::string& owner, uint64_t owner_id) const noexcept
        {
            return ascii_text_contains_u64_value(owner, owner_id);
        }

        static bool is_required_lobby_metadata_key(
            const std::string& key) noexcept
        {
            return ascii_iequals(key, "NUMPUBCONN")
                || ascii_iequals(key, "NUMPRIVCONN")
                || ascii_iequals(key, "SESSIONFLAGS")
                || ascii_iequals(key, "BUILDID")
                || ascii_iequals(key, "OWNINGID")
                || ascii_iequals(key, "OWNINGNAME")
                || ascii_iequals(key, "NUMOPENPRIVCONN")
                || ascii_iequals(key, "NUMOPENPUBCONN");
        }

