        bool query_player_match_session_fname(
            RC::Unreal::FName& out) noexcept
        {
            if (m_player_match_session_name_value != 0)
            {
                out = RC::Unreal::FName(
                    static_cast<int64_t>(
                        m_player_match_session_name_value));
                return true;
            }

            m_player_match_session_name_attempted = true;
            m_player_match_session_name_failure = "starting";
            try
            {
                auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                    RC::Unreal::UObject*>(
                        nullptr, nullptr,
                        STR("/Script/LuxorSessionUtil."
                            "Default__LuxorSessionData"));
                if (!safe_is_real(cdo))
                {
                    m_player_match_session_name_failure =
                        "LuxorSessionData CDO unavailable";
                    return false;
                }
                auto* fn = cdo->GetFunctionByNameInChain(
                    L"PlayerMatchName");
                auto* return_prop = fn
                    ? RC::Unreal::CastField<RC::Unreal::FNameProperty>(
                          fn->GetReturnProperty())
                    : nullptr;
                const int32_t param_bytes =
                    fn ? fn->GetPropertiesSize() : 0;
                if (!fn || !return_prop || param_bytes <= 0 ||
                    param_bytes > 256)
                {
                    m_player_match_session_name_failure =
                        "PlayerMatchName reflection unavailable";
                    return false;
                }

                std::vector<uint8_t> params(
                    static_cast<size_t>(param_bytes), 0);
                return_prop->InitializeValue_InContainer(params.data());
                const bool called =
                    safe_process_event(cdo, fn, params.data());
                auto* value = return_prop->ContainerPtrToValuePtr<
                    RC::Unreal::FName>(params.data());
                if (called && value && value->ToUnstableInt() != 0)
                {
                    out = *value;
                    m_player_match_session_name_value =
                        value->ToUnstableInt();
                    m_player_match_session_name_text =
                        narrow_rc_string(value->ToString());
                    m_player_match_session_name_failure = "ok";
                }
                else
                {
                    m_player_match_session_name_failure =
                        called ? "PlayerMatchName returned None"
                               : "PlayerMatchName ProcessEvent failed";
                }
                return_prop->DestroyValue_InContainer(params.data());
                return m_player_match_session_name_value != 0;
            }
            catch (...)
            {
                m_player_match_session_name_failure =
                    "PlayerMatchName reflection threw";
                return false;
            }
        }

        RC::Unreal::FName make_join_session_fname()
        {
            RC::Unreal::FName player_match_name;
            if (query_player_match_session_fname(player_match_name))
                return player_match_name;
            const std::string session = effective_join_session_name();
            const std::wstring session_w = widen_utf8(session);
            return RC::Unreal::FName(
                session_w.c_str(), RC::Unreal::FNAME_Add);
        }

