        bool service_ready_open_compat_if_needed(
            uint64_t tick,
            bool is_host) noexcept
        {
            const bool canonical_stock_route =
                RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route);
            if (canonical_stock_route)
            {
                if (!is_host)
                {
                    m_ready_open_compat_failure = "role-not-host";
                    return false;
                }
                if (!m_ready_open_compat_mark_ready_attempted ||
                    !m_ready_open_compat_mark_ready_call_ok)
                {
                    m_ready_open_compat_failure =
                        "stock-session-transport-mark-pending";
                    return false;
                }
                if (s_session_opcode0b_response_calls.load(
                        std::memory_order_acquire) == 0 ||
                    !s_session_opcode0b_response_result.load(
                        std::memory_order_acquire))
                {
                    m_ready_open_compat_failure =
                        "stock-peer-transport-response-pending";
                    return false;
                }
                if (m_ready_open_compat_count > 0)
                    return m_ready_open_compat_call_ok;
                if (!m_luxor_session_connection_object ||
                    !m_luxor_active_transport ||
                    !m_ready_preconditions_sampled ||
                    m_ready_connect_state != 3 ||
                    m_ready_channel_state != 1 ||
                    m_ready_channel_can_send)
                {
                    m_ready_open_compat_failure =
                        "stock-ready-open-boundary-pending";
                    return false;
                }

                const uintptr_t addr = native_address(
                    kRVA_OpenLuxorReadyChannelForSession);
                if (!addr)
                {
                    m_ready_open_compat_failure =
                        "native-address-unavailable";
                    return false;
                }
                m_ready_open_compat_attempted = true;
                ++m_ready_open_compat_count;
                m_ready_open_compat_last_tick = tick;
                m_ready_open_compat_can_send_before =
                    m_ready_channel_can_send_raw_4c;
                m_ready_open_compat_call_ok =
                    safe_native_open_luxor_ready_channel(
                        reinterpret_cast<
                            OpenLuxorReadyChannelForSessionFn>(addr),
                        reinterpret_cast<void*>(
                            m_luxor_session_connection_object),
                        reinterpret_cast<void*>(
                            m_luxor_active_transport));
                m_ready_open_compat_failure =
                    m_ready_open_compat_call_ok
                        ? "stock-post-response-open-called"
                        : "native-call-exception";

                ReplayTraceFields f;
                f.string("request_id", m_cfg.request_id)
                 .string("client_role", m_cfg.client_role)
                 .uinteger("tick", tick)
                 .hex("session_connection",
                      m_luxor_session_connection_object)
                 .hex("active_transport", m_luxor_active_transport)
                 .uinteger("ready_channel_state",
                           m_ready_channel_state)
                 .uinteger("ready_channel_can_send_before",
                           m_ready_channel_can_send_raw_4c)
                 .boolean("call_ok", m_ready_open_compat_call_ok)
                 .string("phase", "stock-post-response");
                ReplayDebugTrace::instance().event(
                    "rollback_online_stage_ready_open_compat", f);
                return m_ready_open_compat_call_ok;
            }
            if (!m_cfg.online_stage_ready_open_compat)
            {
                m_ready_open_compat_failure = "disabled";
                return false;
            }
            if (!is_host)
            {
                m_ready_open_compat_failure = "role-not-host";
                return false;
            }
            if (m_ready_open_compat_count > 0)
            {
                m_ready_open_compat_failure =
                    m_ready_open_compat_call_ok
                        ? "already-called"
                        : "already-attempted";
                return false;
            }
            if (!m_session_connect_complete_seen ||
                !m_session_connect_complete_result)
            {
                m_ready_open_compat_failure =
                    "session-connect-complete-not-ready";
                return false;
            }
            if (!m_luxor_session_connection_object)
            {
                m_ready_open_compat_failure =
                    "session-connection-missing";
                return false;
            }
            if (!m_luxor_active_transport)
            {
                m_ready_open_compat_failure =
                    "active-transport-missing";
                return false;
            }
            const bool active_connect_ready_for_open =
                m_luxor_active_connect_state == 1 ||
                m_luxor_active_connect_state == 3;
            if (!active_connect_ready_for_open)
            {
                m_ready_open_compat_failure =
                    "active-connect-state-not-ready-open";
                return false;
            }
            if (!m_luxor_active_session_name_raw ||
                !m_luxor_active_session_event_handle)
            {
                m_ready_open_compat_failure =
                    "active-connect-session-fields-missing";
                return false;
            }
            if (!m_ready_preconditions_sampled ||
                !m_ready_online_session_present ||
                !m_ready_connect_system ||
                !m_ready_connect_channel ||
                !m_ready_session_connection_registry)
            {
                m_ready_open_compat_failure =
                    "ready-precondition-evidence-missing";
                return false;
            }
            if (m_ready_connect_state != 3 ||
                m_ready_channel_state != 1 ||
                m_ready_channel_can_send)
            {
                m_ready_open_compat_failure =
                    "ready-precondition-not-in-open-gap";
                return false;
            }
            if (m_start_latch_requested || m_ready_requested)
            {
                m_ready_open_compat_failure =
                    "ready-already-requested";
                return false;
            }
            const uint64_t open_calls_before =
                s_ready_channel_open_calls.load(
                    std::memory_order_acquire);
            if (open_calls_before != 0)
            {
                m_ready_open_compat_failure =
                    "native-open-already-observed";
                return false;
            }
            if (!s_ready_channel_open_hook_installed.load(
                    std::memory_order_acquire))
            {
                m_ready_open_compat_failure =
                    "open-hook-not-installed";
                return false;
            }

            const LuxorRouteTagGlobalsSnapshot route_tag_globals =
                sample_luxor_route_tag_globals();
            const uint64_t route_writer_assign_calls =
                s_route_writer_assign_calls.load(
                    std::memory_order_acquire);
            const uint64_t route_writer_acquire_calls =
                s_route_writer_acquire_calls.load(
                    std::memory_order_acquire);
            const uintptr_t route_writer_assign_tag =
                s_route_writer_assign_last_route_tag.load(
                    std::memory_order_acquire);
            const uintptr_t route_writer_acquire_tag =
                s_route_writer_acquire_last_route_tag.load(
                    std::memory_order_acquire);
            const uint32_t route_writer_assign_index =
                s_route_writer_assign_last_selected_index.load(
                    std::memory_order_acquire);
            const uint32_t route_writer_acquire_index =
                s_route_writer_acquire_last_selected_index.load(
                    std::memory_order_acquire);
            const bool assigned_peer_writer =
                route_writer_assign_calls > 0 &&
                route_writer_assign_index != 0xffffffffu &&
                route_writer_assign_index > 0 &&
                route_writer_assign_tag != 0 &&
                !luxor_route_tag_matches_replacement(
                    route_writer_assign_tag, route_tag_globals);
            const bool acquired_peer_writer =
                route_writer_acquire_calls > 0 &&
                route_writer_acquire_index != 0xffffffffu &&
                route_writer_acquire_index > 0 &&
                route_writer_acquire_tag != 0 &&
                !luxor_route_tag_matches_replacement(
                    route_writer_acquire_tag, route_tag_globals);
            if (!assigned_peer_writer && !acquired_peer_writer)
            {
                m_ready_open_compat_failure =
                    "peer-route-writer-not-assigned";
                return false;
            }

            const bool peer_route_tag_fix_enabled =
                s_peer_route_tag_fix_enabled.load(
                    std::memory_order_acquire);
            const uintptr_t peer_route_tag =
                s_peer_route_tag_fix_last_peer_tag.load(
                    std::memory_order_acquire);
            const uintptr_t peer_writer =
                s_peer_route_tag_fix_last_peer_writer.load(
                    std::memory_order_acquire);
            const uint32_t peer_registry_index =
                s_peer_route_tag_fix_last_peer_registry_index.load(
                    std::memory_order_acquire);
            m_ready_open_compat_peer_writer = peer_writer;
            m_ready_open_compat_peer_route_tag = peer_route_tag;
            m_ready_open_compat_peer_registry_index =
                peer_registry_index;
            auto remember_small_route_gate =
                [this](const LuxorSmallRouteStateSnapshot& snapshot)
                    noexcept
            {
                m_ready_open_compat_small_route_sample_ok =
                    snapshot.ok ? 1u : 0u;
                m_ready_open_compat_small_route_next_available =
                    snapshot.next_available ? 1u : 0u;
                m_ready_open_compat_small_route_next_slot_present =
                    snapshot.next_slot_present ? 1u : 0u;
                m_ready_open_compat_small_route_count = snapshot.count;
                m_ready_open_compat_small_route_limit = snapshot.limit;
                m_ready_open_compat_small_route_sequence_counter =
                    snapshot.sequence_counter;
                m_ready_open_compat_small_route_next_sequence =
                    snapshot.next_sequence;
                m_ready_open_compat_small_route_collision_index =
                    snapshot.collision_entry_index;
            };
            auto remember_parent_gate =
                [this](
                    const LuxorRouteWriterParentReadySnapshot& snapshot)
                    noexcept
            {
                m_ready_open_compat_parent_sample_ok =
                    snapshot.ok ? 1u : 0u;
                m_ready_open_compat_parent_state = snapshot.state;
                m_ready_open_compat_parent_ready_flags =
                    snapshot.ready_flags;
                m_ready_open_compat_parent_ready_flag_set =
                    snapshot.flag_set ? 1u : 0u;
                m_ready_open_compat_parent_ready_state_ok =
                    snapshot.state_ok ? 1u : 0u;
                m_ready_open_compat_parent_ready =
                    snapshot.ready ? 1u : 0u;
                m_ready_open_compat_parent_state_target =
                    snapshot.state_target;
            };
            LuxorRouteWriterParentReadySnapshot parent_before_open {};
            auto emit_small_route_gate =
                [&](const char* phase,
                    const LuxorSmallRouteStateSnapshot& snapshot) noexcept
            {
                if (!s_session_trace_enabled.load(
                        std::memory_order_acquire))
                    return;
                ReplayTraceFields f;
                f.string("request_id", m_cfg.request_id)
                 .string("client_role", m_cfg.client_role)
                 .uinteger("tick", tick)
                 .string("phase", phase ? phase : "")
                 .string("failure", m_ready_open_compat_failure)
                 .hex("peer_route_tag", peer_route_tag)
                 .hex("peer_writer", peer_writer)
                 .uinteger("peer_registry_index",
                           peer_registry_index)
                 .boolean("peer_route_tag_fix_enabled",
                          peer_route_tag_fix_enabled)
                 .hex("parent", parent_before_open.parent)
                 .hex("parent_vtable", parent_before_open.vtable)
                 .hex("parent_state_target",
                      parent_before_open.state_target)
                 .hex("parent_ready_target",
                      parent_before_open.ready_target)
                 .hex("parent_backend_get_target",
                      parent_before_open.backend_get_target)
                 .boolean("parent_sample_ok",
                          parent_before_open.ok)
                 .uinteger("parent_state",
                           parent_before_open.state)
                 .uinteger("parent_ready_flags",
                           parent_before_open.ready_flags)
                 .boolean("parent_ready_flag_set",
                          parent_before_open.flag_set)
                 .boolean("parent_ready_state_ok",
                          parent_before_open.state_ok)
                 .boolean("parent_ready", parent_before_open.ready)
                 .hex("small_route_state", snapshot.state)
                 .hex("small_route_vtable", snapshot.vtable)
                 .hex("small_route_entries", snapshot.entries)
                 .hex("small_route_buckets", snapshot.buckets)
                 .boolean("small_route_sample_ok", snapshot.ok)
                 .uinteger("small_route_count", snapshot.count)
                 .uinteger("small_route_limit", snapshot.limit)
                 .uinteger(
                     "small_route_bucket_mask_plus_one",
                     snapshot.bucket_mask_plus_one)
                 .uinteger(
                     "small_route_sequence_counter",
                     snapshot.sequence_counter)
                 .uinteger("small_route_next_sequence",
                           snapshot.next_sequence)
                 .boolean("small_route_next_available",
                          snapshot.next_available)
                 .boolean("small_route_next_slot_present",
                          snapshot.next_slot_present)
                 .integer("small_route_bucket_index",
                          snapshot.bucket_index)
                 .integer(
                     "small_route_collision_entry_index",
                     snapshot.collision_entry_index)
                 .uinteger("small_route_walk_steps",
                           snapshot.walk_steps);
                ReplayDebugTrace::instance().event(
                    "rollback_online_stage_ready_open_small_route_gate",
                    f);
            };
            LuxorSmallRouteStateSnapshot small_route_before_open {};
            if (peer_route_tag_fix_enabled)
            {
                if (!luxor_route_tag_is_peer_fix_candidate(
                        peer_route_tag, route_tag_globals) ||
                    !peer_writer ||
                    peer_registry_index == 0xffffffffu ||
                    peer_registry_index == 0)
                {
                    m_ready_open_compat_failure =
                        "peer-route-tag-fix-cache-missing";
                    remember_parent_gate(parent_before_open);
                    remember_small_route_gate(small_route_before_open);
                    emit_small_route_gate(
                        "peer-cache-missing",
                        small_route_before_open);
                    return false;
                }
                parent_before_open =
                    sample_luxor_route_writer_parent_ready(
                        reinterpret_cast<void*>(peer_writer));
                small_route_before_open =
                    sample_luxor_small_route_state(
                        reinterpret_cast<void*>(peer_writer));
                remember_parent_gate(parent_before_open);
                remember_small_route_gate(small_route_before_open);
                if (!parent_before_open.ok)
                {
                    m_ready_open_compat_failure =
                        "parent-ready-sample-unavailable";
                    emit_small_route_gate(
                        "parent-sample-unavailable",
                        small_route_before_open);
                    return false;
                }
                if (!parent_before_open.flag_set)
                {
                    m_ready_open_compat_failure =
                        "parent-ready-flag-missing";
                    emit_small_route_gate(
                        "parent-ready-flag-missing",
                        small_route_before_open);
                    return false;
                }
                if (!parent_before_open.state_ok)
                {
                    m_ready_open_compat_failure =
                        "parent-ready-state-not-ready";
                    emit_small_route_gate(
                        "parent-ready-state-not-ready",
                        small_route_before_open);
                    return false;
                }
                if (!small_route_before_open.ok)
                {
                    m_ready_open_compat_failure =
                        "small-route-sample-unavailable";
                    emit_small_route_gate(
                        "sample-unavailable",
                        small_route_before_open);
                    return false;
                }
                if (!small_route_before_open.next_available)
                {
                    m_ready_open_compat_failure =
                        "small-route-next-slot-busy";
                    emit_small_route_gate(
                        "next-slot-busy",
                        small_route_before_open);
                    return false;
                }
                emit_small_route_gate(
                    "next-slot-ready",
                    small_route_before_open);
            }

            const uintptr_t addr =
                native_address(kRVA_OpenLuxorReadyChannelForSession);
            if (!addr)
            {
                m_ready_open_compat_failure =
                    "native-address-unavailable";
                return false;
            }

            m_ready_open_compat_attempted = true;
            m_ready_open_compat_call_ok = false;
            ++m_ready_open_compat_count;
            m_ready_open_compat_last_tick = tick;
            m_ready_open_compat_open_calls_before = open_calls_before;
            m_ready_open_compat_can_send_before =
                m_ready_channel_can_send_raw_4c;
            m_ready_open_compat_failure = "starting";

            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("tick", tick)
             .hex("session_connection", m_luxor_session_connection_object)
             .hex("active_transport", m_luxor_active_transport)
             .uinteger("active_transport_ready_state",
                       m_luxor_active_transport_ready_state)
             .hex("ready_channel", m_ready_connect_channel)
             .uinteger("ready_channel_can_send_raw_4c",
                       m_ready_channel_can_send_raw_4c)
             .uinteger("open_calls_before", open_calls_before)
             .uinteger("route_writer_assign_calls",
                       route_writer_assign_calls)
             .hex("route_writer_assign_last_route_tag",
                  route_writer_assign_tag)
             .uinteger("route_writer_assign_last_selected_index",
                       route_writer_assign_index)
             .uinteger("route_writer_acquire_calls",
                       route_writer_acquire_calls)
             .hex("route_writer_acquire_last_route_tag",
                  route_writer_acquire_tag)
             .uinteger("route_writer_acquire_last_selected_index",
                       route_writer_acquire_index)
             .boolean("assigned_peer_writer", assigned_peer_writer)
             .boolean("acquired_peer_writer", acquired_peer_writer)
             .boolean("peer_route_tag_fix_enabled",
                      peer_route_tag_fix_enabled)
             .hex("peer_route_tag", peer_route_tag)
             .hex("peer_writer", peer_writer)
             .uinteger("peer_registry_index", peer_registry_index)
             .hex("parent", parent_before_open.parent)
             .hex("parent_vtable", parent_before_open.vtable)
             .hex("parent_state_target",
                  parent_before_open.state_target)
             .hex("parent_ready_target",
                  parent_before_open.ready_target)
             .hex("parent_backend_get_target",
                  parent_before_open.backend_get_target)
             .boolean("parent_sample_ok", parent_before_open.ok)
             .uinteger("parent_state", parent_before_open.state)
             .uinteger("parent_ready_flags",
                       parent_before_open.ready_flags)
             .boolean("parent_ready_flag_set",
                      parent_before_open.flag_set)
             .boolean("parent_ready_state_ok",
                      parent_before_open.state_ok)
             .boolean("parent_ready", parent_before_open.ready)
             .boolean("small_route_sample_ok",
                      small_route_before_open.ok)
             .uinteger("small_route_count",
                       small_route_before_open.count)
             .uinteger("small_route_limit",
                       small_route_before_open.limit)
             .uinteger(
                 "small_route_sequence_counter",
                 small_route_before_open.sequence_counter)
             .uinteger("small_route_next_sequence",
                       small_route_before_open.next_sequence)
             .boolean("small_route_next_available",
                      small_route_before_open.next_available)
             .boolean("small_route_next_slot_present",
                      small_route_before_open.next_slot_present)
             .integer(
                 "small_route_collision_entry_index",
                 small_route_before_open.collision_entry_index)
             .boolean("mark_ready_attempted",
                      m_ready_open_compat_mark_ready_attempted)
             .boolean("mark_ready_call_ok",
                      m_ready_open_compat_mark_ready_call_ok)
             .uinteger("mark_ready_before",
                       m_ready_open_compat_mark_ready_before)
             .uinteger("mark_ready_after",
                       m_ready_open_compat_mark_ready_after)
             .string("mark_ready_failure",
                     m_ready_open_compat_mark_ready_failure)
             .string("phase", "before-call");
            ReplayDebugTrace::instance().event(
                "rollback_online_stage_ready_open_compat", f);

            m_ready_open_compat_call_ok =
                safe_native_open_luxor_ready_channel(
                    reinterpret_cast<OpenLuxorReadyChannelForSessionFn>(
                        addr),
                    reinterpret_cast<void*>(
                        m_luxor_session_connection_object),
                    reinterpret_cast<void*>(m_luxor_active_transport));
            m_ready_open_compat_failure =
                m_ready_open_compat_call_ok ? "ok"
                                            : "native-call-exception";

            if (!m_ready_open_compat_call_ok)
            {
                m_ready_open_compat_failure = "native-call-exception";
            }

            m_ready_open_compat_open_calls_after =
                s_ready_channel_open_calls.load(
                    std::memory_order_acquire);
            m_ready_open_compat_can_send_after =
                s_ready_channel_open_last_can_send_after.load(
                    std::memory_order_acquire);
            const LuxorSmallRouteStateSnapshot small_route_after_open =
                peer_route_tag_fix_enabled && peer_writer
                    ? sample_luxor_small_route_state(
                          reinterpret_cast<void*>(peer_writer))
                    : LuxorSmallRouteStateSnapshot {};

            if (m_ready_open_compat_call_ok &&
                m_ready_open_compat_open_calls_after >
                    m_ready_open_compat_open_calls_before &&
                m_ready_open_compat_can_send_after == 0)
            {
                m_ready_open_compat_failure =
                    "queued-awaiting-can-send";
            }

            ReplayTraceFields after;
            after.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("tick", tick)
             .boolean("call_ok", m_ready_open_compat_call_ok)
             .string("failure", m_ready_open_compat_failure)
             .uinteger("open_calls_after",
                       m_ready_open_compat_open_calls_after)
             .uinteger("ready_channel_can_send_after",
                       m_ready_open_compat_can_send_after)
             .boolean("peer_route_tag_fix_enabled",
                      peer_route_tag_fix_enabled)
             .hex("peer_route_tag", peer_route_tag)
             .hex("peer_writer", peer_writer)
             .uinteger("peer_registry_index", peer_registry_index)
             .boolean("small_route_before_sample_ok",
                      small_route_before_open.ok)
             .uinteger("small_route_before_count",
                       small_route_before_open.count)
             .uinteger(
                 "small_route_before_sequence_counter",
                 small_route_before_open.sequence_counter)
             .uinteger("small_route_before_next_sequence",
                       small_route_before_open.next_sequence)
             .boolean("small_route_before_next_available",
                      small_route_before_open.next_available)
             .boolean("small_route_before_next_slot_present",
                      small_route_before_open.next_slot_present)
             .integer(
                 "small_route_before_collision_entry_index",
                 small_route_before_open.collision_entry_index)
             .boolean("small_route_after_sample_ok",
                      small_route_after_open.ok)
             .uinteger("small_route_after_count",
                       small_route_after_open.count)
             .uinteger(
                 "small_route_after_sequence_counter",
                 small_route_after_open.sequence_counter)
             .uinteger("small_route_after_next_sequence",
                       small_route_after_open.next_sequence)
             .boolean("small_route_after_next_available",
                      small_route_after_open.next_available)
             .boolean("small_route_after_next_slot_present",
                      small_route_after_open.next_slot_present)
             .integer(
                 "small_route_after_collision_entry_index",
                 small_route_after_open.collision_entry_index)
             .boolean("mark_ready_attempted",
                      m_ready_open_compat_mark_ready_attempted)
             .boolean("mark_ready_call_ok",
                      m_ready_open_compat_mark_ready_call_ok)
             .uinteger("mark_ready_before",
                       m_ready_open_compat_mark_ready_before)
             .uinteger("mark_ready_after",
                       m_ready_open_compat_mark_ready_after)
             .string("mark_ready_failure",
                     m_ready_open_compat_mark_ready_failure)
             .string("phase", "after-call");
            ReplayDebugTrace::instance().event(
                "rollback_online_stage_ready_open_compat", after);
            return m_ready_open_compat_call_ok;
        }

        static bool safe_native_open_luxor_ready_channel(
            OpenLuxorReadyChannelForSessionFn fn,
            void* session_connection,
            void* active_transport) noexcept
        {
            if (!fn || !session_connection || !active_transport)
                return false;
            __try
            {
                fn(session_connection, active_transport);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        void sample_request_ready_preconditions() noexcept
        {
            m_ready_preconditions_sampled = true;
            m_ready_preconditions_ok = false;
            m_ready_precondition_failure = "starting";
            m_ready_online_session_present = false;
            m_ready_connect_system = 0;
            m_ready_connect_vtable = 0;
            m_ready_connect_get_channel_fn = 0;
            m_ready_connect_state_fn = 0;
            m_ready_connect_channel = 0;
            m_ready_channel_vtable = 0;
            m_ready_channel_can_send_fn = 0;
            m_ready_channel_state_fn = 0;
            m_ready_connect_sender = 0;
            m_ready_sender_vtable = 0;
            m_ready_session_connection_registry = 0;
            m_ready_session_connection_registry_vtable = 0;
            m_ready_session_connection_registry_attach_fn = 0;
            m_ready_session_connection_registry_lookup_fn = 0;
            m_ready_session_connection_registry_step80_fn = 0;
            m_ready_session_connection_registry_stepd0_fn = 0;
            m_ready_session_connection_registry_stepd8_fn = 0;
            m_ready_channel_qword_08 = 0;
            m_ready_channel_field_20 = 0xffffffffu;
            m_ready_channel_raw_48 = 0xffffffffffffffffull;
            m_ready_channel_byte_49 = 0xffu;
            m_ready_channel_byte_4a = 0xffu;
            m_ready_channel_byte_4b = 0xffu;
            m_ready_channel_can_send_raw_4c = 0xffu;
            m_ready_channel_byte_4d = 0xffu;
            m_ready_channel_byte_4e = 0xffu;
            m_ready_channel_byte_4f = 0xffu;
            m_ready_channel_qword_58 = 0;
            m_ready_channel_qword_70 = 0;
            m_ready_channel_qword_88 = 0;
            m_ready_channel_qword_90 = 0;
            m_ready_connect_state = -1;
            m_ready_channel_state = -1;
            m_ready_channel_can_send = false;

            const uintptr_t online_addr =
                native_address(kRVA_GetOnlineSessionInterfaceShared);
            if (!online_addr)
            {
                m_ready_precondition_failure =
                    "online-session-resolver-unavailable";
                return;
            }
            SharedInterfaceNative shared {};
            if (!safe_get_online_session_interface(
                    reinterpret_cast<GetOnlineSessionInterfaceSharedFn>(
                        online_addr),
                    0,
                    &shared))
            {
                m_ready_precondition_failure =
                    "online-session-resolver-threw";
                return;
            }
            m_ready_online_session_present = shared.object != nullptr;
            if (!m_ready_online_session_present)
            {
                m_ready_precondition_failure =
                    "online-session-unavailable";
                return;
            }

            const uintptr_t connect_addr =
                native_address(kRVA_ResolveConnectSystem);
            const uintptr_t sender_addr =
                native_address(kRVA_ResolveConnectSender);
            if (!connect_addr || !sender_addr)
            {
                m_ready_precondition_failure =
                    "connect-system-resolver-unavailable";
                return;
            }

            auto* resolve_connect =
                reinterpret_cast<ResolveConnectObjectFn>(connect_addr);
            auto* resolve_sender =
                reinterpret_cast<ResolveConnectObjectFn>(sender_addr);
            void* connect = nullptr;
            void* channel = nullptr;
            void* sender = nullptr;
            __try
            {
                connect = resolve_connect();
                sender = resolve_sender();
                m_ready_connect_system =
                    reinterpret_cast<uintptr_t>(connect);
                m_ready_connect_sender =
                    reinterpret_cast<uintptr_t>(sender);
                if (sender)
                {
                    void* sender_vtable = nullptr;
                    if (SafeReadPtr(sender, &sender_vtable))
                        m_ready_sender_vtable =
                            reinterpret_cast<uintptr_t>(sender_vtable);
                }
                if (!connect)
                {
                    m_ready_precondition_failure =
                        "connect-system-unavailable";
                    return;
                }

                void* connect_vtable = nullptr;
                if (!SafeReadPtr(connect, &connect_vtable) ||
                    !connect_vtable)
                {
                    m_ready_precondition_failure =
                        "connect-system-vtable-unreadable";
                    return;
                }
                m_ready_connect_vtable =
                    reinterpret_cast<uintptr_t>(connect_vtable);
                auto get_channel =
                    *reinterpret_cast<ConnectSystemGetChannelFn*>(
                        static_cast<uint8_t*>(connect_vtable) + 0x48);
                auto get_connect_state =
                    *reinterpret_cast<ConnectSystemByteQueryFn*>(
                        static_cast<uint8_t*>(connect_vtable) + 0x38);
                m_ready_connect_get_channel_fn =
                    reinterpret_cast<uintptr_t>(get_channel);
                m_ready_connect_state_fn =
                    reinterpret_cast<uintptr_t>(get_connect_state);
                if (!get_channel || !get_connect_state)
                {
                    m_ready_precondition_failure =
                        "connect-system-vtable-slot-unavailable";
                    return;
                }

                void* channel_key =
                    reinterpret_cast<void*>(
                        native_address(kRVA_ReadyToConnectChannelKey));
                channel = get_channel(connect, channel_key);
                m_ready_connect_channel =
                    reinterpret_cast<uintptr_t>(channel);
                m_ready_connect_state =
                    static_cast<int32_t>(get_connect_state(connect));
                if (!channel)
                {
                    m_ready_precondition_failure =
                        "ready-channel-unavailable";
                    return;
                }

                if (m_luxor_session_connection_object)
                {
                    const auto* const session_bytes =
                        reinterpret_cast<const uint8_t*>(
                            m_luxor_session_connection_object);
                    const auto* const registry = session_bytes + 0x60;
                    m_ready_session_connection_registry =
                        reinterpret_cast<uintptr_t>(registry);
                    void* registry_vtable = nullptr;
                    if (SafeReadPtr(registry, &registry_vtable) &&
                        registry_vtable)
                    {
                        m_ready_session_connection_registry_vtable =
                            reinterpret_cast<uintptr_t>(registry_vtable);
                        void* fn = nullptr;
                        if (SafeReadPtr(
                                static_cast<uint8_t*>(registry_vtable) +
                                    0x28,
                                &fn))
                        {
                            m_ready_session_connection_registry_attach_fn =
                                reinterpret_cast<uintptr_t>(fn);
                        }
                        if (SafeReadPtr(
                                static_cast<uint8_t*>(registry_vtable) +
                                    0x60,
                                &fn))
                        {
                            m_ready_session_connection_registry_lookup_fn =
                                reinterpret_cast<uintptr_t>(fn);
                        }
                        if (SafeReadPtr(
                                static_cast<uint8_t*>(registry_vtable) +
                                    0x80,
                                &fn))
                        {
                            m_ready_session_connection_registry_step80_fn =
                                reinterpret_cast<uintptr_t>(fn);
                        }
                        if (SafeReadPtr(
                                static_cast<uint8_t*>(registry_vtable) +
                                    0xD0,
                                &fn))
                        {
                            m_ready_session_connection_registry_stepd0_fn =
                                reinterpret_cast<uintptr_t>(fn);
                        }
                        if (SafeReadPtr(
                                static_cast<uint8_t*>(registry_vtable) +
                                    0xD8,
                                &fn))
                        {
                            m_ready_session_connection_registry_stepd8_fn =
                                reinterpret_cast<uintptr_t>(fn);
                        }
                    }
                }

                const auto* const channel_bytes =
                    static_cast<const uint8_t*>(channel);
                (void)SafeReadUInt64(
                    channel_bytes + 0x08, &m_ready_channel_qword_08);
                (void)SafeReadUInt32(
                    channel_bytes + 0x20, &m_ready_channel_field_20);
                (void)SafeReadUInt64(
                    channel_bytes + 0x48, &m_ready_channel_raw_48);
                uint8_t channel_byte = 0xffu;
                if (SafeReadUInt8(channel_bytes + 0x49, &channel_byte))
                    m_ready_channel_byte_49 = channel_byte;
                if (SafeReadUInt8(channel_bytes + 0x4A, &channel_byte))
                    m_ready_channel_byte_4a = channel_byte;
                if (SafeReadUInt8(channel_bytes + 0x4B, &channel_byte))
                    m_ready_channel_byte_4b = channel_byte;
                if (SafeReadUInt8(channel_bytes + 0x4C, &channel_byte))
                    m_ready_channel_can_send_raw_4c = channel_byte;
                if (SafeReadUInt8(channel_bytes + 0x4D, &channel_byte))
                    m_ready_channel_byte_4d = channel_byte;
                if (SafeReadUInt8(channel_bytes + 0x4E, &channel_byte))
                    m_ready_channel_byte_4e = channel_byte;
                if (SafeReadUInt8(channel_bytes + 0x4F, &channel_byte))
                    m_ready_channel_byte_4f = channel_byte;
                (void)SafeReadUInt64(
                    channel_bytes + 0x58, &m_ready_channel_qword_58);
                (void)SafeReadUInt64(
                    channel_bytes + 0x70, &m_ready_channel_qword_70);
                (void)SafeReadUInt64(
                    channel_bytes + 0x88, &m_ready_channel_qword_88);
                (void)SafeReadUInt64(
                    channel_bytes + 0x90, &m_ready_channel_qword_90);

                void* channel_vtable = nullptr;
                if (!SafeReadPtr(channel, &channel_vtable) ||
                    !channel_vtable)
                {
                    m_ready_precondition_failure =
                        "ready-channel-vtable-unreadable";
                    return;
                }
                m_ready_channel_vtable =
                    reinterpret_cast<uintptr_t>(channel_vtable);
                auto get_channel_can_send =
                    *reinterpret_cast<ConnectSystemByteQueryFn*>(
                        static_cast<uint8_t*>(channel_vtable) + 0x28);
                auto get_channel_state =
                    *reinterpret_cast<ConnectSystemByteQueryFn*>(
                        static_cast<uint8_t*>(channel_vtable) + 0x40);
                m_ready_channel_can_send_fn =
                    reinterpret_cast<uintptr_t>(get_channel_can_send);
                m_ready_channel_state_fn =
                    reinterpret_cast<uintptr_t>(get_channel_state);
                if (!get_channel_can_send || !get_channel_state)
                {
                    m_ready_precondition_failure =
                        "ready-channel-vtable-slot-unavailable";
                    return;
                }

                m_ready_channel_state =
                    static_cast<int32_t>(get_channel_state(channel));
                m_ready_channel_can_send =
                    get_channel_can_send(channel) != 0;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                m_ready_precondition_failure =
                    "ready-precondition-sample-threw";
                return;
            }

            if (m_ready_connect_state != 3)
            {
                m_ready_precondition_failure =
                    "connect-state-not-ready";
                return;
            }
            if (m_ready_channel_state != 1)
            {
                m_ready_precondition_failure =
                    "ready-channel-state-not-ready";
                return;
            }
            if (!m_ready_channel_can_send)
            {
                m_ready_precondition_failure =
                    "ready-channel-cannot-send";
                return;
            }

            m_ready_preconditions_ok = true;
            m_ready_precondition_failure = "ok";
        }


        bool service_online_stage_start_cleanup(
            uint64_t tick,
            OnlineNavigatorObjects& nav,
            RC::Unreal::UObject* session_hub,
            bool session_hub_ok,
            bool is_host) noexcept
        {
            if (!m_cfg.online_stage_cleanup_only ||
                !m_cfg.online_stage_requested)
                return true;
            (void)is_host;
            const bool in_battle = identity_contains_scene(
                nav.current_scene_identity, "PlayerMatchScene");
            const bool in_lobby = identity_contains_scene(
                nav.current_scene_identity, "PlayerMatchLobbyScene");
            const bool in_main_menu = identity_contains_scene(
                nav.current_scene_identity, "MainMenuScene");
            const bool in_title = identity_contains_scene(
                nav.current_scene_identity, "TitleScene");

            (void)m_stock_driver.observe_cleanup({
                nav.current_scene != nullptr
                    && nav.current_scene_identity.object_real
                    && nav.current_scene_identity.class_real,
                in_battle,
                in_lobby,
                in_title,
                in_main_menu,
                m_cleanup_battle_exit_requested,
                m_destroy_start_wait_complete,
                m_cleanup_title_scene_seen,
                m_cleanup_title_scene_seen
                    && in_main_menu
                    && m_cleanup_main_menu_stable,
            });

            // A failed invite can already have returned one client to Main
            // Menu while the room owner is still in its lobby.  That client
            // has no session to destroy, but it still needs the canonical
            // Title -> EmulateTitleDecide -> Main Menu reset or the next
            // Player Match attempt can retain stale online state.
            if (!m_destroy_start_requested && (in_main_menu || in_title))
            {
                bool main_menu_ready = false;
                std::string reason;
                (void)request_stock_cleanup_main_menu_scene(
                    tick, nav, main_menu_ready, reason);
                m_destroy_start_failure = main_menu_ready
                    ? "ok" : "main-menu-transition-pending";
                m_destroy_start_wait_complete = main_menu_ready;
                return main_menu_ready;
            }
            if (in_battle)
            {
                // PlayerMatchScene's cooked UI lifecycle is deliberately two
                // step. GoBackToLobby sends ExitBattle through SessionHub;
                // OnRecvPacketMessage then sets bExitBattle. The Result
                // OnDecide handler observes that flag, calls RequestBattleEnd,
                // and performs the normal battlelobby/InRoom transition. Do
                // not replace either step with a direct scene launch: doing so
                // skips stock session teardown and poisons later room creates.
                if (!m_cleanup_battle_exit_requested)
                {
                    m_cleanup_battle_exit_request_tick = tick;
                    std::string reason;
                    m_cleanup_battle_exit_request_ok = session_hub_ok
                        && call_player_match_input_command(
                            nav.current_scene,
                            RollbackStockOnlineLabDriver::battle_exit_menu(),
                            RollbackStockOnlineLabDriver::battle_exit_command(),
                            nullptr,
                            nullptr,
                            reason,
                            nullptr,
                            nullptr,
                            "PlayerMatchScene");
                    m_cleanup_battle_exit_requested =
                        m_cleanup_battle_exit_request_ok;
                    if (!m_cleanup_battle_exit_request_ok)
                        m_destroy_start_failure = reason.empty()
                            ? (session_hub_ok
                                ? "GoBackToLobby UI command failed"
                                : "SessionHub unavailable for ExitBattle")
                            : reason;
                }

                bool exit_battle = false;
                if (m_cleanup_battle_exit_requested
                    && safe_read_bool_property(
                        nav.current_scene, L"bExitBattle", exit_battle)
                    && exit_battle)
                {
                    m_cleanup_battle_exit_observed = true;
                }
                if (m_cleanup_battle_exit_observed
                    && !m_cleanup_result_decide_requested)
                {
                    m_cleanup_result_decide_request_tick = tick;
                    std::string reason;
                    m_cleanup_result_decide_request_ok =
                        call_player_match_input_command(
                            nav.current_scene,
                            RollbackStockOnlineLabDriver::
                                battle_exit_confirm_menu(),
                            RollbackStockOnlineLabDriver::
                                battle_exit_confirm_command(),
                            nullptr,
                            nullptr,
                            reason,
                            nullptr,
                            nullptr,
                            "PlayerMatchScene");
                    m_cleanup_result_decide_requested =
                        m_cleanup_result_decide_request_ok;
                    if (!m_cleanup_result_decide_request_ok)
                    {
                        m_destroy_start_failure = reason.empty()
                            ? "Result OnDecide UI command failed"
                            : reason;
                    }
                }
                m_destroy_start_failure =
                    m_cleanup_result_decide_request_ok
                        ? "waiting-for-stock-battle-lobby-transition"
                        : (m_cleanup_battle_exit_observed
                            ? m_destroy_start_failure
                            : (m_cleanup_battle_exit_request_ok
                                ? "waiting-for-ExitBattle-receive"
                                : m_destroy_start_failure));
                return false;
            }

            if (identity_contains_scene(
                    nav.current_scene_identity, "PlayerMatchSetupScene"))
            {
                // Setup already belongs to the stock scene state machine.
                // Do not launch battlelobby directly: doing so skips teardown
                // and can leave the next room creation permanently pending.
                // The cleanup timeout reports this phase if the stock
                // transition never reaches battle or its lobby.
                m_destroy_start_failure =
                    "waiting-for-stock-setup-transition";
                return false;
            }

            if (!m_destroy_start_requested)
            {
                if (!session_hub_ok)
                {
                    m_destroy_start_failure = "session-hub-unavailable";
                    return false;
                }
                if (!in_lobby)
                {
                    m_destroy_start_failure =
                        "waiting-for-PlayerMatchLobbyScene";
                    return false;
                }
                RC::Unreal::UObject* in_room_state =
                    find_active_player_match_in_room_state(nav.current_scene);
                if (!safe_is_real(in_room_state))
                {
                    // CreateSession can fail before InRoom exists. There is
                    // then no native room to destroy; unwind through the same
                    // SelectRoomType Cancel/Exit semantics directly.
                    bool main_menu_ready = false;
                    std::string reason;
                    if (!m_cleanup_battle_lobby_requested)
                    {
                        m_cleanup_battle_lobby_requested =
                            request_player_match_lobby_state(
                                nav.current_scene,
                                L"SelectRoomType",
                                reason,
                                tick);
                    }
                    else
                    {
                        (void)request_stock_cleanup_main_menu_scene(
                            tick, nav, main_menu_ready, reason);
                    }
                    m_destroy_start_failure = main_menu_ready
                        ? "ok"
                        : (reason.empty()
                            ? "failed-create-reset-pending"
                            : reason);
                    m_destroy_start_wait_complete = main_menu_ready;
                    return main_menu_ready;
                }
                m_destroy_start_requested = true;
                m_destroy_start_tick = tick;
                // Use the same Blueprint semantic action as the InRoom UI.
                // Calling SessionHub.DestroySession directly skips state-owned
                // teardown and can leave the next CreateSession hung.
                m_destroy_start_call_ok = call_no_param_function(
                    in_room_state, L"RequestDestroySession");
                m_destroy_start_failure =
                    m_destroy_start_call_ok
                        ? "ok"
                        : "InRoomState.RequestDestroySession-failed";
            }

            const bool settle_elapsed =
                tick >= m_destroy_start_tick
                && tick - m_destroy_start_tick >= kSessionDestroySettleTicks;
            const bool destroy_complete =
                m_destroy_start_call_ok
                && m_destroy_callback_seen
                && m_destroy_callback_result;
            m_destroy_start_wait_complete = destroy_complete;
            if (!destroy_complete && m_destroy_start_call_ok
                && !m_destroy_callback_seen)
            {
                if (settle_elapsed)
                {
                    // A stale SC6/Steam room can accept the stock destroy
                    // request without ever producing OnDestroySession.  Do
                    // not strand the operator in that lobby.  The verified
                    // recovery is the same canonical reset used after Steam
                    // downtime: leave Player Match, Main Menu -> Title, then
                    // EmulateTitleDecide back to a fresh Main Menu.
                    bool main_menu_ready = false;
                    std::string reason;
                    if (!m_cleanup_battle_lobby_requested)
                    {
                        m_cleanup_battle_lobby_requested =
                            request_player_match_lobby_state(
                                nav.current_scene,
                                L"SelectRoomType",
                                reason,
                                tick);
                    }
                    else
                    {
                        (void)request_stock_cleanup_main_menu_scene(
                            tick, nav, main_menu_ready, reason);
                    }
                    m_destroy_start_failure = main_menu_ready
                        ? "ok"
                        : (reason.empty()
                            ? "destroy-timeout-reset-pending"
                            : reason);
                    m_destroy_start_wait_complete = main_menu_ready;
                }
                else
                {
                    m_destroy_start_failure = "destroy-callback-pending";
                }
            }
            else if (!destroy_complete && m_destroy_start_call_ok
                     && !m_destroy_callback_result)
            {
                bool main_menu_ready = false;
                std::string reason;
                if (!m_cleanup_battle_lobby_requested)
                {
                    m_cleanup_battle_lobby_requested =
                        request_player_match_lobby_state(
                            nav.current_scene,
                            L"SelectRoomType",
                            reason,
                            tick);
                }
                else
                {
                    (void)request_stock_cleanup_main_menu_scene(
                        tick, nav, main_menu_ready, reason);
                }
                m_destroy_start_failure = main_menu_ready
                    ? "ok"
                    : (reason.empty()
                        ? "destroy-failed-reset-pending"
                            : reason);
                m_destroy_start_wait_complete = main_menu_ready;
            }
            else if (destroy_complete)
            {
                // Only leave Player Match after its actual Blueprint receiver
                // observed OnDestroySession(true). Then perform the canonical
                // Title -> Main Menu online-status reset below.
                bool main_menu_ready = false;
                std::string reason;
                if (!m_cleanup_battle_lobby_requested)
                {
                    m_cleanup_battle_lobby_requested =
                        request_player_match_lobby_state(
                            nav.current_scene,
                            L"SelectRoomType",
                            reason,
                            tick);
                }
                else
                {
                    (void)request_stock_cleanup_main_menu_scene(
                        tick, nav, main_menu_ready, reason);
                }
                m_destroy_start_failure = main_menu_ready
                    ? "ok"
                    : (reason.empty()
                        ? "main-menu-transition-pending"
                            : reason);
                m_destroy_start_wait_complete = main_menu_ready;
            }
            return m_destroy_start_wait_complete;
        }

        void service_gameflow_observe(uint64_t tick) noexcept
        {
            if (!m_manual_lobby_capture_armed_emitted)
            {
                if (m_cfg.observe_gameflow_process_events &&
                    !m_process_event_hook_ok)
                {
                    m_process_event_hook_ok = ensure_process_event_hook();
                }
                m_manual_lobby_capture_create_hook_ok =
                    ensure_create_player_session_observe_hook();
                m_manual_lobby_capture_invite_event_hook_ok =
                    ensure_steam_invite_event_hook();
                m_manual_lobby_capture_invite_delegate_hook_ok =
                    ensure_steam_invite_delegate_hook();
                (void)ensure_steam_join_lobby_task_hook();
                m_manual_lobby_capture_conversion_hook_ok =
                    ensure_steam_lobby_conversion_hook();
                s_session_trace_enabled.store(
                    true, std::memory_order_release);
                s_join_capture_enabled.store(
                    false, std::memory_order_release);

                const bool process_event_ok =
                    !m_cfg.observe_gameflow_process_events ||
                    m_process_event_hook_ok;
                const bool hooks_ok = process_event_ok &&
                    m_manual_lobby_capture_create_hook_ok &&
                    m_manual_lobby_capture_invite_event_hook_ok &&
                    m_manual_lobby_capture_invite_delegate_hook_ok &&
                    m_manual_lobby_capture_conversion_hook_ok;
                ReplayTraceFields armed;
                armed.boolean("ok", hooks_ok)
                     .string("request_id", m_cfg.request_id)
                     .string("client_role", m_cfg.client_role)
                     .uinteger("tick", tick)
                     .boolean("passive_capture", true)
                     .boolean("process_event_requested",
                              m_cfg.observe_gameflow_process_events)
                     .boolean("process_event_hook_ok", process_event_ok)
                     .boolean("create_player_session_hook_ok",
                              m_manual_lobby_capture_create_hook_ok)
                     .boolean("steam_invite_event_hook_ok",
                              m_manual_lobby_capture_invite_event_hook_ok)
                     .boolean("steam_invite_delegate_hook_ok",
                              m_manual_lobby_capture_invite_delegate_hook_ok)
                     .boolean("steam_lobby_conversion_hook_ok",
                              m_manual_lobby_capture_conversion_hook_ok)
                     .boolean("session_process_event_trace_enabled", true)
                     .boolean("menu_navigation_enabled", false)
                     .boolean("input_synthesis_enabled", false)
                     .boolean("invite_synthesis_enabled", false)
                     .boolean("join_capture_enabled", false)
                     .boolean("callback_followup_enabled", false);
                ReplayDebugTrace::instance().event(
                    "rollback_manual_lobby_capture_armed", armed);
                m_manual_lobby_capture_armed_emitted = true;
            }

            OnlineNavigatorObjects nav = resolve_online_navigator_objects();
            const RollbackP2PUObjectIdentity& current_info =
                nav.current_scene_identity;
            const RollbackP2PUObjectIdentity& next_info =
                nav.next_scene_identity;
            const RollbackP2PUObjectIdentity& match_lobby_info =
                nav.match_lobby_identity;
            const bool battle_scene =
                is_direct_online_battle_scene(current_info);
            const bool player_match_scene =
                is_online_player_match_battle_scene(current_info);
            const bool player_match_lobby_scene =
                scene_identity_contains(current_info,
                                        "PlayerMatchLobbyScene");
            const bool main_menu_scene =
                scene_identity_contains(current_info, "MainMenu");
            if (battle_scene)
                m_observe_gameflow_battle_scene_seen = true;

            const std::string scene_key =
                current_info.class_name + "/" + current_info.object_name +
                "|" + next_info.class_name + "/" + next_info.object_name;
            const bool emit =
                m_observe_gameflow_last_emit_tick == 0 ||
                scene_key != m_observe_gameflow_last_scene_key ||
                battle_scene ||
                tick - m_observe_gameflow_last_emit_tick >= 60;
            if (!emit)
                return;

            m_observe_gameflow_last_emit_tick = tick;
            m_observe_gameflow_last_scene_key = scene_key;

            ReplayTraceFields f;
            f.boolean("ok", battle_scene)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
              .uinteger("tick", tick)
              .boolean("observe_gameflow_requested",
                       m_cfg.observe_gameflow_requested)
              .boolean("process_event_trace_enabled",
                       m_cfg.observe_gameflow_process_events)
             .boolean("process_event_hook_ok",
                       !m_cfg.observe_gameflow_process_events ||
                       m_process_event_hook_ok)
             .uinteger("process_event_count",
                       m_observe_gameflow_process_event_count)
             .uinteger("process_event_overflow_count",
                       m_observe_gameflow_process_event_overflow_count)
             .boolean("battle_scene", battle_scene)
             .boolean("battle_scene_seen",
                      m_observe_gameflow_battle_scene_seen)
             .boolean("player_match_scene", player_match_scene)
             .boolean("player_match_lobby_scene",
                      player_match_lobby_scene)
             .boolean("main_menu_scene", main_menu_scene)
             .string("current_scene_name_text", nav.current_scene_name)
             .string("prev_scene_name_text", nav.prev_scene_name)
             .boolean("manager_ready_flag_ok",
                      nav.manager_ready_flag_ok)
             .boolean("manager_ready_flag", nav.manager_ready_flag)
             .boolean("manager_start_latch_flag_ok",
                      nav.manager_start_latch_flag_ok)
             .boolean("manager_start_latch_flag",
                      nav.manager_start_latch_flag)
             .boolean("manager_enable_change_flag_ok",
                      nav.manager_enable_change_flag_ok)
             .boolean("manager_enable_change_flag",
                      nav.manager_enable_change_flag)
             .boolean("ready_to_start_query_ok", nav.ready_to_start_ok)
             .boolean("ready_to_start", nav.ready_to_start)
             .boolean("enable_change_scene_query_ok",
                      nav.enable_change_scene_ok)
             .boolean("enable_change_scene", nav.enable_change_scene)
             .hex("game_flow_manager",
                  reinterpret_cast<uintptr_t>(nav.game_flow_manager))
             .hex("game_flow_automation",
                  reinterpret_cast<uintptr_t>(
                      nav.game_flow_automation))
             .string("game_flow_automation_source",
                     nav.game_flow_automation_source)
             .hex("session_hub",
                  reinterpret_cast<uintptr_t>(nav.session_hub))
             .hex("battle_launcher",
                  reinterpret_cast<uintptr_t>(nav.battle_launcher))
             .hex("current_scene_direct",
                  reinterpret_cast<uintptr_t>(
                      nav.current_scene_direct))
             .hex("next_scene_direct",
                  reinterpret_cast<uintptr_t>(nav.next_scene_direct));
            add_uobject_identity_fields(f, "current_scene", current_info);
            add_uobject_identity_fields(f, "next_scene", next_info);
            add_uobject_identity_fields(
                f, "game_flow_match_lobby", match_lobby_info);
            ReplayDebugTrace::instance().event(
                "rollback_gameflow_observe", f);

            emit_scene_reflection_once(
                nav.current_scene, &nav.current_scene_identity);
            emit_scene_reflection_once(
                nav.next_scene, &nav.next_scene_identity);
            emit_scene_reflection_once(
                nav.match_lobby, &nav.match_lobby_identity);
        }

        static bool safe_start_luxor_ready_channel_state_request(
            StartLuxorReadyChannelStateRequestFn fn,
            void* context) noexcept
        {
            if (!fn || !context) return false;
            __try
            {
                fn(context);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool safe_mark_luxor_session_transport_ready(
            MarkLuxorSessionTransportReadyFn fn,
            void* session_transport) noexcept
        {
            if (!fn || !session_transport) return false;
            __try
            {
                fn(session_transport);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        void service_host_session_transport_ready_after_peer_request(
            uint64_t tick,
            bool is_host,
            bool peer_state3_ready) noexcept
        {
            if (!is_host
                || !RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route)
                || m_ready_open_compat_mark_ready_attempted
                || !m_luxor_session_connection_object
                || !peer_state3_ready
                || s_transport_open_send_calls.load(
                       std::memory_order_acquire) != 0)
            {
                return;
            }

            // The runner releases this barrier only after observing the guest
            // in native connect state 3 in the same Steam lobby. Marking after
            // a guessed request count can send opcode 0x14 while the guest is
            // still state 2, which deterministically fails the join to state 5.
            // MarkLuxorSessionTransportReady takes the embedded session
            // transport at SessionConnection + 0x60. Its +0x21 byte is the
            // exact 0xff gate checked by the native peer-ready handler before
            // SendLuxorTransportOpenMessage. Do not pass the unrelated active
            // transport and do not substitute OpenLuxorReadyChannelForSession;
            // neither changes this gate.
            auto* const session_transport = reinterpret_cast<uint8_t*>(
                m_luxor_session_connection_object + 0x60);
            uint8_t ready_before = 0;
            if (!SafeReadUInt8(session_transport + 0x21, &ready_before))
            {
                m_ready_open_compat_mark_ready_failure =
                    "session-transport-read-failed";
                return;
            }

            m_ready_open_compat_mark_ready_attempted = true;
            m_ready_open_compat_mark_ready_before = ready_before;
            m_ready_open_compat_mark_ready_after = ready_before;
            m_ready_open_compat_last_tick = tick;
            if (ready_before == 0xffu)
            {
                m_ready_open_compat_mark_ready_call_ok = true;
                m_ready_open_compat_call_ok = true;
                m_ready_open_compat_mark_ready_failure = "already-ready";
            }
            else
            {
                const uintptr_t addr = native_address(
                    kRVA_MarkLuxorSessionTransportReady);
                if (!addr)
                {
                    m_ready_open_compat_mark_ready_failure =
                        "native-address-unavailable";
                }
                else
                {
                    const bool native_ok =
                        safe_mark_luxor_session_transport_ready(
                            reinterpret_cast<
                                MarkLuxorSessionTransportReadyFn>(addr),
                            session_transport);
                    uint8_t ready_after = 0;
                    if (native_ok && SafeReadUInt8(
                            session_transport + 0x21, &ready_after))
                    {
                        m_ready_open_compat_mark_ready_after = ready_after;
                        m_ready_open_compat_mark_ready_call_ok =
                            ready_after == 0xffu;
                    }
                    m_ready_open_compat_call_ok =
                        m_ready_open_compat_mark_ready_call_ok;
                    m_ready_open_compat_mark_ready_failure =
                        m_ready_open_compat_mark_ready_call_ok
                            ? "ok" : "native-mark-failed";
                }
            }
            m_ready_open_compat_failure =
                m_ready_open_compat_mark_ready_failure;

            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("tick", tick)
             .hex("session_connection",
                  m_luxor_session_connection_object)
             .hex("session_transport",
                  reinterpret_cast<uintptr_t>(session_transport))
             .uinteger("ready_before",
                       m_ready_open_compat_mark_ready_before)
             .uinteger("ready_after",
                       m_ready_open_compat_mark_ready_after)
             .boolean("call_ok",
                      m_ready_open_compat_mark_ready_call_ok)
             .string("failure",
                     m_ready_open_compat_mark_ready_failure);
            ReplayDebugTrace::instance().event(
                "rollback_stock_session_transport_ready", f);
        }

        void service_opcode14_injected_timing_shim(
            uint64_t tick,
            bool is_sandbox,
            const OnlineNavigatorObjects& nav) noexcept
        {
            if (!is_sandbox || m_cfg.online_stage_cleanup_only
                || !RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route)
                || m_opcode14_timing_shim_attempts >= 6)
                return;
            if (!s_opcode14_initial_route_observed.load(
                    std::memory_order_acquire))
            {
                m_opcode14_timing_shim_failure =
                    "initial-route-not-observed";
                return;
            }
            if (m_opcode14_timing_shim_observed_tick == 0)
            {
                m_opcode14_timing_shim_observed_tick = tick;
                m_opcode14_timing_shim_lobby_id =
                    m_native_named_session_lobby_id;
            }
            if (s_opcode14_initial_route_count.load(
                    std::memory_order_acquire) != 0)
            {
                m_opcode14_timing_shim_failure =
                    "initial-mode0-route-not-empty";
                return;
            }
            if (s_opcode14_requested_active_connect.load(
                    std::memory_order_acquire) == 0
                || s_opcode14_requested_state.load(
                    std::memory_order_acquire) == 0xffu
                || s_opcode14_start_callback_rva.load(
                    std::memory_order_acquire)
                    != kRVA_StartLuxorReadyChannelStateRequest
                || s_opcode14_request_timeout_millis.load(
                    std::memory_order_acquire) != 20000)
            {
                m_opcode14_timing_shim_failure =
                    "original-request-capture-invalid";
                return;
            }
            const uintptr_t active = s_opcode14_active_connect.load(
                std::memory_order_acquire);
            if (!active || active != m_luxor_active_connect_object
                || active != s_opcode14_requested_active_connect.load(
                    std::memory_order_acquire))
            {
                m_opcode14_timing_shim_failure =
                    "active-connect-changed";
                return;
            }
            const bool initial_retry =
                m_opcode14_timing_shim_attempts == 0;
            if (initial_retry && !identity_contains_scene(
                    nav.current_scene_identity,
                    "PlayerMatchInviteScene"))
            {
                m_opcode14_timing_shim_failure = "invite-scene-changed";
                return;
            }
            if (!initial_retry && !identity_contains_scene(
                    nav.current_scene_identity,
                    "PlayerMatchLobbyScene"))
            {
                m_opcode14_timing_shim_failure = "lobby-scene-changed";
                return;
            }
            if (m_opcode14_timing_shim_lobby_id == 0)
                m_opcode14_timing_shim_lobby_id =
                    m_native_named_session_lobby_id;
            if (m_opcode14_timing_shim_lobby_id == 0
                || m_native_named_session_lobby_id
                    != m_opcode14_timing_shim_lobby_id)
            {
                m_opcode14_timing_shim_failure = "lobby-changed";
                return;
            }
            // Synthetic invite dispatch reaches the stock request starter
            // before opcode 0x15 installs the guest transport channels. The
            // first retry fixes that ordering at state 2. If the host consumes
            // it before its own session registry is ready, resend the same
            // stock request at bounded 15-second intervals while the guest is
            // still parked at state 3. Stop as soon as transport-open arrives
            // or the guest owns a session connection.
            const bool routes_ready =
                s_active_packet_dispatch_opcode21_calls.load(
                    std::memory_order_acquire) != 0
                && m_luxor_active_transport_channel_count != 0
                && m_luxor_active_transport_channel_count != 0xffffffffu;
            const bool initial_boundary =
                initial_retry && m_luxor_active_connect_state == 2;
            const bool pending_transport_open =
                !initial_retry
                && m_luxor_active_connect_state == 3
                && m_luxor_session_connection_object == 0
                && s_active_packet_dispatch_opcode20_calls.load(
                       std::memory_order_acquire) == 0
                && tick >= m_opcode14_timing_shim_last_attempt_tick
                && tick - m_opcode14_timing_shim_last_attempt_tick >= 120;
            if (!routes_ready
                || (!initial_boundary && !pending_transport_open))
            {
                m_opcode14_timing_shim_failure =
                    "stock-handshake-not-ready";
                return;
            }
            if (initial_retry
                && (tick < m_opcode14_timing_shim_observed_tick
                || tick - m_opcode14_timing_shim_observed_tick > 900)
               )
            {
                m_opcode14_timing_shim_failure = "stock-timeout-near";
                return;
            }

            LuxorReadyChannelStateStartContext start_context {};
            start_context.active_connect = reinterpret_cast<void*>(active);
            start_context.requested_state = static_cast<uint8_t>(
                s_opcode14_requested_state.load(
                    std::memory_order_acquire));
            void* const context = &start_context;
            const uintptr_t target = native_address(
                kRVA_StartLuxorReadyChannelStateRequest);
            ++m_opcode14_timing_shim_attempts;
            m_opcode14_timing_shim_last_attempt_tick = tick;
            bool native_ok = false;
            s_opcode14_retry_in_progress.store(
                true, std::memory_order_release);
            if (context && target)
            {
                auto* fn = reinterpret_cast<
                    StartLuxorReadyChannelStateRequestFn>(target);
                native_ok =
                    safe_start_luxor_ready_channel_state_request(
                        fn, context);
            }
            s_opcode14_retry_in_progress.store(
                false, std::memory_order_release);
            const uint32_t retry_route_count =
                s_opcode14_retry_route_count.load(
                    std::memory_order_acquire);
            m_opcode14_timing_shim_call_ok =
                native_ok && retry_route_count > 0
                && retry_route_count != 0xffffffffu;
            m_opcode14_timing_shim_failure =
                m_opcode14_timing_shim_call_ok
                    ? "ok" : "stock-retry-route-empty";

            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("tick", tick)
             .uinteger("attempt", m_opcode14_timing_shim_attempts)
             .hex("context", reinterpret_cast<uintptr_t>(context))
             .hex("active_connect", active)
             .uinteger("requested_state",
                       start_context.requested_state)
             .uinteger("lobby_id", m_opcode14_timing_shim_lobby_id)
             .uinteger("initial_mode0_route_count",
                       s_opcode14_initial_route_count.load(
                           std::memory_order_acquire))
             .uinteger("retry_mode0_route_count", retry_route_count)
             .boolean("call_ok", m_opcode14_timing_shim_call_ok)
             .string("failure", m_opcode14_timing_shim_failure);
            ReplayDebugTrace::instance().event(
                "rollback_opcode14_injected_timing_shim", f);
        }

        void service_online_stage(uint64_t tick) noexcept
        {
            emit_online_stage_followup_progress("online-begin", tick);

            if (m_cfg.stock_session_observe_only)
            {
                // Manual attach observes the stock session the user created.
                // It must not navigate menus, ready players, alter rules, or
                // invoke any setup transition. ProcessEvent plus these native
                // read-only samples provide the same authenticated Steam
                // identity used by automated setup.
                if (!m_process_event_hook_ok)
                    m_process_event_hook_ok = ensure_process_event_hook();
                s_session_trace_enabled.store(
                    true, std::memory_order_release);
                sync_session_callback_state();
                capture_steam_identity_for_stock_fallback();
                if (m_native_session_sample_tick == 0
                    || tick - m_native_session_sample_tick >= 15)
                {
                    const bool is_sandbox =
                        m_cfg.client_role == "sandbox";
                    m_native_session_sample_tick = tick;
                    sample_named_online_session_state(tick, is_sandbox);
                    m_connect_manager_sample_tick = tick;
                    sample_luxor_connect_manager_state(is_sandbox);
                }
                uint32_t native_stage_identity = 0;
                if (CaptureRollbackNativeStageIdentity(
                        native_stage_identity, false, true))
                {
                    m_stock_native_stage_identity_cached = true;
                    m_stock_native_stage_identity = native_stage_identity;
                }
                emit_stock_observed_selection_if_ready();
                return;
            }

            // Cleanup is its own stock-UI workflow.  It must keep running after
            // CasualMatch presence disappears; the normal lifecycle guard
            // below intentionally disarms match automation at that boundary.
            // Keeping cleanup ahead of that guard also prevents it from ever
            // entering room creation, discovery, invite, or setup code.
            if (m_cfg.online_stage_cleanup_only)
            {
                const bool is_host = m_cfg.client_role == "host";
                OnlineNavigatorObjects nav =
                    resolve_online_navigator_objects();
                // Cleanup is still an automated stock UI lifecycle. Keep the
                // game thread running while either local window is
                // unfocused; otherwise SC6 can advance only a few lobby ticks
                // per minute and miss the cleanup deadline.
                (void)ensure_background_idle_override(nav.current_scene);
                RC::Unreal::UObject* const session_hub = nav.session_hub;
                const bool session_hub_ok = session_hub != nullptr;

                if (!m_process_event_hook_ok)
                    m_process_event_hook_ok = ensure_process_event_hook();
                s_session_trace_enabled.store(
                    !m_stock_process_event_capture_complete.load(
                        std::memory_order_acquire),
                    std::memory_order_release);
                sync_session_callback_state();
                const bool cleanup_ok = service_online_stage_start_cleanup(
                    tick, nav, session_hub, session_hub_ok, is_host);
                sync_session_callback_state();
                if (cleanup_ok)
                    restore_background_idle_override();

                m_last_failure = cleanup_ok
                    ? "ok" : "destroy-session-settle-pending";
                if (should_emit_online_stage(tick, cleanup_ok))
                {
                    emit_online_stage(
                        cleanup_ok,
                        nav,
                        nav.game_flow_manager,
                        session_hub,
                        nullptr,
                        false);
                    remember_online_stage_emit_state(tick, cleanup_ok);
                }
                return;
            }

            // Automated setup reports the synchronized in-game selection too;
            // the callback inventory must not rely on requested values alone.
            emit_stock_observed_selection_if_ready();

            const GamePresence presence =
                GameMode::instance().current_presence();
            if (presence == GamePresence::CasualMatch)
                m_online_stage_seen_casual_match = true;
            else if (m_online_stage_seen_casual_match)
            {
                if (!m_online_stage_lifecycle_disarmed)
                {
                    m_online_stage_lifecycle_disarmed = true;
                    restore_background_idle_override();
                    reset_online_navigator_caches();
                    s_peer_route_tag_fix_enabled.store(
                        false, std::memory_order_release);
                    s_session_trace_enabled.store(
                        false, std::memory_order_release);
                    ReplayTraceFields f;
                    f.string("request_id", m_cfg.request_id)
                     .string("client_role", m_cfg.client_role)
                     .uinteger("tick", tick)
                     .string("reason", "left-casual-match");
                    ReplayDebugTrace::instance().event(
                        "rollback_online_stage_lifecycle_disarmed", f);
                }
                return;
            }
            if (m_cfg.online_stage_diagnostic_reflection &&
                !m_process_event_hook_ok)
            {
                m_process_event_hook_ok = ensure_process_event_hook();
            }
            const bool needs_luxor_diagnostics =
                m_cfg.online_stage_diagnostic_reflection ||
                m_cfg.online_stage_network_check_compat ||
                m_cfg.online_stage_join_complete_compat ||
                m_cfg.online_stage_transport_ready_compat ||
                m_cfg.online_stage_ready_open_compat ||
                m_cfg.online_stage_in_room_transition_compat;
            if (m_cfg.online_stage_peer_route_tag_fix)
                (void)ensure_peer_route_tag_fix_hooks();
            if (needs_luxor_diagnostics)
                (void)ensure_ready_channel_observe_hooks();
            if (RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route))
            {
                // Observation only: preserve Steam's callback behavior while
                // identifying whether the stock peer transport reaches SC6.
                (void)ensure_steam_p2p_callback_observe_hooks();
                (void)ensure_transport_open_send_observe_hook();
                (void)ensure_session_ready_request_observe_hook();
                if (m_cfg.client_role == "host")
                {
                    // The guest's state-4 transport request is handled here.
                    // Observe this one boundary instead of enabling the broad
                    // legacy Luxor diagnostics hook set.
                    (void)ensure_session_opcode0b_observe_hook();
                    (void)ensure_session_opcode0b_response_observe_hook();
                }
            }
            if (RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route) &&
                m_cfg.client_role == "sandbox")
            {
                // Keep only the low-volume request boundary needed by the
                // acceptance report plus the single native receive boundary.
                // This distinguishes a missing opcode 0x15 packet from a
                // later route/handler rejection without enabling the wide
                // state-5 diagnostic hook set.
                (void)ensure_active_request_queue_observe_hook();
                (void)ensure_active_packet_dispatch_observe_hook();
                (void)ensure_ready_keyed_dispatch_observe_hook();
                (void)install_luxor_route_key_list_build_hook_for_target(
                    native_address(kRVA_BuildLuxorRouteKeyListForMode));
            }
            if (m_cfg.online_stage_network_check_compat
                && m_cfg.client_role == "sandbox")
                (void)ensure_luxor_network_check_compat_hook();

            const bool is_host = m_cfg.client_role == "host";
            const bool is_sandbox = m_cfg.client_role == "sandbox";
            const bool role_room_ready_marker_ok =
                role_room_ready_marker_released(tick);
            if (RollbackStockJoinRouteUsesAuthenticatedOffer(
                    m_cfg.stock_join_route))
            {
                capture_steam_identity_for_stock_fallback();
            }
            OnlineNavigatorObjects nav = resolve_online_navigator_objects();
            if (!m_cfg.online_stage_cleanup_only)
            {
                (void)ensure_background_idle_override(nav.current_scene);
            }
            const bool navigation_ready =
                m_cfg.online_stage_cleanup_only
                    ? true
                    : pump_online_stage_navigation(
                        tick, nav, is_host, is_sandbox);
            m_game_flow_match_lobby =
                reinterpret_cast<uintptr_t>(nav.match_lobby);
            RC::Unreal::UObject* flow_manager = nav.game_flow_manager;
            RC::Unreal::UObject* session_hub = nav.session_hub;
            const bool waiting_for_stock_menu_rate =
                RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route)
                && identity_is_main_menu(nav.current_scene_identity)
                && (!m_stock_menu_rate_complete
                    || !m_stock_menu_rate_ok
                    || !stock_menu_pair_rate_released());
            if (waiting_for_stock_menu_rate)
            {
                if (should_emit_online_stage(tick, false))
                {
                    emit_online_stage(
                        false, nav, flow_manager, session_hub, nullptr, false);
                    remember_online_stage_emit_state(tick, false);
                }
                return;
            }
            if (online_stage_goal_is("main-menu") ||
                online_stage_goal_is("player-match-nav") ||
                online_stage_goal_is("proof-only"))
            {
                // Startup/navigation proof does not consume SessionHub or
                // MatchData. Validating both here performs two full
                // GUObjectArray scans before an immediate return.
                const bool gate_ok = navigation_ready;
                if (should_emit_online_stage(tick, gate_ok))
                {
                    emit_online_stage(gate_ok,
                                      nav,
                                      flow_manager,
                                      session_hub,
                                      nullptr,
                                      false);
                    remember_online_stage_emit_state(tick, gate_ok);
                }
                return;
            }
            auto emit_first_tick_boundary =
                [&](const char* phase, uintptr_t object = 0) noexcept
            {
                if (tick != 1) return;
                ReplayTraceFields f;
                f.string("request_id", m_cfg.request_id)
                 .string("client_role", m_cfg.client_role)
                 .string("phase", phase ? phase : "")
                 .hex("object", object)
                 .boolean("navigation_ready", navigation_ready);
                ReplayDebugTrace::instance().event(
                    "rollback_online_stage_first_tick_boundary", f);
            };
            emit_first_tick_boundary(
                "before-session-hub",
                reinterpret_cast<uintptr_t>(session_hub));
            // SessionHub was read from the already-live GameFlowManager in
            // this service pass. UObject::IsReal performs a full global
            // object-array scan in this UE4SS build and can block the game
            // thread during PlayerMatch lobby setup; reflected/native calls
            // below are SEH-guarded instead.
            const bool session_hub_ok = session_hub != nullptr;
            emit_first_tick_boundary(
                "before-get-match-data",
                reinterpret_cast<uintptr_t>(session_hub));
            RC::Unreal::UObject* match_data =
                session_hub_ok ? call_get_match_data(session_hub) : nullptr;
            emit_first_tick_boundary(
                "after-get-match-data",
                reinterpret_cast<uintptr_t>(match_data));
            const bool match_data_present = match_data != nullptr;
            // MatchSettingSync does not exist until the native session has a
            // connected peer. Discovering it here scanned the whole object
            // array several times before host create / guest find could even
            // start. Resolve it only after that role gate is proven below.
            RC::Unreal::UObject* match_setting_sync = nullptr;
            emit_first_tick_boundary(
                "match-setting-sync-deferred");
            emit_online_stage_followup_progress("after-navigation", tick);

            emit_first_tick_boundary("before-process-event-hook");
            const bool process_event_observation_ready =
                !RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route)
                || (m_stock_menu_rate_complete
                    && m_stock_menu_rate_ok
                    && stock_menu_pair_rate_released());
            if (process_event_observation_ready &&
                !m_process_event_hook_ok &&
                !m_stock_process_event_capture_complete.load(
                    std::memory_order_acquire))
                m_process_event_hook_ok = ensure_process_event_hook();
            emit_first_tick_boundary("after-process-event-hook");
            s_session_trace_enabled.store(
                !m_stock_process_event_capture_complete.load(
                    std::memory_order_acquire),
                std::memory_order_release);
            if (session_hub_ok)
            {
                const uintptr_t session_hub_addr =
                    reinterpret_cast<uintptr_t>(session_hub);
                if (m_session_hub_initialize_object != session_hub_addr)
                {
                    m_session_hub_initialize_object = session_hub_addr;
                    m_session_hub_initialize_requested = false;
                    m_session_hub_initialize_ok = false;
                    m_session_hub_initialize_native_owned = false;
                }
                const bool native_owned_initialize_proven =
                    match_data_present &&
                    identity_contains_scene(
                        nav.current_scene_identity,
                        "PlayerMatchLobbyScene");
                const bool stock_invite_flow_owns_initialize =
                    RollbackStockJoinRouteInjectsStockHandler(
                        m_cfg.stock_join_route);
                emit_first_tick_boundary(
                    "before-session-hub-initialize",
                    session_hub_addr);
                if (native_owned_initialize_proven ||
                    stock_invite_flow_owns_initialize)
                {
                    // The stock Player Match UI owns SessionHub startup.  In
                    // the injected-stock-invite route we enter through that
                    // exact UI lifecycle, so calling Initialize here would
                    // bind delegates a second time and can make a later join
                    // time out or leave "Creating a room..." stuck.  Never
                    // turn this back into harness-owned setup.  A current
                    // lobby plus live MatchData is the equivalent proof for
                    // the other routes. Initialize is not idempotent.
                    m_session_hub_initialize_native_owned = true;
                    m_session_hub_initialize_ok = true;
                }
                else if (!m_session_hub_initialize_requested)
                {
                    m_session_hub_initialize_requested = true;
                    m_session_hub_initialize_ok =
                        call_initialize_session_hub(session_hub);
                }
                emit_first_tick_boundary(
                    "after-session-hub-initialize",
                    session_hub_addr);
            }
            if (!m_main_user_id_cached)
            {
                emit_first_tick_boundary("before-main-user-query");
                m_main_user_id_query_ok =
                    query_lux_main_user_id(m_lux_main_user_id);
                if (m_main_user_id_query_ok)
                {
                    m_session_main_user_id =
                        m_lux_main_user_id >= 0 ? m_lux_main_user_id : 0;
                    m_main_user_id_cached = true;
                }
                else
                {
                    m_session_main_user_id = 0;
                }
                emit_first_tick_boundary("after-main-user-query");
            }
            if (m_cfg.main_user_id_override >= 0)
            {
                m_session_main_user_id = m_cfg.main_user_id_override;
                m_session_main_user_id_overridden = true;
            }

            // Copy callback atomics before any pipeline decision.  Calls made
            // below may synchronously emit another callback, so a second copy
            // remains after polling.
            sync_session_callback_state();
            emit_online_stage_followup_progress(
                "before-pipeline-sync-callback", tick);

            if (is_host && navigation_ready &&
                !m_create_request_ok)
            {
                (void)service_host_room_create_pipeline(nav, tick);
            }

            sync_session_callback_state();
            if (m_battle_comp_seen ||
                (m_battle_ready_seen && m_battle_ready_result))
            {
                // Ready is a completed stock transition once either callback
                // succeeds.  Keep that result latched; channel state 2 is the
                // expected post-Ready state, not a reason to re-run the
                // pre-Ready state-1 eligibility check.
                m_ready_requested = true;
                m_ready_request_ok = true;
                m_ready_request_failure = "ok";
                m_start_latch_requested = true;
                m_start_latch_ok = true;
                m_start_latch_method =
                    "lux-match-lobby-request-ready";
                m_start_latch_failure = "ok";
            }
            emit_online_stage_followup_progress("after-sync-callback", tick);
            sample_online_native_session_state(tick, is_host, is_sandbox);
            service_host_session_transport_ready_after_peer_request(
                tick, is_host, role_room_ready_marker_ok);
            service_opcode14_injected_timing_shim(
                tick, is_sandbox, nav);
            if (is_sandbox &&
                m_luxor_active_connect_state == 4 &&
                m_luxor_active_transport_ready_sampled &&
                m_luxor_active_transport_ready &&
                !m_luxor_session_connection_object)
            {
                // The stock opcode-0x05 response callback has now
                // deserialized the peer transport and moved ActiveConnect to
                // state 4.  The real OnlineSession delegate normally calls
                // HandleLuxorDeferredSessionConnection next.  Authenticated
                // invite injection does not deliver that delegate, so call
                // the same native follow-up at this proven boundary.  Do not
                // call it in states 2/3, force transport readiness, or create
                // a session connection directly.
                service_deferred_session_connection_if_needed(
                    tick, is_sandbox);
            }
            if (is_sandbox && !m_join_request_ok
                && has_reusable_guest_named_session())
            {
                // A later acceptance phase can begin after the native guest
                // named session survived while request-local callback latches
                // were reset.  Adopt membership evidence, but never infer
                // transport readiness from the named session alone.
                m_guest_adopted_existing_session = true;
                m_join_callback_requested = true;
                m_join_request_ok = true;
                m_join_complete_seen = true;
                m_join_complete_result = true;
                m_join_callback_failure = "ok-existing-native-session";
                s_join_callback_failure = m_join_callback_failure;
            }
            service_player_match_in_room_transition(
                nav.current_scene, is_host, is_sandbox);
            // The authenticated stock invite offer comes from the native
            // PlayerMatch named session.  Capture it only after the stock
            // room transition has completed; otherwise the host advertises
            // an empty offer and the guest can never enter the invite path.
            service_steam_private_lobby_if_needed(is_host);
            service_stock_online_setup_semantics(
                nav, tick, is_host, is_sandbox);
            sample_stock_online_battle_entry(nav, tick);
            (void)m_stock_driver.observe_setup({
                identity_contains_scene(
                    nav.current_scene_identity, "TitleScene"),
                identity_contains_scene(
                    nav.current_scene_identity, "MainMenuScene"),
                identity_contains_scene(
                    nav.current_scene_identity, "PlayerMatchLobbyScene"),
                identity_contains_scene(
                    nav.current_scene_identity, "PlayerMatchSetupScene"),
                identity_contains_scene(
                    nav.current_scene_identity, "PlayerMatchScene"),
                m_create_request_ok,
                is_host
                    ? (m_session_connect_complete_result
                        || m_luxor_session_connection_object != 0)
                    : (is_sandbox && m_join_request_ok),
                production_steam_session_contract_ready(),
                m_ready_request_ok || m_start_latch_ok,
                m_stock_synced_characters_observed,
                m_stock_synced_stage_observed,
                m_stock_selection_bilateral_ok,
                m_stock_native_battle_tick_seen,
            });
            emit_online_stage_followup_progress("after-native-sample", tick);
            // Manual join-complete and forced transport-ready calls remain
            // unreachable.  The only native follow-up above is gated on the
            // genuine stock opcode-0x05 state-4 response boundary.
            m_join_complete_compat_failure = "unsupported-unsafe-compat";
            m_transport_ready_compat_failure = "unsupported-unsafe-compat";
            emit_online_stage_followup_progress("after-compat", tick);
            // Authenticated stock invite injection is the only guest route.
            // Public FindSessions owns FOnlineSessionSteam +0xA88 and races
            // the stock invite-accepted task, so it must never run here.
            m_stock_browser_exhausted = is_sandbox;
            m_stock_no_presence_exhausted = is_sandbox;
            capture_steam_identity_for_stock_fallback();
            m_stock_fallback_active = is_host
                ? m_stock_peer_fallback_ready
                : (m_stock_peer_alive && m_stock_offer_valid);
            service_native_invite_bridge_if_needed(is_sandbox, nav);

            const bool role_navigation_ready = navigation_ready;
            RollbackOnlineReadinessEvidence sandbox_evidence {};
            sandbox_evidence.join_request_ok = m_join_request_ok;
            sandbox_evidence.join_complete_seen = m_join_complete_seen;
            sandbox_evidence.join_complete_result = m_join_complete_result;
            sandbox_evidence.member_join_seen =
                m_session_member_join_seen
                || m_guest_adopted_existing_session
                || (is_sandbox &&
                    m_luxor_active_connect_state == 3 &&
                    m_luxor_session_connection_object != 0);
            sandbox_evidence.session_connect_complete_seen =
                m_session_connect_complete_seen;
            sandbox_evidence.session_connect_complete_result =
                m_session_connect_complete_result;
            sandbox_evidence.named_session_valid =
                RollbackOnlineNamedSessionReusable(
                    current_named_session_evidence());
            sandbox_evidence.active_connect_state =
                m_luxor_active_connect_state;
            sandbox_evidence.session_connection =
                m_luxor_session_connection_object;
            const RollbackOnlineReadiness sandbox_readiness =
                EvaluateRollbackOnlineReadiness(sandbox_evidence);
            const bool sandbox_membership_ready =
                is_sandbox && sandbox_readiness.membership_ready;
            const bool sandbox_transport_ready =
                is_sandbox && sandbox_readiness.transport_ready;

            const bool host_callback_transport_ready =
                is_host
                && m_create_request_ok
                && m_session_connect_complete_seen
                && m_session_connect_complete_result;
            const bool host_native_transport_ready =
                is_host
                && m_create_request_ok
                && RollbackOnlineNamedSessionReusable(
                    current_named_session_evidence())
                && m_luxor_active_connect_state == 3
                && m_luxor_session_connection_object != 0;
            const bool host_transport_ready =
                host_callback_transport_ready
                || host_native_transport_ready;
            const bool host_ready_followup_due =
                host_transport_ready
                && !m_start_latch_ok;
            const bool sandbox_ready_followup_due =
                sandbox_transport_ready
                && !m_start_latch_ok;
            const bool ready_followup_due =
                (host_ready_followup_due
                 && tick - m_online_stage_last_attempt_tick
                        >= kOnlineStageReadyRetryTicks)
                || (sandbox_ready_followup_due
                    && tick - m_online_stage_last_attempt_tick
                           >= kOnlineStageReadyRetryTicks);
            const bool host_callback_kind_ready =
                std::strcmp(
                    m_process_event_followup_last_kind,
                    "OnSessionConnectComplete") == 0;
            const bool host_active_state_ready_for_callback =
                m_luxor_active_connect_state == 3;
            const bool host_native_callback_ready_followup =
                m_process_event_followup_in_progress &&
                is_host &&
                host_ready_followup_due &&
                host_callback_kind_ready &&
                m_luxor_session_connection_object != 0 &&
                host_active_state_ready_for_callback &&
                m_luxor_active_session_name_raw != 0 &&
                m_luxor_active_session_event_handle != 0;
            const bool host_callback_ready_followup_blocked =
                m_process_event_followup_in_progress &&
                is_host &&
                host_ready_followup_due &&
                !host_native_callback_ready_followup;
            const bool sandbox_callback_ready_followup =
                m_process_event_followup_in_progress &&
                is_sandbox &&
                sandbox_ready_followup_due;
            const bool should_attempt =
                session_hub_ok
                && role_navigation_ready
                && !host_callback_ready_followup_blocked
                && !sandbox_callback_ready_followup
                && (ready_followup_due
                    || m_online_stage_attempts == 0
                    || tick - m_online_stage_last_attempt_tick
                           >= kOnlineStageAdvanceRetryTicks);
            emit_online_stage_followup_progress("before-should-attempt", tick);
            if (should_attempt)
            {
                emit_online_stage_followup_progress("should-attempt-begin", tick);
                ++m_online_stage_attempts;
                m_online_stage_last_attempt_tick = tick;
                if (sandbox_membership_ready)
                    m_session_member_join_attempted_count =
                        m_session_member_join_count;
                if (is_host && !m_create_request_ok)
                {
                    (void)service_host_room_create_pipeline(nav, tick);
                }
                if (is_sandbox && !m_join_request_ok)
                {
                    m_find_retry_reason = m_stock_offer_valid
                        ? "authenticated-private-invite-processing"
                        : "waiting-for-authenticated-private-lobby-offer";
                    emit_online_stage_followup_progress(
                        "sandbox-private-invite-route", tick);
                }
                const bool injected_guest_joined =
                    !is_sandbox
                    || !RollbackStockJoinRouteInjectsStockHandler(
                        m_cfg.stock_join_route)
                    || m_stock_native_event_dispatch_ok;
                if (injected_guest_joined &&
                    (!m_play_side_requested || !m_play_side_request_ok))
                {
                    m_play_side_requested = true;
                    m_play_side_request_ok = call_request_change_play_side(
                        session_hub, is_host ? 0 : 1);
                }
                const bool host_create_confirmed = m_create_request_ok;
                const bool sandbox_join_confirmed =
                    sandbox_transport_ready;
                const bool host_session_connected =
                    host_create_confirmed && host_transport_ready;
                // The native session-connection object is the peer-join
                // boundary. ProcessEvent can miss the Blueprint member-join
                // callback, and the host Steam client can briefly retain the
                // pre-invite member count even after the connection exists.
                // Both are useful diagnostics, but neither should block the
                // stock lobby Ready function.
                const bool host_member_join_ready = host_session_connected;
                const bool host_lobby_connected = host_member_join_ready;
                if (is_host && host_session_connected &&
                    !host_lobby_connected && !m_start_latch_ok)
                {
                    m_ready_request_ok = false;
                    m_ready_request_failure =
                        "host-waiting-for-peer-join";
                    m_start_latch_failure =
                        "host-waiting-for-peer-join";
                    emit_online_stage_followup_progress(
                        "host-waiting-for-peer-join", tick);
                }
                const bool battle_sync_ready_role_gate =
                    is_host ? host_lobby_connected
                            : (is_sandbox ? sandbox_join_confirmed : false);
                if (battle_sync_ready_role_gate)
                {
                    if (m_match_setting_sync != 0)
                    {
                        match_setting_sync =
                            reinterpret_cast<RC::Unreal::UObject*>(
                                m_match_setting_sync);
                    }
                    else if (m_match_setting_sync_resolution_last_tick == 0 ||
                             tick -
                                     m_match_setting_sync_resolution_last_tick >=
                                 60)
                    {
                        m_match_setting_sync_resolution_last_tick = tick;
                        match_setting_sync = resolve_match_setting_sync(
                            nav, session_hub, match_data);
                        if (match_setting_sync)
                        {
                            m_match_setting_sync =
                                reinterpret_cast<uintptr_t>(
                                    match_setting_sync);
                            sample_match_setting_sync_raw(
                                match_setting_sync);
                        }
                    }
                }
                if (battle_sync_ready_role_gate &&
                    !match_setting_sync)
                {
                    emit_online_stage_followup_progress(
                        "match-setting-sync-unavailable", tick);
                    m_match_setting_sync_failure =
                        "match-setting-sync-unavailable";
                }
                if (battle_sync_ready_role_gate && match_setting_sync)
                {
                    sample_match_setting_sync_raw(match_setting_sync);
                }
                const bool local_stage_connected =
                    is_host ? host_lobby_connected
                            : (is_sandbox ? sandbox_join_confirmed : false);
                const bool lobby_state_observation_ready =
                    m_player_match_in_room_ok;
                const bool canonical_peer_ready_for_host =
                    !RollbackStockJoinRouteInjectsStockHandler(
                        m_cfg.stock_join_route) ||
                    (s_session_opcode0b_response_calls.load(
                         std::memory_order_acquire) > 0 &&
                     s_session_opcode0b_response_result.load(
                         std::memory_order_acquire) &&
                     stock_peer_session_ready_marker_released() &&
                     stock_peer_ready_marker_released());
                const bool stock_ready_ui_gate =
                    !is_host ||
                    (canonical_peer_ready_for_host &&
                     (m_lux_match_lobby_request_ready_requested ||
                      role_room_ready_marker_ok));
                const bool stock_guest_dispatch_ready =
                    !RollbackStockJoinRouteInjectsStockHandler(
                        m_cfg.stock_join_route) ||
                    !is_sandbox ||
                    s_active_packet_dispatch_opcode20_calls.load(
                        std::memory_order_acquire) > 0;
                const bool local_stage_ready_for_lobby_request =
                    RollbackStockOnlineLabDriver::stock_lobby_ready_gate(
                        local_stage_connected,
                        lobby_state_observation_ready,
                        stock_ready_ui_gate,
                        stock_guest_dispatch_ready,
                        production_steam_session_contract_ready());
                if ((is_host || is_sandbox) && navigation_ready
                    && local_stage_ready_for_lobby_request
                    && match_data_present
                    && !m_start_latch_ok)
                {
                    m_ready_request_type =
                        local_stage_connected ? 0 : 1;
                    m_ready_request_skipped_by_role = false;
                    m_start_latch_method = is_host
                        ? "lux-match-lobby-request-ready"
                        : "lux-match-lobby-request-ready-joiner";
                    emit_online_stage_followup_progress(
                        "ready-preconditions-begin", tick);
                    sample_request_ready_preconditions();
                    emit_online_stage_followup_progress(
                        "ready-preconditions-end", tick);
                    const bool ready_open_called =
                        !m_ready_preconditions_ok &&
                        service_ready_open_compat_if_needed(
                            tick, is_host);
                    if (!m_ready_preconditions_ok &&
                        !ready_open_called &&
                        m_cfg.online_stage_ready_open_compat &&
                        is_host &&
                        (m_ready_open_compat_failure ==
                             "parent-ready-sample-unavailable" ||
                         m_ready_open_compat_failure ==
                             "parent-ready-flag-missing" ||
                         m_ready_open_compat_failure ==
                             "parent-ready-state-not-ready" ||
                         m_ready_open_compat_failure ==
                             "small-route-sample-unavailable" ||
                         m_ready_open_compat_failure ==
                             "small-route-next-slot-busy"))
                    {
                        m_ready_request_ok = false;
                        m_ready_request_failure =
                            m_ready_open_compat_failure.c_str();
                        m_start_latch_failure =
                            m_ready_open_compat_failure.c_str();
                        const uint64_t followup_tick =
                            tick + kOnlineStageReadyRetryTicks;
                        const char* followup_kind =
                            (m_process_event_followup_last_kind &&
                             m_process_event_followup_last_kind[0] != '\0')
                                ? m_process_event_followup_last_kind
                                : "OnSessionConnectComplete";
                        ++m_process_event_followup_count;
                        m_process_event_followup_last_tick =
                            followup_tick;
                        m_process_event_followup_last_kind =
                            followup_kind;
                        m_process_event_followup_pending = true;
                        ReplayTraceFields f;
                        f.string("request_id", m_cfg.request_id)
                         .string("client_role", m_cfg.client_role)
                         .string(
                             "function",
                             m_process_event_followup_last_kind)
                         .string("reason", "ready-open-gate-pending")
                         .string(
                             "gate_failure",
                             m_ready_open_compat_failure)
                         .uinteger(
                             "followup_count",
                             m_process_event_followup_count)
                         .uinteger("followup_tick", followup_tick)
                         .uinteger("last_service_tick",
                                   m_last_service_tick)
                         .uinteger(
                             "last_attempt_tick",
                             m_online_stage_last_attempt_tick)
                         .boolean("deferred", true);
                        ReplayDebugTrace::instance().event(
                            "rollback_online_stage_callback_followup",
                            f);
                        emit_online_stage_followup_progress(
                            "ready-open-gate-pending", tick);
                        return;
                    }
                    if (ready_open_called)
                    {
                        emit_online_stage_followup_progress(
                            "ready-open-compat-called", tick);
                        sample_request_ready_preconditions();
                        emit_online_stage_followup_progress(
                            "ready-preconditions-after-open", tick);
                        if (!m_ready_preconditions_ok &&
                            m_ready_open_compat_open_calls_after >
                                m_ready_open_compat_open_calls_before)
                        {
                            m_ready_request_ok = false;
                            m_ready_request_failure =
                                "ready-open-queued";
                            m_start_latch_failure =
                                "ready-open-queued";
                            const uint64_t followup_tick =
                                tick + kOnlineStageReadyRetryTicks;
                            const char* followup_kind =
                                (m_process_event_followup_last_kind &&
                                 m_process_event_followup_last_kind[0] != '\0')
                                    ? m_process_event_followup_last_kind
                                    : "OnSessionConnectComplete";
                            ++m_process_event_followup_count;
                            m_process_event_followup_last_tick =
                                followup_tick;
                            m_process_event_followup_last_kind =
                                followup_kind;
                            m_process_event_followup_pending = true;
                            ReplayTraceFields f;
                            f.string("request_id", m_cfg.request_id)
                             .string("client_role", m_cfg.client_role)
                             .string("function",
                                     m_process_event_followup_last_kind)
                             .string("reason", "ready-open-queued")
                             .uinteger("followup_count",
                                       m_process_event_followup_count)
                             .uinteger("followup_tick", followup_tick)
                             .uinteger("last_service_tick",
                                       m_last_service_tick)
                             .uinteger("last_attempt_tick",
                                       m_online_stage_last_attempt_tick)
                             .boolean("deferred", true);
                            ReplayDebugTrace::instance().event(
                                "rollback_online_stage_callback_followup",
                                f);
                            emit_online_stage_followup_progress(
                                "ready-open-queued-wait", tick);
                            return;
                        }
                    }
                    const bool native_battle_ready =
                        m_battle_comp_seen ||
                        (m_battle_ready_seen && m_battle_ready_result);
                    if (!m_ready_preconditions_ok)
                    {
                        m_ready_request_ok = false;
                        m_ready_request_failure =
                            !m_ready_precondition_failure.empty()
                                ? m_ready_precondition_failure.c_str()
                                : "ready-preconditions-not-met";
                        m_start_latch_failure = m_ready_request_failure;
                    }
                    else
                    {
                        m_ready_requested = true;
                        m_start_latch_requested = true;
                        m_start_latch_method =
                            "lux-match-lobby-request-ready";
                        if (native_battle_ready)
                        {
                            sample_replay_seed_launcher_observation();
                            if (m_cfg.live_replay_input_requested
                                && !m_replay_match_seed_apply_ok)
                            {
                                m_replay_match_seed_arm_terminal_failure = true;
                                m_replay_match_seed_failure =
                                    m_replay_match_seed_arm_serial == 0
                                        ? "replay-random-seed-battle-ready-before-arm"
                                        : "replay-random-seed-battle-ready-before-proof";
                                m_ready_request_ok = false;
                                m_ready_request_failure =
                                    m_replay_match_seed_failure;
                                m_start_latch_ok = false;
                                m_start_latch_failure =
                                    m_replay_match_seed_failure;
                                return;
                            }
                            m_ready_request_ok = true;
                            m_ready_request_failure = "ok";
                            m_start_latch_ok = true;
                            m_start_latch_failure = "ok";
                        }
                        else if (!m_lux_match_lobby_request_ready_requested)
                        {
                            if (!arm_replay_seed_before_ready(nav))
                            {
                                m_ready_request_ok = false;
                                m_ready_request_failure =
                                    m_replay_match_seed_failure;
                                m_start_latch_ok = false;
                                m_start_latch_failure =
                                    m_replay_match_seed_failure;
                                emit_online_stage_followup_progress(
                                    "replay-seed-arm-pending", tick);
                                return;
                            }
                            m_lux_match_lobby_request_ready_requested = true;
                            emit_online_stage_followup_progress(
                                "ready-call-begin", tick);
                            // The InRoomMenu Ready button emits
                            // LuxMatchLobby::RequestReady.  Its native handler
                            // resolves the current game-flow hub before sending
                            // request type 0.  Do not substitute a cached
                            // SessionHub call or call MatchSettingSync's
                            // ReadyToConnect directly: both skip stock UI/state
                            // sequencing and can leave both clients in lobby.
                            m_lux_match_lobby_request_ready_ok =
                                call_lux_match_lobby_request_ready();
                            if (!m_lux_match_lobby_request_ready_ok
                                && m_replay_match_seed_arm_serial != 0)
                            {
                                LuxBattleLauncherStartHook::instance()
                                    .clear_replay_seed_override();
                                m_replay_match_seed_arm_terminal_failure = true;
                                m_replay_match_seed_failure =
                                    "replay-random-seed-ready-call-failed";
                            }
                            emit_online_stage_followup_progress(
                                "ready-call-end", tick);
                            m_ready_request_ok =
                                m_lux_match_lobby_request_ready_ok;
                            m_ready_request_failure =
                                m_ready_request_ok
                                    ? "ready-command-sent"
                                    : (m_replay_match_seed_arm_terminal_failure
                                        ? m_replay_match_seed_failure
                                        : m_lux_match_lobby_request_ready_failure);
                            m_start_latch_ok = false;
                            m_start_latch_failure =
                                m_ready_request_ok
                                    ? "waiting-for-OnBattleReady"
                                    : (m_replay_match_seed_arm_terminal_failure
                                        ? m_replay_match_seed_failure
                                        : m_lux_match_lobby_request_ready_failure);
                        }
                        else if (m_battle_ready_seen &&
                                 !m_battle_ready_result)
                        {
                            m_ready_request_ok = false;
                            m_ready_request_failure =
                                "OnBattleReady(false)";
                            m_start_latch_ok = false;
                            m_start_latch_failure =
                                "OnBattleReady(false)";
                        }
                        else
                        {
                            m_ready_request_ok =
                                m_lux_match_lobby_request_ready_ok;
                            m_ready_request_failure =
                                m_ready_request_ok
                                    ? "ready-command-sent"
                                    : m_lux_match_lobby_request_ready_failure;
                            m_start_latch_ok = false;
                            m_start_latch_failure =
                                m_ready_request_ok
                                    ? "waiting-for-OnBattleReady"
                                    : m_lux_match_lobby_request_ready_failure;
                        }
                    }
                }
                emit_online_stage_followup_progress("should-attempt-end", tick);
            }
            sync_session_callback_state();

            const bool stage_request_ok =
                is_host ? m_create_request_ok
                        : (is_sandbox
                            ? (m_guest_adopted_existing_session
                               || (m_stock_native_event_dispatch_ok
                                   && m_join_request_ok))
                            : false);
            const bool sandbox_find_target_found =
                m_stock_native_event_dispatch_ok
                    && m_stock_remote_offer.lobby_id != 0
                    && m_native_named_session_lobby_id ==
                        m_stock_remote_offer.lobby_id;
            const bool lobby_membership_goal =
                online_stage_goal_is("player-match-lobby");
            const bool current_stock_lobby_scene =
                identity_is_player_match_lobby_context(
                    nav.current_scene_identity);
            const bool authenticated_offer_route =
                RollbackStockJoinRouteUsesAuthenticatedOffer(
                    m_cfg.stock_join_route);
            const bool injected_offer_route =
                RollbackStockJoinRouteInjectsStockHandler(
                    m_cfg.stock_join_route);
            const bool host_private_lobby_membership_ready =
                !lobby_membership_goal
                || !authenticated_offer_route
                || (m_steam_private_lobby_ok
                    && RollbackPrivateLobbyMemberCountReady(
                        m_steam_private_lobby_member_count, true)
                    && current_stock_lobby_scene);
            const bool sandbox_private_lobby_membership_ready =
                !lobby_membership_goal
                || !authenticated_offer_route
                || ((injected_offer_route
                        ? (m_stock_native_event_dispatch_ok
                           && m_steam_join_lobby_direct_call_count == 0)
                        : m_steam_join_lobby_ok)
                    && RollbackPrivateLobbyMemberCountReady(
                        m_steam_join_lobby_member_count, true)
                    && current_stock_lobby_scene);
            const bool sandbox_stage_complete =
                (sandbox_find_target_found
                 || m_guest_adopted_existing_session)
                && (lobby_membership_goal
                     ? sandbox_membership_ready
                     : sandbox_transport_ready)
                && sandbox_private_lobby_membership_ready;
            const bool ready_gate_ok =
                is_host && !lobby_membership_goal
                    ? m_start_latch_ok : true;
            const bool ok =
                session_hub_ok
                && navigation_ready
                && stage_request_ok
                && match_data_present
                && m_play_side_request_ok
                && ready_gate_ok
                && (is_host
                        ? host_private_lobby_membership_ready
                        : sandbox_stage_complete);
            const bool invite_bridge_proven =
                authenticated_offer_route
                && m_stock_native_event_dispatch_ok;

            if (!session_hub_ok)
                m_last_failure = "session-hub-unavailable";
            else if (!navigation_ready)
                m_last_failure = "player-match-scene-not-ready";
            else if ((is_host || is_sandbox) &&
                     m_cfg.online_stage_wait_host_room_ready_marker &&
                     !m_host_room_ready_marker_observed)
                m_last_failure =
                    m_host_room_ready_marker_failure.empty()
                        ? "host-room-ready-marker-missing"
                        : m_host_room_ready_marker_failure.c_str();
            else if (is_sandbox && authenticated_offer_route
                     && !m_stock_offer_valid)
                m_last_failure = "authenticated-stock-offer-pending";
            else if (is_sandbox && authenticated_offer_route
                     && !m_stock_native_event_dispatch_ok)
                m_last_failure = m_stock_native_event_dispatched
                    ? "native-invite-conversion-or-delegate-pending"
                    : "native-invite-event-pending";
            else if (!stage_request_ok)
            {
                if (is_host)
                {
                    m_last_failure =
                        m_host_room_create_pipeline_step ==
                                kHostRoomCreatePipelineFailed
                            ? "create-player-session-failed"
                            : "host-room-create-pending";
                }
                else
                {
                    m_last_failure = "find-player-session-failed";
                }
            }
            else if (is_host && !lobby_membership_goal
                     && !host_transport_ready)
                m_last_failure = m_session_connect_complete_seen
                    && !m_session_connect_complete_result
                    ? "host-session-connect-complete-failed"
                    : "host-native-transport-pending";
            else if (is_host && lobby_membership_goal
                     && !host_private_lobby_membership_ready)
                m_last_failure = !m_steam_private_lobby_ok
                    ? "host-private-lobby-not-proven"
                    : (m_steam_private_lobby_member_count != 2
                        ? (m_steam_private_lobby_member_count > 2
                            ? "host-unexpected-third-lobby-member"
                            : "host-steam-lobby-member-count-below-two")
                        : "host-stock-lobby-scene-not-current");
            else if (is_sandbox && !m_join_request_ok)
                m_last_failure = m_join_callback_failure;
            else if (is_sandbox && !lobby_membership_goal
                     && sandbox_membership_ready
                     && !sandbox_transport_ready)
                m_last_failure = "membership-ready-transport-pending";
            else if (is_sandbox && !lobby_membership_goal
                     && !sandbox_transport_ready)
                m_last_failure = "native-transport-not-ready";
            else if (is_sandbox && lobby_membership_goal
                     && !sandbox_private_lobby_membership_ready)
                m_last_failure = !m_steam_join_lobby_ok
                    ? "sandbox-steam-lobby-join-not-proven"
                    : (m_steam_join_lobby_member_count != 2
                        ? (m_steam_join_lobby_member_count > 2
                            ? "sandbox-unexpected-third-lobby-member"
                            : "sandbox-steam-lobby-member-count-below-two")
                        : "sandbox-stock-lobby-scene-not-current");
            else if (is_sandbox && m_session_connect_complete_seen &&
                     !m_session_connect_complete_result &&
                     !sandbox_stage_complete)
            {
                const int32_t false_count =
                    s_session_connect_callback_false_count.load(
                        std::memory_order_acquire);
                m_last_failure =
                    false_count >= 30
                        ? repeated_session_connect_failure()
                        : "session-connect-complete-failed";
            }
            else if (!match_data_present)
                m_last_failure = "match-data-not-present";
            else if (!m_play_side_request_ok)
                m_last_failure = "change-play-side-failed";
            else if (is_host && !lobby_membership_goal
                     && !m_start_latch_ok)
                m_last_failure = m_start_latch_failure.empty()
                    ? "start-latch-failed"
                    : m_start_latch_failure.c_str();
            else
                m_last_failure = "ok";

            emit_online_stage_followup_progress("before-online-emit", tick);
            if (should_emit_online_stage(tick, ok))
            {
                emit_online_stage(
                    ok,
                    nav,
                    flow_manager,
                    session_hub,
                    match_data,
                    match_data_present);
                remember_online_stage_emit_state(tick, ok);
            }
            emit_online_stage_followup_progress("online-end", tick);
        }

        bool should_emit_online_stage(uint64_t tick, bool ok) const noexcept
        {
            if (RollbackOnlineStageTraceCadence::due(
                    tick,
                    m_online_stage_last_emit_tick,
                    m_online_stage_last_emit_ok,
                    ok))
            {
                return true;
            }
            // Follow-up scheduling has dedicated lightweight trace events.
            // Its counter can advance more than once per service call while
            // readiness retries are pending, so it must not force another
            // full ~70 KiB stage snapshot here.
            if (m_create_callback_seen
                != m_online_stage_last_emit_create_callback_seen)
                return true;
            if (m_session_connect_complete_seen
                != m_online_stage_last_emit_session_connect_seen)
                return true;
            if (m_session_connect_complete_result
                != m_online_stage_last_emit_session_connect_result)
                return true;
            if (m_find_callback_seen
                != m_online_stage_last_emit_find_callback_seen)
                return true;
            if (m_join_complete_seen
                != m_online_stage_last_emit_join_complete_seen)
                return true;
            if (m_session_member_join_seen
                != m_online_stage_last_emit_session_member_join_seen)
                return true;
            if (m_start_latch_ok != m_online_stage_last_emit_start_latch_ok)
                return true;
            if (m_player_match_in_room_requested !=
                m_online_stage_last_emit_player_match_in_room_requested)
                return true;
            if (m_player_match_in_room_ok !=
                m_online_stage_last_emit_player_match_in_room_ok)
                return true;
            if (m_host_room_ready_marker_observed !=
                m_online_stage_last_emit_host_room_ready_marker_observed)
                return true;
            if (m_host_room_create_pipeline_step !=
                m_online_stage_last_emit_host_room_create_pipeline_step)
                return true;
            if (m_last_failure
                && m_online_stage_last_emit_failure != m_last_failure)
                return true;
            return false;
        }

        void remember_online_stage_emit_state(uint64_t tick,
                                              bool ok) noexcept
        {
            if (!m_process_event_followup_in_progress)
                m_online_stage_last_emit_tick = tick;
            m_online_stage_last_emit_ok = ok;
            m_online_stage_last_emit_failure =
                m_last_failure ? m_last_failure : "";
            m_online_stage_last_emit_create_callback_seen =
                m_create_callback_seen;
            m_online_stage_last_emit_session_connect_seen =
                m_session_connect_complete_seen;
            m_online_stage_last_emit_session_connect_result =
                m_session_connect_complete_result;
            m_online_stage_last_emit_find_callback_seen =
                m_find_callback_seen;
            m_online_stage_last_emit_join_complete_seen =
                m_join_complete_seen;
            m_online_stage_last_emit_session_member_join_seen =
                m_session_member_join_seen;
            m_online_stage_last_emit_start_latch_ok = m_start_latch_ok;
            m_online_stage_last_emit_player_match_in_room_requested =
                m_player_match_in_room_requested;
            m_online_stage_last_emit_player_match_in_room_ok =
                m_player_match_in_room_ok;
            m_online_stage_last_emit_host_room_ready_marker_observed =
                m_host_room_ready_marker_observed;
            m_online_stage_last_emit_host_room_create_pipeline_step =
                m_host_room_create_pipeline_step;
        }

